import type { ApplyPatchOperation } from './types/protocol';
import type { RunContext } from './runContext';
export type { ApplyPatchOperation } from './types/protocol';

/**
 * Result returned by an Editor operation.
 */
export type ApplyPatchResult = {
  /**
   * Whether the operation completed successfully. Defaults to `completed`.
   */
  status?: 'completed' | 'failed';
  /**
   * Optional textual output to forward to the model.
   */
  output?: string;
};

/**
 * Runtime context passed to editor operations.
 */
export type EditorInvocationContext = {
  /**
   * Current run context.
   */
  runContext: RunContext;
};

/**
 * Host interface responsible for applying diffs on disk.
 */
export interface Editor {
  /**
   * Creates a new file from a V4A diff.
   */
  createFile(
    operation: Extract<ApplyPatchOperation, { type: 'create_file' }>,
    context?: EditorInvocationContext,
  ): Promise<ApplyPatchResult | void>;

  /**
   * Updates an existing file based on a V4A diff.
   */
  updateFile(
    operation: Extract<ApplyPatchOperation, { type: 'update_file' }>,
    context?: EditorInvocationContext,
  ): Promise<ApplyPatchResult | void>;

  /**
   * Deletes an existing file.
   */
  deleteFile(
    operation: Extract<ApplyPatchOperation, { type: 'delete_file' }>,
    context?: EditorInvocationContext,
  ): Promise<ApplyPatchResult | void>;
}

import {
  applyDiff,
  UserError,
  type ApplyPatchOperation,
  type ApplyPatchResult,
  type Editor,
} from '@openai/agents-core';
import { isSandboxPathNotFoundError } from '@openai/agents-core/sandbox/internal';
import { posixDirname } from './paths';
import type { RemoteEditorIo } from './types';

export class RemoteSandboxEditor implements Editor {
  private readonly io: RemoteEditorIo;

  constructor(io: RemoteEditorIo) {
    this.io = io;
  }

  async createFile(
    operation: Extract<ApplyPatchOperation, { type: 'create_file' }>,
  ): Promise<ApplyPatchResult> {
    const path = await this.resolvePath(operation.path, { forWrite: true });
    if (await this.pathExists(path)) {
      throw new UserError(
        `Cannot create file because it already exists: ${path}`,
      );
    }
    const content = applyDiff('', operation.diff, 'create');
    const parent = posixDirname(path);
    if (this.io.mkdir && parent !== '.' && parent !== '/') {
      await this.io.mkdir(parent);
    }
    await this.io.writeText(path, content);
    return {};
  }

  async updateFile(
    operation: Extract<ApplyPatchOperation, { type: 'update_file' }>,
  ): Promise<ApplyPatchResult> {
    const moveTo = operation.moveTo;
    const path = await this.resolvePath(operation.path, { forWrite: true });
    const destination = moveTo
      ? await this.resolvePath(moveTo, { forWrite: true })
      : path;
    const current = await this.io.readText(path);
    const next = applyDiff(current, operation.diff);
    const parent = posixDirname(destination);
    if (this.io.mkdir && parent !== '.' && parent !== '/') {
      await this.io.mkdir(parent);
    }
    await this.io.writeText(destination, next);
    if (moveTo && destination !== path) {
      await this.io.deletePath(path);
    }
    return {};
  }

  async deleteFile(
    operation: Extract<ApplyPatchOperation, { type: 'delete_file' }>,
  ): Promise<ApplyPatchResult> {
    await this.io.deletePath(
      await this.resolvePath(operation.path, { forWrite: true }),
    );
    return {};
  }

  private async resolvePath(
    path: string,
    options?: { forWrite?: boolean },
  ): Promise<string> {
    return this.io.resolvePath
      ? await this.io.resolvePath(path, options)
      : path;
  }

  private async pathExists(path: string): Promise<boolean> {
    if (this.io.pathExists) {
      return await this.io.pathExists(path);
    }
    try {
      await this.io.readText(path);
      return true;
    } catch (error) {
      if (isSandboxPathNotFoundError(error)) {
        return false;
      }
      throw error;
    }
  }
}

import { Manifest } from '@openai/agents/sandbox';
import { UnixLocalSandboxClient } from '@openai/agents/sandbox/local';

const manifest = new Manifest();
const client = new UnixLocalSandboxClient({
  snapshot: { type: 'local', baseDir: '/tmp/my-sandbox-snapshots' },
});

const session = await client.create({ manifest });
const state = await client.serializeSessionState?.(session.state);
await session.close?.();

if (state) {
  const restored = await client.resume?.(
    await client.deserializeSessionState!(state),
  );
  await restored?.close?.();
}

/**
 * A CLI simulation, not an HTTP service or authentication implementation.
 * Complete snapshots and RunResult objects stay in the server implementation.
 * Production needs trusted authentication, request protections, atomic shared
 * storage, bounded retention, and recovery that reconciles tool side effects.
 */
import { Agent, tool } from '@openai/agents';
import { z } from 'zod';
import readline from 'node:readline/promises';
import { ApprovalServer } from '../docs/human-in-the-loop/server';

async function main() {
  const server = new ApprovalServer(
    new Agent({
      name: 'Weather assistant',
      instructions: 'Use get_temperature to answer temperature questions.',
      tools: [
        tool({
          name: 'get_temperature',
          description: 'Return a sample temperature for a city.',
          parameters: z.object({ city: z.string() }),
          needsApproval: true,
          execute: async ({ city }) =>
            `The temperature in ${city} is 20 Celsius.`,
        }),
      ],
    }),
  );
  // Server-side simulation of authenticated middleware; never a request-body field.
  const authenticatedUserId = 'example-user';
  let response = await server.start(
    authenticatedUserId,
    'What is the temperature in Oakland?',
  );
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
  try {
    while (response.kind === 'approval') {
      const decisions: Record<string, boolean> = {};
      for (const prompt of response.prompts) {
        // JSON quoting also keeps terminal control characters out of the prompt.
        const answer = await rl.question(
          `Allow ${JSON.stringify(prompt.toolName)} with ${JSON.stringify(prompt.arguments)}? (y/n): `,
        );
        decisions[prompt.decisionId] = answer.trim().toLowerCase() === 'y';
      }
      response = await server.decide(
        authenticatedUserId,
        response.requestId,
        decisions,
      );
    }
    console.log(response.output);
  } finally {
    rl.close();
  }
}

main().catch(() => {
  // Raw SDK errors can contain execution state. Keep diagnostics server-side.
  console.error(
    'The approval run failed. Reconcile side effects before retrying.',
  );
  process.exitCode = 1;
});

import { z } from 'zod';
import readline from 'node:readline/promises';
import { Agent, run, tool } from '@openai/agents';

const AUTO_APPROVE_HITL = process.env.AUTO_APPROVE_HITL === '1';

// Prompt user for yes/no confirmation
async function confirm(question: string): Promise<boolean> {
  if (AUTO_APPROVE_HITL) {
    console.log(`[auto-approve] ${question}`);
    return true;
  }
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
  const answer = await rl.question(`${question} (y/n): `);
  rl.close();
  return ['y', 'yes'].includes(answer.trim().toLowerCase());
}

async function main() {
  // Define a tool that requires approval for certain inputs
  const getWeatherTool = tool({
    name: 'get_weather',
    description:
      'Get weather conditions for one city. The result does not include temperature.',
    parameters: z.object({
      city: z.string().describe('City whose weather conditions to retrieve.'),
    }),
    async execute({ city }) {
      return `The weather in ${city} is sunny.`;
    },
  });

  const weatherAgent = new Agent({
    name: 'Weather agent',
    instructions:
      'Use the available tool to report weather conditions for every requested city. Report conditions only, without temperatures.',
    handoffDescription: 'Handles weather-related queries',
    tools: [getWeatherTool],
  });

  const getTemperatureTool = tool({
    name: 'get_temperature',
    description:
      'Get the current temperature for one city. Call separately for each requested city.',
    parameters: z.object({
      city: z.string().describe('City whose current temperature to retrieve.'),
    }),
    needsApproval: async (_ctx, { city }) => city.includes('Oakland'),
    execute: async ({ city }) => {
      return `The temperature in ${city} is 20° Celsius`;
    },
  });

  const mainAgent = new Agent({
    name: 'Main agent',
    instructions:
      'Use the available tools to answer weather questions. Retrieve every requested kind of information for every requested city before answering.',
    tools: [
      getTemperatureTool,
      weatherAgent.asTool({
        toolName: 'ask_weather_agent',
        toolDescription:
          'Get weather conditions for one or more locations. This tool does not return temperatures.',
        // Require approval when the generated input mentions San Francisco.
        needsApproval: async (_ctx, { input }) =>
          input.includes('San Francisco'),
      }),
    ],
  });

  let stream = await run(
    mainAgent,
    'What is the weather and temperature in San Francisco and Oakland?',
    { stream: true },
  );
  stream.toTextStream({ compatibleWithNodeStreams: true }).pipe(process.stdout);
  await stream.completed;

  while (stream.interruptions?.length) {
    console.log(
      'Human-in-the-loop: approval required for the following tool calls:',
    );
    const state = stream.state;
    for (const interruption of stream.interruptions) {
      if (interruption.rawItem.type !== 'function_call') {
        throw new Error(
          'Invalid interruption type: ' + interruption.rawItem.type,
        );
      }
      const ok = await confirm(
        `Agent ${interruption.agent.name} would like to use the tool ${interruption.rawItem.name} with "${interruption.rawItem.arguments}". Do you approve?`,
      );
      if (ok) {
        state.approve(interruption);
      } else {
        state.reject(interruption);
      }
    }

    // Resume execution with streaming output
    stream = await run(mainAgent, state, { stream: true });
    const textStream = stream.toTextStream({ compatibleWithNodeStreams: true });
    textStream.pipe(process.stdout);
    await stream.completed;
  }

  console.log('\n\nDone');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import {
  createGenerationSpan,
  getGlobalTraceProvider,
  createFunctionSpan,
  setTraceProcessors,
  setTracingDisabled,
  withTrace,
  type Span,
  type Trace,
  type TracingProcessor,
} from '@openai/agents-core';
import { OpenAITracingExporter } from '../src/openaiTracingExporter';
import { OpenAIChatCompletionsModel } from '../src/openaiChatCompletionsModel';

const endpoint = 'https://api.openai.com/v1/traces/ingest';
const reasoning = {
  type: 'reasoning',
  content: [{ type: 'input_text', text: 'synthetic-private-thought' }],
  rawContent: [{ type: 'reasoning_text', text: 'synthetic-private-thought' }],
};
const answer = {
  type: 'message',
  role: 'assistant',
  status: 'completed',
  content: [{ type: 'output_text', text: 'ordinary answer' }],
};

describe('generation reasoning trace exports', () => {
  const fetchMock = vi.fn();
  beforeEach(() => {
    setTraceProcessors([]);
    setTracingDisabled(false);
    fetchMock.mockReset().mockResolvedValue({ ok: true });
    vi.stubGlobal('fetch', fetchMock);
  });
  afterEach(() => {
    setTraceProcessors([]);
    setTracingDisabled(true);
    vi.unstubAllGlobals();
  });

  function span(
    data: NonNullable<Parameters<typeof createGenerationSpan>[0]>['data'],
  ) {
    return createGenerationSpan(
      { data },
      getGlobalTraceProvider().createTrace({ name: 'synthetic' }),
    );
  }
  async function exported(item: Span<any>, destination?: string) {
    await new OpenAITracingExporter({
      apiKey: 'synthetic-key',
      endpoint: destination,
    }).export([item]);
    return JSON.parse(fetchMock.mock.calls.at(-1)![1].body).data[0];
  }

  it.each([undefined, endpoint, `${endpoint}/`])(
    'omits supported reasoning at the default destination %s without mutating spans',
    async (destination) => {
      const tool = {
        type: 'function_call',
        name: 'lookup',
        callId: 'call_1',
        arguments: JSON.stringify({ reasoning: 'ordinary tool data' }),
      };
      const input = [
        {
          role: 'assistant',
          content: [
            { type: 'reasoning', text: 'synthetic-private-thought' },
            { type: 'text', text: 'ordinary input' },
            {
              type: 'tool-call',
              toolCallId: 'call_1',
              toolName: 'lookup',
              input: { reasoning: 'ordinary tool data' },
            },
          ],
        },
      ];
      const item = span({
        input,
        output: [reasoning, answer, tool],
        model: 'test-model',
        model_config: { reasoning_effort: 'high' },
        usage: {
          input_tokens: 4,
          output_tokens: 8,
          output_tokens_details: { reasoning_tokens: 3 },
        },
      });
      const before = structuredClone(item.toJSON());
      const sent = await exported(item, destination);
      expect(JSON.stringify(sent)).not.toContain('synthetic-private-thought');
      expect(sent.span_data.input).toEqual([
        { ...input[0], content: input[0].content.slice(1) },
      ]);
      expect(sent.span_data.output).toEqual([answer, tool]);
      expect(sent.span_data).toMatchObject({
        model: 'test-model',
        model_config: { reasoning_effort: 'high' },
        usage: {
          input_tokens: 4,
          output_tokens: 8,
          details: { output_tokens_details: { reasoning_tokens: 3 } },
        },
      });
      expect(sent).toMatchObject({ id: item.spanId, trace_id: item.traceId });
      expect(item.toJSON()).toEqual(before);
      const custom = await exported(item, 'https://example.test/ingest');
      expect(custom.span_data.input).toEqual(input);
      expect(custom.span_data.output).toEqual([reasoning, answer, tool]);
      expect(custom.span_data.usage).toEqual(sent.span_data.usage);
    },
  );

  it('filters before byte truncation and still bounds retained text', async () => {
    const retained = {
      ...answer,
      content: [{ type: 'output_text', text: 'a'.repeat(70_000) }],
    };
    const oversizedReasoning = {
      ...reasoning,
      content: [{ type: 'input_text', text: 'r'.repeat(70_000) }],
    };
    const item = span({ output: [oversizedReasoning, retained] });
    expect((await exported(item)).span_data.output).toEqual([retained]);
    const custom = (await exported(item, 'https://example.test/ingest'))
      .span_data.output;
    expect(custom.some((entry: any) => entry.type === 'reasoning')).toBe(true);
    expect(
      new TextEncoder().encode(JSON.stringify(custom)).length,
    ).toBeLessThanOrEqual(100_000);
    item.spanData.output = [
      {
        ...answer,
        content: [{ type: 'output_text', text: 'a'.repeat(150_000) }],
      },
    ];
    const limited = (await exported(item)).span_data.output;
    expect(
      new TextEncoder().encode(JSON.stringify(limited)).length,
    ).toBeLessThanOrEqual(100_000);
    expect(JSON.stringify(limited)).toContain('[truncated]');
  });

  it('keeps empty reasoning-only results and assistant envelopes', async () => {
    const item = span({
      input: [
        {
          role: 'assistant',
          content: [{ type: 'reasoning', text: 'synthetic-private-thought' }],
        },
      ],
      output: [reasoning],
      model: 'test-model',
    });
    expect((await exported(item)).span_data).toEqual({
      type: 'generation',
      input: [{ role: 'assistant', content: [] }],
      output: [],
      model: 'test-model',
    });
  });

  it('preserves user and tool data, opaque metadata, and non-generation spans', async () => {
    const ordinary = {
      reasoning: 'ordinary data',
      nested: { type: 'reasoning', text: 'ordinary data' },
    };
    const input = [
      {
        role: 'user',
        content: 'reasoning is a word',
        reasoning: 'ordinary data',
      },
      { role: 'tool', content: ordinary },
      {
        role: 'user',
        content: [
          {
            type: 'text',
            text: JSON.stringify(ordinary),
            reasoning: 'ordinary data',
          },
        ],
      },
      {
        role: 'tool',
        content: [
          {
            type: 'text',
            text: JSON.stringify(ordinary),
            reasoning: 'ordinary data',
          },
        ],
      },
      {
        role: 'assistant',
        content: 'ordinary text',
        providerOptions: ordinary,
      },
    ];
    expect((await exported(span({ input }))).span_data.input).toEqual(input);
    const functionSpan = createFunctionSpan(
      {
        data: {
          name: 'lookup',
          input: JSON.stringify(ordinary),
          output: JSON.stringify([reasoning]),
        },
      },
      getGlobalTraceProvider().createTrace({ name: 'synthetic' }),
    );
    expect((await exported(functionSpan)).span_data).toEqual(
      functionSpan.spanData,
    );
  });

  it.each([
    { stream: false, refusal: false },
    { stream: true, refusal: false },
    { stream: false, refusal: true },
  ])(
    'exports replayed Chat Completions reasoning only to custom destinations ($stream, $refusal)',
    async ({ stream, refusal }) => {
      const ended: Span<any>[] = [];
      const processor: TracingProcessor = {
        async onTraceStart(_trace: Trace) {},
        async onTraceEnd(_trace: Trace) {},
        async onSpanStart(_span: Span<any>) {},
        async onSpanEnd(span) {
          ended.push(span);
        },
        async shutdown() {},
        async forceFlush() {},
      };
      setTraceProcessors([processor]);
      const raw = {
        id: 'completion_1',
        object: 'chat.completion',
        created: 1,
        model: 'test-model',
        choices: [
          {
            index: 0,
            finish_reason: 'stop',
            logprobs: null,
            message: {
              role: 'assistant',
              content: refusal ? null : 'ordinary answer',
              ...(refusal ? { refusal: 'ordinary refusal' } : {}),
              reasoning: 'synthetic-private-thought',
            },
          },
        ],
        usage: { prompt_tokens: 2, completion_tokens: 3, total_tokens: 5 },
      };
      const chunks = [
        {
          id: raw.id,
          object: 'chat.completion.chunk',
          created: 1,
          model: raw.model,
          choices: [
            {
              index: 0,
              delta: {
                role: 'assistant',
                content: 'ordinary answer',
                reasoning: 'synthetic-private-thought',
              },
              finish_reason: null,
            },
          ],
        },
        {
          id: raw.id,
          object: 'chat.completion.chunk',
          created: 1,
          model: raw.model,
          choices: [{ index: 0, delta: {}, finish_reason: 'stop' }],
          usage: raw.usage,
        },
      ];
      const create = vi.fn().mockImplementation(async (params) =>
        params.stream
          ? (async function* () {
              yield* chunks;
            })()
          : raw,
      );
      const model = new OpenAIChatCompletionsModel(
        {
          chat: { completions: { create } },
          baseURL: 'https://example.test',
        } as any,
        'test-model',
      );
      const request = {
        input: 'Hello',
        modelSettings: {},
        tools: [],
        handoffs: [],
        outputType: 'text' as const,
        tracing: true as const,
      };
      let output: unknown;
      let replay: Awaited<ReturnType<typeof model.getResponse>>['output'];
      await withTrace('synthetic', async () => {
        const first = await model.getResponse(request);
        replay = first.output;
        const followUp = { ...request, input: replay };
        if (stream) {
          for await (const event of model.getStreamedResponse(followUp)) {
            if (event.type === 'response_done') output = event.response.output;
          }
        } else output = (await model.getResponse(followUp)).output;
      });
      const item = ended
        .filter((entry) => entry.spanData.type === 'generation')
        .at(-1)!;
      expect(item).toBeDefined();
      const before = structuredClone(item.toJSON());
      const outputBefore = structuredClone(output);
      const replayBefore = structuredClone(replay!);
      expect(item.spanData.input[0].content[0].reasoning).toBe(
        'synthetic-private-thought',
      );
      expect(JSON.stringify(output)).toContain('synthetic-private-thought');
      expect(item.spanData.input[0].reasoning).toBe(
        'synthetic-private-thought',
      );
      const sent = await exported(item);
      expect(JSON.stringify(sent)).not.toContain('synthetic-private-thought');
      expect(sent.span_data.input[0].content).toEqual([
        refusal
          ? {
              type: 'refusal',
              refusal: 'ordinary refusal',
              role: 'assistant',
              content: null,
            }
          : { type: 'text', text: 'ordinary answer', role: 'assistant' },
      ]);
      expect(sent.span_data.output[0].choices[0].message).toMatchObject(
        refusal
          ? { content: null, refusal: 'ordinary refusal' }
          : { content: 'ordinary answer' },
      );
      expect(item.toJSON()).toEqual(before);
      expect(output).toEqual(outputBefore);
      expect(replay!).toEqual(replayBefore);
      const custom = await exported(item, 'https://example.test/ingest');
      expect(custom.span_data.input[0].reasoning).toBe(
        'synthetic-private-thought',
      );
      if (!stream)
        expect(custom.span_data.output[0].choices[0].message.reasoning).toBe(
          'synthetic-private-thought',
        );
      expect(custom.span_data.input).toEqual(item.spanData.input);
      expect(ended).toHaveLength(2);
    },
  );
});

