        table.insert(
            "type",
            match disabled_tool.kind {
                ToolSuggestDiscoverableType::Connector => "connector",
                ToolSuggestDiscoverableType::Plugin => "plugin",
            }
            .into(),
        );
        table.insert("id", disabled_tool.id.clone().into());
