			}
			case "http/protobuf": {
				return new OTLPTraceExporterProto({ url: tracesUrl.toString(), headers })
			}
			default:
				Logger.warn(`[OTEL] Unknown OTLP protocol for traces: ${protocol}`)
				return null
		}
	} catch (error) {
		Logger.error("[OTEL] Error creating OTLP trace exporter:", error)
		return null
	}
}

