import { runStreamCase, StreamEvent } from "../lib/stream-harness"

const LONG_PROMPT =
	'Run exactly this command and do not summarize until it finishes: sleep 12 && echo "done". After it finishes, reply with exactly "done".'

async function main() {
	const startRequestId = `start-a-${Date.now()}`
	const cancelRequestId = `cancel-${Date.now()}`
	const shutdownRequestId = `shutdown-${Date.now()}`

	let initSeen = false
	let startAccepted = false
	let startCommandToolUseSeen = false
	let sentCancel = false
	let cancelDone = false
	let sentShutdown = false

	await runStreamCase({
		onEvent(event: StreamEvent, context) {
			if (event.type === "system" && event.subtype === "init" && !initSeen) {
				initSeen = true
				context.sendCommand({
					command: "start",
					requestId: startRequestId,
					prompt: LONG_PROMPT,
				})
				return
			}

			if (
				event.type === "control" &&
				event.subtype === "ack" &&
				event.command === "start" &&
				event.requestId === startRequestId
			) {
				startAccepted = true
				return
			}

			if (
				event.type === "tool_use" &&
				event.subtype === "command" &&
				event.done === true &&
				event.requestId === startRequestId
			) {
				startCommandToolUseSeen = true
			}

			if (startAccepted && startCommandToolUseSeen && !sentCancel) {
				context.sendCommand({
					command: "cancel",
					requestId: cancelRequestId,
				})
				sentCancel = true
				return
			}

			if (
				event.type === "control" &&
				event.subtype === "done" &&
				event.command === "cancel" &&
				event.requestId === cancelRequestId
			) {
				if (event.code === "cancel_requested" || event.code === "no_active_task") {
					cancelDone = true
				}
				return
			}

			if (cancelDone && !sentShutdown) {
				context.sendCommand({
					command: "shutdown",
					requestId: shutdownRequestId,
				})
				sentShutdown = true
				return
			}

			if (event.type === "control" && event.subtype === "error" && event.requestId === cancelRequestId) {
				throw new Error(
					`cancel command failed with code=${event.code ?? "unknown"} content="${event.content ?? ""}"`,
				)
			}

			if (event.type === "error") {
				throw new Error(`unexpected stream error event: ${event.content ?? "unknown error"}`)
			}
		},
		onTimeoutMessage() {
			return `timed out waiting for cancel flow (initSeen=${initSeen}, startAccepted=${startAccepted}, startCommandToolUseSeen=${startCommandToolUseSeen}, sentCancel=${sentCancel}, cancelDone=${cancelDone}, sentShutdown=${sentShutdown})`
		},
	})

	if (!startAccepted || !startCommandToolUseSeen || !sentCancel || !cancelDone || !sentShutdown) {
		throw new Error(
			`cancel flow did not complete expected transitions (startAccepted=${startAccepted}, startCommandToolUseSeen=${startCommandToolUseSeen}, sentCancel=${sentCancel}, cancelDone=${cancelDone}, sentShutdown=${sentShutdown})`,
		)
	}
}

main().catch((error) => {
	console.error(`[FAIL] ${error instanceof Error ? error.message : String(error)}`)
	process.exit(1)
})

import { runStreamCase, StreamEvent } from "../lib/stream-harness"

async function main() {
	const cancelRequestId = `cancel-${Date.now()}`
	const shutdownRequestId = `shutdown-${Date.now()}`

	let initSeen = false
	let cancelAckSeen = false
	let cancelDoneSeen = false
	let shutdownSent = false

	await runStreamCase({
		onEvent(event: StreamEvent, context) {
			if (event.type === "system" && event.subtype === "init" && !initSeen) {
				initSeen = true
				context.sendCommand({
					command: "cancel",
					requestId: cancelRequestId,
				})
				return
			}

			if (
				event.type === "control" &&
				event.subtype === "ack" &&
				event.command === "cancel" &&
				event.requestId === cancelRequestId
			) {
				cancelAckSeen = true
				return
			}

			if (
				event.type === "control" &&
				event.subtype === "done" &&
				event.command === "cancel" &&
				event.requestId === cancelRequestId
			) {
				cancelDoneSeen = true

				if (event.code !== "no_active_task") {
					throw new Error(`cancel without task should return no_active_task, got "${event.code ?? "none"}"`)
				}
				if (event.success !== true) {
					throw new Error("cancel without task should be treated as successful no-op")
				}

				if (!shutdownSent) {
					context.sendCommand({
						command: "shutdown",
						requestId: shutdownRequestId,
					})
					shutdownSent = true
				}
				return
			}

			if (event.type === "control" && event.subtype === "error") {
				throw new Error(
					`unexpected control error command=${event.command ?? "unknown"} code=${event.code ?? "unknown"} content=${event.content ?? ""}`,
				)
			}
		},
		onTimeoutMessage() {
			return `timed out waiting for cancel-without-active-task validation (initSeen=${initSeen}, cancelAckSeen=${cancelAckSeen}, cancelDoneSeen=${cancelDoneSeen}, shutdownSent=${shutdownSent})`
		},
	})
}

main().catch((error) => {
	console.error(`[FAIL] ${error instanceof Error ? error.message : String(error)}`)
	process.exit(1)
})

import { memo } from "react"
import { Text } from "ink"

import * as theme from "../theme.js"

interface ProgressBarProps {
	/** Current value (e.g., contextTokens) */
	value: number
	/** Maximum value (e.g., contextWindow) */
	max: number
	/** Width of the bar in characters (default: 16) */
	width?: number
}

/**
 * A progress bar component with color gradient based on fill percentage.
 *
 * Colors:
 * - 0-50%: Green (safe zone)
 * - 50-75%: Yellow (warning zone)
 * - 75-100%: Red (danger zone)
 *
 * Visual example: [████████░░░░░░░░] 50%
 */
function ProgressBar({ value, max, width = 16 }: ProgressBarProps) {
	// Calculate percentage, clamped to 0-100
	const percentage = max > 0 ? Math.min(100, Math.max(0, (value / max) * 100)) : 0

	// Calculate how many blocks to fill
	const filledBlocks = Math.round((percentage / 100) * width)
	const emptyBlocks = width - filledBlocks

	// Determine color based on percentage
	let barColor: string
	if (percentage <= 50) {
		barColor = theme.successColor // Green
	} else if (percentage <= 75) {
		barColor = theme.warningColor // Yellow
	} else {
		barColor = theme.errorColor // Red
	}

	// Unicode block characters for smooth appearance
	const filledChar = "█"
	const emptyChar = "░"

	const filledPart = filledChar.repeat(filledBlocks)
	const emptyPart = emptyChar.repeat(emptyBlocks)

	return (
		<Text>
			<Text color={theme.dimText}>[</Text>
			<Text color={barColor}>{filledPart}</Text>
			<Text color={theme.dimText}>
				{emptyPart}] {Math.round(percentage)}%
			</Text>
		</Text>
	)
}

export default memo(ProgressBar)

/**
 * Event System for Agent State Changes
 *
 * This module provides a strongly-typed event emitter specifically designed
 * for tracking agent state changes. It uses Node.js EventEmitter under the hood
 * but provides type safety for all events.
 */

import { EventEmitter } from "events"

import { ClineMessage, ClineAsk } from "@roo-code/types"

import type { AgentStateInfo } from "./agent-state.js"

// =============================================================================
// Event Types
// =============================================================================

/**
 * All events that can be emitted by the client.
 *
 * Design note: We use a string literal union type for event names to ensure
 * type safety when subscribing to events. The payload type is determined by
 * the event name.
 */
export interface ClientEventMap {
	/**
	 * Emitted whenever the agent state changes.
	 * This is the primary event for tracking state.
	 */
	stateChange: AgentStateChangeEvent

	/**
	 * Emitted when a new message is added to the message list.
	 */
	message: ClineMessage

	/**
	 * Emitted when an existing message is updated (e.g., partial -> complete).
	 */
	messageUpdated: ClineMessage

	/**
	 * Emitted when the agent starts waiting for user input.
	 * Convenience event - you can also use stateChange.
	 */
	waitingForInput: WaitingForInputEvent

	/**
	 * Emitted when the agent stops waiting and resumes running.
	 */
	resumedRunning: void

	/**
	 * Emitted when the agent starts streaming content.
	 */
	streamingStarted: void

	/**
	 * Emitted when streaming ends.
	 */
	streamingEnded: void

	/**
	 * Emitted when a task completes (either successfully or with error).
	 */
	taskCompleted: TaskCompletedEvent

	/**
	 * Emitted when a task is cleared/cancelled.
	 */
	taskCleared: void

	/**
	 * Emitted when the current mode changes.
	 */
	modeChanged: ModeChangedEvent

	/**
	 * Emitted on any error during message processing.
	 */
	error: Error
}

/**
 * Event payload for state changes.
 */
export interface AgentStateChangeEvent {
	/** The previous state info */
	previousState: AgentStateInfo
	/** The new/current state info */
	currentState: AgentStateInfo
	/** Whether this is a significant state transition (state enum changed) */
	isSignificantChange: boolean
}

/**
 * Event payload when agent starts waiting for input.
 */
export interface WaitingForInputEvent {
	/** The specific ask type */
	ask: ClineAsk
	/** Full state info for context */
	stateInfo: AgentStateInfo
	/** The message that triggered this wait */
	message: ClineMessage
}

/**
 * Event payload when a task completes.
 */
export interface TaskCompletedEvent {
	/** Whether the task completed successfully */
	success: boolean
	/** The final state info */
	stateInfo: AgentStateInfo
	/** The completion message if available */
	message?: ClineMessage
}

/**
 * Event payload when mode changes.
 */
export interface ModeChangedEvent {
	/** The previous mode (undefined if first mode set) */
	previousMode: string | undefined
	/** The new/current mode */
	currentMode: string
}

// =============================================================================
// Typed Event Emitter
// =============================================================================

/**
 * Type-safe event emitter for client events.
 *
 * Usage:
 * ```typescript
 * const emitter = new TypedEventEmitter()
 *
 * // Type-safe subscription
 * emitter.on('stateChange', (event) => {
 *   console.log(event.currentState) // TypeScript knows this is AgentStateChangeEvent
 * })
 *
 * // Type-safe emission
 * emitter.emit('stateChange', { previousState, currentState, isSignificantChange })
 * ```
 */
export class TypedEventEmitter {
	private emitter = new EventEmitter()

	/**
	 * Subscribe to an event.
	 *
	 * @param event - The event name
	 * @param listener - The callback function
	 * @returns Function to unsubscribe
	 */
	on<K extends keyof ClientEventMap>(event: K, listener: (payload: ClientEventMap[K]) => void): () => void {
		this.emitter.on(event, listener)
		return () => this.emitter.off(event, listener)
	}

	/**
	 * Subscribe to an event, but only once.
	 *
	 * @param event - The event name
	 * @param listener - The callback function
	 */
	once<K extends keyof ClientEventMap>(event: K, listener: (payload: ClientEventMap[K]) => void): void {
		this.emitter.once(event, listener)
	}

	/**
	 * Unsubscribe from an event.
	 *
	 * @param event - The event name
	 * @param listener - The callback function to remove
	 */
	off<K extends keyof ClientEventMap>(event: K, listener: (payload: ClientEventMap[K]) => void): void {
		this.emitter.off(event, listener)
	}

	/**
	 * Emit an event.
	 *
	 * @param event - The event name
	 * @param payload - The event payload
	 */
	emit<K extends keyof ClientEventMap>(event: K, payload: ClientEventMap[K]): void {
		this.emitter.emit(event, payload)
	}

	/**
	 * Remove all listeners for an event, or all events.
	 *
	 * @param event - Optional event name. If not provided, removes all listeners.
	 */
	removeAllListeners<K extends keyof ClientEventMap>(event?: K): void {
		if (event) {
			this.emitter.removeAllListeners(event)
		} else {
			this.emitter.removeAllListeners()
		}
	}

	/**
	 * Get the number of listeners for an event.
	 */
	listenerCount<K extends keyof ClientEventMap>(event: K): number {
		return this.emitter.listenerCount(event)
	}
}

// =============================================================================
// State Change Detector
// =============================================================================

/**
 * Helper to determine if a state change is "significant".
 *
 * A significant change is when the AgentLoopState enum value changes,
 * as opposed to just internal state updates within the same state.
 */
export function isSignificantStateChange(previous: AgentStateInfo, current: AgentStateInfo): boolean {
	return previous.state !== current.state
}

/**
 * Helper to determine if we transitioned to waiting for input.
 */
export function transitionedToWaiting(previous: AgentStateInfo, current: AgentStateInfo): boolean {
	return !previous.isWaitingForInput && current.isWaitingForInput
}

/**
 * Helper to determine if we transitioned from waiting to running.
 */
export function transitionedToRunning(previous: AgentStateInfo, current: AgentStateInfo): boolean {
	return previous.isWaitingForInput && !current.isWaitingForInput && current.isRunning
}

/**
 * Helper to determine if streaming started.
 */
export function streamingStarted(previous: AgentStateInfo, current: AgentStateInfo): boolean {
	return !previous.isStreaming && current.isStreaming
}

/**
 * Helper to determine if streaming ended.
 */
export function streamingEnded(previous: AgentStateInfo, current: AgentStateInfo): boolean {
	return previous.isStreaming && !current.isStreaming
}

/**
 * Helper to determine if task completed.
 */
export function taskCompleted(previous: AgentStateInfo, current: AgentStateInfo): boolean {
	const completionAsks = ["completion_result", "resume_completed_task"]
	const wasNotComplete = !previous.currentAsk || !completionAsks.includes(previous.currentAsk)
	const isNowComplete = current.currentAsk !== undefined && completionAsks.includes(current.currentAsk)
	return wasNotComplete && isNowComplete
}

// =============================================================================
// Observable Pattern (Alternative API)
// =============================================================================

/**
 * Subscription function type for observable pattern.
 */
export type Observer<T> = (value: T) => void

/**
 * Unsubscribe function type.
 */
export type Unsubscribe = () => void

/**
 * Simple observable for state.
 *
 * This provides an alternative to the event emitter pattern
 * for those who prefer a more functional approach.
 *
 * Usage:
 * ```typescript
 * const stateObservable = new Observable<AgentStateInfo>()
 *
 * const unsubscribe = stateObservable.subscribe((state) => {
 *   console.log('New state:', state)
 * })
 *
 * // Later...
 * unsubscribe()
 * ```
 */
export class Observable<T> {
	private observers: Set<Observer<T>> = new Set()
	private currentValue: T | undefined

	/**
	 * Create an observable with an optional initial value.
	 */
	constructor(initialValue?: T) {
		this.currentValue = initialValue
	}

	/**
	 * Subscribe to value changes.
	 *
	 * @param observer - Function called when value changes
	 * @returns Unsubscribe function
	 */
	subscribe(observer: Observer<T>): Unsubscribe {
		this.observers.add(observer)

		// Immediately emit current value if we have one
		if (this.currentValue !== undefined) {
			observer(this.currentValue)
		}

		return () => {
			this.observers.delete(observer)
		}
	}

	/**
	 * Update the value and notify all subscribers.
	 */
	next(value: T): void {
		this.currentValue = value
		for (const observer of this.observers) {
			try {
				observer(value)
			} catch (error) {
				console.error("Error in observer:", error)
			}
		}
	}

	/**
	 * Get the current value without subscribing.
	 */
	getValue(): T | undefined {
		return this.currentValue
	}

	/**
	 * Check if there are any subscribers.
	 */
	hasSubscribers(): boolean {
		return this.observers.size > 0
	}

	/**
	 * Get the number of subscribers.
	 */
	getSubscriberCount(): number {
		return this.observers.size
	}

	/**
	 * Remove all subscribers.
	 */
	clear(): void {
		this.observers.clear()
	}
}

/**
 * JsonEventEmitter - Handles structured JSON output for the CLI
 *
 * This class transforms internal CLI events (ClineMessage, state changes, etc.)
 * into structured JSON events and outputs them to stdout.
 *
 * Supports two output modes:
 * - "stream-json": NDJSON format (one JSON object per line) for real-time streaming
 * - "json": Single JSON object at the end with accumulated events
 *
 * Schema is optimized for efficiency with high message volume:
 * - Minimal fields per event
 * - No redundant wrappers
 * - `done` flag instead of partial:false
 */

import type { ClineMessage } from "@roo-code/types"

import type { JsonEvent, JsonEventCost, JsonEventQueueItem, JsonFinalOutput } from "@/types/json-events.js"

import type { ExtensionClient } from "./extension-client.js"
import type { AgentStateChangeEvent, TaskCompletedEvent } from "./events.js"
import { AgentLoopState } from "./agent-state.js"

/**
 * Options for JsonEventEmitter.
 */
export interface JsonEventEmitterOptions {
	/** Output mode: "json" or "stream-json" */
	mode: "json" | "stream-json"
	/** Output stream (defaults to process.stdout) */
	stdout?: NodeJS.WriteStream
	/** Optional request id provider for correlating stream events */
	requestIdProvider?: () => string | undefined
	/** Transport schema version emitted in system:init */
	schemaVersion?: number
	/** Transport protocol identifier emitted in system:init */
	protocol?: string
	/** Supported stdin protocol capabilities emitted in system:init */
	capabilities?: string[]
}

/**
 * Parse tool information from a ClineMessage text field.
 * Tool messages are JSON with a `tool` field containing the tool name.
 */
function parseToolInfo(text: string | undefined): { name: string; input: Record<string, unknown> } | null {
	if (!text) return null
	try {
		const parsed = JSON.parse(text)
		return parsed.tool ? { name: parsed.tool, input: parsed } : null
	} catch {
		return null
	}
}

/**
 * Parse API request cost information from api_req_started message text.
 */
function parseApiReqCost(text: string | undefined): JsonEventCost | undefined {
	if (!text) return undefined
	try {
		const parsed = JSON.parse(text)
		return parsed.cost !== undefined
			? {
					totalCost: parsed.cost,
					inputTokens: parsed.tokensIn,
					outputTokens: parsed.tokensOut,
					cacheWrites: parsed.cacheWrites,
					cacheReads: parsed.cacheReads,
				}
			: undefined
	} catch {
		return undefined
	}
}

/** Internal events that should not be emitted */
const SKIP_SAY_TYPES = new Set([
	"api_req_finished",
	"api_req_retried",
	"api_req_retry_delayed",
	"api_req_rate_limit_wait",
	"api_req_deleted",
	"checkpoint_saved",
	"condense_context",
	"condense_context_error",
	"sliding_window_truncation",
])

/** Key offset for reasoning content to avoid collision with text content delta tracking */
const REASONING_KEY_OFFSET = 1_000_000_000
/** Grace period to wait for final say:command_output after status:exited */
const COMMAND_OUTPUT_EXIT_GRACE_MS = 250

export class JsonEventEmitter {
	private mode: "json" | "stream-json"
	private stdout: NodeJS.WriteStream
	private events: JsonEvent[] = []
	private unsubscribers: (() => void)[] = []
	private pendingWrites = new Set<Promise<void>>()
	private lastCost: JsonEventCost | undefined
	private requestIdProvider: () => string | undefined
	private schemaVersion: number
	private protocol: string
	private capabilities: string[]
	private seenMessageIds = new Set<number>()
	// Track previous content for delta computation
	private previousContent = new Map<number, string>()
	// Track previous tool-use content for structured (non-append-only) delta computation.
	private previousToolUseContent = new Map<number, string>()
	// Track the currently active execute_command tool_use id for command_output correlation.
	private activeCommandToolUseId: number | undefined
	// Track command output snapshots by command tool-use id for delta computation.
	private previousCommandOutputByToolUseId = new Map<number, string>()
	// Track command ids whose output is being streamed from commandExecutionStatus updates.
	private statusDrivenCommandOutputIds = new Set<number>()
	// Track command ids that already emitted a terminal command_output done event.
	private completedCommandOutputIds = new Set<number>()
	// Track exited commands awaiting final say:command_output completion.
	private pendingCommandCompletionByToolUseId = new Map<number, { exitCode?: number; timer: NodeJS.Timeout }>()
	// Track the completion result content
	private completionResultContent: string | undefined
	// Track the latest assistant text as a fallback for result.content.
	private lastAssistantText: string | undefined
	// The first non-partial "say:text" per task is the echoed user prompt.
	private expectPromptEchoAsUser = true

	constructor(options: JsonEventEmitterOptions) {
		this.mode = options.mode
		this.stdout = options.stdout ?? process.stdout
		this.requestIdProvider = options.requestIdProvider ?? (() => undefined)
		this.schemaVersion = options.schemaVersion ?? 1
		this.protocol = options.protocol ?? "roo-cli-stream"
		this.capabilities = options.capabilities ?? [
			"stdin:start",
			"stdin:message",
			"stdin:cancel",
			"stdin:ping",
			"stdin:shutdown",
		]
	}

	/**
	 * Attach to an ExtensionClient and subscribe to its events.
	 */
	attachToClient(client: ExtensionClient): void {
		// Subscribe to message events
		const unsubMessage = client.on("message", (msg) => this.handleMessage(msg, false))
		const unsubMessageUpdated = client.on("messageUpdated", (msg) => this.handleMessage(msg, true))
		const unsubStateChange = client.on("stateChange", (event) => this.handleStateChange(event))
		const unsubTaskCompleted = client.on("taskCompleted", (event) => this.handleTaskCompleted(event))
		const unsubError = client.on("error", (error) => this.handleError(error))

		this.unsubscribers.push(unsubMessage, unsubMessageUpdated, unsubStateChange, unsubTaskCompleted, unsubError)

		// Emit init event
		this.emitEvent({
			type: "system",
			subtype: "init",
			content: "Task started",
			schemaVersion: this.schemaVersion,
			protocol: this.protocol,
			capabilities: this.capabilities,
		})
	}

	emitControl(event: {
		subtype: "ack" | "done" | "error"
		requestId?: string
		command?: JsonEvent["command"]
		taskId?: string
		content?: string
		success?: boolean
		code?: string
	}): void {
		this.emitEvent({
			type: "control",
			subtype: event.subtype,
			requestId: event.requestId,
			command: event.command,
			taskId: event.taskId,
			content: event.content,
			success: event.success,
			code: event.code,
			done: event.subtype === "done" ? true : undefined,
		})
	}

	emitQueue(event: {
		subtype: "snapshot" | "enqueued" | "dequeued" | "drained" | "updated"
		taskId?: string
		content?: string
		queueDepth: number
		queue: JsonEventQueueItem[]
	}): void {
		this.emitEvent({
			type: "queue",
			subtype: event.subtype,
			taskId: event.taskId,
			content: event.content,
			queueDepth: event.queueDepth,
			queue: event.queue,
		})
	}

	private handleStateChange(event: AgentStateChangeEvent): void {
		// Only treat the next say:text as a prompt echo when a new task starts.
		if (
			event.previousState.state === AgentLoopState.NO_TASK &&
			event.currentState.state !== AgentLoopState.NO_TASK
		) {
			this.expectPromptEchoAsUser = true
		}
	}

	/**
	 * Detach from the client and clean up subscriptions.
	 */
	detach(): void {
		for (const unsub of this.unsubscribers) {
			unsub()
		}
		this.unsubscribers = []
	}

	/**
	 * Compute the delta (new content) for a streaming message.
	 * Returns null if there's no new content.
	 */
	private computeDelta(msgId: number, fullContent: string | undefined): string | null {
		if (!fullContent) return null

		const previous = this.previousContent.get(msgId) || ""
		if (fullContent === previous) return null

		this.previousContent.set(msgId, fullContent)
		// If content is appended, return only the new part
		return fullContent.startsWith(previous) ? fullContent.slice(previous.length) : fullContent
	}

	/**
	 * Compute a compact delta for structured strings (for tool_use snapshots).
	 *
	 * Unlike append-only text streams, tool-use payloads are often full snapshots
	 * where edits happen before a stable suffix (e.g., inside JSON strings). This
	 * extracts the inserted segment when possible; otherwise it falls back to the
	 * full snapshot so consumers can recover.
	 */
	private computeStructuredDelta(msgId: number, fullContent: string | undefined): string | null {
		if (!fullContent) {
			return null
		}

		const previous = this.previousToolUseContent.get(msgId) || ""

		if (fullContent === previous) {
			return null
		}

		this.previousToolUseContent.set(msgId, fullContent)

		if (previous.length === 0) {
			return fullContent
		}

		if (fullContent.startsWith(previous)) {
			return fullContent.slice(previous.length)
		}

		let prefix = 0

		while (prefix < previous.length && prefix < fullContent.length && previous[prefix] === fullContent[prefix]) {
			prefix++
		}

		let suffix = 0

		while (
			suffix < previous.length - prefix &&
			suffix < fullContent.length - prefix &&
			previous[previous.length - 1 - suffix] === fullContent[fullContent.length - 1 - suffix]
		) {
			suffix++
		}

		const isPureInsertion = fullContent.length >= previous.length && prefix + suffix >= previous.length

		if (isPureInsertion) {
			return fullContent.slice(prefix, fullContent.length - suffix)
		}

		return fullContent
	}

	/**
	 * Check if this is a streaming partial message with no new content.
	 */
	private isEmptyStreamingDelta(content: string | null): boolean {
		return this.mode === "stream-json" && content === null
	}

	private computeCommandOutputDelta(commandId: number, fullOutput: string | undefined): string | null {
		const normalized = fullOutput ?? ""
		const previous = this.previousCommandOutputByToolUseId.get(commandId) || ""

		if (normalized === previous) {
			return null
		}

		this.previousCommandOutputByToolUseId.set(commandId, normalized)
		return normalized.startsWith(previous) ? normalized.slice(previous.length) : normalized
	}

	private emitCommandOutputEvent(
		commandId: number,
		fullOutput: string | undefined,
		isDone: boolean,
		exitCode?: number,
	): void {
		if (this.mode === "stream-json") {
			const outputDelta = this.computeCommandOutputDelta(commandId, fullOutput)
			const event: JsonEvent = {
				type: "tool_result",
				id: commandId,
				subtype: "command",
				tool_result: { name: "execute_command" },
			}

			if (outputDelta !== null && outputDelta.length > 0) {
				event.tool_result = { name: "execute_command", output: outputDelta }
			}

			if (isDone && exitCode !== undefined) {
				event.tool_result = {
					...(event.tool_result ?? { name: "execute_command" }),
					exitCode,
				}
			}

			if (isDone) {
				event.done = true
				this.clearPendingCommandCompletion(commandId)
				this.previousCommandOutputByToolUseId.delete(commandId)
				this.statusDrivenCommandOutputIds.delete(commandId)
				this.completedCommandOutputIds.add(commandId)
				if (this.activeCommandToolUseId === commandId) {
					this.activeCommandToolUseId = undefined
				}
			}

			// Suppress empty partial updates that carry no delta.
			if (!isDone && outputDelta === null) {
				return
			}

			this.emitEvent(event)
			return
		}

		this.emitEvent({
			type: "tool_result",
			id: commandId,
			subtype: "command",
			tool_result: {
				name: "execute_command",
				output: fullOutput,
				...(isDone && exitCode !== undefined ? { exitCode } : {}),
			},
			...(isDone ? { done: true } : {}),
		})

		if (isDone) {
			this.clearPendingCommandCompletion(commandId)
			this.previousCommandOutputByToolUseId.delete(commandId)
			this.statusDrivenCommandOutputIds.delete(commandId)
			this.completedCommandOutputIds.add(commandId)
			if (this.activeCommandToolUseId === commandId) {
				this.activeCommandToolUseId = undefined
			}
		}
	}

	public emitCommandOutputChunk(outputSnapshot: string): void {
		const commandId = this.activeCommandToolUseId
		if (commandId === undefined) {
			return
		}

		this.statusDrivenCommandOutputIds.add(commandId)
		this.emitCommandOutputEvent(commandId, outputSnapshot, false)
	}

	public markCommandOutputExited(exitCode?: number): void {
		const commandId = this.activeCommandToolUseId
		if (commandId === undefined) {
			return
		}

		this.statusDrivenCommandOutputIds.add(commandId)
		this.clearPendingCommandCompletion(commandId)

		const timer = setTimeout(() => {
			// Fallback close if final say:command_output never arrives.
			if (!this.pendingCommandCompletionByToolUseId.has(commandId)) {
				return
			}
			this.pendingCommandCompletionByToolUseId.delete(commandId)
			this.emitCommandOutputEvent(commandId, undefined, true, exitCode)
		}, COMMAND_OUTPUT_EXIT_GRACE_MS)
		timer.unref?.()

		this.pendingCommandCompletionByToolUseId.set(commandId, { exitCode, timer })
	}

	public emitCommandOutputDone(exitCode?: number): void {
		const commandId = this.activeCommandToolUseId
		if (commandId === undefined) {
			return
		}

		this.statusDrivenCommandOutputIds.add(commandId)
		this.emitCommandOutputEvent(commandId, undefined, true, exitCode)
	}

	private clearPendingCommandCompletion(commandId: number): void {
		const pending = this.pendingCommandCompletionByToolUseId.get(commandId)
		if (!pending) {
			return
		}
		clearTimeout(pending.timer)
		this.pendingCommandCompletionByToolUseId.delete(commandId)
	}

	/**
	 * Get content to send for a message (delta for streaming, full for json mode).
	 */
	private getContentToSend(msgId: number, text: string | undefined, isPartial: boolean): string | null {
		if (this.mode === "stream-json" && isPartial) {
			return this.computeDelta(msgId, text)
		}

		return text ?? null
	}

	/**
	 * Build a base event with optional done flag.
	 */
	private buildTextEvent(
		type: "assistant" | "thinking" | "user",
		id: number,
		content: string | null,
		isDone: boolean,
		subtype?: string,
	): JsonEvent {
		const event: JsonEvent = { type, id }

		if (content !== null) {
			event.content = content
		}

		if (subtype) {
			event.subtype = subtype
		}

		if (isDone) {
			event.done = true
		}

		return event
	}

	/**
	 * Handle a ClineMessage and emit the appropriate JSON event.
	 */
	private handleMessage(msg: ClineMessage, _isUpdate: boolean): void {
		const isDone = !msg.partial

		// In json mode, only emit complete (non-partial) messages
		if (this.mode === "json" && msg.partial) {
			return
		}

		// Skip duplicate complete messages
		if (isDone && this.seenMessageIds.has(msg.ts)) {
			return
		}

		if (isDone) {
			this.seenMessageIds.add(msg.ts)
			this.previousContent.delete(msg.ts)
			this.previousToolUseContent.delete(msg.ts)
		}

		if (msg.type === "say" && msg.say) {
			const contentToSend = this.getContentToSend(msg.ts, msg.text, msg.partial ?? false)

			// Skip if no new content for streaming partial messages
			if (msg.partial && this.isEmptyStreamingDelta(contentToSend)) {
				return
			}

			this.handleSayMessage(msg, contentToSend, isDone)
		}

		if (msg.type === "ask" && msg.ask) {
			this.handleAskMessage(msg, isDone)
		}
	}

	/**
	 * Handle "say" type messages.
	 */
	private handleSayMessage(msg: ClineMessage, contentToSend: string | null, isDone: boolean): void {
		switch (msg.say) {
			case "text":
				if (this.expectPromptEchoAsUser) {
					this.emitEvent(this.buildTextEvent("user", msg.ts, contentToSend, isDone))
					if (isDone) {
						this.expectPromptEchoAsUser = false
					}
				} else {
					this.emitEvent(this.buildTextEvent("assistant", msg.ts, contentToSend, isDone))
					if (msg.text) {
						this.lastAssistantText = msg.text
					}
				}
				break

			case "reasoning":
				this.handleReasoningMessage(msg, isDone)
				break

			case "error":
				this.emitEvent({ type: "error", id: msg.ts, content: contentToSend ?? undefined })
				break

			case "command_output":
				this.handleCommandOutputMessage(msg, isDone)
				break

			case "user_feedback":
			case "user_feedback_diff":
				this.emitEvent(this.buildTextEvent("user", msg.ts, contentToSend, isDone))
				if (isDone) {
					this.expectPromptEchoAsUser = false
				}
				break

			case "api_req_started": {
				const cost = parseApiReqCost(msg.text)
				if (cost) {
					this.lastCost = cost
				}
				break
			}

			case "mcp_server_response":
				this.emitEvent({
					type: "tool_result",
					subtype: "mcp",
					tool_result: { name: "mcp_server", output: msg.text },
				})
				break

			case "completion_result":
				if (msg.text && !msg.partial) {
					this.completionResultContent = msg.text
				}
				break

			default:
				if (SKIP_SAY_TYPES.has(msg.say!)) {
					break
				}
				if (msg.text) {
					this.emitEvent(this.buildTextEvent("assistant", msg.ts, contentToSend, isDone, msg.say))
				}
				break
		}
	}

	/**
	 * Handle reasoning/thinking messages with separate delta tracking.
	 */
	private handleReasoningMessage(msg: ClineMessage, isDone: boolean): void {
		const reasoningContent = msg.reasoning || msg.text
		const reasoningKey = msg.ts + REASONING_KEY_OFFSET
		const reasoningDelta = this.getContentToSend(reasoningKey, reasoningContent, msg.partial ?? false)

		if (msg.partial && this.isEmptyStreamingDelta(reasoningDelta)) {
			return
		}

		if (!msg.partial) {
			this.previousContent.delete(reasoningKey)
		}

		this.emitEvent(this.buildTextEvent("thinking", msg.ts, reasoningDelta, isDone))
	}

	/**
	 * Handle "ask" type messages.
	 */
	private handleAskMessage(msg: ClineMessage, isDone: boolean): void {
		switch (msg.ask) {
			case "tool":
				this.handleToolUseAsk(msg, "tool", isDone)
				break

			case "command":
				this.handleToolUseAsk(msg, "command", isDone)
				break

			case "use_mcp_server":
				this.handleToolUseAsk(msg, "mcp", isDone)
				break

			case "followup": {
				const contentToSend = this.getContentToSend(msg.ts, msg.text, msg.partial ?? false)

				// Skip if no new content for streaming partial messages
				if (msg.partial && this.isEmptyStreamingDelta(contentToSend)) {
					return
				}

				this.emitEvent(this.buildTextEvent("assistant", msg.ts, contentToSend, isDone, "followup"))
				break
			}

			case "command_output":
				// Handled in say type
				break

			case "completion_result":
				if (msg.text && !msg.partial) {
					this.completionResultContent = msg.text
				}
				break

			default:
				if (msg.text) {
					const contentToSend = this.getContentToSend(msg.ts, msg.text, msg.partial ?? false)

					// Skip if no new content for streaming partial messages
					if (msg.partial && this.isEmptyStreamingDelta(contentToSend)) {
						return
					}

					this.emitEvent(this.buildTextEvent("assistant", msg.ts, contentToSend, isDone, msg.ask))
				}
				break
		}
	}

	private handleToolUseAsk(msg: ClineMessage, subtype: "tool" | "command" | "mcp", isDone: boolean): void {
		const isStreamingPartial = this.mode === "stream-json" && msg.partial === true
		const toolInfo = parseToolInfo(msg.text)

		if (subtype === "command") {
			if (this.activeCommandToolUseId !== undefined && this.activeCommandToolUseId !== msg.ts) {
				const previousCommandId = this.activeCommandToolUseId
				const pending = this.pendingCommandCompletionByToolUseId.get(previousCommandId)
				if (pending) {
					clearTimeout(pending.timer)
					this.pendingCommandCompletionByToolUseId.delete(previousCommandId)
					this.emitCommandOutputEvent(previousCommandId, undefined, true, pending.exitCode)
				}
			}

			this.activeCommandToolUseId = msg.ts
			this.completedCommandOutputIds.delete(msg.ts)
			this.clearPendingCommandCompletion(msg.ts)

			if (isStreamingPartial) {
				const commandDelta = this.computeStructuredDelta(msg.ts, msg.text)
				if (commandDelta === null) {
					return
				}

				this.emitEvent({
					type: "tool_use",
					id: msg.ts,
					subtype: "command",
					content: commandDelta,
					tool_use: { name: "execute_command", input: { command: commandDelta } },
				})
				return
			}

			this.emitEvent({
				type: "tool_use",
				id: msg.ts,
				subtype: "command",
				tool_use: { name: "execute_command", input: { command: msg.text } },
				...(isDone ? { done: true } : {}),
			})
			return
		}

		if (subtype === "mcp") {
			if (isStreamingPartial) {
				const mcpDelta = this.computeStructuredDelta(msg.ts, msg.text)
				if (mcpDelta === null) {
					return
				}

				this.emitEvent({
					type: "tool_use",
					id: msg.ts,
					subtype: "mcp",
					content: mcpDelta,
					tool_use: { name: "mcp_server" },
				})
				return
			}

			this.emitEvent({
				type: "tool_use",
				id: msg.ts,
				subtype: "mcp",
				tool_use: { name: "mcp_server", input: { raw: msg.text } },
				...(isDone ? { done: true } : {}),
			})
			return
		}

		if (isStreamingPartial) {
			const toolDelta = this.computeStructuredDelta(msg.ts, msg.text)
			if (toolDelta === null) {
				return
			}

			this.emitEvent({
				type: "tool_use",
				id: msg.ts,
				subtype: "tool",
				content: toolDelta,
				tool_use: { name: toolInfo?.name ?? "unknown_tool" },
			})
			return
		}

		this.emitEvent({
			type: "tool_use",
			id: msg.ts,
			subtype: "tool",
			tool_use: toolInfo ?? { name: "unknown_tool", input: { raw: msg.text } },
			...(isDone ? { done: true } : {}),
		})
	}

	private handleCommandOutputMessage(msg: ClineMessage, isDone: boolean): void {
		const commandId = this.activeCommandToolUseId ?? msg.ts
		if (this.completedCommandOutputIds.has(commandId)) {
			return
		}

		const pending = this.pendingCommandCompletionByToolUseId.get(commandId)
		if (pending) {
			if (!isDone) {
				return
			}
			clearTimeout(pending.timer)
			this.pendingCommandCompletionByToolUseId.delete(commandId)
			this.emitCommandOutputEvent(commandId, msg.text, true, pending.exitCode)
			return
		}

		if (this.statusDrivenCommandOutputIds.has(commandId)) {
			return
		}

		this.emitCommandOutputEvent(commandId, msg.text, isDone)
	}

	/**
	 * Handle task completion and emit result event.
	 */
	private handleTaskCompleted(event: TaskCompletedEvent): void {
		// Prefer the completion payload from the current event. If it is empty,
		// fall back to the most recent tracked completion text, then assistant text.
		const resultContent = event.message?.text || this.completionResultContent || this.lastAssistantText

		this.emitEvent({
			type: "result",
			id: event.message?.ts ?? Date.now(),
			content: resultContent,
			done: true,
			success: event.success,
			cost: this.lastCost,
		})

		// Prevent stale completion content from leaking into later turns.
		this.completionResultContent = undefined
		this.lastAssistantText = undefined

		// For "json" mode, output the final accumulated result
		if (this.mode === "json") {
			this.outputFinalResult(event.success, resultContent)
		}
	}

	/**
	 * Handle errors and emit error event.
	 */
	private handleError(error: Error): void {
		this.emitEvent({
			type: "error",
			id: Date.now(),
			content: error.message,
		})
	}

	/**
	 * Emit a JSON event.
	 * For stream-json mode: immediately output to stdout
	 * For json mode: accumulate for final output
	 */
	private emitEvent(event: JsonEvent): void {
		const requestId = event.requestId ?? this.requestIdProvider()
		const payload = requestId ? { ...event, requestId } : event

		this.events.push(payload)

		if (this.mode === "stream-json") {
			this.outputLine(payload)
		}
	}

	/**
	 * Output a single JSON line (NDJSON format).
	 */
	private outputLine(data: unknown): void {
		this.writeToStdout(JSON.stringify(data) + "\n")
	}

	/**
	 * Output the final accumulated result (for "json" mode).
	 */
	private outputFinalResult(success: boolean, content?: string): void {
		const output: JsonFinalOutput = {
			type: "result",
			success,
			content,
			cost: this.lastCost,
			events: this.events.filter((e) => e.type !== "result"), // Exclude the result event itself
		}

		this.writeToStdout(JSON.stringify(output, null, 2) + "\n")
	}

	private writeToStdout(content: string): void {
		const writePromise = new Promise<void>((resolve, reject) => {
			this.stdout.write(content, (error?: Error | null) => {
				if (error) {
					reject(error)
					return
				}
				resolve()
			})
		})

		this.pendingWrites.add(writePromise)

		void writePromise.finally(() => {
			this.pendingWrites.delete(writePromise)
		})
	}

	async flush(): Promise<void> {
		while (this.pendingWrites.size > 0) {
			await Promise.all([...this.pendingWrites])
		}
	}

	/**
	 * Get accumulated events (for testing or external use).
	 */
	getEvents(): JsonEvent[] {
		return [...this.events]
	}

	/**
	 * Clear accumulated events and state.
	 */
	clear(): void {
		this.events = []
		this.lastCost = undefined
		this.seenMessageIds.clear()
		this.previousContent.clear()
		this.previousToolUseContent.clear()
		this.activeCommandToolUseId = undefined
		this.previousCommandOutputByToolUseId.clear()
		this.statusDrivenCommandOutputIds.clear()
		this.completedCommandOutputIds.clear()
		for (const pending of this.pendingCommandCompletionByToolUseId.values()) {
			clearTimeout(pending.timer)
		}
		this.pendingCommandCompletionByToolUseId.clear()
		this.completionResultContent = undefined
		this.lastAssistantText = undefined
		this.expectPromptEchoAsUser = true
	}
}

import * as path from "path"
import * as os from "os"
import * as fs from "fs/promises"

import { runTests } from "@vscode/test-electron"

async function main() {
	try {
		// The folder containing the Extension Manifest package.json
		// Passed to `--extensionDevelopmentPath`
		const extensionDevelopmentPath = path.resolve(__dirname, "../../../src")

		// The path to the extension test script
		// Passed to --extensionTestsPath
		const extensionTestsPath = path.resolve(__dirname, "./suite/index")

		// Create a temporary workspace folder for tests
		const testWorkspace = await fs.mkdtemp(path.join(os.tmpdir(), "roo-test-workspace-"))

		// Get test filter from command line arguments or environment variable
		// Usage examples:
		// - npm run test:e2e -- --grep "write-to-file"
		// - TEST_GREP="apply-diff" npm run test:e2e
		// - TEST_FILE="task.test.js" npm run test:e2e
		const testGrep = process.argv.find((arg, i) => process.argv[i - 1] === "--grep") || process.env.TEST_GREP
		const testFile = process.argv.find((arg, i) => process.argv[i - 1] === "--file") || process.env.TEST_FILE

		// Pass test filters as environment variables to the test runner
		const extensionTestsEnv = {
			...process.env,
			...(testGrep && { TEST_GREP: testGrep }),
			...(testFile && { TEST_FILE: testFile }),
		}

		// Download VS Code, unzip it and run the integration test
		await runTests({
			extensionDevelopmentPath,
			extensionTestsPath,
			launchArgs: [testWorkspace],
			extensionTestsEnv,
			version: process.env.VSCODE_VERSION || "1.101.2",
		})

		// Clean up the temporary workspace
		await fs.rm(testWorkspace, { recursive: true, force: true })
	} catch (error) {
		console.error("Failed to run tests", error)
		process.exit(1)
	}
}

main()

import { CANVAS_UI_CLIENT_TOOL_NAME } from "#/constants/canvas-ui";

export {
  CANVAS_UI_CLIENT_ACTION_KIND,
  CANVAS_UI_CLIENT_TOOL_NAME,
  LEGACY_CANVAS_UI_TOOL_NAME,
} from "#/constants/canvas-ui";

export interface ClientToolSpec {
  name: string;
  description: string;
  parameters: Record<string, unknown>;
  annotations?: {
    title?: string | null;
    readOnlyHint: boolean;
    destructiveHint: boolean;
    idempotentHint: boolean;
    openWorldHint: boolean;
  };
}

const CANVAS_UI_DESCRIPTION = `The user is interacting with you inside Agent Canvas — a web UI with a chat panel on the left and a tabbed right-side panel (files, terminal, browser, vscode, planner, tasklist). This tool lets you drive that right-side panel so the user sees what you just produced.

They will NOT see the files you wrote, the terminal output, or the browser
unless you call this tool to switch the right-side panel to the relevant
tab. Call this every time you finish work that produces something the user
should look at — don't rely on them noticing on their own.

When to call (pick the most specific option that matches your last action):

* You wrote or modified a single file (ANY language, ANY size — including
  small scripts like a hello-world bash file) →
    command="navigate_to_file", path=<workspace-relative path of that file>

* You generated an HTML page, image, SVG, PDF, markdown report, or other
  previewable artifact →
    command="show_preview", path=<that file>

* You finished editing multiple files in one logical step →
    command="open_tab", tab="files"
    (The Files tab automatically renders a diff view when the workspace has
    uncommitted git changes, which covers the "highlight changes" case.)

* You ran a long-running terminal command, or one whose output the user
  should inspect →
    command="open_tab", tab="terminal"

* You browsed to a URL the user should see →
    First call browser_get_state(include_screenshot=true) after your final
    browser interaction so Agent Canvas has a screenshot to display, then call
    command="open_tab", tab="browser"
    (browser_navigate alone only updates the URL; without browser_get_state,
    the Browser tab will open without a screenshot.)

Call this BEFORE writing your chat-message summary of the change, so the
artifact is visible while the user reads what you did. One canvas_ui_control
call per logical step is enough — don't repeat it for the same file or tab in
the same turn.`;

export const CANVAS_UI_CLIENT_TOOL: ClientToolSpec = {
  name: CANVAS_UI_CLIENT_TOOL_NAME,
  description: CANVAS_UI_DESCRIPTION,
  parameters: {
    type: "object",
    additionalProperties: false,
    properties: {
      command: {
        type: "string",
        enum: ["navigate_to_file", "open_tab", "show_preview"],
        description: "UI command to dispatch.",
      },
      path: {
        type: "string",
        description:
          "Workspace-relative file path. Required for navigate_to_file and show_preview; ignored otherwise.",
      },
      tab: {
        type: "string",
        enum: ["files", "browser", "vscode", "terminal", "planner", "tasklist"],
        description: "Tab to open. Required for open_tab; ignored otherwise.",
      },
    },
    required: ["command"],
  },
  annotations: {
    readOnlyHint: true,
    destructiveHint: false,
    idempotentHint: true,
    openWorldHint: false,
  },
};

import {
  CHILD_CONVERSATION_ISOLATIONS,
  CHILD_CONVERSATION_RESULT_PREFIX,
  CHILD_CONVERSATION_TARGETS,
  LAUNCH_CHILD_CONVERSATION_TOOL_NAME,
} from "#/constants/child-conversation";
import type { ClientToolSpec } from "./canvas-ui-client-tool";

export {
  LAUNCH_CHILD_CONVERSATION_ACTION_KIND,
  LAUNCH_CHILD_CONVERSATION_TOOL_NAME,
} from "#/constants/child-conversation";

const LAUNCH_CHILD_CONVERSATION_DESCRIPTION = `Start a NEW, independent conversation to work on a well-scoped task in parallel with this one, without the user having to run any CLI command. The new conversation is recorded as a child of this one.

The child runs on its own. It does not block you, you do not see its output,
and it cannot see this conversation's history — everything it needs must be in
the task brief.

Choosing target:

* target="local" — runs on the same machine, in this conversation's workspace.
  Fast, no repository clone, no sandbox provisioning. Use this by default when
  the work is on code that is already checked out here.

* target="cloud" — runs on OpenHands Cloud in its own isolated sandbox, from a
  git repository. Use this when the work should not touch the user's machine or
  when it needs a repository that is not checked out locally. Requires the user
  to have an OpenHands Cloud backend connected in Agent Canvas; if none is
  connected you will be told so and should fall back to target="local".

Writing the task brief:

* Put everything the child needs in "task": the goal, the relevant file paths,
  the constraints, the expected deliverable, and how it should report back.
* Keep each child's scope independent of its siblings so parallel children do
  not fight over the same files.
* One call per delegated task. Do NOT call this tool twice for the same task.

Parameter rules (a call that breaks one of these launches nothing and comes
back with corrective guidance):

* "repository" and "branch" apply to target="cloud" only. A local child always
  inherits this conversation's workspace, so do not pass them with
  target="local".
* "isolation" applies to target="local" only. Cloud sandboxes are always
  isolated, so do not pass it with target="cloud".
* isolation="worktree" (the default) gives the child its own git worktree and
  branch, cut from the repository's default branch — it will NOT see this
  conversation's uncommitted or committed work. isolation="shared" puts the
  child in this conversation's exact directory; only choose it when the child
  genuinely must see work in progress, and expect the two agents to conflict.

What comes back: this tool is acknowledged immediately, before the conversation
exists. The real outcome arrives moments later as a follow-up message starting
with "${CHILD_CONVERSATION_RESULT_PREFIX.trim()}" that carries the child's
conversation id, URL, target and initial status — or an error with guidance.
Wait for it, then tell the user what you launched and give them the URL. If it
reports an error, fix the parameters and call this tool again.`;

export const LAUNCH_CHILD_CONVERSATION_CLIENT_TOOL: ClientToolSpec = {
  name: LAUNCH_CHILD_CONVERSATION_TOOL_NAME,
  description: LAUNCH_CHILD_CONVERSATION_DESCRIPTION,
  parameters: {
    type: "object",
    additionalProperties: false,
    properties: {
      target: {
        type: "string",
        enum: [...CHILD_CONVERSATION_TARGETS],
        description:
          "Where the child runs. 'local' reuses this machine and this conversation's workspace; 'cloud' runs in an isolated OpenHands Cloud sandbox.",
      },
      task: {
        type: "string",
        description:
          "Self-contained task brief, sent as the child's first message. The child cannot see this conversation, so state the goal, constraints, expected output and handoff criteria.",
      },
      title: {
        type: "string",
        description:
          "Optional short title for the child conversation. Omit to let it title itself from the task.",
      },
      repository: {
        type: "string",
        description:
          "target='cloud' only. Repository to clone into the sandbox, as 'owner/repo'. Defaults to this conversation's repository when it has one.",
      },
      branch: {
        type: "string",
        description:
          "target='cloud' only, and only together with 'repository'. Defaults to the repository's default branch.",
      },
      isolation: {
        type: "string",
        enum: [...CHILD_CONVERSATION_ISOLATIONS],
        description:
          "target='local' only. 'worktree' (default) gives the child its own git worktree and branch; 'shared' runs it in this conversation's exact directory.",
      },
    },
    required: ["target", "task"],
  },
  annotations: {
    // Launching a conversation writes real state and is not repeatable, so the
    // agent is asked to predict a security risk before every call.
    readOnlyHint: false,
    destructiveHint: false,
    idempotentHint: false,
    // The cloud target reaches OpenHands Cloud.
    openWorldHint: true,
  },
};

import { useQuery } from "@tanstack/react-query";
import { getCloudOrganizationMe } from "#/api/cloud/organization-service.api";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useCloudCurrentUserId } from "./query/use-cloud-current-user-id";
import type { Automation } from "#/types/automation";

/**
 * Server-defined permission strings (mirror the automation service's
 * `view_automations` / `manage_automations` and the enterprise
 * `authorization.Permission` enum). The `/me` endpoint returns whichever
 * subset the caller's role grants.
 */
export const VIEW_AUTOMATIONS = "view_automations";
export const MANAGE_AUTOMATIONS = "manage_automations";

export interface AutomationPermissionsResult {
  /** Read-only access (list, get, list runs, capabilities, git-sync status). */
  canView: boolean;
  /** Full write access (update, delete, dispatch, git-sync config). */
  canManage: boolean;
  /**
   * `true` when permissions are still being resolved on cloud. Local always
   * resolves synchronously. Mutating controls should stay hidden while this is
   * `true` so a member never sees a flash of write controls before the
   * server-defined permission set arrives.
   */
  isLoading: boolean;
}

/**
 * Resolve the caller's automation-level permissions on the active backend.
 *
 * - Local agent-server (OSS): always `{ canView: true, canManage: true }`.
 * - Cloud: reads the server-defined `permissions` array from
 *   `GET /api/organizations/{orgId}/me` (same query `useCloudCurrentUserId`
 *   and `useCanManageOrgProfiles` use, so no extra request is issued) and
 *   falls back to a role check (`owner`/`admin` ⇒ both, `member` ⇒ view
 *   only) when an older app-server doesn't return `permissions`.
 */
export function useAutomationPermissions(): AutomationPermissionsResult {
  const { backend, orgId } = useActiveBackend();
  const isCloud = backend.kind === "cloud";

  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  const { data, isLoading } = useQuery({
    queryKey: [
      "cloud-current-user",
      backend.id,
      orgId,
      backend.connectionRevision ?? 0,
    ],
    queryFn: () => getCloudOrganizationMe(orgId!, backend),
    enabled: isCloud && !!orgId,
    staleTime: 1000 * 60 * 5,
    retry: false,
    meta: { disableToast: true },
  });

  if (!isCloud) {
    return { canView: true, canManage: true, isLoading: false };
  }

  if (isLoading || !data) {
    return { canView: false, canManage: false, isLoading };
  }

  if (data.permissions) {
    const canView = data.permissions.includes(VIEW_AUTOMATIONS);
    const canManage = data.permissions.includes(MANAGE_AUTOMATIONS);
    return { canView, canManage, isLoading: false };
  }

  // Fall back to role check for older app-servers without `permissions`.
  const isOwnerOrAdmin = data.role === "owner" || data.role === "admin";
  return {
    canView: isOwnerOrAdmin || data.role === "member",
    canManage: isOwnerOrAdmin,
    isLoading: false,
  };
}

/**
 * Resolve whether the current user is the creator of the given automation.
 *
 * - Local: always `true` (the local user owns every automation; and since
 *   local always has `manage_automations`, the distinction is moot).
 * - Cloud: compares `automation.user_id` with the caller's `user_id` from
 *   `GET /api/organizations/{orgId}/me`. Returns `false` while the id is
 *   still loading so the creator escape hatch never flashes open prematurely.
 */
export function useIsAutomationOwner(automation: Automation): boolean {
  const { backend } = useActiveBackend();
  // Always call the hook so rules-of-hooks is satisfied; it's a no-op for
  // local backends since the early return below short-circuits before use.
  const userIds = useCloudCurrentUserId();

  if (backend.kind !== "cloud") return true;

  const entry = userIds[backend.id];
  if (!entry || entry.isLoading || !entry.userId) return false;
  return automation.user_id === entry.userId;
}

