import { Divider } from "#/ui/divider";
import { cn } from "#/utils/utils";
import { chatInputIconButtonClassName } from "#/utils/form-control-classes";
import {
  formatCompactTokenCount,
  getContextWindowUsagePercentage,
} from "#/utils/format-token-count";
import { getContextFillTone } from "#/components/features/conversation/usage-panel/context-meter";
import {
  ContextWindowRing,
  CONTEXT_WINDOW_TRACK_COLOR,
} from "./context-window-ring";

const TONE_BAR_CLASS = {
  neutral: "bg-foreground",
  warning: "bg-amber-500",
  danger: "bg-red-500",
} as const;

const TONE_LABEL_CLASS = {
  neutral: "text-muted",
  warning: "text-amber-500",
  danger: "text-red-500",
} as const;

export function ContextWindowMeter() {
  const { t } = useTranslation("openhands");
  const usage = useContextWindowUsage();
  const { navigateToTab } = useSelectConversationTab();
  const [isPopoverOpen, setIsPopoverOpen] = React.useState(false);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const popoverRef = useClickOutsideElement<HTMLDivElement>(
    () => setIsPopoverOpen(false),
    triggerRef,
  );
  const { handleCompact, isCompacting, isDisabled } = useCompactContextAction(
    usage?.perTurnToken ?? 0,
  );

  if (!usage) {
    return null;
  }

  const usagePercentage = getContextWindowUsagePercentage(
    usage.perTurnToken,
    usage.contextWindow,
  );
  const roundedPercentage = Math.round(usagePercentage);
  const remainingPercentage = Math.max(0, 100 - roundedPercentage);
  const usagePercentLabel = `${roundedPercentage}% ${t(I18nKey.CONVERSATION$USED)} (${remainingPercentage}% ${t(I18nKey.CONVERSATION$LEFT)})`;
  const usageTokenSummary = `${formatCompactTokenCount(usage.perTurnToken)} / ${formatCompactTokenCount(usage.contextWindow)}`;
  const tone = getContextFillTone(usagePercentage);

  const openUsagePanel = () => {
    setIsPopoverOpen(false);
    navigateToTab("usage");
  };

  return (
    <div className="relative shrink-0">
      <StyledTooltip
        content={t(I18nKey.CHAT_INTERFACE$SHOW_CONTEXT)}
        placement="top"
      >
        <button
          ref={triggerRef}
          type="button"
          className={cn(chatInputIconButtonClassName, "size-8")}
          aria-label={`${t(I18nKey.CHAT_INTERFACE$CONTEXT_WINDOW_METER_LABEL)}: ${usagePercentLabel}`}
          aria-expanded={isPopoverOpen}
          aria-haspopup="dialog"
          data-testid="context-window-meter"
          onClick={(event) => {
            event.preventDefault();
            event.stopPropagation();
            setIsPopoverOpen((open) => !open);
          }}
        >
          <ContextWindowRing percentage={usagePercentage} />
        </button>
      </StyledTooltip>

      {isPopoverOpen && (
        <div
          ref={popoverRef}
          data-testid="context-window-meter-popover"
          className={cn(
            "absolute bottom-full right-0 z-[60] mb-2 w-70",
            "flex flex-col gap-0.5 rounded-md border border-border-subtle bg-tertiary px-1 py-1 shadow-lg",
          )}
        >
          <div className="flex flex-col gap-2 px-2 py-1.5">
            <div className="flex items-center justify-between gap-2 text-sm">
              <span className="font-semibold text-foreground">
                {t(I18nKey.CONVERSATION$CONTEXT_WINDOW)}
              </span>
              <span className={cn("shrink-0 text-xs", TONE_LABEL_CLASS[tone])}>
                {usagePercentLabel}
              </span>
            </div>

            <button
              type="button"
              data-testid="context-window-meter-bar-button"
              className="relative h-1.5 w-full rounded-full cursor-pointer"
              style={{ backgroundColor: CONTEXT_WINDOW_TRACK_COLOR }}
              aria-label={t(I18nKey.COMMON$USAGE)}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                openUsagePanel();
              }}
            >
              <span
                className={cn(
                  "absolute inset-y-0 left-0 rounded-full transition-all duration-300",
                  TONE_BAR_CLASS[tone],
                )}
                style={{ width: `${Math.min(100, usagePercentage)}%` }}
              />
            </button>

            <div className="flex items-center justify-between gap-2">
              <button
                type="button"
                data-testid="context-window-compact-button"
                disabled={isDisabled}
                aria-busy={isCompacting}
                aria-label={t(I18nKey.CONVERSATION$COMPACT_CONTEXT)}
                className={cn(
                  "inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-xs",
                  "text-muted hover:bg-interactive-hover hover:text-foreground",
                  "transition-colors disabled:cursor-not-allowed disabled:opacity-50",
                )}
                onClick={(event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  handleCompact();
                }}
              >
                {isCompacting ? (
                  <Loader2 className="size-3 animate-spin" aria-hidden />
                ) : (
                  <Minimize className="size-3" aria-hidden />
                )}
                <span>{t(I18nKey.CONVERSATION$COMPACT_CONTEXT)}</span>
              </button>
              <span className="text-xs text-muted">{usageTokenSummary}</span>
            </div>
          </div>

          <Divider inset="menu" />

          <ContextMenuListItem
            testId="context-window-plan-usage"
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              openUsagePanel();
            }}
          >
            <ConversationNameContextMenuIconText
              icon={<Gauge size={16} />}
              text={t(I18nKey.COMMON$USAGE)}
            />
          </ContextMenuListItem>
        </div>
      )}
    </div>
  );
}

import type {
  ProviderConnection,
  CreateProviderConnectionRequest,
  UpdateProviderConnectionRequest,
} from "../provider-connections-service/provider-connections-service.api";
import { getActiveBackend } from "../backend-registry/active-store";
import type { Backend } from "../backend-registry/types";
import { callCloudProxy } from "./proxy";

/**
 * Cloud provider-connections service.
 *
 * Provider-connection CRUD is routed to the org-scoped endpoints
 * `/api/organizations/{orgId}/provider-connections`, which enforce
 * `EDIT_ORG_SETTINGS` server-side (listing requires `VIEW_ORG_SETTINGS`) — so a
 * member's mutation is rejected with 403 even on a direct API call, not just
 * hidden in the UI. This mirrors the cloud LLM-profile service.
 *
 * Unlike the local agent-server (which returns a bare array), the org list
 * route wraps results as `{ connections: [...] }`; this service unwraps that so
 * callers see the same `ProviderConnection[]` shape on both backends. Individual
 * mutations return a bare `ProviderConnection` on both backends. Neither route
 * exposes the stored key; each item carries `api_key_set` instead.
 *
 * Cloud has no unbound-org fallback here: provider connections are inherently
 * org-scoped, so an org must be bound. A cloud backend without an org id is a
 * programming error rather than a legacy-key case.
 */

interface CloudProviderConnectionListResponse {
  connections: ProviderConnection[];
}

/** Resolve the backend + org-scoped base path for the active cloud backend. */
function cloudProviderConnectionsTarget(): { backend: Backend; base: string } {
  const { backend, orgId } = getActiveBackend();
  if (backend.kind !== "cloud") {
    throw new Error(
      "Cloud provider-connections call requires a cloud backend.",
    );
  }
  if (!orgId) {
    throw new Error(
      "Cloud provider connections require an organization-bound backend.",
    );
  }
  return {
    backend,
    base: `/api/organizations/${encodeURIComponent(orgId)}/provider-connections`,
  };
}

export async function fetchCloudProviderConnections(): Promise<
  ProviderConnection[]
> {
  const { backend, base } = cloudProviderConnectionsTarget();
  const result = await callCloudProxy<CloudProviderConnectionListResponse>({
    backend,
    method: "GET",
    path: base,
  });
  return result.connections ?? [];
}

export async function createCloudProviderConnection(
  request: CreateProviderConnectionRequest,
): Promise<ProviderConnection> {
  const { backend, base } = cloudProviderConnectionsTarget();
  return callCloudProxy<ProviderConnection>({
    backend,
    method: "POST",
    path: base,
    body: request,
  });
}

export async function updateCloudProviderConnection(
  id: string,
  request: UpdateProviderConnectionRequest,
): Promise<ProviderConnection> {
  const { backend, base } = cloudProviderConnectionsTarget();
  return callCloudProxy<ProviderConnection>({
    backend,
    method: "PATCH",
    path: `${base}/${encodeURIComponent(id)}`,
    body: request,
  });
}

export async function deleteCloudProviderConnection(
  id: string,
): Promise<ProviderConnection> {
  const { backend, base } = cloudProviderConnectionsTarget();
  return callCloudProxy<ProviderConnection>({
    backend,
    method: "DELETE",
    path: `${base}/${encodeURIComponent(id)}`,
  });
}

import { SettingsClient } from "@openhands/typescript-client/clients";
import { getAgentServerClientOptions } from "#/api/agent-server-client-options";
import { SecretsService } from "#/api/secrets-service";
import { getActiveBackend } from "#/api/backend-registry/active-store";
import type { Provider } from "#/types/settings";
import { constructPullRequestUrl, getGitProviderBaseUrl } from "#/utils/utils";

export interface GitProviderItem {
  id: number;
  number: number;
  title: string;
  url: string;
  authorLogin: string | null;
  updatedAt: string | null;
}

const PROVIDER_TOKEN_SECRET_CANDIDATES: Partial<Record<Provider, string[]>> = {
  github: ["GITHUB_TOKEN", "GH_TOKEN", "github"],
  gitlab: ["GITLAB_TOKEN", "GL_TOKEN", "gitlab"],
  bitbucket: ["BITBUCKET_TOKEN", "bitbucket"],
  forgejo: ["FORGEJO_TOKEN", "forgejo"],
};

const LIST_LIMIT = 30;

async function resolveProviderToken(
  provider: Provider,
): Promise<string | null> {
  // Cloud backends keep provider tokens server-side; browser-side secret
  // lookup is only meaningful for the local agent-server secrets store.
  if (getActiveBackend().backend.kind !== "local") {
    return null;
  }

  const candidates = PROVIDER_TOKEN_SECRET_CANDIDATES[provider] ?? [];
  if (candidates.length === 0) {
    return null;
  }

  const secrets = await SecretsService.getSecrets();
  const available = new Set(secrets.map((secret) => secret.name));
  const match = candidates.find((name) => available.has(name));
  if (!match) {
    return null;
  }

  try {
    return await new SettingsClient(getAgentServerClientOptions()).getSecret(
      match,
    );
  } catch {
    return null;
  }
}

function constructIssueUrl(
  issueNumber: number,
  provider: Provider,
  repositoryName: string,
): string {
  const baseUrl = getGitProviderBaseUrl(provider);
  switch (provider) {
    case "gitlab":
      return `${baseUrl}/${repositoryName}/-/issues/${issueNumber}`;
    case "bitbucket":
      return `${baseUrl}/${repositoryName}/issues/${issueNumber}`;
    case "forgejo":
      return `${baseUrl}/${repositoryName}/issues/${issueNumber}`;
    case "github":
    default:
      return `${baseUrl}/${repositoryName}/issues/${issueNumber}`;
  }
}

function constructIssuesListUrl(
  provider: Provider,
  repositoryName: string,
): string {
  const baseUrl = getGitProviderBaseUrl(provider);
  switch (provider) {
    case "gitlab":
      return `${baseUrl}/${repositoryName}/-/issues`;
    case "bitbucket":
      return `${baseUrl}/${repositoryName}/issues`;
    case "forgejo":
      return `${baseUrl}/${repositoryName}/issues`;
    case "github":
    default:
      return `${baseUrl}/${repositoryName}/issues`;
  }
}

function constructPullRequestsListUrl(
  provider: Provider,
  repositoryName: string,
): string {
  const baseUrl = getGitProviderBaseUrl(provider);
  switch (provider) {
    case "gitlab":
      return `${baseUrl}/${repositoryName}/-/merge_requests`;
    case "bitbucket":
      return `${baseUrl}/${repositoryName}/pull-requests`;
    case "forgejo":
      return `${baseUrl}/${repositoryName}/pulls`;
    case "github":
    default:
      return `${baseUrl}/${repositoryName}/pulls`;
  }
}

async function fetchGithubJson<T>(
  path: string,
  token: string | null,
): Promise<T> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "X-GitHub-Api-Version": "2022-11-28",
  };
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  const response = await fetch(`https://api.github.com${path}`, { headers });
  if (!response.ok) {
    throw new Error(`GitHub API ${response.status}`);
  }
  return response.json() as Promise<T>;
}

async function fetchForgejoJson<T>(
  path: string,
  token: string | null,
): Promise<T> {
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (token) {
    // Forgejo/Gitea accept the `token` scheme on every supported version;
    // `Bearer` only landed in later releases.
    headers.Authorization = `token ${token}`;
  }

  // The provider host's own REST API (`/api/v1`), not api.github.com:
  // Forgejo speaks the Gitea API shape on the instance that hosts the repo.
  // eslint-disable-next-line local/no-direct-agent-server-fetch
  const response = await fetch(
    `${getGitProviderBaseUrl("forgejo")}/api/v1${path}`,
    {
      headers,
    },
  );
  if (!response.ok) {
    throw new Error(`Forgejo API ${response.status}`);
  }
  return response.json() as Promise<T>;
}

async function fetchGitlabJson<T>(
  path: string,
  token: string | null,
): Promise<T> {
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (token) {
    headers["PRIVATE-TOKEN"] = token;
  }

  // gitlab.com's public REST API — an external host, not the agent-server
  // `/api` surface the rule guards (its `/api/v4` prefix just trips the
  // substring heuristic; the companion no-direct-agent-server-calls test
  // matches only relative `/api/...` URLs and is not affected).
  // eslint-disable-next-line local/no-direct-agent-server-fetch
  const response = await fetch(`https://gitlab.com/api/v4${path}`, { headers });
  if (!response.ok) {
    throw new Error(`GitLab API ${response.status}`);
  }
  return response.json() as Promise<T>;
}

type GithubIssueOrPr = {
  id: number;
  number: number;
  title: string;
  html_url: string;
  user?: { login?: string } | null;
  updated_at?: string | null;
  pull_request?: unknown;
};

type GitlabMergeRequest = {
  id: number;
  iid: number;
  title: string;
  web_url: string;
  author?: { username?: string } | null;
  updated_at?: string | null;
};

type GitlabIssue = {
  id: number;
  iid: number;
  title: string;
  web_url: string;
  author?: { username?: string } | null;
  updated_at?: string | null;
};

/**
 * Lists open pull requests / merge requests and issues for a connected
 * repository by calling the provider's public REST API from the browser.
 * When a matching token secret exists locally (e.g. `GITHUB_TOKEN`), it is
 * used for auth so private repos work; otherwise public-repo unauthenticated
 * requests are attempted.
 */
export class GitProviderItemsService {
  static constructIssuesListUrl = constructIssuesListUrl;

  static constructPullRequestsListUrl = constructPullRequestsListUrl;

  static async listPullRequests(
    repository: string,
    provider: Provider,
  ): Promise<GitProviderItem[]> {
    const token = await resolveProviderToken(provider);

    if (provider === "gitlab") {
      const encoded = encodeURIComponent(repository);
      const items = await fetchGitlabJson<GitlabMergeRequest[]>(
        `/projects/${encoded}/merge_requests?state=opened&per_page=${LIST_LIMIT}`,
        token,
      );
      return items.map((item) => ({
        id: item.id,
        number: item.iid,
        title: item.title,
        url: item.web_url,
        authorLogin: item.author?.username ?? null,
        updatedAt: item.updated_at ?? null,
      }));
    }

    if (provider === "forgejo") {
      const [forgejoOwner, forgejoRepo] = repository.split("/");
      if (!forgejoOwner || !forgejoRepo) {
        return [];
      }
      const items = await fetchForgejoJson<GithubIssueOrPr[]>(
        `/repos/${forgejoOwner}/${forgejoRepo}/pulls?state=open&limit=${LIST_LIMIT}`,
        token,
      );
      return items.map((item) => ({
        id: item.id,
        number: item.number,
        title: item.title,
        url:
          item.html_url ||
          constructPullRequestUrl(item.number, provider, repository),
        authorLogin: item.user?.login ?? null,
        updatedAt: item.updated_at ?? null,
      }));
    }

    if (provider !== "github") {
      return [];
    }

    const [owner, repo] = repository.split("/");
    if (!owner || !repo) {
      return [];
    }

    const items = await fetchGithubJson<GithubIssueOrPr[]>(
      `/repos/${owner}/${repo}/pulls?state=open&per_page=${LIST_LIMIT}`,
      token,
    );

    return items.map((item) => ({
      id: item.id,
      number: item.number,
      title: item.title,
      url:
        item.html_url ||
        constructPullRequestUrl(item.number, provider, repository),
      authorLogin: item.user?.login ?? null,
      updatedAt: item.updated_at ?? null,
    }));
  }

  static async listIssues(
    repository: string,
    provider: Provider,
  ): Promise<GitProviderItem[]> {
    const token = await resolveProviderToken(provider);

    if (provider === "gitlab") {
      const encoded = encodeURIComponent(repository);
      const items = await fetchGitlabJson<GitlabIssue[]>(
        `/projects/${encoded}/issues?state=opened&per_page=${LIST_LIMIT}`,
        token,
      );
      return items.map((item) => ({
        id: item.id,
        number: item.iid,
        title: item.title,
        url: item.web_url,
        authorLogin: item.author?.username ?? null,
        updatedAt: item.updated_at ?? null,
      }));
    }

    if (provider === "forgejo") {
      const [forgejoOwner, forgejoRepo] = repository.split("/");
      if (!forgejoOwner || !forgejoRepo) {
        return [];
      }
      const items = await fetchForgejoJson<GithubIssueOrPr[]>(
        `/repos/${forgejoOwner}/${forgejoRepo}/issues?state=open&type=issues&limit=${LIST_LIMIT}`,
        token,
      );
      // Forgejo's issues endpoint can still return pull requests.
      return items
        .filter((item) => !item.pull_request)
        .map((item) => ({
          id: item.id,
          number: item.number,
          title: item.title,
          url:
            item.html_url ||
            constructIssueUrl(item.number, provider, repository),
          authorLogin: item.user?.login ?? null,
          updatedAt: item.updated_at ?? null,
        }));
    }

    if (provider !== "github") {
      return [];
    }

    const [owner, repo] = repository.split("/");
    if (!owner || !repo) {
      return [];
    }

    const items = await fetchGithubJson<GithubIssueOrPr[]>(
      `/repos/${owner}/${repo}/issues?state=open&per_page=${LIST_LIMIT}`,
      token,
    );

    // GitHub's issues endpoint also returns pull requests.
    return items
      .filter((item) => !item.pull_request)
      .map((item) => ({
        id: item.id,
        number: item.number,
        title: item.title,
        url:
          item.html_url || constructIssueUrl(item.number, provider, repository),
        authorLogin: item.user?.login ?? null,
        updatedAt: item.updated_at ?? null,
      }));
  }
}

import type { Config } from "@react-router/dev/config";
import { vercelPreset } from "@vercel/react-router/vite";

const normalizeBasePath = (value?: string) => {
  const raw = value?.trim();
  if (!raw || raw === "/") return undefined;

  const withLeadingSlash = raw.startsWith("/") ? raw : `/${raw}`;
  return withLeadingSlash.replace(/\/+$/, "");
};

const basename = normalizeBasePath(process.env.VITE_BASE_PATH);

/**
 * This script is used to unpack the client directory from the frontend build directory.
 * Remix SPA mode builds the client directory into the build directory. This function
 * moves the contents of the client directory to the build directory and then removes the
 * client directory.
 *
 * This script is used in the buildEnd function of the Vite config.
 */
let unpackClientDirectoryPromise: Promise<void> | null = null;

const moveBuildEntry = async (
  fs: typeof import("fs"),
  source: string,
  destination: string,
) => {
  await fs.promises.rm(destination, { recursive: true, force: true });

  try {
    await fs.promises.rename(source, destination);
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code !== "EPERM" && code !== "EXDEV") {
      throw error;
    }

    await fs.promises.cp(source, destination, {
      recursive: true,
      force: true,
    });
    await fs.promises.rm(source, { recursive: true, force: true });
  }
};

const unpackClientDirectoryOnce = async () => {
  if (process.env.VERCEL) {
    // Vercel's React Router builder reads static assets from build/client.
    return;
  }

  const fs = await import("fs");
  const path = await import("path");

  const buildDir = path.resolve(__dirname, "build");
  const clientDir = path.resolve(buildDir, "client");

  let files: string[];
  try {
    files = await fs.promises.readdir(clientDir);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return;
    }
    throw error;
  }

  for (const file of files) {
    await moveBuildEntry(
      fs,
      path.resolve(clientDir, file),
      path.resolve(buildDir, file),
    );
  }

  await fs.promises.rm(clientDir, { recursive: true, force: true });
};

