});

sdk.start();

run(async () => {
  const result = streamText({
    model: anthropic('claude-sonnet-4-5'),
    prompt: 'Cook me a lasagna.',
    tools: {
      cookRecipe: {
        description: 'Cook a recipe',
        inputSchema: z.object({
          recipe: z.object({
            name: z.string(),
            ingredients: z.array(
              z.object({
                name: z.string(),
