  if (!PI_SESSION_FILE_NAME_PATTERN.test(sessionFileName)) {
    throw new Error(`Invalid Pi session file name: ${sessionFileName}`);
  }
  return sessionFileName;
}

const piSessionFileNameSchema = z
  .string()
  .refine(
    sessionFileName => PI_SESSION_FILE_NAME_PATTERN.test(sessionFileName),
    'Pi sessionFileName must be a safe .jsonl or .json basename.',
  );

/**
 * Schema for the adapter-specific portion of lifecycle state `data` produced
 * by Pi's resumable lifecycle methods. Carries the basename
 * (including extension) of the Pi session file. The actual session bytes live
 * in a private, session-scoped directory under sandbox HOME so they survive
 * cross-process resume without appearing in the agent workspace.
 */
export const piResumeStateSchema = z.looseObject({
  sessionFileName: piSessionFileNameSchema.optional(),
});

export type PiResumeStateData = z.infer<typeof piResumeStateSchema>;

export function resolvePiPrivateSessionDirectory(input: {
  readonly sandboxHomeDir: string;
  readonly sessionWorkDir: string;
  readonly sessionId: string;
}): string {
  const sessionKey = createHash('sha256').update(input.sessionId).digest('hex');
  const privateSessionDir = path.posix.join(
    input.sandboxHomeDir,
    '.ai-sdk',
    'harness-pi',
    sessionKey,
  );
  const relativePath = path.posix.relative(
    input.sessionWorkDir,
    privateSessionDir,
  );
  if (
    relativePath === '' ||
    (!relativePath.startsWith('../') && !path.posix.isAbsolute(relativePath))
  ) {
    throw new Error(
      `Pi private session directory ${JSON.stringify(privateSessionDir)} must be outside sessionWorkDir ${JSON.stringify(input.sessionWorkDir)}.`,
    );
  }
  return privateSessionDir;
}

function resolveContainedHostPath(input: {
  readonly baseDir: string;
  readonly sessionFileName: string;
}): string {
  const baseDir = path.resolve(input.baseDir);
  const filePath = path.resolve(
    baseDir,
    safePiSessionFileName(input.sessionFileName),
  );
  const relativePath = path.relative(baseDir, filePath);
  if (
    relativePath === '' ||
    relativePath.startsWith('..') ||
    path.isAbsolute(relativePath)
  ) {
    throw new Error(`Invalid Pi session file name: ${input.sessionFileName}`);
  }
  return filePath;
}

function resolveContainedSandboxPath(input: {
  readonly privateSessionDir: string;
  readonly sessionFileName: string;
}): string {
  const sessionDir = path.posix.resolve(input.privateSessionDir);
  const filePath = path.posix.resolve(
    sessionDir,
    safePiSessionFileName(input.sessionFileName),
  );
  const relativePath = path.posix.relative(sessionDir, filePath);
  if (
    relativePath === '' ||
    relativePath.startsWith('..') ||
    path.posix.isAbsolute(relativePath)
  ) {
    throw new Error(`Invalid Pi session file name: ${input.sessionFileName}`);
  }
  return filePath;
}

/**
 * Copy the Pi session file from the host's local mirror to private sandbox
 * state. Called during resumable lifecycle methods so the session survives a
 * sandbox snapshot or a process handoff.
 */
export async function persistSessionFileToSandbox(args: {
  readonly sandbox: Experimental_SandboxSession;
  readonly privateSessionDir: string;
  readonly hostSessionDir: string;
  readonly sessionFileName: string;
  readonly abortSignal?: AbortSignal;
}): Promise<void> {
  const hostPath = resolveContainedHostPath({
    baseDir: args.hostSessionDir,
    sessionFileName: args.sessionFileName,
  });
  const content = await readFile(hostPath);
  const remotePath = resolveContainedSandboxPath({
    privateSessionDir: args.privateSessionDir,
    sessionFileName: args.sessionFileName,
  });
  await args.sandbox.writeBinaryFile({
    path: remotePath,
    content,
    ...(args.abortSignal ? { abortSignal: args.abortSignal } : {}),
  });
}

/**
 * Pull a previously persisted Pi session file from the sandbox into a fresh
 * local mirror dir. Called during `doStart` on the resume path before Pi is
 * initialised. Returns the absolute path of the local session file or
 * `undefined` if the sandbox copy is missing.
 */
export async function pullSessionFileFromSandbox(args: {
  readonly sandbox: Experimental_SandboxSession;
  readonly privateSessionDir: string;
  readonly hostSessionDir: string;
  readonly sessionFileName: string;
  readonly abortSignal?: AbortSignal;
}): Promise<string | undefined> {
  const remotePath = resolveContainedSandboxPath({
    privateSessionDir: args.privateSessionDir,
    sessionFileName: args.sessionFileName,
  });
  const bytes = await args.sandbox.readBinaryFile({
    path: remotePath,
    ...(args.abortSignal ? { abortSignal: args.abortSignal } : {}),
  });
  if (bytes == null) return undefined;
  await mkdir(args.hostSessionDir, { recursive: true });
  const hostPath = resolveContainedHostPath({
    baseDir: args.hostSessionDir,
    sessionFileName: args.sessionFileName,
  });
  await writeFile(hostPath, bytes);
  return hostPath;
}

import { openai } from '@ai-sdk/openai';
import {
  createUIMessageStreamResponse,
  streamText,
  createUIMessageStream,
  convertToModelMessages,
  isStepCount,
  toUIMessageStream,
} from 'ai';
import { processToolCalls } from './utils';
import { tools } from './tools';
import type { HumanInTheLoopUIMessage } from './types';

// Allow streaming responses up to 30 seconds
export const maxDuration = 30;

export async function POST(req: Request) {
  const { messages }: { messages: HumanInTheLoopUIMessage[] } =
    await req.json();

  const stream = createUIMessageStream({
    originalMessages: messages,
    execute: async ({ writer }) => {
      // Utility function to handle tools that require human confirmation
      // Checks for confirmation in last message and then runs associated tool
      const processedMessages = await processToolCalls(
        {
          messages,
          writer,
          tools,
        },
        {
          // type-safe object for tools without an execute function
          getWeatherInformation: async ({ city }) => {
            const conditions = ['sunny', 'cloudy', 'rainy', 'snowy'];
            return `The weather in ${city} is ${
              conditions[Math.floor(Math.random() * conditions.length)]
            }.`;
          },
        },
      );

      const result = streamText({
        model: openai('gpt-4o'),
        messages: await convertToModelMessages(processedMessages),
        tools,
        stopWhen: isStepCount(20),
      });

      writer.merge(
        toUIMessageStream({
          stream: result.stream,
          originalMessages: processedMessages,
        }),
      );
    },
    onStepFinish: ({ messages, responseMessage }) => {
      console.log('--- Step finished ---');
      console.log('Parts count:', responseMessage.parts.length);
      console.log('Messages:', JSON.stringify(messages, null, 2));
    },
    onFinish: ({}) => {
      // save messages here
      console.log('Finished!');
    },
  });

  return createUIMessageStreamResponse({ stream });
}

import {
  getTelemetryEvents,
  type TelemetryScenario,
} from '@/lib/telemetry-store';

const expectations: Record<TelemetryScenario, string[]> = {
  'happy-path': [
    'onStart',
    'onStepStart',
    'onLanguageModelCallStart',
    'onLanguageModelCallEnd',
    'onToolExecutionStart',
    'onToolExecutionEnd',
    'onStepFinish',
    'onFinish',
  ],
  'context-filtering': [
    'onStart',
    'onStepStart',
    'onToolExecutionStart',
    'onToolExecutionEnd',
    'onFinish',
  ],
  approval: [
    'onStart',
    'onStepStart',
    'onLanguageModelCallStart',
    'onLanguageModelCallEnd',
    'onFinish',
  ],
  'tool-error': [
    'onStart',
    'onToolExecutionStart',
    'onToolExecutionEnd',
    'onFinish',
  ],
  'model-error': ['onStart', 'onLanguageModelCallStart', 'onError'],
  reconnect: [
    'onStart',
    'onStepStart',
    'onFinish',
    'transport:postStreamInterrupted',
    'transport:reconnectStream',
  ],
};

export async function GET(
  request: Request,
  { params }: { params: Promise<{ telemetryRunId: string }> },
) {
  const { telemetryRunId } = await params;
  const scenario =
    (new URL(request.url).searchParams.get(
      'scenario',
    ) as TelemetryScenario | null) ?? 'happy-path';
  const events = getTelemetryEvents(telemetryRunId);
  const telemetryEvents = events.filter(event => event.source === 'telemetry');
  const serializedTelemetryEvents = JSON.stringify(telemetryEvents);

  return Response.json({
    telemetryRunId,
    scenario,
    events,
    expectations: expectations[scenario].map(name => {
      const [source, eventName] = name.includes(':')
        ? name.split(':')
        : ['telemetry', name];
      return {
        name,
        met: events.some(
          event => event.source === source && event.name === eventName,
        ),
      };
    }),
    contextFiltering: {
      includesAllowedRuntimeContext: serializedTelemetryEvents.includes(
        'tenant_telemetry_e2e',
      ),
      excludesRuntimeSecret: !serializedTelemetryEvents.includes(
        'runtime-secret-not-for-telemetry',
      ),
      excludesToolSecret:
        !serializedTelemetryEvents.includes(
          'weather-secret-not-for-telemetry',
        ) &&
        !serializedTelemetryEvents.includes('delete-secret-not-for-telemetry'),
    },
  });
}

import type { Telemetry } from 'ai';

/**
 * A harness observability reporter that renders an ASCII trace tree of a
 * turn's span lifecycle (turn → steps → tools) to a stream at turn end. It is a
 * `Telemetry` integration — register it in `telemetry.integrations`. Useful for
 * zero-setup local debugging when no OTel collector is wired up; a real OTel
 * backend (via `@ai-sdk/otel`) is a strict superset.
 */
export interface TraceTreeReporterOptions {
  /** Where to write the rendered tree. Default `process.stderr.write`. */
  write?: (chunk: string) => void;
}

type Node = {
  label: string;
  startMs: number;
  endMs?: number;
  children: Node[];
};

export function createTraceTreeReporter(
  options: TraceTreeReporterOptions = {},
): Telemetry {
  const write =
    options.write ?? ((chunk: string) => void process.stderr.write(chunk));

  type TurnState = {
    root: Node;
    step?: Node;
    tools: Map<string, Node>;
  };
  const turns = new Map<string, TurnState>();

  const render = (node: Node, depth: number): string => {
    const indent = '  '.repeat(depth);
    const dur =
      node.endMs != null
        ? `${Math.max(0, Math.round(node.endMs - node.startMs))}ms`
        : '(open)';
    let out = `${indent}- ${node.label} ${dur}\n`;
    for (const child of node.children) out += render(child, depth + 1);
    return out;
  };

  return {
    onStart(event) {
      const e = event as {
        callId: string;
        operationId?: string;
        modelId?: string;
      };
      turns.set(e.callId, {
        root: {
          label: `${e.operationId ?? 'turn'}${e.modelId ? ` ${e.modelId}` : ''}`,
          startMs: Date.now(),
          children: [],
        },
        tools: new Map(),
      });
    },
    onStepStart(event) {
      const e = event as { callId: string; stepNumber?: number };
      const turn = turns.get(e.callId);
      if (!turn) return;
      const step: Node = {
        label: `step ${(e.stepNumber ?? turn.root.children.length) + 1}`,
        startMs: Date.now(),
        children: [],
      };
      turn.step = step;
      turn.root.children.push(step);
    },
    onToolExecutionStart(event) {
      const e = event as {
        callId: string;
        toolCall: { toolName: string; toolCallId: string };
      };
      const turn = turns.get(e.callId);
      const parent = turn?.step ?? turn?.root;
      if (!turn || !parent) return;
      const node: Node = {
        label: `tool ${e.toolCall.toolName}`,
        startMs: Date.now(),
        children: [],
      };
      turn.tools.set(e.toolCall.toolCallId, node);
      parent.children.push(node);
    },
    onToolExecutionEnd(event) {
      const e = event as {
        callId: string;
        toolCall: { toolCallId: string };
        toolOutput: { type: string };
      };
      const node = turns.get(e.callId)?.tools.get(e.toolCall.toolCallId);
      if (!node) return;
      node.endMs = Date.now();
      if (e.toolOutput.type === 'error') node.label += ' [error]';
    },
    onStepFinish(event) {
      const e = event as { callId: string };
      const turn = turns.get(e.callId);
      if (turn?.step) {
        turn.step.endMs = Date.now();
        turn.step = undefined;
      }
    },
    onEnd(event) {
      const e = event as { callId: string };
      const turn = turns.get(e.callId);
      if (!turn) return;
      turn.root.endMs = Date.now();
      turns.delete(e.callId);
      try {
        write(`\n${render(turn.root, 0)}`);
      } catch {
        // Never let rendering break the turn.
      }
    },
  };
}

