import { useState } from 'react';
import Expand from './ui/Expand';

export type ToolCallArgumentValue =
  | string
  | number
  | boolean
  | null
  | ToolCallArgumentValue[]
  | { [key: string]: ToolCallArgumentValue };

interface ToolCallArgumentsProps {
  args: Record<string, ToolCallArgumentValue>;
}

function formatValue(value: ToolCallArgumentValue): string {
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && value !== null) return JSON.stringify(value, null, 2);
  return String(value);
}

export function ToolCallArguments({ args }: ToolCallArgumentsProps) {
  const [expandedKeys, setExpandedKeys] = useState<Record<string, boolean>>({});

  const toggleKey = (key: string) => {
    setExpandedKeys((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const renderValue = (key: string, value: ToolCallArgumentValue) => {
    const text = formatValue(value).trim();
    const needsExpansion = text.length > 60 || text.includes('\n');
    const isExpanded = expandedKeys[key];

    return (
      <div className="font-sans text-sm mb-2">
        <div className={`flex flex-row items-stretch ${!isExpanded && needsExpansion ? 'truncate min-w-0' : ''}`}>
          <button
            onClick={() => needsExpansion && toggleKey(key)}
            className={`flex text-left text-text-secondary min-w-[140px] ${needsExpansion ? 'cursor-pointer' : 'cursor-default'}`}
          >
            <span>{key}</span>
          </button>
          <div className={`w-full flex items-stretch ${!isExpanded && needsExpansion ? 'truncate min-w-0' : ''}`}>
            {isExpanded ? (
              <pre className="font-mono text-xs text-text-secondary whitespace-pre-wrap max-w-full overflow-x-auto">
                {text}
              </pre>
            ) : (
              <button
                onClick={() => needsExpansion && toggleKey(key)}
                className={`text-left text-text-secondary font-mono text-xs ${needsExpansion ? 'truncate min-w-0 cursor-pointer' : 'cursor-default'}`}
              >
                {text.split('\n')[0]}
              </button>
            )}
            {needsExpansion && (
              <button
                onClick={() => toggleKey(key)}
                className="flex flex-row items-stretch grow text-text-secondary pr-2"
              >
                <div className="min-w-2 grow" />
                <Expand size={5} isExpanded={isExpanded} />
              </button>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="my-2">
      {Object.entries(args).map(([key, value]) => (
        <div key={key}>{renderValue(key, value)}</div>
      ))}
    </div>
  );
}

use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Permission {
    AlwaysAllow,
    AllowOnce,
    Cancel,
    DenyOnce,
    AlwaysDeny,
}

#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
pub enum PrincipalType {
    Extension,
    Tool,
}

#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
pub struct PermissionConfirmation {
    pub principal_type: PrincipalType,
    pub permission: Permission,
}

//! Resolves approval requirements for pending tool requests.

use std::collections::{HashMap, HashSet};

use anyhow::Result;
use async_trait::async_trait;

use crate::agents::state_machine::ops_toolcalling::request_was_advertised;
use crate::agents::state_machine::{
    applied, messages_since_kickoff, not_applicable, ConversationEffect, Emitter, GooseEffect,
    Operation, OperationResult,
};
use crate::config::permission::PermissionLevel;
use crate::config::GooseMode;
use crate::conversation::message::{ActionRequiredData, Message, MessageContent, ToolRequest};
use crate::conversation::Conversation;
use crate::permission::Permission;
use crate::session::Session;
use crate::tool_inspection::{
    get_security_finding_id_from_results, InspectionAction, ToolInspectionManager,
};
use tokio::sync::Mutex;

pub const TOOL_EXECUTABLE_KEY: &str = "goose.executable";

pub struct ToolApprovalOperation<'a> {
    goose_mode: &'a Mutex<GooseMode>,
    tool_inspection_manager: &'a ToolInspectionManager,
}

impl<'a> ToolApprovalOperation<'a> {
    pub fn new(
        goose_mode: &'a Mutex<GooseMode>,
        tool_inspection_manager: &'a ToolInspectionManager,
    ) -> Self {
        Self {
            goose_mode,
            tool_inspection_manager,
        }
    }
}

#[async_trait]
impl Operation<Session, GooseEffect> for ToolApprovalOperation<'_> {
    fn name(&self) -> &'static str {
        "tool_approval"
    }

    async fn run(
        &self,
        session: &Session,
        conversation: &Conversation,
        _emit: &Emitter,
    ) -> Result<OperationResult<GooseEffect>> {
        let goose_mode = *self.goose_mode.lock().await;
        if goose_mode == GooseMode::Chat {
            return not_applicable();
        }

        let state = ApprovalState::from_messages(messages_since_kickoff(conversation)?);
        let mut effects = Vec::new();

        for pending in state.responses() {
            let executable = permission_allows(&pending.permission);

            if let Some(tool_name) = pending.tool_name {
                if pending.permission == Permission::AlwaysAllow && pending.executable != Some(true)
                {
                    self.tool_inspection_manager
                        .update_permission_manager(&tool_name, PermissionLevel::AlwaysAllow)
                        .await;
                } else if pending.permission == Permission::AlwaysDeny {
                    self.tool_inspection_manager
                        .update_permission_manager(&tool_name, PermissionLevel::NeverAllow)
                        .await;
                }
            }

            if pending.executable != Some(executable) {
                effects.push(mark_executable(&pending.tool_call_id, executable));
            }
        }

        let pending_requests = state.pending_requests();
        if !pending_requests.is_empty() {
            let inspection_results = self
                .tool_inspection_manager
                .inspect_tools(
                    &session.id,
                    &pending_requests,
                    conversation.messages(),
                    goose_mode,
                )
                .await?;
            let permission_check_result = self
                .tool_inspection_manager
                .process_inspection_results_with_permission_inspector(
                    &pending_requests,
                    &inspection_results,
                )
                .unwrap_or_else(
                    || crate::permission::permission_judge::PermissionCheckResult {
                        approved: Vec::new(),
                        needs_approval: Vec::new(),
                        denied: Vec::new(),
                    },
                );

            for request in permission_check_result.denied {
                effects.push(mark_executable(&request.id, false));
            }

            for request in permission_check_result.needs_approval {
                let tool_call = request.tool_call.clone()?;
                effects.push(mark_executable(&request.id, false));

                let security_message = inspection_results
                    .iter()
                    .find(|result| result.tool_request_id == request.id)
                    .and_then(|result| match &result.action {
                        InspectionAction::RequireApproval(Some(message)) => Some(message.clone()),
                        _ => None,
                    });

                let action_required = Message::assistant()
                    .with_action_required(
                        request.id.clone(),
                        tool_call.name.to_string(),
                        tool_call.arguments.clone().unwrap_or_default(),
                        security_message,
                    )
                    .user_only();
                effects.push(action_required.into());

                if let Some(finding_id) =
                    get_security_finding_id_from_results(&request.id, &inspection_results)
                {
                    tracing::info!(
                        monotonic_counter.goose.prompt_injection_user_decisions = 1,
                        security.event_type = "approval_request",
                        security.finding_id = %finding_id,
                        tool.request_id = %request.id,
                        "security finding: approval requested"
                    );
                }
            }
        }

        if effects.is_empty() {
            not_applicable()
        } else {
            applied(effects)
        }
    }
}

struct PendingResponse {
    tool_call_id: String,
    tool_name: Option<String>,
    permission: Permission,
    executable: Option<bool>,
}

pub(super) struct ApprovalState {
    answered: HashSet<String>,
    approval_requests: HashSet<String>,
    approval_responses: HashMap<String, Permission>,
    tool_requests: Vec<ToolRequest>,
}

impl ApprovalState {
    pub(super) fn from_messages(messages: &[Message]) -> Self {
        let mut answered = HashSet::new();
        let mut approval_requests = HashSet::new();
        let mut approval_responses = HashMap::new();
        let mut tool_requests = Vec::new();

        for message in messages {
            for content in &message.content {
                match content {
                    MessageContent::ToolResponse(response) => {
                        answered.insert(response.id.clone());
                    }
                    MessageContent::ToolRequest(request)
                        if request_was_advertised(messages, request) =>
                    {
                        tool_requests.push(request.clone());
                    }
                    MessageContent::ActionRequired(action) => match &action.data {
                        ActionRequiredData::ToolConfirmation { id, .. } => {
                            approval_requests.insert(id.clone());
                        }
                        ActionRequiredData::ToolConfirmationResponse { id, permission } => {
                            approval_responses.insert(id.clone(), permission.clone());
                        }
                        _ => {}
                    },
                    _ => {}
                }
            }
        }

        Self {
            answered,
            approval_requests,
            approval_responses,
            tool_requests,
        }
    }

    fn responses(&self) -> Vec<PendingResponse> {
        self.tool_requests
            .iter()
            .filter_map(|request| {
                if self.answered.contains(&request.id) {
                    return None;
                }
                let permission = self.approval_responses.get(&request.id)?.clone();
                let tool_name = request
                    .tool_call
                    .as_ref()
                    .ok()
                    .map(|tool_call| tool_call.name.to_string());
                Some(PendingResponse {
                    tool_call_id: request.id.clone(),
                    tool_name,
                    permission,
                    executable: request_executable(request),
                })
            })
            .collect()
    }

    fn pending_requests(&self) -> Vec<ToolRequest> {
        self.tool_requests
            .iter()
            .filter_map(|request| {
                if self.answered.contains(&request.id)
                    || self.approval_requests.contains(&request.id)
                    || self.approval_responses.contains_key(&request.id)
                    || request.was_executed_externally()
                    || request_executable(request) == Some(false)
                    || request.tool_call.is_err()
                {
                    return None;
                }
                Some(request.clone())
            })
            .collect()
    }

    pub(super) fn has_confirmation_request(&self, request_id: &str) -> bool {
        self.approval_requests.contains(request_id)
            && self
                .tool_requests
                .iter()
                .any(|request| request.id == request_id)
    }

    pub(super) fn has_unapplied_confirmation_response(&self) -> bool {
        self.tool_requests.iter().any(|request| {
            !self.answered.contains(&request.id)
                && self.approval_requests.contains(&request.id)
                && self.approval_responses.contains_key(&request.id)
        })
    }

    pub(super) fn confirmation_response(&self, request_id: &str) -> Option<&Permission> {
        self.approval_responses.get(request_id)
    }

    pub(super) fn has_tool_response(&self, request_id: &str) -> bool {
        self.answered.contains(request_id)
    }
}

pub fn request_executable(request: &ToolRequest) -> Option<bool> {
    request
        .tool_meta
        .as_ref()
        .and_then(|meta| meta.get(TOOL_EXECUTABLE_KEY))
        .and_then(|value| value.as_bool())
}

fn permission_allows(permission: &Permission) -> bool {
    matches!(permission, Permission::AllowOnce | Permission::AlwaysAllow)
}

fn mark_executable(tool_call_id: &str, executable: bool) -> GooseEffect {
    ConversationEffect::PatchToolRequestMeta {
        tool_call_id: tool_call_id.to_string(),
        patch: serde_json::json!({ TOOL_EXECUTABLE_KEY: executable }),
    }
    .into()
}

use anyhow::{Context, Result};
use goose::config::Config;
use goose::conversation::message::Message;
use goose::conversation::Conversation;
use std::fs;
use std::io::Read;
use std::io::Write;
use std::path::Path;
use std::process::Command;
use tempfile::Builder;
use tempfile::NamedTempFile;

/// Resolve the editor command from config and environment variables.
/// Checks GOOSE_PROMPT_EDITOR, then $VISUAL, then $EDITOR.
pub fn resolve_editor_command() -> Option<String> {
    let config = Config::global();
    let config_editor = config.get_goose_prompt_editor().ok().flatten();
    let visual = std::env::var("VISUAL").ok();
    let editor_env = std::env::var("EDITOR").ok();
    resolve_editor_from_sources(
        config_editor.as_deref(),
        visual.as_deref(),
        editor_env.as_deref(),
    )
}

fn resolve_editor_from_sources(
    config_editor: Option<&str>,
    visual: Option<&str>,
    editor_env: Option<&str>,
) -> Option<String> {
    for cmd in [config_editor, visual, editor_env].into_iter().flatten() {
        if !cmd.is_empty() {
            return Some(cmd.to_string());
        }
    }
    None
}

/// Resolve the editor command, falling back to vi (or notepad on Windows).
pub fn resolve_editor_or_default() -> String {
    let config = Config::global();
    let config_editor = config.get_goose_prompt_editor().ok().flatten();
    let visual = std::env::var("VISUAL").ok();
    let editor_env = std::env::var("EDITOR").ok();
    resolve_editor_or_default_from_sources(
        config_editor.as_deref(),
        visual.as_deref(),
        editor_env.as_deref(),
    )
}

fn resolve_editor_default() -> String {
    if cfg!(windows) {
        "notepad".to_string()
    } else {
        "vi".to_string()
    }
}

fn resolve_editor_or_default_from_sources(
    config_editor: Option<&str>,
    visual: Option<&str>,
    editor_env: Option<&str>,
) -> String {
    resolve_editor_from_sources(config_editor, visual, editor_env)
        .unwrap_or_else(resolve_editor_default)
}

/// Open a YAML temp file with the user's editor to edit a conversation.
/// Returns the edited conversation, or an error if the editor failed or YAML was invalid.
pub fn edit_conversation(conversation: &Conversation) -> Result<Conversation> {
    let yaml = serde_yaml::to_string(conversation.messages())?;

    let mut tmp = NamedTempFile::with_suffix(".yaml")?;
    tmp.write_all(yaml.as_bytes())?;
    tmp.flush()?;

    let editor = resolve_editor_or_default();
    let path = tmp.path().to_path_buf();

    launch_editor(&editor, &path).with_context(|| format!("failed to launch editor '{editor}'"))?;

    let edited = std::fs::read_to_string(&path)?;
    let messages: Vec<Message> =
        serde_yaml::from_str(&edited).context("invalid YAML — session unchanged")?;

    Ok(Conversation::new_unvalidated(messages))
}

/// Build the markdown template content for the editor prompt.
fn build_template(messages: &[&str], prefill: Option<&str>) -> String {
    let mut content = String::from("# Goose Prompt Editor\n\n");

    content.push_str("# Your prompt:\n\n");
    if let Some(text) = prefill {
        if !text.is_empty() {
            content.push_str(text);
            content.push('\n');
        }
    }

    if !messages.is_empty() {
        content.push_str("# Recent conversation for context (newest first):\n\n");
        for message in messages.iter().rev() {
            content.push_str(&format!("{}\n", message));
        }
        content.push('\n');
    }

    content
}

/// Create temporary markdown file with conversation history and optional prefill text
fn create_temp_file(messages: &[&str], prefill: Option<&str>) -> Result<NamedTempFile> {
    let temp_file = Builder::new()
        .prefix("goose_prompt_")
        .suffix(".md")
        .tempfile()?;

    fs::write(temp_file.path(), build_template(messages, prefill))?;
    Ok(temp_file)
}

/// Split an editor command into program and arguments.
///
/// Uses shell-word splitting only when the command contains quotes, so values like
/// `"/Applications/Sublime Text.app/.../subl" -w` work. Unquoted commands are split on
/// whitespace to avoid shlex stripping backslashes from Windows paths like
/// `C:\Windows\System32\notepad.exe`.
fn split_editor_command(editor_cmd: &str) -> Result<Vec<String>> {
    if editor_cmd.contains(['"', '\'']) {
        shlex::split(editor_cmd).ok_or_else(|| {
            anyhow::anyhow!("Invalid editor command: unmatched quotes in '{editor_cmd}'")
        })
    } else {
        Ok(editor_cmd.split_whitespace().map(String::from).collect())
    }
}

/// Launch editor and wait for completion
fn launch_editor(editor_cmd: &str, file_path: &Path) -> Result<()> {
    use std::process::Stdio;

    let parts = split_editor_command(editor_cmd)?;
    if parts.is_empty() {
        return Err(anyhow::anyhow!("Empty editor command"));
    }

    let mut cmd = Command::new(&parts[0]);
    if let Ok(cwd) = std::env::current_dir() {
        cmd.current_dir(cwd);
    }
    if parts.len() > 1 {
        cmd.args(&parts[1..]);
    }
    cmd.arg(file_path)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    let status = cmd.status()?;

    if !status.success() {
        return Err(anyhow::anyhow!(
            "Editor exited with non-zero status: {}",
            status.code().unwrap_or(-1)
        ));
    }

    Ok(())
}

/// Main function to get input from editor
pub fn get_editor_input(
    editor_cmd: &str,
    messages: &[&str],
    prefill: Option<&str>,
) -> Result<(String, bool)> {
    let temp_file = create_temp_file(messages, prefill)?;
    let temp_path = temp_file.path().to_path_buf();

    launch_editor(editor_cmd, &temp_path)?;

    let mut content = String::new();
    let mut file = temp_file.reopen()?;
    file.read_to_string(&mut content)?;

    let user_input = extract_user_input(&content);

    let has_meaningful_content = !user_input.trim().is_empty();

    Ok((user_input, has_meaningful_content))
}

/// Extract only the user's input from the markdown file
fn extract_user_input(content: &str) -> String {
    if let Some(start) = content.find("# Your prompt:") {
        let marker_len = "# Your prompt:".len();
        #[allow(clippy::string_slice)]
        let user_section = &content[start + marker_len..];

        let end_patterns = [
            "# Recent conversation for context",
            "# Recent conversation for context (newest first):",
        ];

        let mut end_pos = None;
        for pattern in &end_patterns {
            if let Some(pos) = user_section.find(pattern) {
                end_pos = Some(pos);
                break;
            }
        }

        let user_input_section = match end_pos {
            Some(pos) =>
            {
                #[allow(clippy::string_slice)]
                &user_section[..pos]
            }
            None => user_section,
        };

        user_input_section.trim().to_string()
    } else {
        content.trim().to_string()
    }
}

