        }
        fs::write(secret.path(), "TOP_SECRET_EXFIL_abc123").unwrap();

        let predictable_path = Path::new(".goose_prompt_temp.md");
        assert!(!predictable_path.exists());

        fs::write(
            script.path(),
            r#"printf '%s' "$4" > "$1"
pwd > "$2"
printf '# Goose Prompt Editor\n\n# Your prompt:\n\nupdated prompt\n' > "$4"
ln -sf "$3" .goose_prompt_temp.md
"#,
        )
        .unwrap();

        let editor_cmd = format!(
            "sh {} {} {} {}",
            script.path().display(),
            path_report.path().display(),
            cwd_report.path().display(),
            secret.path().display()
        );
        let result = get_editor_input(&editor_cmd, &["## User: previous"], None);

        let malicious_target = fs::read_link(predictable_path).unwrap();
        fs::remove_file(predictable_path).unwrap();
        assert_eq!(malicious_target, secret.path());

        let (input, has_content) = result.unwrap();

        let edited_path = fs::read_to_string(path_report.path()).unwrap();
        let edited_path = Path::new(edited_path.trim());
        assert!(edited_path
            .file_name()
            .unwrap()
            .to_string_lossy()
            .starts_with("goose_prompt_"));
        assert_ne!(edited_path, Path::new(".goose_prompt_temp.md"));
        assert!(!edited_path.exists());
        assert_eq!(
            Path::new(fs::read_to_string(cwd_report.path()).unwrap().trim()),
            std::env::current_dir().unwrap()
        );
        assert_eq!(input, "updated prompt");
        assert!(!input.contains("TOP_SECRET_EXFIL_abc123"));
        assert!(has_content);
    }
}

#!/usr/bin/env python3
"""
Compare two CLI structure JSON files and output detected changes.

Usage:
    ./diff-cli-structures.py <old-file> <new-file> > output/cli-changes.json

Example:
    ./diff-cli-structures.py output/cli-structure-v1.14.0.json \
                            output/cli-structure-v1.15.0.json \
                            > output/cli-changes.json
"""

import sys
import json
from datetime import datetime, timezone
from typing import Dict, List


def get_command_path(command: Dict, parent_path: str = "") -> str:
    """Get the full path of a command (e.g., 'session list')."""
    if parent_path:
        return f"{parent_path} {command['name']}"
    return command['name']


def flatten_commands(commands: List[Dict], parent_path: str = "") -> Dict[str, Dict]:
    """
    Flatten nested command structure into a dict keyed by full command path.

    Returns:
        Dict mapping command path to command data
    """
    result = {}

    for cmd in commands:
        cmd_path = get_command_path(cmd, parent_path)
        # Store command without subcommands to avoid recursion in comparisons
        cmd_copy = cmd.copy()
        subcommands = cmd_copy.pop('subcommands', [])
        result[cmd_path] = cmd_copy

        # Recursively flatten subcommands
        if subcommands:
            result.update(flatten_commands(subcommands, cmd_path))

    return result


def compare_options(old_opts: List[Dict], new_opts: List[Dict]) -> Dict:
    """
    Compare two lists of options and detect changes.

    Returns dict with: added, removed, modified
    """
    # Create dicts keyed by long flag (or short if no long)
    old_opts_dict = {opt.get('long') or opt.get('short'): opt for opt in old_opts}
    new_opts_dict = {opt.get('long') or opt.get('short'): opt for opt in new_opts}

    old_keys = set(old_opts_dict.keys())
    new_keys = set(new_opts_dict.keys())

    added = []
    removed = []
    modified = []

    # Find added options
    for key in new_keys - old_keys:
        added.append(new_opts_dict[key])

    # Find removed options
    for key in old_keys - new_keys:
        removed.append(old_opts_dict[key])

    # Find modified options
    for key in old_keys & new_keys:
        old_opt = old_opts_dict[key]
        new_opt = new_opts_dict[key]

        changes = {}

        # Check each field for changes
        if old_opt.get('short') != new_opt.get('short'):
            changes['short'] = {'old': old_opt.get('short'), 'new': new_opt.get('short')}

        if old_opt.get('long') != new_opt.get('long'):
            changes['long'] = {'old': old_opt.get('long'), 'new': new_opt.get('long')}

        if old_opt.get('value_name') != new_opt.get('value_name'):
            changes['value_name'] = {'old': old_opt.get('value_name'), 'new': new_opt.get('value_name')}

        if old_opt.get('help') != new_opt.get('help'):
            changes['help'] = {'old': old_opt.get('help'), 'new': new_opt.get('help')}

        if old_opt.get('default') != new_opt.get('default'):
            changes['default'] = {'old': old_opt.get('default'), 'new': new_opt.get('default')}

        if old_opt.get('possible_values') != new_opt.get('possible_values'):
            changes['possible_values'] = {'old': old_opt.get('possible_values'), 'new': new_opt.get('possible_values')}

        if changes:
            modified.append({
                'option': key,
                'changes': changes
            })

    return {
        'added': added,
        'removed': removed,
        'modified': modified
    }


def compare_commands(old_cmds: Dict[str, Dict], new_cmds: Dict[str, Dict]) -> Dict:
    """
    Compare two command dictionaries and detect changes.

    Returns dict with: added, removed, modified
    """
    old_paths = set(old_cmds.keys())
    new_paths = set(new_cmds.keys())

    added = []
    removed = []
    modified = []

    # Find added commands
    for path in new_paths - old_paths:
        added.append({
            'command': path,
            'data': new_cmds[path]
        })

    # Find removed commands
    for path in old_paths - new_paths:
        removed.append({
            'command': path,
            'data': old_cmds[path]
        })

    # Find modified commands
    for path in old_paths & new_paths:
        old_cmd = old_cmds[path]
        new_cmd = new_cmds[path]

        changes = {}

        # Check about text
        if old_cmd.get('about') != new_cmd.get('about'):
            changes['about'] = {
                'old': old_cmd.get('about'),
                'new': new_cmd.get('about')
            }

        # Check aliases
        old_aliases = set(old_cmd.get('aliases', []))
        new_aliases = set(new_cmd.get('aliases', []))
        if old_aliases != new_aliases:
            changes['aliases'] = {
                'old': sorted(old_aliases),
                'new': sorted(new_aliases),
                'added': sorted(new_aliases - old_aliases),
                'removed': sorted(old_aliases - new_aliases)
            }

        # Check usage
        if old_cmd.get('usage') != new_cmd.get('usage'):
            changes['usage'] = {
                'old': old_cmd.get('usage'),
                'new': new_cmd.get('usage')
            }

        # Check options
        option_changes = compare_options(
            old_cmd.get('options', []),
            new_cmd.get('options', [])
        )
        if any(option_changes.values()):
            changes['options'] = option_changes

        if changes:
            modified.append({
                'command': path,
                'changes': changes
            })

    return {
        'added': added,
        'removed': removed,
        'modified': modified
    }


def categorize_breaking_changes(changes: Dict) -> List[Dict]:
    """
    Identify changes that are likely breaking changes.

    Returns list of breaking change descriptions.
    """
    breaking = []

    # Removed commands are breaking
    for item in changes['commands']['removed']:
        breaking.append({
            'type': 'command_removed',
            'command': item['command'],
            'severity': 'high',
            'description': f"Command '{item['command']}' was removed"
        })

    # Check modified commands for breaking changes
    for item in changes['commands']['modified']:
        cmd = item['command']
        cmd_changes = item['changes']

        # Removed options are breaking
        if 'options' in cmd_changes:
            for opt in cmd_changes['options']['removed']:
                opt_name = f"--{opt.get('long')}" if opt.get('long') else f"-{opt.get('short')}"
                breaking.append({
                    'type': 'option_removed',
                    'command': cmd,
                    'option': opt_name,
                    'severity': 'high',
                    'description': f"Option '{opt_name}' removed from '{cmd}'"
                })

            # Changed option flags are breaking
            for mod in cmd_changes['options']['modified']:
                if 'short' in mod['changes'] or 'long' in mod['changes']:
                    breaking.append({
                        'type': 'option_renamed',
                        'command': cmd,
                        'option': mod['option'],
                        'severity': 'high',
                        'description': f"Option flags changed in '{cmd}': {mod['option']}"
                    })

                # Changed default values might be breaking
                if 'default' in mod['changes']:
                    breaking.append({
                        'type': 'default_changed',
                        'command': cmd,
                        'option': mod['option'],
                        'severity': 'medium',
                        'description': f"Default value changed for '{cmd} --{mod['option']}'"
                    })

                # Removed possible values are breaking
                if 'possible_values' in mod['changes']:
                    old_vals = set(mod['changes']['possible_values']['old'] or [])
                    new_vals = set(mod['changes']['possible_values']['new'] or [])
                    removed_vals = old_vals - new_vals
                    if removed_vals:
                        breaking.append({
                            'type': 'enum_values_removed',
                            'command': cmd,
                            'option': mod['option'],
                            'severity': 'high',
                            'description': f"Possible values removed from '{cmd} --{mod['option']}': {', '.join(removed_vals)}"
                        })

        # Removed aliases might be breaking (users might rely on them)
        if 'aliases' in cmd_changes and cmd_changes['aliases']['removed']:
            for alias in cmd_changes['aliases']['removed']:
                breaking.append({
                    'type': 'alias_removed',
                    'command': cmd,
                    'alias': alias,
                    'severity': 'medium',
                    'description': f"Alias '{alias}' removed from '{cmd}'"
                })

    return breaking


def main():
    if len(sys.argv) != 3:
        print("Usage: diff-cli-structures.py <old-file> <new-file>", file=sys.stderr)
        print("Example: diff-cli-structures.py old.json new.json", file=sys.stderr)
        sys.exit(1)

    old_file = sys.argv[1]
    new_file = sys.argv[2]

    # Load JSON files
    try:
        with open(old_file, 'r') as f:
            old_data = json.load(f)
    except Exception as e:
        print(f"Error reading {old_file}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(new_file, 'r') as f:
            new_data = json.load(f)
    except Exception as e:
        print(f"Error reading {new_file}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Comparing {old_data['version']} → {new_data['version']}...", file=sys.stderr)

    # Flatten command structures
    old_commands = flatten_commands(old_data['commands'])
    new_commands = flatten_commands(new_data['commands'])

    print(f"Old version: {len(old_commands)} commands", file=sys.stderr)
    print(f"New version: {len(new_commands)} commands", file=sys.stderr)

    # Compare commands
    command_changes = compare_commands(old_commands, new_commands)

    # Categorize breaking changes
    breaking_changes = categorize_breaking_changes({'commands': command_changes})

    # Determine if there are any changes
    has_changes = (
        len(command_changes['added']) > 0 or
        len(command_changes['removed']) > 0 or
        len(command_changes['modified']) > 0
    )

    # Build output
    now = datetime.now(timezone.utc).isoformat().replace('+00:00', 'Z')

    output = {
        'old_version': old_data['version'],
        'new_version': new_data['version'],
        'compared_at': now,
        'has_changes': has_changes,
        'summary': {
            'commands_added': len(command_changes['added']),
            'commands_removed': len(command_changes['removed']),
            'commands_modified': len(command_changes['modified']),
            'breaking_changes': len([b for b in breaking_changes if b['severity'] == 'high'])
        },
        'changes': {
            'commands': command_changes
        },
        'breaking_changes': breaking_changes
    }

    # Output JSON
    print(json.dumps(output, indent=2))

    # Print summary to stderr
    print(f"\nSummary:", file=sys.stderr)
    print(f"  Commands added: {output['summary']['commands_added']}", file=sys.stderr)
    print(f"  Commands removed: {output['summary']['commands_removed']}", file=sys.stderr)
    print(f"  Commands modified: {output['summary']['commands_modified']}", file=sys.stderr)
    print(f"  Breaking changes: {output['summary']['breaking_changes']}", file=sys.stderr)


if __name__ == '__main__':
    main()

use goose::agents::subagent_execution_tool::lib::TaskStatus;
use goose::agents::subagent_execution_tool::notification_events::{
    TaskExecutionNotificationEvent, TaskInfo,
};
use goose::utils::safe_truncate;
use serde_json::Value;
use std::sync::atomic::{AtomicBool, Ordering};

#[cfg(test)]
mod tests;

pub const TASK_EXECUTION_NOTIFICATION_TYPE: &str = "task_execution";

static INITIAL_SHOWN: AtomicBool = AtomicBool::new(false);

fn format_result_data_for_display(result_data: &Value) -> String {
    match result_data {
        Value::String(s) => s.to_string(),
        Value::Object(obj) => {
            if let Some(partial_output) = obj.get("partial_output").and_then(|v| v.as_str()) {
                format!("Partial output: {}", partial_output)
            } else {
                serde_json::to_string_pretty(obj).unwrap_or_default()
            }
        }
        Value::Array(arr) => serde_json::to_string_pretty(arr).unwrap_or_default(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => "null".to_string(),
    }
}

fn process_output_for_display(output: &str) -> String {
    const MAX_OUTPUT_LINES: usize = 2;
    const OUTPUT_PREVIEW_LENGTH: usize = 100;

    let lines: Vec<&str> = output.lines().collect();
    let recent_lines = if lines.len() > MAX_OUTPUT_LINES {
        &lines[lines.len() - MAX_OUTPUT_LINES..]
    } else {
        &lines
    };

    let clean_output = recent_lines.join(" ... ");
    safe_truncate(&clean_output, OUTPUT_PREVIEW_LENGTH)
}

pub fn format_task_execution_notification(
    data: &Value,
) -> Option<(String, Option<String>, Option<String>)> {
    if let Ok(event) = serde_json::from_value::<TaskExecutionNotificationEvent>(data.clone()) {
        return Some(match event {
            TaskExecutionNotificationEvent::LineOutput { output, .. } => (
                format!("{}\n", output),
                None,
                Some(TASK_EXECUTION_NOTIFICATION_TYPE.to_string()),
            ),
            TaskExecutionNotificationEvent::TasksUpdate { .. } => {
                let formatted_display = format_tasks_update_from_event(&event);
                (
                    formatted_display,
                    None,
                    Some(TASK_EXECUTION_NOTIFICATION_TYPE.to_string()),
                )
            }
            TaskExecutionNotificationEvent::TasksComplete { .. } => {
                let formatted_summary = format_tasks_complete_from_event(&event);
                (
                    formatted_summary,
                    None,
                    Some(TASK_EXECUTION_NOTIFICATION_TYPE.to_string()),
                )
            }
        });
    }
    None
}

fn format_tasks_update_from_event(event: &TaskExecutionNotificationEvent) -> String {
    if let TaskExecutionNotificationEvent::TasksUpdate { stats, tasks } = event {
        let mut display = String::new();

        if !INITIAL_SHOWN.swap(true, Ordering::SeqCst) {
            display.push_str("🎯 Task Execution Dashboard\n");
            display.push_str("═══════════════════════════\n\n");
        }

        display.push_str(&format!(
            "📊 Progress: {} total | ⏳ {} pending | 🏃 {} running | ✅ {} completed | ❌ {} failed\n\n",
            stats.total, stats.pending, stats.running, stats.completed, stats.failed
        ));

        let mut sorted_tasks = tasks.clone();
        sorted_tasks.sort_by(|a, b| a.id.cmp(&b.id));

        for task in sorted_tasks {
            display.push_str(&format_task_display(&task));
        }

        display
    } else {
        String::new()
    }
}

fn format_tasks_complete_from_event(event: &TaskExecutionNotificationEvent) -> String {
    if let TaskExecutionNotificationEvent::TasksComplete {
        stats,
        failed_tasks,
    } = event
    {
        let mut summary = String::new();
        summary.push_str("Execution Complete!\n");
        summary.push_str("═══════════════════════\n");

        summary.push_str(&format!("Total Tasks: {}\n", stats.total));
        summary.push_str(&format!("✅ Completed: {}\n", stats.completed));
        summary.push_str(&format!("❌ Failed: {}\n", stats.failed));
        summary.push_str(&format!("📈 Success Rate: {:.1}%\n", stats.success_rate));

        if !failed_tasks.is_empty() {
            summary.push_str("\n❌ Failed Tasks:\n");
            for task in failed_tasks {
                summary.push_str(&format!("   • {}\n", task.name));
                if let Some(error) = &task.error {
                    summary.push_str(&format!("     Error: {}\n", error));
                }
            }
        }

        summary.push_str("\n📝 Generating summary...\n");
        summary
    } else {
        String::new()
    }
}

fn format_task_display(task: &TaskInfo) -> String {
    let mut task_display = String::new();

    let status_icon = match task.status {
        TaskStatus::Pending => "⏳",
        TaskStatus::Running => "🏃",
        TaskStatus::Completed => "✅",
        TaskStatus::Failed => "❌",
    };

    task_display.push_str(&format!(
        "{} {} ({})\n",
        status_icon, task.task_name, task.task_type
    ));

    if !task.task_metadata.is_empty() {
        task_display.push_str(&format!("   📋 Parameters: {}\n", task.task_metadata));
    }

    if let Some(duration_secs) = task.duration_secs {
        task_display.push_str(&format!("   ⏱️  {:.1}s\n", duration_secs));
    }

    if matches!(task.status, TaskStatus::Running) && !task.current_output.trim().is_empty() {
        let processed_output = process_output_for_display(&task.current_output);
        if !processed_output.is_empty() {
            task_display.push_str(&format!("   💬 {}\n", processed_output));
        }
    }

    if matches!(task.status, TaskStatus::Completed) {
        if let Some(result_data) = &task.result_data {
            let result_preview = format_result_data_for_display(result_data);
            if !result_preview.is_empty() {
                task_display.push_str(&format!("   📄 {}\n", result_preview));
            }
        }
    }

    if matches!(task.status, TaskStatus::Failed) {
        if let Some(error) = &task.error {
            let error_preview = safe_truncate(error, 80);
            task_display.push_str(&format!("   ⚠️  {}\n", error_preview.replace('\n', " ")));
        }
    }

    task_display.push('\n');
    task_display
}

use crate::conversation::message::Message;
use crate::conversation::Conversation;
use crate::providers::base::ProviderUsage;
use crate::recipe::Recipe;
use crate::session::ExtensionData;
use goose_agent::operation::{ConversationEffect, MachineEffect};

pub enum GooseEffect {
    Conversation(ConversationEffect),
    CompactConversation {
        conversation: Conversation,
        usage: Option<ProviderUsage>,
    },
    SetRecipe(Box<Option<Recipe>>),
    SetExtensionData(ExtensionData),
    RecordUsage(ProviderUsage),
}

impl MachineEffect for GooseEffect {
    fn ensure_message_ids(&mut self) {
        match self {
            GooseEffect::Conversation(effect) => effect.ensure_message_ids(),
            GooseEffect::CompactConversation { conversation, .. } => {
                for message in conversation.messages_mut() {
                    if message.id.is_none() {
                        message.id = Some(format!("msg_{}", uuid::Uuid::new_v4()));
                    }
                }
            }
            _ => {}
        }
    }
}

impl From<ConversationEffect> for GooseEffect {
    fn from(effect: ConversationEffect) -> Self {
        GooseEffect::Conversation(effect)
    }
}

impl From<Message> for GooseEffect {
    fn from(message: Message) -> Self {
        ConversationEffect::from(message).into()
    }
}

impl From<Conversation> for GooseEffect {
    fn from(conversation: Conversation) -> Self {
        ConversationEffect::from(conversation).into()
    }
}

import { Fragment, memo, useEffect, useMemo, useRef, useState } from 'react';
import { isEqual } from 'lodash';
import { defineMessages, useIntl } from '../i18n';
import GooseMessage from './GooseMessage';
import UserMessage from './UserMessage';
import {
  SystemNotificationInline,
  getInlineSystemNotification,
} from './context_management/SystemNotificationInline';
import {
  CreditsExhaustedNotification,
  getCreditsExhaustedNotification,
} from './context_management/CreditsExhaustedNotification';
import type {
  ImageData,
  Message,
  NotificationEvent,
  SystemNotificationContent,
} from '../types/message';
import LoadingGoose from './LoadingGoose';
import { getModelDisplayName } from './settings/models/predefinedModelsUtils';
import { deriveMessageRowContexts, type MessageRowContext } from './messageRowContext';

const i18n = defineMessages({
  loadingMessages: {
    id: 'progressiveMessageList.loadingMessages',
    defaultMessage: 'Loading messages... ({renderedCount}/{totalCount})',
  },
  searchHint: {
    id: 'progressiveMessageList.searchHint',
    defaultMessage: 'Press Cmd/Ctrl+F to load all messages immediately for search',
  },
  modelChanged: {
    id: 'progressiveMessageList.modelChanged',
    defaultMessage: 'Model changed: {previousModel} → {currentModel}',
  },
});

const emptyToolCallNotifications = new Map<string, NotificationEvent[]>();
const emptyAppend = () => {};

function getResolvedModel(message: Message): string | null {
  if (message.role !== 'assistant' || !message.metadata.userVisible) return null;
  return message.metadata.inference?.resolvedModel ?? null;
}

function getSystemNotification(message: Message): SystemNotificationContent | undefined {
  return getCreditsExhaustedNotification(message) ?? getInlineSystemNotification(message);
}

function renderSystemNotification(notification: SystemNotificationContent) {
  switch (notification.notificationType) {
    case 'creditsExhausted':
      return <CreditsExhaustedNotification notification={notification} />;
    case 'inlineMessage':
      return <SystemNotificationInline notification={notification} />;
    default:
      return null;
  }
}

interface MessageRowProps {
  append: (value: string) => void;
  index: number;
  isStreaming: boolean;
  isUser: boolean;
  message: Message;
  modelChangeMessage: string | null;
  onMessageUpdate?: (
    messageId: string,
    newContent: string,
    editType: 'fork' | 'edit',
    retainedImages: ImageData[]
  ) => void;
  rowContext: MessageRowContext;
  sessionId: string;
  submitElicitationResponse?: (
    elicitationId: string,
    userData: Record<string, unknown>
  ) => Promise<boolean>;
  toolNotifications: readonly (NotificationEvent[] | undefined)[];
}

function MessageRowComponent({
  append,
  index,
  isStreaming,
  isUser,
  message,
  modelChangeMessage,
  onMessageUpdate,
  rowContext,
  sessionId,
  submitElicitationResponse,
  toolNotifications,
}: MessageRowProps) {
  const notification = getSystemNotification(message);

  if (notification) {
    return (
      <div
        className={`relative ${index === 0 ? 'mt-0' : 'mt-4'} assistant`}
        data-testid="message-container"
      >
        {renderSystemNotification(notification)}
      </div>
    );
  }

  const hasOnlyToolResponses = message.content.every((content) => content.type === 'toolResponse');

  return (
    <Fragment>
      {modelChangeMessage && (
        <SystemNotificationInline
          notification={{
            msg: modelChangeMessage,
            notificationType: 'inlineMessage',
          }}
        />
      )}
      <div
        className={`relative ${index === 0 ? 'mt-0' : 'mt-4'} ${isUser ? 'user' : 'assistant'} ${rowContext.isInToolCallChain ? 'in-chain' : ''}`}
        data-testid="message-container"
      >
        {isUser ? (
          !hasOnlyToolResponses && (
            <UserMessage message={message} onMessageUpdate={onMessageUpdate} />
          )
        ) : (
          <GooseMessage
            sessionId={sessionId}
            message={message}
            hideTimestamp={rowContext.hideTimestamp}
            toolStates={rowContext.toolStates}
            toolNotifications={toolNotifications}
            toolConfirmationShownInline={rowContext.toolConfirmationShownInline}
            append={append}
            isStreaming={isStreaming}
            submitElicitationResponse={submitElicitationResponse}
          />
        )}
      </div>
    </Fragment>
  );
}

const MessageRow = memo(MessageRowComponent, isEqual);

interface ProgressiveMessageListProps {
  messages: Message[];
  sessionId: string;
  toolCallNotifications?: Map<string, NotificationEvent[]>;
  append?: (value: string) => void;
  isUserMessage: (message: Message) => boolean;
  batchSize?: number;
  batchDelay?: number;
  showLoadingThreshold?: number;
  renderMessage?: (message: Message, index: number) => React.ReactNode | null;
  isStreamingMessage?: boolean;
  onMessageUpdate?: (
    messageId: string,
    newContent: string,
    editType: 'fork' | 'edit',
    retainedImages: ImageData[]
  ) => void;
  onRenderingComplete?: () => void;
  submitElicitationResponse?: (
    elicitationId: string,
    userData: Record<string, unknown>
  ) => Promise<boolean>;
}

export default function ProgressiveMessageList({
  messages,
  sessionId,
  toolCallNotifications = emptyToolCallNotifications,
  append = emptyAppend,
  isUserMessage,
  batchSize = 5,
  batchDelay = 20,
  showLoadingThreshold = 50,
  renderMessage,
  isStreamingMessage = false,
  onMessageUpdate,
  onRenderingComplete,
  submitElicitationResponse,
}: ProgressiveMessageListProps) {
  const intl = useIntl();
  const [renderedCount, setRenderedCount] = useState(() =>
    messages.length <= showLoadingThreshold ? messages.length : Math.min(batchSize, messages.length)
  );
  const completedMessageKeyRef = useRef<string | null>(null);
  const isLoading = renderedCount < messages.length;

  useEffect(() => {
    if (messages.length <= showLoadingThreshold) {
      setRenderedCount(messages.length);
      return;
    }

    if (!isLoading) return;

    const timeout = window.setTimeout(() => {
      setRenderedCount((current) => Math.min(current + batchSize, messages.length));
    }, batchDelay);

    return () => window.clearTimeout(timeout);
  }, [batchDelay, batchSize, isLoading, messages.length, renderedCount, showLoadingThreshold]);

  useEffect(() => {
    if (isLoading) return;

    const completedMessageKey = `${sessionId}:${messages.length}`;
    if (completedMessageKeyRef.current === completedMessageKey) return;

    const timeout = window.setTimeout(() => {
      completedMessageKeyRef.current = completedMessageKey;
      onRenderingComplete?.();
    }, 50);

    return () => window.clearTimeout(timeout);
  }, [isLoading, messages.length, onRenderingComplete, sessionId]);

  useEffect(() => {
    if (!isLoading) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      const isMac = window.electron.platform === 'darwin';
      const isSearchShortcut = (isMac ? event.metaKey : event.ctrlKey) && event.key === 'f';

      if (isSearchShortcut) {
        setRenderedCount(messages.length);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isLoading, messages.length]);

  const rowContexts = useMemo(() => deriveMessageRowContexts(messages), [messages]);
  const messagesToRender = messages.slice(0, renderedCount);
  const messageRows = messagesToRender
    .map((message, index) => {
      if (!message.metadata.userVisible) return null;
      if (renderMessage) return renderMessage(message, index);

      const isUser = isUserMessage(message);
      const messageIdentifier = message.id ?? `msg-${index}-${message.created}`;
      const messageKey = getSystemNotification(message)
        ? `notification-${messageIdentifier}`
        : messageIdentifier;
      const rowContext = rowContexts[index];
      const currentResolvedModel = getResolvedModel(message);
      const modelChangeMessage =
        currentResolvedModel &&
        rowContext.previousResolvedModel &&
        currentResolvedModel !== rowContext.previousResolvedModel
          ? intl.formatMessage(i18n.modelChanged, {
              previousModel: getModelDisplayName(rowContext.previousResolvedModel),
              currentModel: getModelDisplayName(currentResolvedModel),
            })
          : null;
      const toolNotifications = rowContext.toolStates.map((toolState) =>
        toolCallNotifications.get(toolState.requestId)
      );

      return (
        <MessageRow
          key={messageKey}
          append={append}
          index={index}
          isStreaming={
            isStreamingMessage &&
            !isUser &&
            index === messagesToRender.length - 1 &&
            message.role === 'assistant'
          }
          isUser={isUser}
          message={message}
          modelChangeMessage={modelChangeMessage}
          onMessageUpdate={onMessageUpdate}
          rowContext={rowContext}
          sessionId={sessionId}
          submitElicitationResponse={submitElicitationResponse}
          toolNotifications={toolNotifications}
        />
      );
    })
    .filter(Boolean);

  return (
    <>
      {messageRows}

      {isLoading && (
        <div className="flex flex-col items-center justify-center py-8">
          <LoadingGoose
            message={intl.formatMessage(i18n.loadingMessages, {
              renderedCount,
              totalCount: messages.length,
            })}
          />
          <div className="text-xs text-text-secondary mt-2">
            {intl.formatMessage(i18n.searchHint)}
          </div>
        </div>
      )}
    </>
  );
}

use goose_provider_types::conversation::{
    message::{Message, MessageUsage},
    token_usage::ProviderUsage,
    Conversation,
};
use rmcp::model::ServerNotification;

#[derive(Clone, Debug)]
pub enum AgentEvent {
    Message(Message),
    Usage(ProviderUsage),
    MessageUsage {
        message_id: Option<String>,
        usage: MessageUsage,
    },
    McpNotification((String, ServerNotification)),
    HistoryReplaced(Conversation),
}

//! Structured provider request/response observability for GDK callers.
//!
//! Kotlin and Python consumers register an [`ObservabilityHook`] to receive
//! typed lifecycle events (start, response metadata, completion) for both
//! streaming and non-streaming provider calls instead of scraping logs.
//!
//! Hooks are opt-in: with no hook registered nothing is emitted and no work is
//! performed on the request path. The hook is invoked synchronously, wrapped in
//! `catch_unwind` so a throwing foreign callback cannot fail the request.

use std::{
    panic::{catch_unwind, AssertUnwindSafe},
    sync::{
        atomic::{AtomicBool, AtomicU64, Ordering},
