/**
 * Tests for the iOS Enter + text-replacement acceptance boundary.
 *
 * $maybeMoveSelectionPastTrailingAcceptanceBoundary compensates for Chrome and
 * Firefox, which fire the input event for the key press that triggered the
 * acceptance *before* the one for the replacement text, leaving the caret before
 * the acceptance boundary.
 *
 * iOS fires them in the opposite order — insertReplacementText first, then
 * insertParagraph. The paragraph has therefore not been split yet, so the block
 * the caret sits in still has its original next sibling. Moving the caret there
 * makes the following insertParagraph split *that* block instead, leaving the
 * caret one block further down than a single Enter should have taken it.
 */

import {buildEditorFromExtensions} from '@lexical/extension';
import {RichTextExtension} from '@lexical/rich-text';
import {
  $createParagraphNode,
  $createTextNode,
  $getRoot,
  $getSelection,
  $isRangeSelection,
  $isTextNode,
  isDOMTextNode,
  isHTMLElement,
  type LexicalEditor,
  type LexicalEditorWithDispose,
} from 'lexical';
import {$assertNodeType} from 'lexical/src/__tests__/utils';
import {assert, describe, expect, test, vi} from 'vitest';

// `vi.mock` is hoisted above all imports, so LexicalEvents.ts observes
// IS_IOS=true and CAN_USE_BEFORE_INPUT=true.
vi.mock('lexical/src/environment', () => ({
  CAN_USE_BEFORE_INPUT: true,
  CAN_USE_DOM: true,
  IS_ANDROID: false,
  IS_ANDROID_CHROME: false,
  IS_APPLE: true,
  IS_APPLE_WEBKIT: true,
  IS_CHROME: false,
  IS_FIREFOX: false,
  IS_IOS: true,
  IS_SAFARI: true,
}));

function createBeforeInputEvent(
  inputType: string,
  {
    data,
    dataTransferText,
    targetRanges = [],
  }: {
    data?: string;
    dataTransferText?: string;
    targetRanges?: StaticRange[];
  } = {},
): InputEvent {
  const event = new InputEvent('beforeinput', {
    bubbles: true,
    cancelable: true,
    data,
    inputType,
  });
  // jsdom's InputEvent exposes neither of these; patch them manually.
  Object.defineProperty(event, 'getTargetRanges', {
    value: () => targetRanges,
  });
  if (dataTransferText !== undefined) {
    Object.defineProperty(event, 'dataTransfer', {
      value: {
        getData: (type: string) =>
          type === 'text/plain' ? dataTransferText : '',
      },
    });
  }
  return event;
}

/**
 * A paragraph containing "Abc" with the caret at its end, optionally followed by
 * another paragraph. The following block is what makes the bug observable — with
 * nothing after it, getNextSibling() is null and the correction is a no-op.
 */
function editorWithParagraphs(
  followingParagraphText: string | null,
): LexicalEditorWithDispose {
  return buildEditorFromExtensions({
    $initialEditorState: () => {
      const first = $createTextNode('Abc');
      $getRoot().append($createParagraphNode().append(first));
      if (followingParagraphText !== null) {
        $getRoot().append(
          $createParagraphNode().append(
            $createTextNode(followingParagraphText),
          ),
        );
      }
      first.select(3, 3);
    },
    afterRegistration: editor => {
      const container = document.createElement('div');
      container.setAttribute('data-lexical-editor', 'true');
      container.contentEditable = 'true';
      document.body.appendChild(container);
      editor.setRootElement(container);
      return () => {
        editor.setRootElement(null);
        document.body.removeChild(container);
      };
    },
    dependencies: [RichTextExtension],
    name: '[test]',
  });
}

/** The DOM text node backing the editor's first text node. */
function firstDOMTextNode(editor: LexicalEditor): Text {
  return editor.read('latest', () => {
    const node = $assertNodeType($getRoot().getFirstDescendant(), $isTextNode);
    const el = editor.getElementByKey(node.getKey());
    assert(isHTMLElement(el));
    const textNode = el.firstChild;
    assert(isDOMTextNode(textNode));
    return textNode;
  });
}

/**
 * Replays the event sequence iOS produces when Enter accepts the "Abc" -> "ABC"
 * replacement: keydown Enter, then insertReplacementText, then insertParagraph.
 */
function acceptReplacementWithEnter(editor: LexicalEditor): void {
  const root = editor.getRootElement()!;
  const domText = firstDOMTextNode(editor);

  root.dispatchEvent(
    new KeyboardEvent('keydown', {
      bubbles: true,
      cancelable: true,
      key: 'Enter',
    }),
  );
  root.dispatchEvent(
    createBeforeInputEvent('insertReplacementText', {
      // The replacement covers the whole "Abc" that the user typed.
      dataTransferText: 'ABC',
      targetRanges: [
        new StaticRange({
          endContainer: domText,
          endOffset: 3,
          startContainer: domText,
          startOffset: 0,
        }),
      ],
    }),
  );
  root.dispatchEvent(createBeforeInputEvent('insertParagraph'));
}

describe('iOS Enter accepting a text replacement', () => {
  test('leaves the caret in the new paragraph when a block already follows', () => {
    using editor = editorWithParagraphs('Zzz');

    acceptReplacementWithEnter(editor);

    editor.read('force-commit', () => {
      const children = $getRoot().getChildren();
      expect(children.map(child => child.getTextContent())).toEqual([
        'ABC',
        '',
        'Zzz',
      ]);

      const selection = $getSelection();
      expect($isRangeSelection(selection)).toBe(true);
      if (!$isRangeSelection(selection)) {
        return;
      }
      // The caret must land in the newly inserted middle paragraph — not in the
      // "Zzz" block that already followed.
      expect(selection.anchor.getNode().getKey()).toBe(children[1].getKey());
      expect(selection.anchor.offset).toBe(0);
    });
  });

  test('is unchanged when the paragraph is the last block', () => {
    // getNextSibling() is null here, so the correction was already a no-op and
    // this case behaved correctly before the fix. Pinned so a future change to
    // the guard cannot regress it.
    using editor = editorWithParagraphs(null);

    acceptReplacementWithEnter(editor);

    editor.read('force-commit', () => {
      const children = $getRoot().getChildren();
      expect(children.map(child => child.getTextContent())).toEqual([
        'ABC',
        '',
      ]);

      const selection = $getSelection();
      expect($isRangeSelection(selection)).toBe(true);
      if (!$isRangeSelection(selection)) {
        return;
      }
      expect(selection.anchor.getNode().getKey()).toBe(children[1].getKey());
      expect(selection.anchor.offset).toBe(0);
    });
  });
});

import {Fragment, Slice, Node, ResolvedPos, NodeType, ContentMatch, Attrs} from "prosemirror-model"

import {Step} from "./step"
import {ReplaceStep, ReplaceAroundStep} from "./replace_step"
import {Transform} from "./transform"
import {insertPoint} from "./structure"

/// ‘Fit’ a slice into a given position in the document, producing a
/// [step](#transform.Step) that inserts it. Will return null if
/// there's no meaningful way to insert the slice here, or inserting it
/// would be a no-op (an empty slice over an empty range).
export function replaceStep(doc: Node, from: number, to = from, slice = Slice.empty): Step | null {
  if (from == to && !slice.size) return null

  let $from = doc.resolve(from), $to = doc.resolve(to)
  // Optimization -- avoid work if it's obvious that it's not needed.
  if (fitsTrivially($from, $to, slice)) return new ReplaceStep(from, to, slice)
  return new Fitter($from, $to, slice).fit()
}

function fitsTrivially($from: ResolvedPos, $to: ResolvedPos, slice: Slice) {
  return !slice.openStart && !slice.openEnd && $from.start() == $to.start() &&
    $from.parent.canReplace($from.index(), $to.index(), slice.content)
}

interface Fittable {
  sliceDepth: number
  frontierDepth: number
  parent: Node | null
  inject?: Fragment | null
  wrap?: readonly NodeType[]
}

// Algorithm for 'placing' the elements of a slice into a gap:
//
// We consider the content of each node that is open to the left to be
// independently placeable. I.e. in <p("foo"), p("bar")>, when the
// paragraph on the left is open, "foo" can be placed (somewhere on
// the left side of the replacement gap) independently from p("bar").
//
// This class tracks the state of the placement progress in the
// following properties:
//
//  - `frontier` holds a stack of `{type, match}` objects that
//    represent the open side of the replacement. It starts at
//    `$from`, then moves forward as content is placed, and is finally
//    reconciled with `$to`.
//
//  - `unplaced` is a slice that represents the content that hasn't
//    been placed yet.
//
//  - `placed` is a fragment of placed content. Its open-start value
//    is implicit in `$from`, and its open-end value in `frontier`.
class Fitter {
  frontier: {type: NodeType, match: ContentMatch}[] = []
  placed: Fragment = Fragment.empty

  constructor(
    readonly $from: ResolvedPos,
    readonly $to: ResolvedPos,
    public unplaced: Slice
  ) {
    for (let i = 0; i <= $from.depth; i++) {
      let node = $from.node(i)
      this.frontier.push({
        type: node.type,
        match: node.contentMatchAt($from.indexAfter(i))
      })
    }

    for (let i = $from.depth; i > 0; i--)
      this.placed = Fragment.from($from.node(i).copy(this.placed))
  }

  get depth() { return this.frontier.length - 1 }

  fit() {
    // As long as there's unplaced content, try to place some of it.
    // If that fails, either increase the open score of the unplaced
    // slice, or drop nodes from it, and then try again.
    while (this.unplaced.size) {
      let fit = this.findFittable()
      if (fit) this.placeNodes(fit)
      else this.openMore() || this.dropNode()
    }
    // When there's inline content directly after the frontier _and_
    // directly after `this.$to`, we must generate a `ReplaceAround`
    // step that pulls that content into the node after the frontier.
    // That means the fitting must be done to the end of the textblock
    // node after `this.$to`, not `this.$to` itself.
    let moveInline = this.mustMoveInline(), placedSize = this.placed.size - this.depth - this.$from.depth
    let $from = this.$from, $to = this.close(moveInline < 0 ? this.$to : $from.doc.resolve(moveInline))
    if (!$to) return null

    // If closing to `$to` succeeded, create a step
    let content = this.placed, openStart = $from.depth, openEnd = $to.depth
    while (openStart && openEnd && content.childCount == 1) { // Normalize by dropping open parent nodes
      content = content.firstChild!.content
      openStart--; openEnd--
    }
    let slice = new Slice(content, openStart, openEnd)
    if (moveInline > -1)
      return new ReplaceAroundStep($from.pos, moveInline, this.$to.pos, this.$to.end(), slice, placedSize)
    if (slice.size || $from.pos != this.$to.pos) // Don't generate no-op steps
      return new ReplaceStep($from.pos, $to.pos, slice)
    return null
  }

  // Find a position on the start spine of `this.unplaced` that has
  // content that can be moved somewhere on the frontier. Returns two
  // depths, one for the slice and one for the frontier.
  findFittable(): Fittable | undefined {
    let startDepth = this.unplaced.openStart
    for (let cur = this.unplaced.content, d = 0, openEnd = this.unplaced.openEnd; d < startDepth; d++) {
      let node = cur.firstChild!
      if (cur.childCount > 1) openEnd = 0
      if (node.type.spec.isolating && openEnd <= d) {
        startDepth = d
        break
      }
      cur = node.content
    }

    // Only try wrapping nodes (pass 2) after finding a place without
    // wrapping failed.
    for (let pass = 1; pass <= 2; pass++) {
      for (let sliceDepth = pass == 1 ? startDepth : this.unplaced.openStart; sliceDepth >= 0; sliceDepth--) {
        let fragment, parent = null
        if (sliceDepth) {
          parent = contentAt(this.unplaced.content, sliceDepth - 1).firstChild
          fragment = parent!.content
        } else {
          fragment = this.unplaced.content
        }
        let first = fragment.firstChild
        for (let frontierDepth = this.depth; frontierDepth >= 0; frontierDepth--) {
          let {type, match} = this.frontier[frontierDepth], wrap, inject: Fragment | null = null
          // In pass 1, if the next node matches, or there is no next
          // node but the parents look compatible, we've found a
          // place.
          if (pass == 1 && (first ? match.matchType(first.type) || (inject = match.fillBefore(Fragment.from(first), false))
                            : parent && type.compatibleContent(parent.type)))
            return {sliceDepth, frontierDepth, parent, inject}
          // In pass 2, look for a set of wrapping nodes that make
          // `first` fit here.
          else if (pass == 2 && first && (wrap = match.findWrapping(first.type)))
            return {sliceDepth, frontierDepth, parent, wrap}
          // Don't continue looking further up if the parent node
          // would fit here.
          if (parent && match.matchType(parent.type)) break
        }
      }
    }
  }

  openMore() {
    let {content, openStart, openEnd} = this.unplaced
    let inner = contentAt(content, openStart)
    if (!inner.childCount || inner.firstChild!.isLeaf) return false
    this.unplaced = new Slice(content, openStart + 1,
                              Math.max(openEnd, inner.size + openStart >= content.size - openEnd ? openStart + 1 : 0))
    return true
  }

  dropNode() {
    let {content, openStart, openEnd} = this.unplaced
    let inner = contentAt(content, openStart)
    if (inner.childCount <= 1 && openStart > 0) {
      let openAtEnd = content.size - openStart <= openStart + inner.size
      this.unplaced = new Slice(dropFromFragment(content, openStart - 1, 1), openStart - 1,
                                openAtEnd ? openStart - 1 : openEnd)
    } else {
      this.unplaced = new Slice(dropFromFragment(content, openStart, 1), openStart, openEnd)
    }
  }

  // Move content from the unplaced slice at `sliceDepth` to the
  // frontier node at `frontierDepth`. Close that frontier node when
  // applicable.
  placeNodes({sliceDepth, frontierDepth, parent, inject, wrap}: Fittable) {
    while (this.depth > frontierDepth) this.closeFrontierNode()
    if (wrap) for (let i = 0; i < wrap.length; i++) this.openFrontierNode(wrap[i])

    let slice = this.unplaced, fragment = parent ? parent.content : slice.content
    let openStart = slice.openStart - sliceDepth
    let taken = 0, add = []
    let {match, type} = this.frontier[frontierDepth]
    if (inject) {
      for (let i = 0; i < inject.childCount; i++) add.push(inject.child(i))
      match = match.matchFragment(inject)!
    }
    // Computes the amount of (end) open nodes at the end of the
    // fragment. When 0, the parent is open, but no more. When
    // negative, nothing is open.
    let openEndCount = (fragment.size + sliceDepth) - (slice.content.size - slice.openEnd)
    // Scan over the fragment, fitting as many child nodes as
    // possible.
    while (taken < fragment.childCount) {
      let next = fragment.child(taken), matches = match.matchType(next.type)
      if (!matches) break
      taken++
      if (taken > 1 || openStart == 0 || next.content.size) { // Drop empty open nodes
        match = matches
        add.push(closeNodeStart(next.mark(type.allowedMarks(next.marks)), taken == 1 ? openStart : 0,
                                taken == fragment.childCount ? openEndCount : -1))
      }
    }
    let toEnd = taken == fragment.childCount
    if (!toEnd) openEndCount = -1

    this.placed = addToFragment(this.placed, frontierDepth, Fragment.from(add))
    this.frontier[frontierDepth].match = match

    // If the parent types match, and the entire node was moved, and
    // it's not open, close this frontier node right away.
    if (toEnd && openEndCount < 0 && parent && parent.type == this.frontier[this.depth].type && this.frontier.length > 1)
      this.closeFrontierNode()

    // Add new frontier nodes for any open nodes at the end.
    for (let i = 0, cur = fragment; i < openEndCount; i++) {
      let node = cur.lastChild!
      this.frontier.push({type: node.type, match: node.contentMatchAt(node.childCount)})
      cur = node.content
    }

    // Update `this.unplaced`. Drop the entire node from which we
    // placed it we got to its end, otherwise just drop the placed
    // nodes.
    this.unplaced = !toEnd ? new Slice(dropFromFragment(slice.content, sliceDepth, taken), slice.openStart, slice.openEnd)
      : sliceDepth == 0 ? Slice.empty
      : new Slice(dropFromFragment(slice.content, sliceDepth - 1, 1),
                  sliceDepth - 1, openEndCount < 0 ? slice.openEnd : sliceDepth - 1)
  }

  mustMoveInline() {
    if (!this.$to.parent.isTextblock) return -1
    let top = this.frontier[this.depth], level
    if (!top.type.isTextblock || !contentAfterFits(this.$to, this.$to.depth, top.type, top.match, false) ||
        (this.$to.depth == this.depth && (level = this.findCloseLevel(this.$to)) && level.depth == this.depth)) return -1

    let {depth} = this.$to, after = this.$to.after(depth)
    while (depth > 1 && after == this.$to.end(--depth)) ++after
    return after
  }

  findCloseLevel($to: ResolvedPos) {
    scan: for (let i = Math.min(this.depth, $to.depth); i >= 0; i--) {
      let {match, type} = this.frontier[i]
      let dropInner = i < $to.depth && $to.end(i + 1) == $to.pos + ($to.depth - (i + 1))
      let fit = contentAfterFits($to, i, type, match, dropInner)
      if (!fit) continue
      for (let d = i - 1; d >= 0; d--) {
        let {match, type} = this.frontier[d]
        let matches = contentAfterFits($to, d, type, match, true)
        if (!matches || matches.childCount) continue scan
      }
      return {depth: i, fit, move: dropInner ? $to.doc.resolve($to.after(i + 1)) : $to}
    }
  }

  close($to: ResolvedPos) {
    let close = this.findCloseLevel($to)
    if (!close) return null

    while (this.depth > close.depth) this.closeFrontierNode()
    if (close.fit.childCount) this.placed = addToFragment(this.placed, close.depth, close.fit)
    $to = close.move
    for (let d = close.depth + 1; d <= $to.depth; d++) {
      let node = $to.node(d), add = node.type.contentMatch.fillBefore(node.content, true, $to.index(d))!
      this.openFrontierNode(node.type, node.attrs, add)
    }
    return $to
  }

  openFrontierNode(type: NodeType, attrs: Attrs | null = null, content?: Fragment) {
    let top = this.frontier[this.depth]
    top.match = top.match.matchType(type)!
    this.placed = addToFragment(this.placed, this.depth, Fragment.from(type.create(attrs, content)))
    this.frontier.push({type, match: type.contentMatch})
  }

  closeFrontierNode() {
    let open = this.frontier.pop()!
    let add = open.match.fillBefore(Fragment.empty, true)!
    if (add.childCount) this.placed = addToFragment(this.placed, this.frontier.length, add)
  }
}

function dropFromFragment(fragment: Fragment, depth: number, count: number): Fragment {
  if (depth == 0) return fragment.cutByIndex(count, fragment.childCount)
  return fragment.replaceChild(0, fragment.firstChild!.copy(dropFromFragment(fragment.firstChild!.content, depth - 1, count)))
}

function addToFragment(fragment: Fragment, depth: number, content: Fragment): Fragment {
  if (depth == 0) return fragment.append(content)
  return fragment.replaceChild(fragment.childCount - 1,
                               fragment.lastChild!.copy(addToFragment(fragment.lastChild!.content, depth - 1, content)))
}

function contentAt(fragment: Fragment, depth: number) {
  for (let i = 0; i < depth; i++) fragment = fragment.firstChild!.content
  return fragment
}

function closeNodeStart(node: Node, openStart: number, openEnd: number) {
  if (openStart <= 0) return node
  let frag = node.content
  if (openStart > 1)
    frag = frag.replaceChild(0, closeNodeStart(frag.firstChild!, openStart - 1, frag.childCount == 1 ? openEnd - 1 : 0))
  if (openStart > 0) {
    frag = node.type.contentMatch.fillBefore(frag)!.append(frag)
    if (openEnd <= 0) frag = frag.append(node.type.contentMatch.matchFragment(frag)!.fillBefore(Fragment.empty, true)!)
  }
  return node.copy(frag)
}

function contentAfterFits($to: ResolvedPos, depth: number, type: NodeType, match: ContentMatch, open: boolean) {
  let node = $to.node(depth), index = open ? $to.indexAfter(depth) : $to.index(depth)
  if (index == node.childCount && !type.compatibleContent(node.type)) return null
  let fit = match.fillBefore(node.content, true, index)
  return fit && !invalidMarks(type, node.content, index) ? fit : null
}

function invalidMarks(type: NodeType, fragment: Fragment, start: number) {
  for (let i = start; i < fragment.childCount; i++)
    if (!type.allowsMarks(fragment.child(i).marks)) return true
  return false
}

function definesContent(type: NodeType) {
  return type.spec.defining || type.spec.definingForContent
}

export function replaceRange(tr: Transform, from: number, to: number, slice: Slice) {
  if (!slice.size) return tr.deleteRange(from, to)

  let $from = tr.doc.resolve(from), $to = tr.doc.resolve(to)
  if (fitsTrivially($from, $to, slice))
    return tr.step(new ReplaceStep(from, to, slice))

  let targetDepths = coveredDepths($from, $to)
  // Can't replace the whole document, so remove 0 if it's present
  if (targetDepths[targetDepths.length - 1] == 0) targetDepths.pop()
  // Negative numbers represent not expansion over the whole node at
  // that depth, but replacing from $from.before(-D) to $to.pos.
  let preferredTarget = -($from.depth + 1)
  targetDepths.unshift(preferredTarget)
  // This loop picks a preferred target depth, if one of the covering
  // depths is not outside of a defining node, and adds negative
  // depths for any depth that has $from at its start and does not
  // cross a defining node.
  for (let d = $from.depth, pos = $from.pos - 1; d > 0; d--, pos--) {
    let spec = $from.node(d).type.spec
    if (spec.defining || spec.definingAsContext || spec.isolating) break
    if (targetDepths.indexOf(d) > -1) preferredTarget = d
    else if ($from.before(d) == pos) targetDepths.splice(1, 0, -d)
  }
  // Try to fit each possible depth of the slice into each possible
  // target depth, starting with the preferred depths.
  let preferredTargetIndex = targetDepths.indexOf(preferredTarget)

  let leftNodes: Node[] = [], preferredDepth = slice.openStart
  for (let content = slice.content, i = 0;; i++) {
    let node = content.firstChild!
    leftNodes.push(node)
    if (i == slice.openStart) break
    content = node.content
  }

  // Back up preferredDepth to cover defining textblocks directly
  // above it, possibly skipping a non-defining textblock.
  for (let d = preferredDepth - 1; d >= 0; d--) {
    let leftNode = leftNodes[d], def = definesContent(leftNode.type)
    if (def && !leftNode.sameMarkup($from.node(Math.abs(preferredTarget) - 1))) preferredDepth = d
    else if (def || !leftNode.type.isTextblock) break
  }

  for (let j = slice.openStart; j >= 0; j--) {
    let openDepth = (j + preferredDepth + 1) % (slice.openStart + 1)
    let insert = leftNodes[openDepth]
    if (!insert) continue
    for (let i = 0; i < targetDepths.length; i++) {
      // Loop over possible expansion levels, starting with the
      // preferred one
      let targetDepth = targetDepths[(i + preferredTargetIndex) % targetDepths.length], expand = true
      if (targetDepth < 0) { expand = false; targetDepth = -targetDepth }
      let parent = $from.node(targetDepth - 1), index = $from.index(targetDepth - 1)
      if (parent.canReplaceWith(index, index, insert.type, insert.marks))
        return tr.replace($from.before(targetDepth), expand ? $to.after(targetDepth) : to,
                            new Slice(closeFragment(slice.content, 0, slice.openStart, openDepth),
                                      openDepth, slice.openEnd))
    }
  }

  let startSteps = tr.steps.length
  for (let i = targetDepths.length - 1; i >= 0; i--) {
    tr.replace(from, to, slice)
    if (tr.steps.length > startSteps) break
    let depth = targetDepths[i]
    if (depth < 0) continue
    from = $from.before(depth); to = $to.after(depth)
  }
}

function closeFragment(fragment: Fragment, depth: number, oldOpen: number, newOpen: number, parent?: Node) {
  if (depth < oldOpen) {
    let first = fragment.firstChild!
    fragment = fragment.replaceChild(0, first.copy(closeFragment(first.content, depth + 1, oldOpen, newOpen, first)))
  }
  if (depth > newOpen) {
    let match = parent!.contentMatchAt(0)!
    let start = match.fillBefore(fragment)!.append(fragment)
    fragment = start.append(match.matchFragment(start)!.fillBefore(Fragment.empty, true)!)
  }
  return fragment
}

export function replaceRangeWith(tr: Transform, from: number, to: number, node: Node) {
  if (!node.isInline && from == to && tr.doc.resolve(from).parent.content.size) {
    let point = insertPoint(tr.doc, from, node.type)
    if (point != null) from = to = point
  }
  tr.replaceRange(from, to, new Slice(Fragment.from(node), 0, 0))
}

export function deleteRange(tr: Transform, from: number, to: number) {
  let $from = tr.doc.resolve(from), $to = tr.doc.resolve(to)

  // When the deleted range spans from the start of one textblock to
  // the start of another one, move out of the start of both blocks.
  if ($from.parent.isTextblock && $to.parent.isTextblock && $from.start() != $to.start() &&
      $from.parentOffset == 0 && $to.parentOffset == 0) {
    let shared = $from.sharedDepth(to), isolated = false
    for (let d = $from.depth; d > shared; d--) if ($from.node(d).type.spec.isolating) isolated = true
    for (let d = $to.depth; d > shared; d--) if ($to.node(d).type.spec.isolating) isolated = true
    if (!isolated) {
      for (let d = $from.depth; d > 0 && from == $from.start(d); d--) from = $from.before(d)
      for (let d = $to.depth; d > 0 && to == $to.start(d); d--) to = $to.before(d)
      $from = tr.doc.resolve(from)
      $to = tr.doc.resolve(to)
    }
  }

  let covered = coveredDepths($from, $to)
  for (let i = 0; i < covered.length; i++) {
    let depth = covered[i], last = i == covered.length - 1
    if ((last && depth == 0) || $from.node(depth).type.contentMatch.validEnd)
      return tr.delete($from.start(depth), $to.end(depth))
    if (depth > 0 && (last || $from.node(depth - 1).canReplace($from.index(depth - 1), $to.indexAfter(depth - 1))))
      return tr.delete($from.before(depth), $to.after(depth))
  }
  for (let d = 1; d <= $from.depth && d <= $to.depth; d++) {
    if (from - $from.start(d) == $from.depth - d && to > $from.end(d) && $to.end(d) - to != $to.depth - d &&
        $from.start(d - 1) == $to.start(d - 1) && $from.node(d - 1).canReplace($from.index(d - 1), $to.index(d - 1)))
      return tr.delete($from.before(d), to)
  }
  tr.delete(from, to)
}

// Returns an array of all depths for which $from - $to spans the
// whole content of the nodes at that depth.
function coveredDepths($from: ResolvedPos, $to: ResolvedPos) {
  let result: number[] = [], minDepth = Math.min($from.depth, $to.depth)
  for (let d = minDepth; d >= 0; d--) {
    let start = $from.start(d)
    if (start < $from.pos - ($from.depth - d) ||
        $to.end(d) > $to.pos + ($to.depth - d) ||
        $from.node(d).type.spec.isolating ||
        $to.node(d).type.spec.isolating) break
    if (start == $to.start(d) ||
        (d == $from.depth && d == $to.depth && $from.parent.inlineContent && $to.parent.inlineContent &&
         d && $to.start(d - 1) == start - 1))
      result.push(d)
  }
  return result
}

import {Slice, Node, Schema} from "prosemirror-model"

import {Step, StepResult} from "./step"
import {StepMap, Mappable} from "./map"

/// Replace a part of the document with a slice of new content.
export class ReplaceStep extends Step {
  /// The given `slice` should fit the 'gap' between `from` and
  /// `to`—the depths must line up, and the surrounding nodes must be
  /// able to be joined with the open sides of the slice. When
  /// `structure` is true, the step will fail if the content between
  /// from and to is not just a sequence of closing and then opening
  /// tokens (this is to guard against rebased replace steps
  /// overwriting something they weren't supposed to).
  constructor(
    /// The start position of the replaced range.
    readonly from: number,
    /// The end position of the replaced range.
    readonly to: number,
    /// The slice to insert.
    readonly slice: Slice,
    /// @internal
    readonly structure = false
  ) {
    super()
  }

  apply(doc: Node) {
    if (this.structure && contentBetween(doc, this.from, this.to))
      return StepResult.fail("Structure replace would overwrite content")
    return StepResult.fromReplace(doc, this.from, this.to, this.slice)
  }

  getMap() {
    return new StepMap([this.from, this.to - this.from, this.slice.size])
  }

  invert(doc: Node) {
    return new ReplaceStep(this.from, this.from + this.slice.size, doc.slice(this.from, this.to))
  }

  map(mapping: Mappable) {
    let to = mapping.mapResult(this.to, -1)
    let from = this.from == this.to && ReplaceStep.MAP_BIAS < 0 ? to : mapping.mapResult(this.from, 1)
    if (from.deletedAcross && to.deletedAcross) return null
    return new ReplaceStep(from.pos, Math.max(from.pos, to.pos), this.slice, this.structure)
  }

  merge(other: Step) {
    if (!(other instanceof ReplaceStep) || other.structure || this.structure) return null

    if (this.from + this.slice.size == other.from && !this.slice.openEnd && !other.slice.openStart) {
      let slice = this.slice.size + other.slice.size == 0 ? Slice.empty
          : new Slice(this.slice.content.append(other.slice.content), this.slice.openStart, other.slice.openEnd)
      return new ReplaceStep(this.from, this.to + (other.to - other.from), slice, this.structure)
    } else if (other.to == this.from && !this.slice.openStart && !other.slice.openEnd) {
      let slice = this.slice.size + other.slice.size == 0 ? Slice.empty
          : new Slice(other.slice.content.append(this.slice.content), other.slice.openStart, this.slice.openEnd)
      return new ReplaceStep(other.from, this.to, slice, this.structure)
    } else {
      return null
    }
  }

  toJSON(): any {
    let json: any = {stepType: "replace", from: this.from, to: this.to}
    if (this.slice.size) json.slice = this.slice.toJSON()
    if (this.structure) json.structure = true
    return json
  }

  /// @internal
  static fromJSON(schema: Schema, json: any) {
    if (typeof json.from != "number" || typeof json.to != "number")
      throw new RangeError("Invalid input for ReplaceStep.fromJSON")
    return new ReplaceStep(json.from, json.to, Slice.fromJSON(schema, json.slice), !!json.structure)
  }

  /// By default, for backwards compatibility, an inserting step
  /// mapped over an insertion at that same position fill move after
  /// the inserted content. In a collaborative editing situation, that
  /// can make redone insertions appear in unexpected places. You can
  /// set this to -1 to make such mapping keep the step before the
  /// insertion instead.
  static MAP_BIAS: -1 | 1 = 1
}

Step.jsonID("replace", ReplaceStep)

/// Replace a part of the document with a slice of content, but
/// preserve a range of the replaced content by moving it into the
/// slice.
export class ReplaceAroundStep extends Step {
  /// Create a replace-around step with the given range and gap.
  /// `insert` should be the point in the slice into which the content
  /// of the gap should be moved. `structure` has the same meaning as
  /// it has in the [`ReplaceStep`](#transform.ReplaceStep) class.
  constructor(
    /// The start position of the replaced range.
    readonly from: number,
    /// The end position of the replaced range.
    readonly to: number,
    /// The start of preserved range.
    readonly gapFrom: number,
    /// The end of preserved range.
    readonly gapTo: number,
    /// The slice to insert.
    readonly slice: Slice,
    /// The position in the slice where the preserved range should be
    /// inserted.
    readonly insert: number,
    /// @internal
    readonly structure = false
  ) {
    super()
  }

  apply(doc: Node) {
    if (this.structure && (contentBetween(doc, this.from, this.gapFrom) ||
                           contentBetween(doc, this.gapTo, this.to)))
      return StepResult.fail("Structure gap-replace would overwrite content")

    let gap = doc.slice(this.gapFrom, this.gapTo)
    if (gap.openStart || gap.openEnd)
      return StepResult.fail("Gap is not a flat range")
    let inserted = this.slice.insertAt(this.insert, gap.content)
    if (!inserted) return StepResult.fail("Content does not fit in gap")
    return StepResult.fromReplace(doc, this.from, this.to, inserted)
  }

  getMap() {
    return new StepMap([this.from, this.gapFrom - this.from, this.insert,
                        this.gapTo, this.to - this.gapTo, this.slice.size - this.insert])
  }

  invert(doc: Node) {
    let gap = this.gapTo - this.gapFrom
    return new ReplaceAroundStep(this.from, this.from + this.slice.size + gap,
                                 this.from + this.insert, this.from + this.insert + gap,
                                 doc.slice(this.from, this.to).removeBetween(this.gapFrom - this.from, this.gapTo - this.from),
                                 this.gapFrom - this.from, this.structure)
  }

  map(mapping: Mappable) {
    let from = mapping.mapResult(this.from, 1), to = mapping.mapResult(this.to, -1)
    let gapFrom = this.from == this.gapFrom ? from.pos : mapping.map(this.gapFrom, -1)
    let gapTo = this.to == this.gapTo ? to.pos : mapping.map(this.gapTo, 1)
    if ((from.deletedAcross && to.deletedAcross) || gapFrom < from.pos || gapTo > to.pos) return null
    return new ReplaceAroundStep(from.pos, to.pos, gapFrom, gapTo, this.slice, this.insert, this.structure)
  }

  toJSON(): any {
    let json: any = {stepType: "replaceAround", from: this.from, to: this.to,
                     gapFrom: this.gapFrom, gapTo: this.gapTo, insert: this.insert}
    if (this.slice.size) json.slice = this.slice.toJSON()
    if (this.structure) json.structure = true
    return json
  }

  /// @internal
  static fromJSON(schema: Schema, json: any) {
    if (typeof json.from != "number" || typeof json.to != "number" ||
        typeof json.gapFrom != "number" || typeof json.gapTo != "number" || typeof json.insert != "number")
      throw new RangeError("Invalid input for ReplaceAroundStep.fromJSON")
    return new ReplaceAroundStep(json.from, json.to, json.gapFrom, json.gapTo,
                                 Slice.fromJSON(schema, json.slice), json.insert, !!json.structure)
  }
}

Step.jsonID("replaceAround", ReplaceAroundStep)

function contentBetween(doc: Node, from: number, to: number) {
  let $from = doc.resolve(from), dist = to - from, depth = $from.depth
  while (dist > 0 && depth > 0 && $from.indexAfter(depth) == $from.node(depth).childCount) {
    depth--
    dist--
  }
  if (dist > 0) {
    let next = $from.node(depth).maybeChild($from.indexAfter(depth))
    while (dist > 0) {
      if (!next || next.isLeaf) return true
      next = next.firstChild
      dist--
    }
  }
  return false
}

/// There are several things that positions can be mapped through.
/// Such objects conform to this interface.
export interface Mappable {
  /// Map a position through this object. When given, `assoc` (should
  /// be -1 or 1, defaults to 1) determines with which side the
  /// position is associated, which determines in which direction to
  /// move when a chunk of content is inserted at the mapped position.
  map: (pos: number, assoc?: number) => number

  /// Map a position, and return an object containing additional
  /// information about the mapping. The result's `deleted` field tells
  /// you whether the position was deleted (completely enclosed in a
  /// replaced range) during the mapping. When content on only one side
  /// is deleted, the position itself is only considered deleted when
  /// `assoc` points in the direction of the deleted content.
  mapResult: (pos: number, assoc?: number) => MapResult
}

// Recovery values encode a range index and an offset. They are
// represented as numbers, because tons of them will be created when
// mapping, for example, a large number of decorations. The number's
// lower 16 bits provide the index, the remaining bits the offset.
//
// Note: We intentionally don't use bit shift operators to en- and
// decode these, since those clip to 32 bits, which we might in rare
// cases want to overflow. A 64-bit float can represent 48-bit
// integers precisely.

const lower16 = 0xffff
const factor16 = Math.pow(2, 16)

function makeRecover(index: number, offset: number) { return index + offset * factor16 }
function recoverIndex(value: number) { return value & lower16 }
function recoverOffset(value: number) { return (value - (value & lower16)) / factor16 }

const DEL_BEFORE = 1, DEL_AFTER = 2, DEL_ACROSS = 4, DEL_SIDE = 8

/// An object representing a mapped position with extra
/// information.
export class MapResult {
  /// @internal
  constructor(
    /// The mapped version of the position.
    readonly pos: number,
    /// @internal
    readonly delInfo: number,
    /// @internal
    readonly recover: number | null
  ) {}

  /// Tells you whether the position was deleted, that is, whether the
  /// step removed the token on the side queried (via the `assoc`)
  /// argument from the document.
  get deleted() { return (this.delInfo & DEL_SIDE) > 0 }

  /// Tells you whether the token before the mapped position was deleted.
  get deletedBefore() { return (this.delInfo & (DEL_BEFORE | DEL_ACROSS)) > 0 }

  /// True when the token after the mapped position was deleted.
  get deletedAfter() { return (this.delInfo & (DEL_AFTER | DEL_ACROSS)) > 0 }

  /// Tells whether any of the steps mapped through deletes across the
  /// position (including both the token before and after the
  /// position).
  get deletedAcross() { return (this.delInfo & DEL_ACROSS) > 0 }
}

/// A map describing the deletions and insertions made by a step, which
/// can be used to find the correspondence between positions in the
/// pre-step version of a document and the same position in the
/// post-step version.
export class StepMap implements Mappable {
  /// Create a position map. The modifications to the document are
  /// represented as an array of numbers, in which each group of three
  /// represents a modified chunk as `[start, oldSize, newSize]`.
  constructor(
    /// @internal
    readonly ranges: readonly number[],
    /// @internal
    readonly inverted = false
  ) {
    if (!ranges.length && StepMap.empty) return StepMap.empty
  }

  /// @internal
  recover(value: number) {
    let diff = 0, index = recoverIndex(value)
    if (!this.inverted) for (let i = 0; i < index; i++)
      diff += this.ranges[i * 3 + 2] - this.ranges[i * 3 + 1]
    return this.ranges[index * 3] + diff + recoverOffset(value)
  }

  mapResult(pos: number, assoc = 1): MapResult { return this._map(pos, assoc, false) as MapResult }

  map(pos: number, assoc = 1): number { return this._map(pos, assoc, true) as number }

  /// @internal
  _map(pos: number, assoc: number, simple: boolean) {
    let diff = 0, oldIndex = this.inverted ? 2 : 1, newIndex = this.inverted ? 1 : 2
    for (let i = 0; i < this.ranges.length; i += 3) {
      let start = this.ranges[i] - (this.inverted ? diff : 0)
      if (start > pos) break
      let oldSize = this.ranges[i + oldIndex], newSize = this.ranges[i + newIndex], end = start + oldSize
      if (pos <= end) {
        let side = !oldSize ? assoc : pos == start ? -1 : pos == end ? 1 : assoc
        let result = start + diff + (side < 0 ? 0 : newSize)
        if (simple) return result
        let recover = pos == (assoc < 0 ? start : end) ? null : makeRecover(i / 3, pos - start)
        let del = pos == start ? DEL_AFTER : pos == end ? DEL_BEFORE : DEL_ACROSS
        if (assoc < 0 ? pos != start : pos != end) del |= DEL_SIDE
        return new MapResult(result, del, recover)
      }
      diff += newSize - oldSize
    }
    return simple ? pos + diff : new MapResult(pos + diff, 0, null)
  }

  /// @internal
  touches(pos: number, recover: number) {
    let diff = 0, index = recoverIndex(recover)
    let oldIndex = this.inverted ? 2 : 1, newIndex = this.inverted ? 1 : 2
    for (let i = 0; i < this.ranges.length; i += 3) {
      let start = this.ranges[i] - (this.inverted ? diff : 0)
      if (start > pos) break
      let oldSize = this.ranges[i + oldIndex], end = start + oldSize
      if (pos <= end && i == index * 3) return true
      diff += this.ranges[i + newIndex] - oldSize
    }
    return false
  }

  /// Calls the given function on each of the changed ranges included in
  /// this map.
  forEach(f: (oldStart: number, oldEnd: number, newStart: number, newEnd: number) => void) {
    let oldIndex = this.inverted ? 2 : 1, newIndex = this.inverted ? 1 : 2
    for (let i = 0, diff = 0; i < this.ranges.length; i += 3) {
      let start = this.ranges[i], oldStart = start - (this.inverted ? diff : 0), newStart = start + (this.inverted ? 0 : diff)
      let oldSize = this.ranges[i + oldIndex], newSize = this.ranges[i + newIndex]
      f(oldStart, oldStart + oldSize, newStart, newStart + newSize)
      diff += newSize - oldSize
    }
  }

  /// Create an inverted version of this map. The result can be used to
  /// map positions in the post-step document to the pre-step document.
  invert() {
    return new StepMap(this.ranges, !this.inverted)
  }

  /// @internal
  toString() {
    return (this.inverted ? "-" : "") + JSON.stringify(this.ranges)
  }

  /// Create a map that moves all positions by offset `n` (which may be
  /// negative). This can be useful when applying steps meant for a
  /// sub-document to a larger document, or vice-versa.
  static offset(n: number) {
    return n == 0 ? StepMap.empty : new StepMap(n < 0 ? [0, -n, 0] : [0, 0, n])
  }

  /// A StepMap that contains no changed ranges.
  static empty = new StepMap([])
}

/// A mapping represents a pipeline of zero or more [step
/// maps](#transform.StepMap). It has special provisions for losslessly
/// handling mapping positions through a series of steps in which some
/// steps are inverted versions of earlier steps. (This comes up when
/// ‘[rebasing](/docs/guide/#transform.rebasing)’ steps for
/// collaboration or history management.)
export class Mapping implements Mappable {
  /// Create a new mapping with the given position maps.
  constructor(
    maps?: readonly StepMap[],
    /// @internal
    public mirror?: number[],
    /// The starting position in the `maps` array, used when `map` or
    /// `mapResult` is called.
    public from = 0,
    /// The end position in the `maps` array.
    public to = maps ? maps.length : 0
  ) {
    this._maps = (maps as StepMap[]) || []
    this.ownData = !(maps || mirror)
  }

  /// The step maps in this mapping.
  get maps(): readonly StepMap[] { return this._maps }

  private _maps: StepMap[]
  // False if maps/mirror are shared arrays that we shouldn't mutate
  private ownData: boolean

  /// Create a mapping that maps only through a part of this one.
  slice(from = 0, to = this.maps.length) {
    return new Mapping(this._maps, this.mirror, from, to)
  }

  /// Add a step map to the end of this mapping. If `mirrors` is
  /// given, it should be the index of the step map that is the mirror
  /// image of this one.
  appendMap(map: StepMap, mirrors?: number) {
    if (!this.ownData) {
      this._maps = this._maps.slice()
      this.mirror = this.mirror && this.mirror.slice()
      this.ownData = true
    }
    this.to = this._maps.push(map)
    if (mirrors != null) this.setMirror(this._maps.length - 1, mirrors)
  }

  /// Add all the step maps in a given mapping to this one (preserving
  /// mirroring information).
  appendMapping(mapping: Mapping) {
    for (let i = 0, startSize = this._maps.length; i < mapping._maps.length; i++) {
      let mirr = mapping.getMirror(i)
      this.appendMap(mapping._maps[i], mirr != null && mirr < i ? startSize + mirr : undefined)
    }
  }

  /// Finds the offset of the step map that mirrors the map at the
  /// given offset, in this mapping (as per the second argument to
  /// `appendMap`).
  getMirror(n: number): number | undefined {
    if (this.mirror) for (let i = 0; i < this.mirror.length; i++)
      if (this.mirror[i] == n) return this.mirror[i + (i % 2 ? -1 : 1)]
  }

  /// @internal
  setMirror(n: number, m: number) {
    if (!this.mirror) this.mirror = []
    this.mirror.push(n, m)
  }

  /// Append the inverse of the given mapping to this one.
  appendMappingInverted(mapping: Mapping) {
    for (let i = mapping.maps.length - 1, totalSize = this._maps.length + mapping._maps.length; i >= 0; i--) {
      let mirr = mapping.getMirror(i)
      this.appendMap(mapping._maps[i].invert(), mirr != null && mirr > i ? totalSize - mirr - 1 : undefined)
    }
  }

  /// Create an inverted version of this mapping.
  invert() {
    let inverse = new Mapping
    inverse.appendMappingInverted(this)
    return inverse
  }

  /// Map a position through this mapping.
  map(pos: number, assoc = 1) {
    if (this.mirror) return this._map(pos, assoc, true) as number
    for (let i = this.from; i < this.to; i++)
      pos = this._maps[i].map(pos, assoc)
    return pos
  }

  /// Map a position through this mapping, returning a mapping
  /// result.
  mapResult(pos: number, assoc = 1) { return this._map(pos, assoc, false) as MapResult }

  /// @internal
  _map(pos: number, assoc: number, simple: boolean) {
    let delInfo = 0

    for (let i = this.from; i < this.to; i++) {
      let map = this._maps[i], result = map.mapResult(pos, assoc)
      if (result.recover != null) {
        let corr = this.getMirror(i)
        if (corr != null && corr > i && corr < this.to) {
          i = corr
          pos = this._maps[corr].recover(result.recover)
          continue
        }
      }

      delInfo |= result.delInfo
      pos = result.pos
    }

    return simple ? pos : new MapResult(pos, delInfo, null)
  }
}

import ist from "ist"
import {Mapping, StepMap} from "prosemirror-transform"

function testMapping(mapping: Mapping, ...cases: [number, number, number?, boolean?][]) {
  let inverted = mapping.invert()
  for (let i = 0; i < cases.length; i++) {
    let [from, to, bias = 1, lossy] = cases[i]
    ist(mapping.map(from, bias), to)
    if (!lossy) ist(inverted.map(to, bias), from)
  }
}

function testDel(mapping: Mapping, pos: number, side: number, flags: string) {
  let r = mapping.mapResult(pos, side), found = ""
  if (r.deleted) found += "d"
  if (r.deletedBefore) found += "b"
  if (r.deletedAfter) found += "a"
  if (r.deletedAcross) found += "x"
  ist(found, flags)
}

function mk(...args: (number[] | {[from: number]: number})[]) {
  let mapping = new Mapping
  args.forEach(arg => {
    if (Array.isArray(arg)) mapping.appendMap(new StepMap(arg))
    else for (let from in arg) mapping.setMirror(+from, arg[from])
  })
  return mapping
}

describe("Mapping", () => {
  it("can map through a single insertion", () => {
    testMapping(mk([2, 0, 4]), [0, 0], [2, 6], [2, 2, -1], [3, 7])
  })

  it("can map through a single deletion", () => {
    testMapping(mk([2, 4, 0]), [0, 0], [2, 2, -1], [3, 2, 1, true], [6, 2, 1], [6, 2, -1, true], [7, 3])
  })

  it("can map through a single replace", () => {
    testMapping(mk([2, 4, 4]), [0, 0], [2, 2, 1], [4, 6, 1, true], [4, 2, -1, true], [6, 6, -1], [8, 8])
  })

  it("can map through a mirrorred delete-insert", () => {
    testMapping(mk([2, 4, 0], [2, 0, 4], {0: 1}), [0, 0], [2, 2], [4, 4], [6, 6], [7, 7])
  })

  it("cap map through a mirrorred insert-delete", () => {
    testMapping(mk([2, 0, 4], [2, 4, 0], {0: 1}), [0, 0], [2, 2], [3, 3])
  })

  it("can map through an delete-insert with an insert in between", () => {
    testMapping(mk([2, 4, 0], [1, 0, 1], [3, 0, 4], {0: 2}), [0, 0], [1, 2], [4, 5], [6, 7], [7, 8])
  })

  it("assigns the correct deleted flags when deletions happen before", () => {
    testDel(mk([0, 2, 0]), 2, -1, "db")
    testDel(mk([0, 2, 0]), 2, 1, "b")
    testDel(mk([0, 2, 2]), 2, -1, "db")
    testDel(mk([0, 1, 0], [0, 1, 0]), 2, -1, "db")
    testDel(mk([0, 1, 0]), 2, -1, "")
  })

  it("assigns the correct deleted flags when deletions happen after", () => {
    testDel(mk([2, 2, 0]), 2, -1, "a")
    testDel(mk([2, 2, 0]), 2, 1, "da")
    testDel(mk([2, 2, 2]), 2, 1, "da")
    testDel(mk([2, 1, 0], [2, 1, 0]), 2, 1, "da")
    testDel(mk([3, 2, 0]), 2, -1, "")
  })

  it("assigns the correct deleted flags when deletions happen across", () => {
    testDel(mk([0, 4, 0]), 2, -1, "dbax")
    testDel(mk([0, 4, 0]), 2, 1, "dbax")
    testDel(mk([0, 4, 0]), 2, 1, "dbax")
    testDel(mk([0, 1, 0], [4, 1, 0], [0, 3, 0]), 2, 1, "dbax")
  })

  it("assigns the correct deleted flags when deletions happen around", () => {
    testDel(mk([4, 1, 0], [0, 1, 0]), 2, -1, "")
    testDel(mk([2, 1, 0], [0, 2, 0]), 2, -1, "dba")
    testDel(mk([2, 1, 0], [0, 1, 0]), 2, -1, "a")
    testDel(mk([3, 1, 0], [0, 2, 0]), 2, -1, "db")
  })
})

import {Node, Mark, Schema} from "prosemirror-model"

import {Selection, TextSelection} from "./selection"
import {Transaction} from "./transaction"
import {Plugin, StateField} from "./plugin"

function bind<T extends Function>(f: T, self: any): T {
  return !self || !f ? f : f.bind(self)
}

class FieldDesc<T> {
  init: (config: EditorStateConfig, instance: EditorState) => T
  apply: (tr: Transaction, value: T, oldState: EditorState, newState: EditorState) => T

  constructor(readonly name: string, desc: StateField<any>, self?: any) {
    this.init = bind(desc.init, self)
    this.apply = bind(desc.apply, self)
  }
}

const baseFields = [
  new FieldDesc<Node>("doc", {
    init(config) { return config.doc || config.schema!.topNodeType.createAndFill() },
    apply(tr) { return tr.doc }
  }),

  new FieldDesc<Selection>("selection", {
    init(config, instance) { return config.selection || Selection.atStart(instance.doc) },
    apply(tr) { return tr.selection }
  }),

  new FieldDesc<readonly Mark[] | null>("storedMarks", {
    init(config) { return config.storedMarks || null },
    apply(tr, _marks, _old, state) { return (state.selection as TextSelection).$cursor ? tr.storedMarks : null }
  }),

  new FieldDesc<number>("scrollToSelection", {
    init() { return 0 },
    apply(tr, prev) { return tr.scrolledIntoView ? prev + 1 : prev }
  })
]

// Object wrapping the part of a state object that stays the same
// across transactions. Stored in the state's `config` property.
class Configuration {
  fields: FieldDesc<any>[]
  plugins: Plugin[] = []
  pluginsByKey: {[key: string]: Plugin} = Object.create(null)

  constructor(readonly schema: Schema, plugins?: readonly Plugin[]) {
    this.fields = baseFields.slice()
    if (plugins) plugins.forEach(plugin => {
      if (this.pluginsByKey[plugin.key])
        throw new RangeError("Adding different instances of a keyed plugin (" + plugin.key + ")")
      this.plugins.push(plugin)
      this.pluginsByKey[plugin.key] = plugin
      if (plugin.spec.state)
        this.fields.push(new FieldDesc<any>(plugin.key, plugin.spec.state, plugin))
    })
  }
}

/// The type of object passed to
/// [`EditorState.create`](#state.EditorState^create).
export interface EditorStateConfig {
  /// The schema to use (only relevant if no `doc` is specified).
  schema?: Schema

  /// The starting document. Either this or `schema` _must_ be
  /// provided.
  doc?: Node

  /// A valid selection in the document.
  selection?: Selection

  /// The initial set of [stored marks](#state.EditorState.storedMarks).
  storedMarks?: readonly Mark[] | null

  /// The plugins that should be active in this state.
  plugins?: readonly Plugin[]
}

/// The state of a ProseMirror editor is represented by an object of
/// this type. A state is a persistent data structure—it isn't
/// updated, but rather a new state value is computed from an old one
/// using the [`apply`](#state.EditorState.apply) method.
///
/// A state holds a number of built-in fields, and plugins can
/// [define](#state.PluginSpec.state) additional fields.
export class EditorState {
  /// @internal
  constructor(
    /// @internal
    readonly config: Configuration
  ) {}

  /// The current document.
  declare doc: Node

  /// The selection.
  declare selection: Selection

  /// A set of marks to apply to the next input. Will be null when
  /// no explicit marks have been set.
  declare storedMarks: readonly Mark[] | null

  /// The schema of the state's document.
  get schema(): Schema {
    return this.config.schema
  }

  /// The plugins that are active in this state.
  get plugins(): readonly Plugin[] {
    return this.config.plugins
  }

  /// Apply the given transaction to produce a new state.
  apply(tr: Transaction): EditorState {
    return this.applyTransaction(tr).state
  }

  /// @internal
  filterTransaction(tr: Transaction, ignore = -1) {
    for (let i = 0; i < this.config.plugins.length; i++) if (i != ignore) {
      let plugin = this.config.plugins[i]
      if (plugin.spec.filterTransaction && !plugin.spec.filterTransaction.call(plugin, tr, this))
        return false
    }
    return true
  }

  /// Verbose variant of [`apply`](#state.EditorState.apply) that
  /// returns the precise transactions that were applied (which might
  /// be influenced by the [transaction
  /// hooks](#state.PluginSpec.filterTransaction) of
  /// plugins) along with the new state.
  applyTransaction(rootTr: Transaction): {state: EditorState, transactions: readonly Transaction[]} {
    if (!this.filterTransaction(rootTr)) return {state: this, transactions: []}

    let trs = [rootTr], newState = this.applyInner(rootTr), seen = null
    // This loop repeatedly gives plugins a chance to respond to
    // transactions as new transactions are added, making sure to only
    // pass the transactions the plugin did not see before.
    for (;;) {
      let haveNew = false
      for (let i = 0; i < this.config.plugins.length; i++) {
        let plugin = this.config.plugins[i]
        if (plugin.spec.appendTransaction) {
          let n = seen ? seen[i].n : 0, oldState = seen ? seen[i].state : this
          let tr = n < trs.length &&
              plugin.spec.appendTransaction.call(plugin, n ? trs.slice(n) : trs, oldState, newState)
          if (tr && newState.filterTransaction(tr, i)) {
            tr.setMeta("appendedTransaction", rootTr)
            if (!seen) {
              seen = []
              for (let j = 0; j < this.config.plugins.length; j++)
                seen.push(j < i ? {state: newState, n: trs.length} : {state: this, n: 0})
            }
            trs.push(tr)
            newState = newState.applyInner(tr)
            haveNew = true
          }
          if (seen) seen[i] = {state: newState, n: trs.length}
        }
      }
      if (!haveNew) return {state: newState, transactions: trs}
    }
  }

  /// @internal
  applyInner(tr: Transaction) {
    if (!tr.before.eq(this.doc)) throw new RangeError("Applying a mismatched transaction")
    let newInstance = new EditorState(this.config), fields = this.config.fields
    for (let i = 0; i < fields.length; i++) {
      let field = fields[i]
      ;(newInstance as any)[field.name] = field.apply(tr, (this as any)[field.name], this, newInstance)
    }
    return newInstance
  }

  /// Accessor that constructs and returns a new [transaction](#state.Transaction) from this state.
  get tr(): Transaction { return new Transaction(this) }

  /// Create a new state.
  static create(config: EditorStateConfig) {
    let $config = new Configuration(config.doc ? config.doc.type.schema : config.schema!, config.plugins)
    let instance = new EditorState($config)
    for (let i = 0; i < $config.fields.length; i++)
      (instance as any)[$config.fields[i].name] = $config.fields[i].init(config, instance)
    return instance
  }

  /// Create a new state based on this one, but with an adjusted set
  /// of active plugins. State fields that exist in both sets of
  /// plugins are kept unchanged. Those that no longer exist are
  /// dropped, and those that are new are initialized using their
  /// [`init`](#state.StateField.init) method, passing in the new
  /// configuration object..
  reconfigure(config: {
    /// New set of active plugins.
    plugins?: readonly Plugin[]    
  }) {
    let $config = new Configuration(this.schema, config.plugins)
    let fields = $config.fields, instance = new EditorState($config)
    for (let i = 0; i < fields.length; i++) {
      let name = fields[i].name
      ;(instance as any)[name] = this.hasOwnProperty(name) ? (this as any)[name] : fields[i].init(config, instance)
    }
    return instance
  }

  /// Serialize this state to JSON. If you want to serialize the state
  /// of plugins, pass an object mapping property names to use in the
  /// resulting JSON object to plugin objects. The argument may also be
  /// a string or number, in which case it is ignored, to support the
  /// way `JSON.stringify` calls `toString` methods.
  toJSON(pluginFields?: {[propName: string]: Plugin}): any {
    let result: any = {doc: this.doc.toJSON(), selection: this.selection.toJSON()}
    if (this.storedMarks) result.storedMarks = this.storedMarks.map(m => m.toJSON())
    if (pluginFields && typeof pluginFields == 'object') for (let prop in pluginFields) {
      if (prop == "doc" || prop == "selection")
        throw new RangeError("The JSON fields `doc` and `selection` are reserved")
      let plugin = pluginFields[prop], state = plugin.spec.state
      if (state && state.toJSON) result[prop] = state.toJSON.call(plugin, (this as any)[plugin.key])
    }
    return result
  }

  /// Deserialize a JSON representation of a state. `config` should
  /// have at least a `schema` field, and should contain array of
  /// plugins to initialize the state with. `pluginFields` can be used
  /// to deserialize the state of plugins, by associating plugin
  /// instances with the property names they use in the JSON object.
  static fromJSON(config: {
    /// The schema to use.
    schema: Schema
    /// The set of active plugins.
    plugins?: readonly Plugin[]
  }, json: any, pluginFields?: {[propName: string]: Plugin}) {
    if (!json) throw new RangeError("Invalid input for EditorState.fromJSON")
    if (!config.schema) throw new RangeError("Required config field 'schema' missing")
    let $config = new Configuration(config.schema, config.plugins)
    let instance = new EditorState($config)
    $config.fields.forEach(field => {
      if (field.name == "doc") {
        instance.doc = Node.fromJSON(config.schema, json.doc)
      } else if (field.name == "selection") {
        instance.selection = Selection.fromJSON(instance.doc, json.selection)
      } else if (field.name == "storedMarks") {
        if (json.storedMarks) instance.storedMarks = json.storedMarks.map(config.schema.markFromJSON)
      } else {
        if (pluginFields) for (let prop in pluginFields) {
          let plugin = pluginFields[prop], state = plugin.spec.state
          if (plugin.key == field.name && state && state.fromJSON &&
              Object.prototype.hasOwnProperty.call(json, prop)) {
            // This field belongs to a plugin mapped to a JSON field, read it from there.
            ;(instance as any)[field.name] = state.fromJSON.call(plugin, config, json[prop], instance)
            return
          }
        }
        ;(instance as any)[field.name] = field.init(config, instance)
      }
    })
    return instance
  }
}

import {EditorState, Selection, TextSelection, NodeSelection, Command, Transaction} from "prosemirror-state"
import {Node, Schema} from "prosemirror-model"

// Wrapper object to make writing state tests easier.

export function selFor(doc: Node) {
  let a = (doc as any).tag.a
  if (a != null) {
    let $a = doc.resolve(a)
    if ($a.parent.inlineContent)
      return new TextSelection($a, (doc as any).tag.b != null ? doc.resolve((doc as any).tag.b) : undefined)
    else return new NodeSelection($a)
  }
  return Selection.atStart(doc)
}

export class TestState {
  state: EditorState
  constructor(config: {selection?: Selection, doc?: Node, schema?: Schema}) {
    if (!config.selection && config.doc) config.selection = selFor(config.doc)
    this.state = EditorState.create(config)
  }

  apply(tr: Transaction) {
    this.state = this.state.apply(tr)
  }

  command(cmd: Command) {
    cmd(this.state, tr => this.apply(tr))
  }

  type(text: string) {
    this.apply(this.tr.insertText(text))
  }

  deleteSelection() {
    this.apply(this.state.tr.deleteSelection())
  }

  textSel(anchor: number, head?: number) {
    let sel = TextSelection.create(this.state.doc, anchor, head)
    this.state = this.state.apply(this.state.tr.setSelection(sel))
  }

  nodeSel(pos: number) {
    let sel = NodeSelection.create(this.state.doc, pos)
    this.state = this.state.apply(this.state.tr.setSelection(sel))
  }

  get doc() { return this.state.doc }
  get selection() { return this.state.selection }
  get tr() { return this.state.tr }
}

import {TextSelection} from "prosemirror-state"

import {schema, eq, doc, blockquote, pre, p, li, ul, img, em, a, br, hr} from "prosemirror-test-builder"
import {TestState} from "./state.js"
import ist from "ist"

describe("Selection", () => {
  it("should follow changes", () => {
    let state = new TestState({doc: doc(p("hi")), schema})
    state.apply(state.tr.insertText("xy", 1))
    ist(state.selection.head, 3)
    ist(state.selection.anchor, 3)
    state.apply(state.tr.insertText("zq", 1))
    ist(state.selection.head, 5)
    ist(state.selection.anchor, 5)
    state.apply(state.tr.insertText("uv", 7))
    ist(state.selection.head, 5)
    ist(state.selection.anchor, 5)
  })

  it("should move after inserted content", () => {
    let state = new TestState({doc: doc(p("hi")), schema})
    state.textSel(2, 3)
    state.apply(state.tr.insertText("o"))
    ist(state.selection.head, 3)
    ist(state.selection.anchor, 3)
  })

  it("moves after an inserted leaf node", () => {
    let state = new TestState({doc: doc(p("foobar")), schema})
    state.textSel(4)
    state.apply(state.tr.replaceSelectionWith(schema.node("horizontal_rule")))
    ist(state.doc, doc(p("foo"), hr(), p("bar")), eq)
    ist(state.selection.head, 7)
    state.textSel(10)
    state.apply(state.tr.replaceSelectionWith(schema.node("horizontal_rule")))
    ist(state.doc, doc(p("foo"), hr(), p("bar"), hr()), eq)
    ist(state.selection.from, 11)
  })

  it("allows typing over a leaf node", () => {
    let state = new TestState({doc: doc(p("a"), "<a>", hr(), p("b")), schema})
    state.nodeSel(3)
    state.apply(state.tr.replaceSelectionWith(schema.text("x")))
    ist(state.doc, doc(p("a"), p("x"), p("b")), eq)
    ist(state.selection.head, 5)
    ist(state.selection.anchor, 5)
  })

  it("allows deleting a selected block", () => {
    let state = new TestState({doc: doc(p("foo"), ul(li(p("bar")), li(p("baz")), li(p("quux")))), schema})
    state.nodeSel(0)
    state.deleteSelection()
    ist(state.doc, doc(ul(li(p("bar")), li(p("baz")), li(p("quux")))), eq)
    ist(state.selection.head, 3)
    state.nodeSel(2)
    state.deleteSelection()
    ist(state.doc, doc(ul(li(p("baz")), li(p("quux")))), eq)
    ist(state.selection.head, 3)
    state.nodeSel(9)
    state.deleteSelection()
    ist(state.doc, doc(ul(li(p("baz")))), eq)
    ist(state.selection.head, 6)
    state.nodeSel(0)
    state.deleteSelection()
    ist(state.doc, doc(p()), eq)
  })

  it("preserves the marks of a deleted selection", () => {
    let state = new TestState({doc: doc(p("foo", em("<a>bar<b>"), "baz"))})
    state.deleteSelection()
    ist(state.state.storedMarks!.length, 1)
  })

  it("doesn't preserve non-inclusive marks of a deleted selection", () => {
    let state = new TestState({doc: doc(p("foo", a(em("<a>bar<b>")), "baz"))})
    state.deleteSelection()
    ist(state.state.storedMarks!.length, 1)
  })

  it("doesn't preserve marks when deleting a selection at the end of a block", () => {
    let state = new TestState({doc: doc(p("foo", em("bar<a>")), p("b<b>az"))})
    state.deleteSelection()
    ist(!state.state.storedMarks)
  })

  it("drops non-inclusive marks at the end of a deleted span when appropriate", () => {
    let state = new TestState({doc: doc(p("foo", a("ba", em("<a>r<b>")), "baz"))})
    state.deleteSelection()
    ist(state.state.storedMarks!.map(x => x.type.name).join(), "em")
  })

  it("keeps non-inclusive marks when still inside them", () => {
    let state = new TestState({doc: doc(p("foo", a("b", em("<a>a<b>"), "r"), "baz"))})
    state.deleteSelection()
    ist(state.state.storedMarks!.length, 2)
  })

  it("preserves marks when typing over marked text", () => {
    let state = new TestState({doc: doc(p("foo ", em("<a>bar<b>"), " baz"))})
    state.apply(state.tr.insertText("quux"))
    ist(state.doc, doc(p("foo ", em("quux"), " baz")), eq)
    state.apply(state.tr.insertText("bar", 5, 9))
    ist(state.doc, doc(p("foo ", em("bar"), " baz")), eq)
  })

  it("allows deleting a leaf", () => {
    let state = new TestState({doc: doc(p("a"), hr(), hr(), p("b")), schema})
    state.nodeSel(3)
    state.deleteSelection()
    ist(state.doc, doc(p("a"), hr(), p("b")), eq)
    ist(state.selection.from, 3)
    state.deleteSelection()
    ist(state.doc, doc(p("a"), p("b")), eq)
    ist(state.selection.head, 4)
  })

  it("properly handles deleting the selection", () => {
    let state = new TestState({doc: doc(p("foo", img(), "bar"), blockquote(p("hi")), p("ay")), schema})
    state.nodeSel(4)
    state.apply(state.tr.deleteSelection())
    ist(state.doc, doc(p("foobar"), blockquote(p("hi")), p("ay")), eq)
    ist(state.selection.head, 4)
    state.nodeSel(9)
    state.apply(state.tr.deleteSelection())
    ist(state.doc, doc(p("foobar"), p("ay")), eq)
    ist(state.selection.from, 9)
    state.nodeSel(8)
    state.apply(state.tr.deleteSelection())
    ist(state.doc, doc(p("foobar")), eq)
    ist(state.selection.from, 7)
  })

  it("can replace inline selections", () => {
    let state = new TestState({doc: doc(p("foo", img(), "bar", img(), "baz")), schema})
    state.nodeSel(4)
    state.apply(state.tr.replaceSelectionWith(schema.node("hard_break")))
    ist(state.doc, doc(p("foo", br(), "bar", img(), "baz")), eq)
    ist(state.selection.head, 5)
    ist(state.selection.empty)
    state.nodeSel(8)
    state.apply(state.tr.insertText("abc"))
    ist(state.doc, doc(p("foo", br(), "barabcbaz")), eq)
    ist(state.selection.head, 11)
    ist(state.selection.empty)
    state.nodeSel(0)
    state.apply(state.tr.insertText("xyz"))
    ist(state.doc, doc(p("xyz")), eq)
  })

  it("can replace a block selection", () => {
    let state = new TestState({doc: doc(p("abc"), hr(), hr(), blockquote(p("ow"))), schema})
    state.nodeSel(5)
    state.apply(state.tr.replaceSelectionWith(schema.node("code_block")))
    ist(state.doc, doc(p("abc"), pre(), hr(), blockquote(p("ow"))), eq)
    ist(state.selection.from, 7)
    state.nodeSel(8)
    state.apply(state.tr.replaceSelectionWith(schema.node("paragraph")))
    ist(state.doc, doc(p("abc"), pre(), hr(), p()), eq)
    ist(state.selection.from, 9)
  })

  it("puts the cursor after the inserted text when inserting a list item", () => {
    let state = new TestState({doc: doc(p("<a>abc"))})
    let source = doc(ul(li(p("<a>def<b>"))))
    state.apply(state.tr.replaceSelection(source.slice((source as any).tag.a, (source as any).tag.b, true)))
    ist(state.selection.from, 6)
  })
})

describe("TextSelection.between", () => {
  it("uses arguments when possible", () => {
    let d = doc(p("f<a>o<b>o"))
    let s = TextSelection.between(d.resolve((d as any).tag.b), d.resolve((d as any).tag.a))
    ist(s.anchor, (d as any).tag.b)
    ist(s.head, (d as any).tag.a)
  })

  it("will adjust when necessary", () => {
    let d = doc("<a>", p("foo"))
    let s = TextSelection.between(d.resolve((d as any).tag.a), d.resolve((d as any).tag.a))
    ist(s.anchor, 1)
  })

  it("uses bias when adjusting", () => {
    let d = doc(p("foo"), "<a>", p("bar")), pos = d.resolve((d as any).tag.a)
    let sUp = TextSelection.between(pos, pos, -1)
    ist(sUp.anchor, 4)
    let sDown = TextSelection.between(pos, pos, 1)
    ist(sDown.anchor, 6)
  })

  it("will fall back to a node selection", () => {
    let d = doc(hr, "<a>")
    let s = TextSelection.between(d.resolve((d as any).tag.a), d.resolve((d as any).tag.a))
    ist((s as any).node, d.firstChild)
  })

  it("will collapse towards the other argument", () => {
    let d = doc("<a>", p("foo"), "<b>")
    let s = TextSelection.between(d.resolve((d as any).tag.a), d.resolve((d as any).tag.b))
    ist(s.anchor, 1)
    ist(s.head, 4)
    s = TextSelection.between(d.resolve((d as any).tag.b), d.resolve((d as any).tag.a))
    ist(s.anchor, 4)
    ist(s.head, 1)
  })
})

import {eq, schema, doc, p} from "prosemirror-test-builder"
import {Slice, Fragment, Node} from "prosemirror-model"
import {EditorState, Plugin, TextSelection, Command} from "prosemirror-state"
import {ReplaceStep} from "prosemirror-transform"
import ist from "ist"
import {history, closeHistory, undo, redo, undoDepth, redoDepth} from "prosemirror-history"

let plugin = history()

function mkState(doc?: Node, config?: any) {
  let plugins = [config ? history(config) : plugin]
  if (config && config.preserveItems) plugins.push(new Plugin({historyPreserveItems: true} as any))
  return EditorState.create({schema, plugins: plugins.concat(config && config.plugins || []), doc})
}

function type(state: EditorState, text: string) {
  return state.apply(state.tr.insertText(text))
}
function command(state: EditorState, command: Command) {
  command(state, tr => state = state.apply(tr))
  return state
}

function compress(state: EditorState) {
  // NOTE: This is mutating stuff that shouldn't be mutated. Not safe
  // to do outside of these tests.
  plugin.getState(state).done = plugin.getState(state).done.compress()
}

describe("history", () => {
  it("enables undo", () => {
    let state = mkState()
    state = type(state, "a")
    state = type(state, "b")
    ist(state.doc, doc(p("ab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
  })

  it("enables redo", () => {
    let state = mkState()
    state = type(state, "a")
    state = type(state, "b")
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
    state = command(state, redo)
    ist(state.doc, doc(p("ab")), eq)
  })

  it("tracks multiple levels of history", () => {
    let state = mkState()
    state = type(state, "a")
    state = type(state, "b")
    state = state.apply(state.tr.insertText("c", 1))
    ist(state.doc, doc(p("cab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("ab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
    state = command(state, redo)
    ist(state.doc, doc(p("ab")), eq)
    state = command(state, redo)
    ist(state.doc, doc(p("cab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("ab")), eq)
  })

  it("starts a new event when newGroupDelay elapses", () => {
    let state = mkState(undefined, {newGroupDelay: 1000})
    state = state.apply(state.tr.insertText("a").setTime(1000))
    state = state.apply(state.tr.insertText("b").setTime(1600))
    ist(undoDepth(state), 1)
    state = state.apply(state.tr.insertText("c").setTime(2700))
    ist(undoDepth(state), 2)
    state = command(state, undo)
    state = state.apply(state.tr.insertText("d").setTime(2800))
    ist(undoDepth(state), 2)
  })

  it("starts a new event for non-adjacent changes", () => {
    let state = mkState(doc(p("abc")), {newGroupDelay: 1000})
    state = state.apply(state.tr.insertText("x", 1))
    state = state.apply(state.tr.insertText("y", 5))
    ist(undoDepth(state), 2)
  })

  it("doesn't get confused by non-replacement steps when checking adjacency", () => {
    let state = mkState(doc(p()), {newGroupDelay: 1000})
    state = state.apply(state.tr.insertText("x", 1).addMark(1, 2, schema.marks.em.create()))
    state = state.apply(state.tr.insertText("y", 2).addMark(2, 3, schema.marks.em.create()))
    ist(undoDepth(state), 1)
  })

  it("allows changes that aren't part of the history", () => {
    let state = mkState()
    state = type(state, "hello")
    state = state.apply(state.tr.insertText("oops", 1).setMeta("addToHistory", false))
    state = state.apply(state.tr.insertText("!", 10).setMeta("addToHistory", false))
    state = command(state, undo)
    ist(state.doc, doc(p("oops!")), eq)
  })

  it("doesn't get confused by an undo not adding any redo item", () => {
    let state = mkState()
    state = state.apply(state.tr.insertText("foo"))
    state = state.apply(state.tr.replaceWith(1, 4, schema.text("bar")).setMeta("addToHistory", false))
    state = command(state, undo)
    state = command(state, redo)
    ist(state.doc, doc(p("bar")), eq)
  })

  function unsyncedComplex(state: EditorState, doCompress: boolean) {
    state = type(state, "hello")
    state = state.apply(closeHistory(state.tr))
    state = type(state, "!")
    state = state.apply(state.tr.insertText("....", 1).setMeta("addToHistory", false))
    state = state.apply(state.tr.split(3))
    ist(state.doc, doc(p(".."), p("..hello!")), eq)
    state = state.apply(state.tr.split(2).setMeta("addToHistory", false))
    if (doCompress) compress(state)
    state = command(state, undo)
    state = command(state, undo)
    ist(state.doc, doc(p("."), p("...hello")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("."), p("...")), eq)
  }

  it("can handle complex editing sequences", () => {
    unsyncedComplex(mkState(), false)
  })

  it("can handle complex editing sequences with compression", () => {
    unsyncedComplex(mkState(), true)
  })

  it("supports overlapping edits", () => {
    let state = mkState()
    state = type(state, "hello")
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.delete(1, 6))
    ist(state.doc, doc(p()), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("hello")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
  })

  it("supports overlapping edits that aren't collapsed", () => {
    let state = mkState()
    state = state.apply(state.tr.insertText("h", 1).setMeta("addToHistory", false))
    state = type(state, "ello")
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.delete(1, 6))
    ist(state.doc, doc(p()), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("hello")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("h")), eq)
  })

  it("supports overlapping unsynced deletes", () => {
    let state = mkState()
    state = type(state, "hi")
    state = state.apply(closeHistory(state.tr))
    state = type(state, "hello")
    state = state.apply(state.tr.delete(1, 8).setMeta("addToHistory", false))
    ist(state.doc, doc(p()), eq)
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
  })

  it("can go back and forth through history multiple times", () => {
    let state = mkState()
    state = type(state, "one")
    state = type(state, " two")
    state = state.apply(closeHistory(state.tr))
    state = type(state, " three")
    state = state.apply(state.tr.insertText("zero ", 1))
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.split(1))
    state = state.apply(state.tr.setSelection(TextSelection.create(state.doc, 1)))
    state = type(state, "top")
    for (let i = 0; i < 6; i++) {
      let re = i % 2
      for (let j = 0; j < 4; j++) state = command(state, re ? redo : undo)
      ist(state.doc, re ? doc(p("top"), p("zero one two three")) : doc(p()), eq)
    }
  })

  it("supports non-tracked changes next to tracked changes", () => {
    let state = mkState()
    state = type(state, "o")
    state = state.apply(state.tr.split(1))
    state = state.apply(state.tr.insertText("zzz", 4).setMeta("addToHistory", false))
    state = command(state, undo)
    ist(state.doc, doc(p("zzz")), eq)
  })

  it("can go back and forth through history when preserving items", () => {
    let state = mkState()
    state = type(state, "one")
    state = type(state, " two")
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.insertText("xxx", state.selection.head).setMeta("addToHistory", false))
    state = type(state, " three")
    state = state.apply(state.tr.insertText("zero ", 1))
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.split(1))
    state = state.apply(state.tr.setSelection(TextSelection.create(state.doc, 1)))
    state = type(state, "top")
    state = state.apply(state.tr.insertText("yyy", 1).setMeta("addToHistory", false))
    for (let i = 0; i < 3; i++) {
      if (i == 2) compress(state)
      for (let j = 0; j < 4; j++) state = command(state, undo)
      ist(state.doc, doc(p("yyyxxx")), eq)
      for (let j = 0; j < 4; j++) state = command(state, redo)
      ist(state.doc, doc(p("yyytop"), p("zero one twoxxx three")), eq)
    }
  })

  it("restores selection on undo", () => {
    let state = mkState()
    state = type(state, "hi")
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.setSelection(TextSelection.create(state.doc, 1, 3)))
    let selection = state.selection
    state = state.apply(state.tr.replaceWith(selection.from, selection.to, schema.text("hello")))
    let selection2 = state.selection
    state = command(state, undo)
    ist(state.selection.eq(selection))
    state = command(state, redo)
    ist(state.selection.eq(selection2))
  })

  it("rebases selection on undo", () => {
    let state = mkState()
    state = type(state, "hi")
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.setSelection(TextSelection.create(state.doc, 1, 3)))
    state = state.apply(state.tr.insert(1, schema.text("hello")))
    state = state.apply(state.tr.insert(1, schema.text("---")).setMeta("addToHistory", false))
    state = command(state, undo)
    ist(state.selection.head, 6)
  })

  it("handles change overwriting in item-preserving mode", () => {
    let state = mkState(undefined, {preserveItems: true})
    state = type(state, "a")
    state = type(state, "b")
    state = state.apply(closeHistory(state.tr))
    state = state.apply(state.tr.setSelection(TextSelection.create(state.doc, 1, 3)))
    state = type(state, "c")
    state = command(state, undo)
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
  })

  it("supports querying for the undo and redo depth", () => {
    let state = mkState()
    state = type(state, "a")
    ist(undoDepth(state), 1)
    ist(redoDepth(state), 0)
    state = state.apply(state.tr.insertText("b", 1).setMeta("addToHistory", false))
    ist(undoDepth(state), 1)
    ist(redoDepth(state), 0)
    state = command(state, undo)
    ist(undoDepth(state), 0)
    ist(redoDepth(state), 1)
    state = command(state, redo)
    ist(undoDepth(state), 1)
    ist(redoDepth(state), 0)
  })

  it("all functions gracefully handle EditorStates without history", () => {
    let state = EditorState.create({schema})
    ist(undoDepth(state), 0)
    ist(redoDepth(state), 0)
    ist(undo(state), false)
    ist(redo(state), false)
  })

  it("truncates history", () => {
    let state = mkState(undefined, {depth: 2})
    for (let i = 1; i < 40; ++i) {
      state = type(state, "a")
      state = state.apply(closeHistory(state.tr))
      ist(undoDepth(state), (i - 2) % 21 + 2)
    }
  })

  it("supports transactions with multiple steps", () => {
    let state = mkState()
    state = state.apply(state.tr.insertText("a").insertText("b"))
    state = state.apply(state.tr.insertText("c", 1))
    ist(state.doc, doc(p("cab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("ab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p()), eq)
    state = command(state, redo)
    ist(state.doc, doc(p("ab")), eq)
    state = command(state, redo)
    ist(state.doc, doc(p("cab")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("ab")), eq)
  })

  it("combines appended transactions in the event started by the base transaction", () => {
    let state = mkState(doc(p("x")), {plugins: [new Plugin({
      appendTransaction: (_trs, _old, state) => {
        if (state.doc.content.size == 4) return state.tr.insert(1, schema.text("A"))
      }
    })]})
    state = state.apply(state.tr.insert(2, schema.text("I")))
    ist(state.doc, doc(p("AxI")), eq)
    ist(undoDepth(state), 1)
    state = command(state, undo)
    ist(state.doc, doc(p("x")), eq)
  })

  it("includes transactions appended to undo in the redo history", () => {
    let state = mkState(doc(p("x")), {plugins: [new Plugin({
      appendTransaction: (trs, _old, state) => {
        let add = trs[0].getMeta("add")
        if (add) return state.tr.insert(1, schema.text(add))
      }
    })]})
    state = state.apply(state.tr.insert(2, schema.text("I")).setMeta("add", "A"))
    ist(state.doc, doc(p("AxI")), eq)
    undo(state, tr => state = state.apply(tr.setMeta("add", "B")))
    ist(state.doc, doc(p("Bx")), eq)
    redo(state, tr => state = state.apply(tr.setMeta("add", "C")))
    ist(state.doc, doc(p("CAxI")), eq)
    state = command(state, undo)
    ist(state.doc, doc(p("Bx")), eq)
  })

  it("doesn't close the history on appended transactions", () => {
    let state = mkState(doc(p("x")), {plugins: [new Plugin({
      appendTransaction: (trs, _old, state) => {
        let add = trs[0].getMeta("add")
        if (add) return state.tr.insert(1, schema.text(add))
      }
    })]})
    state = state.apply(state.tr.insert(2, schema.text("R")).setMeta("add", "A"))
    state = state.apply(state.tr.insert(3, schema.text("M")))
    state = command(state, undo)
    ist(state.doc, doc(p("x")), eq)
  })

  it("supports rebasing", () => {
    // This test simulates a collab editing session where the local editor
    // receives a step (`right`) that's on top of the parent step (`base`) of
    // the last local step (`left`).

    // Shared base step
    let state = mkState()
    state = type(state, "base")
    state = state.apply(closeHistory(state.tr))
    const baseDoc = state.doc

    // Local unconfirmed step
    //
    //        - left
    //       /
    // base -
    //       \
    //        - right
    let rightStep = new ReplaceStep(5, 5, new Slice(Fragment.from(schema.text(" right")), 0, 0))
    state = state.apply(state.tr.step(rightStep))
    ist(state.doc, doc(p("base right")), eq)
    ist(undoDepth(state), 2)
    let leftStep = new ReplaceStep(1, 1, new Slice(Fragment.from(schema.text("left ")), 0, 0))

    // Receive remote step and rebase local unconfirmed step
    //
    // base --> left --> right'
    const tr = state.tr
    tr.step(rightStep.invert(baseDoc))
    tr.step(leftStep)
    tr.step(rightStep.map(tr.mapping.slice(1))!)
    tr.mapping.setMirror(0, tr.steps.length - 1)
    tr.setMeta("addToHistory", false)
    tr.setMeta("rebased", 1)
    state = state.apply(tr)
    ist(state.doc, doc(p("left base right")), eq)
    ist(undoDepth(state), 2)

    // Undo local unconfirmed step
    //
    // base --> left
    state = command(state, undo)
    ist(state.doc, doc(p("left base")), eq)

    // Redo local unconfirmed step
    //
    // base --> left --> right'
    state = command(state, redo)
    ist(state.doc, doc(p("left base right")), eq)
  })

  it("properly maps selection when rebasing", () => {
    let state = mkState(doc(p("123456789ABCD")))
    state = state.apply(state.tr.setSelection(TextSelection.create(state.doc, 6, 13)))
    state = state.apply(state.tr.delete(6, 13))
    let rebase = state.tr.insert(6, schema.text("6789ABC")).insert(14, schema.text("E")).delete(6, 13)
        .setMeta("rebased", 1).setMeta("addToHistory", false)
    rebase.mapping.setMirror(0, 2)
    state = state.apply(rebase)
    state = command(state, undo)
  })
})

import * as t from 'lib0/testing'
import * as s from 'lib0/schema'
import * as Y from '../src/index.js'

/**
 * @param {any} val
 * @return {ContentAttribute<any>}
 */
const attr = val => Y.createContentAttribute('u', val)

/**
 * An IdMap holding one attribute value per range, all on client 1.
 *
 * @param {Array<any>} vals
 * @return {IdMap<any>}
 */
const idMapOf = vals => {
  const m = Y.createIdMap()
  vals.forEach((v, i) => m.add(1, i * 10, 10, [attr(v)]))
  return m
}

/**
 * @return {IdSet}
 */
const idSetOf = () => {
  const set = Y.createIdSet()
  set.add(1, 0, 10)
  return set
}

/**
 * Every schema on the public surface, paired with a value it must accept.
 *
 * The explicit return annotation is required: without it the mixed tuples infer a union element
 * type and destructuring `$schema` loses `.check`.
 *
 * @return {Array<[string, s.Schema<any>, any]>}
 */
const $schemas = () => [
  ['$idSet', Y.$idSet, Y.createIdSet()],
  ['$idMapAny', Y.$idMapAny, Y.createIdMap()],
  ['$idMap($string)', Y.$idMap(s.$string), idMapOf(['a'])],
  ['$contentIds', Y.$contentIds, Y.createContentIds()],
  ['$contentMap', Y.$contentMap, Y.createContentMap()],
  ['$doc', Y.$doc, new Y.Doc()],
  ['$nodeAny', Y.$nodeAny, new Y.Doc().get('n')],
  ['$node({name:"p"})', Y.$node({ name: 'p' }), new Y.Doc().get('n', 'p')]
]

/**
 * @param {t.TestCase} _tc
 */
export const testSchemasAcceptTheirOwnInstance = _tc => {
  $schemas().forEach(([name, $schema, instance]) => {
    t.group(name, () => {
      t.assert($schema.check(instance))
    })
  })
}

/**
 * No schema accepts a foreign value, and none throws. `s.$object` returns false for null and reads
 * its shape's keys off the value, so primitives / arrays / Maps fail on the `undefined` fields.
 *
 * @param {t.TestCase} _tc
 */
export const testSchemasRejectJunk = _tc => {
  const junk = [null, undefined, {}, 0, 1, '', 'idSet', [], true, false, new Map(), new Set(), () => {}]
  $schemas().forEach(([name, $schema]) => {
    t.group(name, () => {
      junk.forEach(j => {
        t.assert(!$schema.check(j), `must reject ${typeof j} ${String(j)}`)
      })
    })
  })
}

/**
 * The nominal tags discriminate IdSet from IdMap in both directions. Structurally an IdSet
 * (`{clients}`) is a *subset* of an IdMap (`{clients, attrsH, attrs}`), and `s.$object` always
 * permits excess properties - so only a nominal check can tell them apart.
 *
 * @param {t.TestCase} _tc
 */
export const testIdSetIdMapDiscrimination = _tc => {
  t.assert(!Y.$idSet.check(Y.createIdMap()), '$idSet rejects an IdMap')
  t.assert(!Y.$idMapAny.check(Y.createIdSet()), '$idMapAny rejects an IdSet')
  t.assert(!Y.$idMap(s.$string).check(Y.createIdSet()), '$idMap rejects an IdSet')
}

/**
 * @param {t.TestCase} _tc
 */
export const testContentIdsVsContentMap = _tc => {
  const cIds = Y.createContentIds()
  const cMap = Y.createContentMap()
  t.group('positive', () => {
    t.assert(Y.$contentIds.check(cIds))
    t.assert(Y.$contentMap.check(cMap))
  })
  t.group('both directions', () => {
    t.assert(!Y.$contentIds.check(cMap), '$contentIds rejects a ContentMap')
    t.assert(!Y.$contentMap.check(cIds), '$contentMap rejects a ContentIds')
  })
  t.group('mixed shapes', () => {
    const a = { inserts: Y.createIdSet(), deletes: Y.createIdMap() }
    const b = { inserts: Y.createIdMap(), deletes: Y.createIdSet() }
    t.assert(!Y.$contentIds.check(a))
    t.assert(!Y.$contentIds.check(b))
    t.assert(!Y.$contentMap.check(a))
    t.assert(!Y.$contentMap.check(b))
  })
  t.group('missing fields', () => {
    t.assert(!Y.$contentIds.check({ inserts: Y.createIdSet() }), 'deletes missing')
    t.assert(!Y.$contentIds.check({ deletes: Y.createIdSet() }), 'inserts missing')
  })
  t.group('excess properties are allowed - s.$object reads the shape keys', () => {
    t.assert(Y.$contentIds.check({ ...Y.createContentIds(), extra: 1 }))
  })
}

/**
 * $idMap($attrs) checks the mapped values, not merely the nominal type.
 *
 * @param {t.TestCase} _tc
 */
export const testIdMapValueSchema = _tc => {
  t.group('accepts the matching value type, rejects the other', () => {
    t.assert(Y.$idMap(s.$string).check(idMapOf(['a', 'b'])))
    t.assert(!Y.$idMap(s.$string).check(idMapOf([1, 2])))
    t.assert(Y.$idMap(s.$number).check(idMapOf([1, 2])))
    t.assert(!Y.$idMap(s.$number).check(idMapOf(['a', 'b'])))
  })
  t.group('a single mismatching value is enough to reject', () => {
    t.assert(!Y.$idMap(s.$string).check(idMapOf(['a', 1])))
    t.assert(!Y.$idMap(s.$number).check(idMapOf([1, 'a'])))
  })
  t.group('an empty map holds no values, so it satisfies every $attrs', () => {
    t.assert(Y.$idMap(s.$string).check(Y.createIdMap()))
    t.assert(Y.$idMap(s.$number).check(Y.createIdMap()))
  })
  t.group('$idMapAny ignores the value type', () => {
    t.assert(Y.$idMapAny.check(idMapOf(['a'])))
    t.assert(Y.$idMapAny.check(idMapOf([1])))
  })
}

/**
 * `check()` must not mutate its argument. `AttrRanges#getIds` sorts and splices in place, so a check
 * built on it would silently reorder the caller's map; `everyAttr` iterates the raw ranges instead.
 *
 * @param {t.TestCase} _tc
 */
export const testIdMapCheckDoesNotMutate = _tc => {
  const m = Y.createIdMap()
  // deliberately out of clock order, so a sort would be observable
  m.add(1, 10, 5, [attr('b')])
  m.add(1, 0, 10, [attr('a')])
  const ranges = /** @type {any} */ (m.clients.get(1))
  t.assert(ranges.sorted === false, 'precondition: not yet sorted')
  t.assert(Y.$idMap(s.$string).check(m))
  t.assert(ranges.sorted === false, 'check() must not have sorted the ranges')
}

/**
 * Every real IdMap producer yields a map that $idMap validates correctly.
 *
 * Every producer fed only string values must be accepted by `$idMap($string)`. The `keepsValues`
 * flag drives the far more important negative assertion: `$idMap($number)` must *reject* it. Only
 * the three genuinely-emptying producers are exempt - they hold nothing, so they satisfy every
 * `$attrs` vacuously and cannot discriminate. Without the negative, `$idMap($string).check` would
 * pass just as happily on a producer that silently dropped every attribute.
 *
 * @param {t.TestCase} _tc
 */
export const testIdMapProducers = _tc => {
  /**
   * @type {Array<[string, () => IdMap<any>, boolean]>}
   */
  const producers = [
    ['createIdMap', () => Y.createIdMap(), false],
    ['add', () => idMapOf(['k']), true],
    ['mergeIdMaps', () => Y.mergeIdMaps([idMapOf(['k']), idMapOf(['j'])]), true],
    ['diffIdMap (exclude all)', () => Y.diffIdMap(idMapOf(['k']), idSetOf()), false],
    ['diffIdMap (partial)', () => {
      const exclude = Y.createIdSet()
      exclude.add(1, 0, 5)
      return Y.diffIdMap(idMapOf(['k']), exclude)
    }, true],
    ['intersectMaps', () => Y.intersectMaps(idMapOf(['k']), idMapOf(['k'])), true],
    ['createIdMapFromIdSet', () => Y.createIdMapFromIdSet(idSetOf(), [attr('k')]), true],
    ['filterIdMap (keep)', () => Y.filterIdMap(idMapOf(['k']), () => true), true],
    ['filterIdMap (drop)', () => Y.filterIdMap(idMapOf(['k']), () => false), false],
    ['decodeIdMap(encodeIdMap)', () => Y.decodeIdMap(Y.encodeIdMap(idMapOf(['k']))), true],
    ['insertIntoIdMap(dest, IdMap)', () => {
      const dest = Y.createIdMap()
      Y.insertIntoIdMap(dest, idMapOf(['k']))
      return dest
    }, true]
  ]
  producers.forEach(([name, produce, keepsValues]) => {
    t.group(name, () => {
      const m = produce()
      t.assert(Y.$idMapAny.check(m), 'is an IdMap')
      t.assert(Y.$idMap(s.$string).check(m), 'holds only string values (vacuously so when empty)')
      if (keepsValues) {
        t.assert(!Y.$idMap(s.$number).check(m), 'carries its value through, so it rejects $number')
      }
    })
  })
}

/**
 * `insertIntoIdMap`'s `src` may be an IdSet, which puts attribute-less `IdRanges` into an `IdMap`.
 * `$idMap` must not throw on those - `IdRange#attrs` is `[]` by design, so they are vacuously fine.
 *
 * @param {t.TestCase} _tc
 */
export const testIdMapWithIdRanges = _tc => {
  t.group('an IdSet merged into an IdMap', () => {
    const dest = Y.createIdMap()
    Y.insertIntoIdMap(dest, idSetOf())
    t.assert(Y.$idMap(s.$string).check(dest), 'no attributes present, so nothing can violate $attrs')
    t.assert(Y.$idMap(s.$number).check(dest))
  })
  t.group('a map holding both AttrRanges and IdRanges still checks its values', () => {
    const dest = idMapOf(['k']) // client 1 -> AttrRanges
    const other = Y.createIdSet()
    other.add(2, 0, 10) // client 2 -> IdRanges
    Y.insertIntoIdMap(dest, other)
    t.assert(Y.$idMap(s.$string).check(dest))
    t.assert(!Y.$idMap(s.$number).check(dest), 'client 1 still holds a string')
  })
  t.group('an IdRanges container that later receives AttrRanges on the SAME client', () => {
    // `_insertIntoIdSet` picks the container class from whichever `src` reaches a client first, and
    // its append branch copies elements without checking their class. So an IdSet-first / IdMap-
    // second sequence leaves real AttrRanges inside an `IdRanges`. `IdRanges#everyAttr` must
    // iterate rather than shortcut to `true`, or these attributes become invisible to `$idMap`.
    const dest = Y.createIdMap()
    const set = Y.createIdSet()
    set.add(1, 0, 10)
    Y.insertIntoIdMap(dest, set) // client 1 -> IdRanges container
    Y.insertIntoIdMap(dest, idMapOf([42])) // same client -> AttrRange(42) appended into it
    t.assert(/** @type {any} */ (dest.clients.get(1)).constructor.name === 'IdRanges', 'precondition: still an IdRanges')
    t.assert(!Y.$idMap(s.$string).check(dest), 'the leaked number 42 must be seen')
    t.assert(!Y.$idMap(s.$never).check(dest), '$never must reject a map that holds a value')
    t.assert(Y.$idMap(s.$number).check(dest), 'and accepted for the matching schema')
    t.group('the verdict agrees with an encode round-trip', () => {
      const rt = Y.decodeIdMap(Y.encodeIdMap(dest))
      t.assert(Y.$idMap(s.$string).check(rt) === Y.$idMap(s.$string).check(dest))
      t.assert(Y.$idMap(s.$number).check(rt) === Y.$idMap(s.$number).check(dest))
    })
  })
}

/**
 * @param {t.TestCase} _tc
 */
export const testNodeSchemas = _tc => {
  const ydoc = new Y.Doc()
  const unnamed = ydoc.get('unnamed')
  const para = ydoc.get('para', 'p')
  t.group('$nodeAny', () => {
    t.assert(Y.$nodeAny.check(unnamed))
    t.assert(Y.$nodeAny.check(para))
    t.assert(!Y.$nodeAny.check(ydoc), 'a Doc is not a Node')
    t.assert(!Y.$doc.check(para), 'a Node is not a Doc')
  })
  t.group('$node(conf) checks the name', () => {
    t.assert(Y.$node({ name: 'p' }).check(para))
    t.assert(!Y.$node({ name: 'h1' }).check(para), 'discriminates between named nodes')
  })
  t.group('a conf without a name accepts any node', () => {
    t.assert(Y.$node({ text: true }).check(para))
    t.assert(Y.$node({ text: true }).check(unnamed))
    t.assert(Y.$node({}).check(unnamed))
  })
  t.group('every ReadableDeltaConf name form', () => {
    t.assert(Y.$node({ name: ['p', 'h1'] }).check(para), 'array form')
    t.assert(!Y.$node({ name: ['h1', 'h2'] }).check(para))
    t.assert(Y.$node({ name: s.$string }).check(para), 'schema form')
  })
  t.group('a named conf rejects a nameless node', () => {
    // Deliberately stricter than lib0's $Delta.check, which skips the name when name == null: a
    // nameless *node* is definitively a fragment, whereas a nameless *delta* asserts nothing.
    t.assert(unnamed.name === null, 'precondition')
    t.assert(!Y.$node({ name: 'p' }).check(unnamed))
    t.assert(!Y.$node({ name: s.$string }).check(unnamed))
  })
}

/**
 * The tags are interned in a global cross-install registry, so re-declaring a name returns the very
 * same schema object. That is what makes `$type` sound across duplicate yjs installations, and what
 * an `x.$type === $idMapAny` dispatch would rely on.
 *
 * Identity (`===`), never `.equals()` - `$Type#equals` compares an unset `.shape`, so any two
 * `$Type`s compare equal.
 *
 * @param {t.TestCase} _tc
 */
export const testTagInterning = _tc => {
  t.assert(s.$type('y:idSet', null) === Y.$idSet)
  t.assert(s.$type('y:idMap', null) === Y.$idMapAny)
  t.assert(s.$type('y:node', null) === Y.$nodeAny)
  t.assert(s.$type('y:doc', null) === Y.$doc)
  t.assert(s.$type('y:renderer', null) === Y.$renderer)
}

/**
 * The prototype stamps are what `check()` reads.
 *
 * @param {t.TestCase} _tc
 */
export const testPrototypeStamps = _tc => {
  t.assert(Y.IdSet.prototype.$type === Y.$idSet)
  t.assert(Y.IdMap.prototype.$type === Y.$idMapAny)
  t.assert(Y.Node.prototype.$type === Y.$nodeAny)
  t.assert(Y.Doc.prototype.$type === Y.$doc)
  t.group('instances carry the tag', () => {
    t.assert(Y.createIdSet().$type === Y.$idSet)
    t.assert(Y.createIdMap().$type === Y.$idMapAny)
    t.assert(new Y.Doc().get('n').$type === Y.$nodeAny)
    t.assert(new Y.Doc().$type === Y.$doc)
  })
}

import * as map from 'lib0/map'
import * as set from 'lib0/set'

import { diffIdSet, intersectSets, mergeIdSets } from './ids.js'
import { createAbsolutePositionFromRelativePosition, createRelativePosition } from './RelativePosition.js'

/**
 * @template {DeltaConf} DConf
 * YEvent describes the changes on a YNode.
 */
export class YEvent {
  /**
   * @param {YNode<DConf>} target The changed type.
   * @param {import('./Transaction.js').Transaction} transaction
   * @param {Set<any>?} subs The keys that changed
   */
  constructor (target, transaction, subs) {
    /**
     * The type on which this event was created on.
     * @type {import('../ynode.js').YNode<DConf>}
     */
    this.target = target
    /**
     * The current target on which the observe callback is called.
     * @type {YNode<any>}
     */
    this.currentTarget = target
    /**
     * The transaction that triggered this event.
     * @type {import('./Transaction.js').Transaction}
     */
    this.transaction = transaction
    /**
     * @type {Delta<import('../ynode.js').DeltaConfDeltaToYNode<DConf>>|null}
     */
    this._delta = null
    /**
     * @type {Delta<DConf>|null}
     */
    this._deltaDeep = null
    /**
     * Whether the children changed.
     * @type {Boolean}
     * @private
     */
    this.childListChanged = false
    /**
     * Set of all changed attributes.
     * @type {Set<string>}
     */
    this.keysChanged = new Set()
    subs?.forEach((sub) => {
      if (sub === null) {
        this.childListChanged = true
      } else {
        this.keysChanged.add(sub)
      }
    })
  }

  /**
   * Check if a struct is deleted by this event.
   *
   * In contrast to change.deleted, this method also returns true if the struct was added and then deleted.
   *
   * @param {AbstractStruct} struct
   * @return {boolean}
   */
  deletes (struct) {
    return this.transaction.deleteSet.hasId(struct.id)
  }

  /**
   * Check if a struct is added by this event.
   *
   * In contrast to change.deleted, this method also returns true if the struct was added and then deleted.
   *
   * @param {AbstractStruct} struct
   * @return {boolean}
   */
  adds (struct) {
    return this.transaction.insertSet.hasId(struct.id)
  }

  /**
   * @template {boolean} [Deep=false]
   * @param {object} [opts]
   * @param {AbstractRenderer?} [opts.renderer] - renders the content (with attributions); defaults to the target type's active renderer (see {@link YNode#useRenderer}), i.e. `null` (render as-is) unless changed
   * @param {Deep} [opts.deep]
   * @return {Deep extends true ? Delta<DConf> : Delta<import('../ynode.js').DeltaConfDeltaToYNode<DConf>>} The Delta representation of this type.
   *
   * @public
   */
  getDelta ({ renderer = this.target._renderer, deep } = {}) {
    const insertSet = this.transaction.insertSet
    const deleteSet = this.transaction.deleteSet
    // content that was both inserted AND deleted by this transaction is normally invisible — but a
    // renderer may still render it (e.g. remote content integrated under a suggestion-deleted
    // parent is auto-deleted yet rendered with a delete attribution). Render
    // `(I ∪ D) − ((I ∩ D) − renderer.attributed)`: the symmetric difference plus the attributed
    // part of the intersection.
    const both = intersectSets(insertSet, deleteSet)
    const itemsToRender = mergeIdSets(
      (both.isEmpty() || renderer === null)
        ? [diffIdSet(insertSet, deleteSet), diffIdSet(deleteSet, insertSet)]
        : [diffIdSet(insertSet, deleteSet), diffIdSet(deleteSet, insertSet), intersectSets(both, renderer.attributed)]
    )
    /**
     * @todo this should be done only one in the transaction step
     *
     * @type {Map<YNode,Set<string|null>>|null}
     */
    let modified = this.transaction.changed
    if (deep) {
      // need to add deep changes to copy of modified
      const dchanged = new Map()
      modified.forEach((attrs, type) => {
        dchanged.set(type, new Set(attrs))
      })
      for (let m of modified.keys()) {
        while (m._item != null) {
          const item = m._item
          const ms = map.setIfUndefined(dchanged, item?.parent, set.create)
          if (item && !ms.has(item.parentSub)) {
            ms.add(item.parentSub)
            m = /** @type {any} */ (item.parent)
          } else {
            break
          }
        }
      }
      modified = dchanged
    }
    return /** @type {any} */ (this.target.toDelta({ renderer, itemsToRender, retainDeletes: true, insertedItems: insertSet, deep: !!deep, modified }))
  }

  /**
   * Compute the changes in the delta format.
   * A {@link https://quilljs.com/docs/delta/|Quill Delta}) that represents the changes on the document.
   *
   * @type {Delta<import('../ynode.js').DeltaConfDeltaToYNode<DConf>>} The Delta representation of this type.
   * @public
   */
  get delta () {
    return /** @type {any} */ (this._delta ?? (this._delta = this.getDelta().done()))
  }

  /**
   * Compute the changes in the delta format.
   * A {@link https://quilljs.com/docs/delta/|Quill Delta}) that represents the changes on the document.
   *
   * @type {Delta<DConf>} The Delta representation of this type.
   * @public
   */
  get deltaDeep () {
    return /** @type {any} */ (this._deltaDeep ?? (this._deltaDeep = /** @type {any} */ (this.getDelta({ deep: true }))))
  }
}

/**
 * Compute the path from this type to the specified target.
 *
 * @example
 *   // `child` should be accessible via `type.get(path[0]).get(path[1])..`
 *   const path = type.getPathTo(child)
 *   // assuming `type instanceof YArray`
 *   console.log(path) // might look like => [2, 'key1']
 *   child === type.get(path[0]).get(path[1])
 *
 * @param {YNode} parent
 * @param {YNode} child target
 * @param {AbstractRenderer?} renderer
 * @return {Array<string|number>} Path to the target
 *
 * @private
 * @function
 */
export const getPathTo = (parent, child, renderer = null) => {
  const path = []
  const doc = /** @type {Doc} */ (parent.doc)
  while (child._item !== null && child !== parent) {
    if (child._item.parentSub !== null) {
      // parent is map-ish
      path.unshift(child._item.parentSub)
    } else {
      const parent = /** @type {import('../ynode.js').YNode} */ (child._item.parent)
      // parent is array-ish
      const apos = /** @type {import('../utils/RelativePosition.js').AbsolutePosition} */ (createAbsolutePositionFromRelativePosition(createRelativePosition(parent, child._item.id), doc, false, renderer))
      path.unshift(apos.index)
    }
    child = /** @type {YNode} */ (child._item.parent)
  }
  return path
}

