  const clockRange = 100
  const idset = createRandomIdSet(tc.prng, clients, clockRange)
  const client = Array.from(idset.clients.keys())[0]
  const clock = prng.int31(tc.prng, 0, clockRange)
  const len = prng.int31(tc.prng, 0, math.round((clockRange - clock) * 1.2)) // allow exceeding range to cover more edge cases
  const idsetOfDeletes = d.createIdSet()
  idsetOfDeletes.add(client, clock, len)
  const diffed = d.diffIdSet(idset, idsetOfDeletes)
  idset.delete(client, clock, len)
  for (let i = 0; i < len; i++) {
    t.assert(!idset.has(client, clock + i))
  }
  compareIdSets(idset, diffed)
}

/**
 * @param {t.TestCase} tc
 */
export const testRepeatMergingMultipleIdsets = tc => {
  const clients = 4
  const clockRange = 100
  /**
   * @type {Array<d.IdSet>}
   */
  const idss = []
  for (let i = 0; i < 3; i++) {
    idss.push(createRandomIdSet(tc.prng, clients, clockRange))
  }
  const merged = d.mergeIdSets(idss)
  const mergedReverse = d.mergeIdSets(idss.reverse())
  compareIdSets(merged, mergedReverse)
  const composed = d.createIdSet()
  for (let iclient = 0; iclient < clients; iclient++) {
    for (let iclock = 0; iclock < clockRange + 42; iclock++) {
      const mergedHas = merged.hasId(new ID(iclient, iclock))
      const oneHas = idss.some(ids => ids.hasId(new ID(iclient, iclock)))
      t.assert(mergedHas === oneHas)
      if (oneHas) {
        composed.add(iclient, iclock, 1)
      }
    }
  }
  compareIdSets(merged, composed)
}

/**
 * @param {t.TestCase} tc
 */
export const testRepeatRandomDiffing2 = tc => {
  const clients = 4
  const clockRange = 100
  const ids1 = createRandomIdSet(tc.prng, clients, clockRange)
  const ids2 = createRandomIdSet(tc.prng, clients, clockRange)
  const idsExclude = createRandomIdSet(tc.prng, clients, clockRange)
  const merged = d.mergeIdSets([ids1, ids2])
  const mergedExcluded = d.diffIdSet(merged, idsExclude)
  const e1 = d.diffIdSet(ids1, idsExclude)
  const e2 = d.diffIdSet(ids2, idsExclude)
  const excludedMerged = d.mergeIdSets([e1, e2])
  compareIdSets(mergedExcluded, excludedMerged)
}

/**
 * @param {t.TestCase} tc
 */
export const testRepeatRandomIntersects = tc => {
  const clients = 4
  const clockRange = 100
  const ids1 = createRandomIdSet(tc.prng, clients, clockRange)
  const ids2 = createRandomIdSet(tc.prng, clients, clockRange)
  const intersected = d.intersectSets(ids1, ids2)
  for (let client = 0; client < clients; client++) {
    for (let clock = 0; clock < clockRange; clock++) {
      t.assert((ids1.has(client, clock) && ids2.has(client, clock)) === intersected.has(client, clock))
    }
  }
  const diffed1 = d.diffIdSet(ids1, ids2)
  const altDiffed1 = d.diffIdSet(ids1, intersected)
  compareIdSets(diffed1, altDiffed1)
}

/**
 * The allocation-free `covers` / `coveredLength` must agree with per-id `has` and with the
 * allocating `slice(...)` reduction.
 *
 * @param {t.TestCase} tc
 */
export const testRepeatRandomCoversAndCoveredLength = tc => {
  const clients = 4
  const clockRange = 100
  const ids = createRandomIdSet(tc.prng, clients, clockRange)
  for (let iter = 0; iter < 300; iter++) {
    const client = prng.int31(tc.prng, 0, clients - 1)
    const clock = prng.int31(tc.prng, 0, clockRange)
    const len = prng.int31(tc.prng, 1, clockRange - clock + 5) // may exceed the range to cover edges
    // reference by scanning every id in the range
    let refCovered = 0
    let refCovers = true
    for (let c = clock; c < clock + len; c++) {
      if (ids.has(client, c)) refCovered++
      else refCovers = false
    }
    t.assert(ids.covers(client, clock, len) === refCovers)
    t.assert(ids.coveredLength(client, clock, len) === refCovered)
    // cross-check against the allocating slice
    const sliceCovered = ids.slice(client, clock, len).reduce((s, r) => r.exists ? s + r.len : s, 0)
    t.assert(ids.coveredLength(client, clock, len) === sliceCovered)
  }
}

/**
 * The struct that covers `clock` for the document's local client.
 *
 * @param {Y.Doc} doc
 * @param {number} clock
 * @return {any}
 */
const structAt = (doc, clock) => {
  const structs = /** @type {Array<any>} */ (doc.store.clients.get(doc.clientID))
  return structs[Y.findIndexSS(structs, clock)]
}

/**
 * `gcIdSet` collects the deleted content referenced by an IdSet on a `gc: false` document,
 * without changing the observable state, and the result still converges with a peer.
 *
 * @param {t.TestCase} _tc
 */
export const testGcIdSetBasic = _tc => {
  const doc = new Y.Doc({ gc: false })
  const yarr = doc.get('array')
  yarr.insert(0, ['a', 'b', 'c', 'd'])
  yarr.delete(1, 2) // delete 'b' (clock 1) and 'c' (clock 2)
  // gc is disabled, so the deleted content is retained
  t.assert(structAt(doc, 1).content instanceof Y.ContentAny)

  Y.gcIdSet(doc, Y.createDeleteSetFromStructStore(doc.store))

  // observable state is unchanged
  t.compare(yarr.toArray(), ['a', 'd'])
  // every collectible deleted item is now collected
  doc.store.clients.forEach(structs => {
    structs.forEach(struct => {
      if (struct.constructor === Y.Item && struct.deleted && !struct.keep) {
        t.assert(struct.content instanceof Y.ContentDeleted)
      }
    })
  })
  // still converges with a fresh peer
  const peer = new Y.Doc()
  Y.applyUpdate(peer, Y.encodeStateAsUpdate(doc))
  t.compare(peer.get('array').toArray(), ['a', 'd'])
}

/**
 * `gcIdSet` splits structs at the IdSet boundaries, so only the exact referenced content is
 * collected - the rest of a partially-covered deleted run is preserved.
 *
 * @param {t.TestCase} _tc
 */
export const testGcIdSetPartialRange = _tc => {
  const doc = new Y.Doc({ gc: false })
  const yarr = doc.get('array')
  yarr.insert(0, ['a', 'b', 'c', 'd', 'e'])
  yarr.delete(1, 4) // delete 'b','c','d','e' (clocks 1..4), retained because gc is off

  // collect only the middle of the deleted run: clocks 2..3 ('c', 'd')
  const ids = d.createIdSet()
  ids.add(doc.clientID, 2, 2)
  Y.gcIdSet(doc, ids)

  t.compare(yarr.toArray(), ['a'])
  // 'b' (clock 1) and 'e' (clock 4) are outside the IdSet -> still retained
  t.assert(structAt(doc, 1).deleted && structAt(doc, 1).content instanceof Y.ContentAny)
  t.assert(structAt(doc, 4).deleted && structAt(doc, 4).content instanceof Y.ContentAny)
  // 'c','d' (clocks 2..3) were inside the IdSet -> collected
  t.assert(structAt(doc, 2).content instanceof Y.ContentDeleted)
}

/**
 * Ids that don't reference collectible content (live content) are skipped.
 *
 * @param {t.TestCase} _tc
 */
export const testGcIdSetSkipsLiveContent = _tc => {
  const doc = new Y.Doc({ gc: false })
  const yarr = doc.get('array')
  yarr.insert(0, ['a', 'b', 'c'])
  yarr.delete(1, 1) // delete only 'b'

  // pass *all* ids (live + deleted); only the deleted one is collectible
  Y.gcIdSet(doc, Y.createInsertSetFromStructStore(doc.store, false))

  t.compare(yarr.toArray(), ['a', 'c'])
  t.assert(structAt(doc, 0).content instanceof Y.ContentAny) // 'a' is live -> untouched
  t.assert(structAt(doc, 2).content instanceof Y.ContentAny) // 'c' is live -> untouched
  t.assert(structAt(doc, 1).content instanceof Y.ContentDeleted) // 'b' was deleted -> collected
}

/**
 * Calling `gcIdSet` twice is a no-op the second time.
 *
 * @param {t.TestCase} _tc
 */
export const testGcIdSetIdempotent = _tc => {
  const doc = new Y.Doc({ gc: false })
  const yarr = doc.get('array')
  yarr.insert(0, ['a', 'b', 'c'])
  yarr.delete(0, 2)
  const ds = Y.createDeleteSetFromStructStore(doc.store)
  Y.gcIdSet(doc, ds)
  const encoded = Y.encodeStateAsUpdate(doc)
  Y.gcIdSet(doc, ds) // second pass changes nothing
  t.compare(yarr.toArray(), ['c'])
  t.compare(Y.encodeStateAsUpdate(doc), encoded)
}

/**
 * Items flagged with `keep` (e.g. protected by an UndoManager) are not collected.
 *
 * @param {t.TestCase} _tc
 */
export const testGcIdSetRespectsKeep = _tc => {
  const doc = new Y.Doc({ gc: false })
  const yarr = doc.get('array')
  yarr.insert(0, ['a', 'b', 'c'])
  yarr.delete(1, 1) // delete 'b' (clock 1)
  structAt(doc, 1).keep = true // protect it from gc

  Y.gcIdSet(doc, Y.createDeleteSetFromStructStore(doc.store))

  // 'b' was kept -> still retained, not collected
  t.assert(structAt(doc, 1).deleted && structAt(doc, 1).content instanceof Y.ContentAny)
}

use crate::clock::ClockRange;
use crate::exid::ExId;
use crate::op_set2::op_set::{TopIter, VisIter};
use crate::op_set2::OpSet;
use crate::types::OpId;

use std::cmp::Ordering;
use std::fmt::Debug;
use std::iter::Peekable;
use std::ops::Range;

#[derive(Clone, Debug)]
pub(crate) struct Unshift<T: Iterator> {
    inner: T,
    next: Option<T::Item>,
}

impl<T: Iterator + Default> Default for Unshift<T> {
    fn default() -> Self {
        Self {
            inner: T::default(),
            next: None,
        }
    }
}

impl<T: Iterator> Unshift<T> {
    pub(crate) fn new(mut inner: T) -> Self {
        let next = inner.next();
        Self { inner, next }
    }

    pub(crate) fn peek(&self) -> Option<&T::Item> {
        self.next.as_ref()
    }
}

impl<T: Shiftable + Iterator> Unshift<T> {
    pub(crate) fn shift(&mut self, range: Range<usize>) {
        self.next = self.inner.shift_next(range);
    }
}

impl<T: Iterator> Iterator for Unshift<T> {
    type Item = T::Item;

    fn next(&mut self) -> Option<Self::Item> {
        let mut next = self.inner.next();
        std::mem::swap(&mut next, &mut self.next);
        next
    }

    fn nth(&mut self, n: usize) -> Option<Self::Item> {
        let mut next = self.inner.nth(n);
        std::mem::swap(&mut next, &mut self.next);
        next
    }
}

pub(crate) trait Skipper: Iterator<Item = usize> {}

pub(crate) trait Shiftable: Iterator + Debug {
    fn shift_next(&mut self, _range: Range<usize>) -> Option<<Self as Iterator>::Item>;
}

/// A peekable iterator that also supports repositioning.
///
/// Unlike [`std::iter::Peekable`] the lookahead can be discarded: [`Self::shift`]
/// repositions the inner iterator to a new range and stores the first item
/// of that range as the new lookahead.
#[derive(Clone, Debug, Default)]
pub(crate) struct PeekShift<I: Iterator> {
    iter: I,
    peeked: Option<I::Item>,
}

impl<I: Iterator> PeekShift<I> {
    pub(crate) fn new(iter: I) -> Self {
        Self { iter, peeked: None }
    }

    pub(crate) fn peek(&mut self) -> Option<&I::Item> {
        if self.peeked.is_none() {
            self.peeked = self.iter.next();
        }
        self.peeked.as_ref()
    }

    /// The next item if it satisfies `f`, leaving it as the lookahead
    /// otherwise.
    pub(crate) fn next_if(&mut self, f: impl FnOnce(&I::Item) -> bool) -> Option<I::Item> {
        match self.peek() {
            Some(item) if f(item) => self.peeked.take(),
            _ => None,
        }
    }
}

impl<I: Iterator + Shiftable> PeekShift<I> {
    /// Reposition to `range`, discarding the current lookahead; the first
    /// item of the new range (if any) becomes the lookahead.
    pub(crate) fn shift(&mut self, range: Range<usize>) {
        self.peeked = self.iter.shift_next(range);
    }
}

impl<I: Iterator> Iterator for PeekShift<I> {
    type Item = I::Item;

    fn next(&mut self) -> Option<Self::Item> {
        self.peeked.take().or_else(|| self.iter.next())
    }
}

#[derive(Debug)]
pub(crate) struct SkipWrap<I: Iterator<Item = usize>> {
    pub(crate) pos: usize,
    iter: I,
}

impl<I: Iterator<Item = usize>> Skipper for SkipWrap<I> {}

impl<I: Iterator<Item = usize>> SkipWrap<I> {
    pub(crate) fn new(pos: usize, iter: I) -> Self {
        Self { pos, iter }
    }
}

impl<I: Iterator<Item = usize>> Iterator for SkipWrap<I> {
    type Item = usize;

    fn next(&mut self) -> Option<Self::Item> {
        let pos = self.iter.next()?;
        let delta = pos - self.pos;
        self.pos = pos + 1;
        Some(delta)
    }
}

#[derive(Clone, Debug)]
pub(crate) struct SkipIter<I: Iterator + Debug + Clone, S: Skipper> {
    iter: I,
    skip: S,
}

impl<I: Iterator + Debug + Clone + Default, S: Skipper + Default> Default for SkipIter<I, S> {
    fn default() -> Self {
        Self {
            iter: I::default(),
            skip: S::default(),
        }
    }
}

impl<I: Iterator + Debug + Clone, S: Skipper> SkipIter<I, S> {
    pub(crate) fn new(iter: I, skip: S) -> Self {
        Self { iter, skip }
    }

    pub(crate) fn inner(&self) -> &I {
        &self.iter
    }
}

impl<I: Iterator + Debug + Clone + Shiftable, S: Skipper + Shiftable> Shiftable for SkipIter<I, S> {
    fn shift_next(&mut self, range: Range<usize>) -> Option<<Self as Iterator>::Item> {
        let skip = self.skip.shift_next(range.clone());
        let start = range.start + skip.unwrap_or(0);
        let end = range.end;
        self.iter.shift_next(start..end)
    }
}

impl<I: Iterator + Debug + Clone, S: Skipper> Iterator for SkipIter<I, S> {
    type Item = I::Item;

    fn next(&mut self) -> Option<Self::Item> {
        let skip = self.skip.next()?;
        if skip == 0 {
            self.iter.next()
        } else {
            self.iter.nth(skip)
        }
    }
}

#[derive(Clone, Debug)]
pub(crate) struct ExIdPromise<'a> {
    pub(crate) id: OpId,
    promise: OpSetOrExId<'a>,
}

impl PartialEq for ExIdPromise<'_> {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

#[derive(Clone)]
enum OpSetOrExId<'a> {
    OpSet(&'a OpSet),
    ExId(ExId),
}

impl std::fmt::Debug for OpSetOrExId<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            OpSetOrExId::OpSet(_) => write!(f, "OpSetOrExId::OpSet"),
            OpSetOrExId::ExId(e) => write!(f, "OpSetOrExId::ExId({:?})", e),
        }
    }
}

impl OpSetOrExId<'_> {
    fn into_owned(self, id: OpId) -> OpSetOrExId<'static> {
        match self {
            Self::OpSet(o) => OpSetOrExId::ExId(o.id_to_exid(id)),
            Self::ExId(e) => OpSetOrExId::ExId(e),
        }
    }
}

impl<'a> ExIdPromise<'a> {
    pub(crate) fn new(op_set: &'a OpSet, id: OpId) -> Self {
        Self {
            id,
            promise: OpSetOrExId::OpSet(op_set),
        }
    }

    pub(crate) fn exid(&self) -> ExId {
        match &self.promise {
            OpSetOrExId::OpSet(o) => o.id_to_exid(self.id),
            OpSetOrExId::ExId(e) => e.clone(),
        }
    }

    pub(crate) fn into_owned(self) -> ExIdPromise<'static> {
        ExIdPromise {
            id: self.id,
            promise: self.promise.into_owned(self.id),
        }
    }
}

// merges two iterators of only increasing usize and throw out dedupes

pub(crate) struct MergeIter<I, J>
where
    I: Iterator<Item = usize>,
    J: Iterator<Item = usize>,
{
    left: Peekable<I>,
    right: Peekable<J>,
    last_yielded: Option<usize>,
}

impl<I, J> MergeIter<I, J>
where
    I: Iterator<Item = usize>,
    J: Iterator<Item = usize>,
{
    pub(crate) fn new(left: I, right: J) -> Self {
        Self {
            left: left.peekable(),
            right: right.peekable(),
            last_yielded: None,
        }
    }

    pub(crate) fn skip(self) -> SkipWrap<Self> {
        let pos = self.last_yielded.map(|n| n + 1).unwrap_or(0);
        SkipWrap::new(pos, self)
    }
}

impl<I, J> Iterator for MergeIter<I, J>
where
    I: Iterator<Item = usize>,
    J: Iterator<Item = usize>,
{
    type Item = usize;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let next_val = match (self.left.peek(), self.right.peek()) {
                (Some(&l), Some(&r)) if l < r => self.left.next()?,
                (Some(&l), Some(&r)) if r < l => self.right.next()?,
                (Some(_), Some(_)) => {
                    self.left.next();
                    self.right.next()?
                }
                (Some(_), None) => self.left.next()?,
                (None, Some(_)) => self.right.next()?,
                (None, None) => return None,
            };

            if Some(next_val) != self.last_yielded {
                self.last_yielded = Some(next_val);
                return Some(next_val);
            }
        }
    }
}

/// A [`BoolColumnSkipper`] is an iterator that iterates over usize values
/// represnting ranges of `false` values in a boolean column. This can then
/// be used by other iterators to skip past elements for which the boolean
/// column is false
#[derive(Clone, Default, Debug)]
pub(crate) struct BoolColumnSkipper<'a> {
    iter: hexane::Iter<'a, bool>,
    range: Range<usize>,
    cursor: usize,
    pending: usize,
    exhausted: bool,
}

impl<'a> BoolColumnSkipper<'a> {
    pub(crate) fn new(iter: hexane::Iter<'a, bool>, range: Range<usize>) -> Self {
        let cursor = range.start;
        Self {
            iter,
            range,
            cursor,
            pending: 0,
            exhausted: false,
        }
    }
}

impl Skipper for BoolColumnSkipper<'_> {}

impl Shiftable for BoolColumnSkipper<'_> {
    fn shift_next(&mut self, range: Range<usize>) -> Option<<Self as Iterator>::Item> {
        self.range = range.clone();
        self.cursor = range.start;
        self.pending = 0;
        self.exhausted = false;

        let Some(value) = self.iter.shift_next(range.clone()) else {
            self.exhausted = true;
            return Some(range.end.saturating_sub(range.start));
        };

        self.cursor = range.start + 1;
        if value {
            Some(0)
        } else {
            Some(1 + self.next().unwrap_or(0))
        }
    }
}

impl Iterator for BoolColumnSkipper<'_> {
    type Item = usize;

    fn next(&mut self) -> Option<Self::Item> {
        if self.exhausted {
            return None;
        }
        if self.pending > 0 {
            self.pending -= 1;
            self.cursor += 1;
            Some(0)
        } else {
            let mut skipped = 0;
            while let Some(run) = self.iter.next_run() {
                if run.value && run.count > 0 {
                    self.pending = run.count - 1;
                    let pos = self.cursor + skipped;
                    self.cursor = pos + 1;
                    return Some(skipped);
                }
                skipped += run.count;
            }
            self.exhausted = true;
            let skip = self.range.end.saturating_sub(self.cursor);
            self.cursor = self.range.end.saturating_add(1);
            Some(skip)
        }
    }
}

#[derive(Clone, Default, Debug)]
struct PastSkipper<S> {
    before: S,
    after: S,
    state: (Diff, usize),
}

#[derive(Clone, Debug)]
enum DiffSkipper<S> {
    Diff(PastSkipper<S>),
    Current(S),
}

impl<S: Default> Default for DiffSkipper<S> {
    fn default() -> Self {
        Self::Current(S::default())
    }
}

impl<'a> DiffSkipper<VisIter<'a>> {
    fn new(op_set: &'a OpSet, clock: ClockRange, range: Range<usize>) -> Self {
        match clock {
            ClockRange::Current(clock) => {
                DiffSkipper::Current(VisIter::new(op_set, clock.as_ref(), range))
            }
            ClockRange::Diff(before, after) => {
                let before = VisIter::new(op_set, Some(&before), range.clone());
                let after = VisIter::new(op_set, Some(&after), range);
                DiffSkipper::Diff(PastSkipper::new(before, after))
            }
        }
    }
}

impl<'a> DiffSkipper<TopIter<'a>> {
    fn new_top(op_set: &'a OpSet, clock: ClockRange, range: Range<usize>) -> Self {
        match clock {
            ClockRange::Current(clock) => DiffSkipper::Current(TopIter::new(op_set, clock, range)),
            ClockRange::Diff(before, after) => {
                let before = TopIter::new(op_set, Some(before), range.clone());
                let after = TopIter::new(op_set, Some(after), range);
                DiffSkipper::Diff(PastSkipper::new(before, after))
            }
        }
    }
}

impl<S: Skipper> PastSkipper<S> {
    fn new(before: S, after: S) -> Self {
        Self {
            before,
            after,
            state: Default::default(),
        }
    }

    fn progress(&mut self, before: usize, after: usize) -> (Diff, usize) {
        match before.cmp(&after) {
            Ordering::Equal => {
                self.state = (Diff::Same, 0);
                (Diff::Same, before)
            }
            Ordering::Less => {
                self.state = (Diff::Del, after - before - 1);
                (Diff::Del, before)
            }
            Ordering::Greater => {
                self.state = (Diff::Add, before - after - 1);
                (Diff::Add, after)
            }
        }
    }

    fn next_skip(&mut self) -> Option<(usize, usize)> {
        match self.state {
            (Diff::Same, _) => {
                let before = self.before.next();
                let after = self.after.next();
                Some((before?, after?))
            }
            (Diff::Del, delta) => {
                let before = self.before.next()?;
                Some((before, delta))
            }
            (Diff::Add, delta) => {
                let after = self.after.next()?;
                Some((delta, after))
            }
        }
    }
}

impl<S> Iterator for DiffSkipper<S>
where
    S: Skipper,
{
    type Item = (Diff, usize);

    fn next(&mut self) -> Option<Self::Item> {
        match self {
            DiffSkipper::Current(iter) => Some((Diff::Add, iter.next()?)),
            DiffSkipper::Diff(iter) => iter.next(),
        }
    }
}

impl<S> Iterator for PastSkipper<S>
where
    S: Skipper,
{
    type Item = (Diff, usize);

    fn next(&mut self) -> Option<Self::Item> {
        let (before, after) = self.next_skip()?;

        Some(self.progress(before, after))
    }
}

impl<S> Shiftable for DiffSkipper<S>
where
    S: Skipper + Shiftable + Debug,
{
    fn shift_next(&mut self, range: Range<usize>) -> Option<(Diff, usize)> {
        match self {
            Self::Current(iter) => Some((Diff::Add, iter.shift_next(range)?)),
            Self::Diff(iter) => iter.shift_next(range),
        }
    }
}

impl<S> Shiftable for PastSkipper<S>
where
    S: Skipper + Shiftable + Debug,
{
    fn shift_next(&mut self, range: Range<usize>) -> Option<(Diff, usize)> {
        let skip_before = self.before.shift_next(range.clone());
        let skip_after = self.after.shift_next(range.clone());

        Some(self.progress(skip_before?, skip_after?))
    }
}

#[derive(Clone, Debug)]
pub(crate) struct DiffIter<'a, I: Iterator + Debug + Clone, S = VisIter<'a>>
where
    S: Skipper,
{
    iter: I,
    skipper: DiffSkipper<S>,
    _phantom: std::marker::PhantomData<&'a ()>,
}

impl<I, S> Default for DiffIter<'_, I, S>
where
    I: Iterator + Debug + Clone + Default,
    S: Skipper + Default,
    DiffSkipper<S>: Default,
{
    fn default() -> Self {
        Self {
            iter: I::default(),
            skipper: DiffSkipper::default(),
            _phantom: Default::default(),
        }
    }
}

impl<'a, I: Iterator + Debug + Clone> DiffIter<'a, I, VisIter<'a>> {
    pub(crate) fn new(op_set: &'a OpSet, iter: I, clock: ClockRange, range: Range<usize>) -> Self {
        Self {
            iter,
            skipper: DiffSkipper::new(op_set, clock, range),
            _phantom: Default::default(),
        }
    }
}

impl<'a, I: Iterator + Debug + Clone> DiffIter<'a, I, TopIter<'a>> {
    pub(crate) fn new_top(
        op_set: &'a OpSet,
        iter: I,
        clock: ClockRange,
        range: Range<usize>,
    ) -> Self {
        Self {
            iter,
            skipper: DiffSkipper::new_top(op_set, clock, range),
            _phantom: Default::default(),
        }
    }
}

impl<I, S> Shiftable for DiffIter<'_, I, S>
where
    I: Iterator + Debug + Clone + Shiftable,
    S: Skipper + Shiftable + Debug,
{
    fn shift_next(&mut self, range: Range<usize>) -> Option<<Self as Iterator>::Item> {
        let (diff, skip) = self.skipper.shift_next(range.clone())?;
        let start = range.start + skip;
        let item = self.iter.shift_next(start..range.end)?;
        Some((diff, item))
    }
}

impl<I, S> Iterator for DiffIter<'_, I, S>
where
    I: Iterator + Debug + Clone,
    S: Skipper,
{
    type Item = (Diff, I::Item);

    fn next(&mut self) -> Option<Self::Item> {
        let (diff, skip) = self.skipper.next()?;
        // nth(0) is noticeably slower for column iterators than next().
        let item = if skip == 0 {
            self.iter.next()
        } else {
            self.iter.nth(skip)
        };
        Some((diff, item?))
    }
}

#[derive(Clone, Default, Copy, Debug, PartialEq)]
pub(crate) enum Diff {
    #[default]
    Same,
    Add,
    Del,
}

impl Diff {
    pub(crate) fn is_del(&self) -> bool {
        matches!(self, Diff::Del)
    }

    pub(crate) fn is_visible(&self) -> bool {
        !self.is_del()
    }
}

use core::fmt;
use std::borrow::Cow;
use std::str::FromStr;

use crate::error;

/// [`Authors`] records change authorship in an Automerge document.
///
/// # Authors and Actors
///
/// An [`Author`] consists of free-form bytes, to identify a single author.
/// For each author, there will be one or more actors associated with the
/// author, giving a 1-to-N relationship. [`Authors`] maintains an index of
/// these relationships.
///
/// # Current Author
///
/// [`Authors`] will also keep track of the current [`Author`] that is acting on
/// the document, if set.
#[derive(Clone, Debug, Default)]
pub(crate) struct Authors {
    /// Previously recorded [`Author`]s.
    ///
    /// The `Vec` must contain unique [`Authors`], and should be indexed by the
    /// existing actor index of an Automerge document.
    ///
    /// Each [`Author`] will have one or more [`ActorId`](crate::ActorId)s related to it, since
    /// a new [`ActorId`](crate::ActorId) is produced when an [`Author`] changes on a document.
    authors: Vec<Author<'static>>,
    // TODO(finto): This is never actually used. It's set to `None` and
    // re-assigned in `put_author`.
    /// The current [`Author`] acting on the document.
    ///
    /// Using the [`AuthorIdx`] to index into [`Authors::authors`].
    current: Option<AuthorIdx>,
    /// A mapping from an actor to an author.
    ///
    /// Each index of the `Vec` is the same as the index into an actors set, and
    /// the entry at the index corresponds to an entry in [`Authors::authors`].
    actor_to_author: Vec<Option<AuthorIdx>>,
}

impl Authors {
    /// Initialize the [`Authors`] set with a known size of actors, setting all
    /// mapping entries to `None`.
    pub(crate) fn with_actors(actors: usize) -> Self {
        Self {
            authors: Vec::default(),
            current: None,
            actor_to_author: vec![None; actors],
        }
    }

    /// Return the set of previously recorded [`Author`]s.
    pub(crate) fn get_authors(&self) -> &[Author<'static>] {
        &self.authors
    }

    /// Return the [`Author`] that is associated with the given `actor`.
    pub(crate) fn get_author_for_actor(&self, actor: usize) -> Option<Author<'_>> {
        let author = self.actor_to_author.get(actor)?.as_ref()?.as_usize();
        self.authors.get(author).map(|author| author.as_borrowed())
    }

    /// Return the actor indices for the given `author`.
    ///
    /// If the `author` exists, this will return at least one element in the
    /// iterator. Otherwise, the iterator will be empty.
    pub(crate) fn get_actors_for_author(
        &self,
        author: &Author<'_>,
    ) -> impl Iterator<Item = usize> + '_ {
        self.authors
            .binary_search(author)
            .ok()
            .map(|idx| {
                let idx = AuthorIdx::from(idx);
                self.actor_to_author
                    .iter()
                    .enumerate()
                    .filter_map(move |(i, a)| (a.as_ref()? == &idx).then_some(i))
            })
            .into_iter()
            .flatten()
    }

    /// Assign the given `actor` to the given `author`.
    pub(crate) fn assign_author(&mut self, author: Author<'static>, actor: usize) {
        let author_id = self.put_author(author);
        self.actor_to_author[actor] = Some(author_id);
    }

    /// Insert the `actor` into the actor-to-author mapping, setting the author
    /// as `None`.
    pub(crate) fn insert_actor(&mut self, actor: usize) {
        self.actor_to_author.insert(actor, None);
    }

    /// Remove the `actor` from the actor to author mapping.
    ///
    /// Note that this may leave a dangling [`Author`] in the set of authors,
    /// once the final actor has been removed. In reality, actors are only
    /// removed as part of rollback semantics, so that should never happen.
    pub(crate) fn remove_actor(&mut self, actor: usize) {
        self.actor_to_author.remove(actor);
    }

    /// [`Author`] is inserted into the set of authors, and the [`Author`] is
    /// ensured to be unique and in-order.
    ///
    /// When a new [`Author`] is being inserted, this function re-indexes.
    #[must_use]
    fn put_author(&mut self, author: Author<'static>) -> AuthorIdx {
        match self.authors.binary_search(&author) {
            Err(index) => {
                self.authors.insert(index, author);
                for a in self.actor_to_author.iter_mut().flatten() {
                    a.with_new_author(index)
                }
                if let Some(a) = self.current.as_mut() {
                    a.with_new_author(index);
                }
                index.into()
            }
            Ok(index) => index.into(),
        }
    }
}

/// An [`Author`] is identified by a free form set of bytes.
///
/// # Construction
///
/// An [`Author`] can be constructed from a raw set of bytes, either `Vec<u8>`
/// or `&[u8]`, or else by parsing string values (see [`hex::decode`]).
///
/// # Formatting
///
/// The author is formatted as a hexadecimal string (see [`hex::encode`]).
#[derive(PartialEq, Hash, Clone, Ord, Eq, PartialOrd)]
pub struct Author<'a>(Cow<'a, [u8]>);

impl<'a> Author<'a> {
    /// Clone the [`Author`] into an owned [`Author`] with a `static` lifetime.
    pub fn into_owned(self) -> Author<'static> {
        Author::from(self.0.clone().into_owned())
    }

    /// Return an [`Author`] with `b` lifetime without cloning the underlying bytes
    pub fn as_borrowed<'b>(&'b self) -> Author<'b>
    where
        'b: 'a,
    {
        Self(Cow::Borrowed(self.as_bytes()))
    }

    /// Return the raw bytes of the [`Author`].
    pub fn as_bytes(&self) -> &[u8] {
        self.0.as_ref()
    }

    /// Encode the [`Author`] to a hexadecimal string (see [`hex::encode`]).
    pub fn to_hex_string(&self) -> String {
        hex::encode(&self.0)
    }
}

impl<'a> fmt::Display for Author<'a> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_hex_string())
    }
}

impl<'a> From<Vec<u8>> for Author<'a> {
    fn from(v: Vec<u8>) -> Self {
        Author(Cow::Owned(v))
    }
}

impl<'a> From<&'a [u8]> for Author<'a> {
    fn from(s: &'a [u8]) -> Self {
        Author(Cow::Borrowed(s))
    }
}

impl<'a> fmt::Debug for Author<'a> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_tuple("Author")
            .field(&hex::encode(&self.0))
            .finish()
    }
}

impl<'a> TryFrom<&str> for Author<'a> {
    type Error = error::InvalidAuthor;

    fn try_from(s: &str) -> Result<Self, Self::Error> {
        hex::decode(s)
            .map(Author::from)
            .map_err(|_| error::InvalidAuthor(s.into()))
    }
}

impl<'a> TryFrom<String> for Author<'a> {
    type Error = error::InvalidAuthor;

    fn try_from(s: String) -> Result<Self, Self::Error> {
        hex::decode(&s)
            .map(Author::from)
            .map_err(|_| error::InvalidAuthor(s))
    }
}

impl<'a> FromStr for Author<'a> {
    type Err = error::InvalidAuthor;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Author::try_from(s)
    }
}

/// An index into the [`Authors::authors`] field.
#[derive(PartialEq, Debug, Clone, Copy)]
struct AuthorIdx(usize);

impl AuthorIdx {
    fn as_usize(&self) -> usize {
        self.0
    }

    fn with_new_author(&mut self, idx: usize) {
        if self.0 >= idx {
            self.0 += 1;
        }
    }
}

impl From<usize> for AuthorIdx {
    fn from(n: usize) -> Self {
        AuthorIdx(n)
    }
}

#[cfg(test)]
mod tests {
    use super::{Author, Authors};
    use proptest::prelude::*;

    // === Generators ===

    fn gen_bytes() -> impl Strategy<Value = Vec<u8>> {
        proptest::collection::vec(any::<u8>(), 0..64)
    }

    fn gen_author() -> impl Strategy<Value = Author<'static>> {
        gen_bytes().prop_map(Author::from)
    }

    /// Authors drawn from a deliberately tiny space, so that operation
    /// sequences frequently re-use the same author and frequently insert
    /// authors that sort before existing ones. This exercises both branches
    /// of `Authors::put_author` and the `AuthorIdx` re-indexing.
    fn gen_small_author() -> impl Strategy<Value = Author<'static>> {
        proptest::collection::vec(0u8..4, 0..3).prop_map(Author::from)
    }

    /// A valid, possibly mixed-case hex string together with the bytes it
    /// encodes.
    fn gen_hex_string() -> impl Strategy<Value = (String, Vec<u8>)> {
        proptest::collection::vec((any::<u8>(), any::<bool>()), 0..64).prop_map(|pairs| {
            let mut s = String::new();
            let mut bytes = Vec::with_capacity(pairs.len());
            for (byte, upper) in pairs {
                let h = hex::encode([byte]);
                if upper {
                    s.push_str(&h.to_uppercase());
                } else {
                    s.push_str(&h);
                }
                bytes.push(byte);
            }
            (s, bytes)
        })
    }

    proptest! {
        /// For all authors `a`: `try_from(to_hex_string(a)) == Ok(a)`.
        #[test]
        fn hex_roundtrip(author in gen_author()) {
            prop_assert_eq!(Author::try_from(author.to_hex_string()).unwrap(), author.clone());
            prop_assert_eq!(Author::try_from(author.to_hex_string().as_str()).unwrap(), author);
        }

        /// For all authors `a`: `Display` output equals `to_hex_string(a)`,
        /// and parsing it back yields `a`.
        #[test]
        fn display_is_hex_and_fromstr_roundtrips(author in gen_author()) {
            let displayed = format!("{}", author);
            prop_assert_eq!(&displayed, &author.to_hex_string());
            prop_assert_eq!(displayed.parse::<Author<'static>>().unwrap(), author);
        }

        /// Every even-length hex string parses; the bytes are its decoding
        /// and re-encoding yields its lowercase form.
        #[test]
        fn valid_hex_parses_and_normalizes((s, bytes) in gen_hex_string()) {
            let author = Author::try_from(s.as_str()).unwrap();
            prop_assert_eq!(author.as_bytes(), &bytes[..]);
            prop_assert_eq!(author.to_hex_string(), s.to_lowercase());
        }

        /// Every odd-length hex string fails to parse.
        #[test]
        fn odd_length_hex_is_rejected((s, _) in gen_hex_string(), extra in 0u8..16) {
            let mut s = s;
            s.push(char::from_digit(u32::from(extra), 16).unwrap());
            prop_assert!(Author::try_from(s.as_str()).is_err());
        }

        /// Every string containing at least one non-hex character fails to
        /// parse.
        #[test]
        fn non_hex_char_is_rejected(
            (s, _) in gen_hex_string(),
            c in any::<char>().prop_filter("non-hex", |c| !c.is_ascii_hexdigit()),
            at in any::<proptest::sample::Index>(),
        ) {
            let mut s = s;
            // `s` is pure ASCII, so any byte index is a char boundary.
            let at = at.index(s.len() + 1);
            s.insert(at, c);
            prop_assert!(Author::try_from(s.as_str()).is_err());
        }

        /// For all byte vectors `b`: `Author::from(b).as_bytes() == b`.
        ///
        /// Construction from bytes is lossless: no normalization is applied.
        #[test]
        fn bytes_preserved(bytes in gen_bytes()) {
            let from_vec = Author::from(bytes.clone());
            let from_slice = Author::from(&bytes[..]);
            prop_assert_eq!(from_vec.as_bytes(), &bytes[..]);
            prop_assert_eq!(from_slice.as_bytes(), &bytes[..]);
        }

        /// For all authors `a`: `a` serializes to exactly the JSON string
        /// `to_hex_string(a)`, and deserializing that yields `a` back.
        #[test]
        fn serde_roundtrip_via_hex_string(author in gen_author()) {
            let value = serde_json::to_value(&author).unwrap();
            prop_assert_eq!(&value, &serde_json::Value::String(author.to_hex_string()));
            prop_assert_eq!(serde_json::from_value::<Author<'static>>(value).unwrap(), author);
        }

        /// For all byte vectors `x` and `y`: `Author(x) <= Author(y)` if
        /// and only if `x <= y`.
        ///
        /// `Ord` on `Author` must coincide with `Ord` on the underlying
        /// bytes, because `Authors::put_author` relies on it for
        /// `binary_search`.
        #[test]
        fn ord_agrees_with_bytes(a in gen_bytes(), b in gen_bytes()) {
            prop_assert_eq!(Author::from(a.clone()).cmp(&Author::from(b.clone())), a.cmp(&b));
        }
    }

    /// One step of an op sequence, applied by `apply` to the `Authors`
    /// under test and the model in lock-step.
    ///
    /// Indices are unconstrained at generation time; `apply` reduces them
    /// to valid slots.
    #[derive(Debug, Clone)]
    enum Op {
        Assign {
            author: Author<'static>,
            actor: usize,
        },
        InsertActor {
            at: usize,
        },
        RemoveActor {
            at: usize,
        },
    }

    fn gen_ops() -> impl Strategy<Value = Vec<Op>> {
        proptest::collection::vec(
            prop_oneof![
                4 => (gen_small_author(), any::<usize>())
                    .prop_map(|(author, actor)| Op::Assign { author, actor }),
                1 => any::<usize>().prop_map(|at| Op::InsertActor { at }),
                1 => any::<usize>().prop_map(|at| Op::RemoveActor { at }),
            ],
            0..40,
        )
    }

    /// Apply `ops` to a fresh `Authors::with_actors(init_actors)` and to the
    /// model in lock-step. Raw indices are reduced modulo the current number
    /// of actor slots so the documented preconditions hold.
    ///
    /// The model for `Authors` is a plain `Vec<Option<Author>>` mapping each
    /// actor slot to its author. The real implementation maintains a sorted,
    /// deduplicated author list with re-indexed pointers into it; the model
    /// does none of that, so any re-indexing bug shows up as a divergence.
    fn apply(init_actors: usize, ops: &[Op]) -> (Authors, Vec<Option<Author<'static>>>) {
        let mut authors = Authors::with_actors(init_actors);
        let mut model: Vec<Option<Author<'static>>> = vec![None; init_actors];
        for op in ops {
            match op {
                Op::Assign { author, actor } => {
                    if model.is_empty() {
                        continue;
                    }
                    let actor = actor % model.len();
                    authors.assign_author(author.clone(), actor);
                    model[actor] = Some(author.clone());
                }
                Op::InsertActor { at } => {
                    let at = at % (model.len() + 1);
                    authors.insert_actor(at);
                    model.insert(at, None);
                }
                Op::RemoveActor { at } => {
                    if model.is_empty() {
                        continue;
                    }
                    let at = at % model.len();
                    authors.remove_actor(at);
                    model.remove(at);
                }
            }
        }
        (authors, model)
    }

    /// The observable state of an `Authors`, given `slots` actor slots.
    fn observe(
        authors: &Authors,
        slots: usize,
    ) -> (Vec<Author<'static>>, Vec<Option<Author<'static>>>) {
        (
            authors.get_authors().to_vec(),
            (0..slots)
                .map(|i| authors.get_author_for_actor(i).map(Author::into_owned))
                .collect(),
        )
    }

    proptest! {
        /// After any op sequence, `get_author_for_actor` agrees with the
        /// model at every actor slot, and returns `None` (rather than
        /// panicking) out of range.
        #[test]
        fn lookup_agrees_with_model(init in 0usize..8, ops in gen_ops()) {
            let (authors, model) = apply(init, &ops);
            for (actor, expected) in model.iter().enumerate() {
                prop_assert_eq!(
                    authors.get_author_for_actor(actor),
                    expected.as_ref().map(Author::as_borrowed)
                );
            }
            // Out-of-range lookups are `None`, not a panic.
            prop_assert_eq!(authors.get_author_for_actor(model.len()), None);
        }

        /// After any op sequence, `get_actors_for_author` returns exactly
        /// the model's slots for that author, in ascending order; an author
        /// absent from `get_authors` yields no actors.
        #[test]
        fn reverse_lookup_agrees_with_model(
            init in 0usize..8,
            ops in gen_ops(),
            probe in gen_author(),
        ) {
            let (authors, model) = apply(init, &ops);
            for author in authors.get_authors() {
                let actual: Vec<usize> = authors.get_actors_for_author(author).collect();
                let expected: Vec<usize> = model
                    .iter()
                    .enumerate()
                    .filter_map(|(i, a)| (a.as_ref() == Some(author)).then_some(i))
                    .collect();
                prop_assert_eq!(actual, expected);
            }
            if !authors.get_authors().contains(&probe) {
                prop_assert_eq!(authors.get_actors_for_author(&probe).count(), 0);
            }
        }

        /// Forward and reverse lookups are mutually consistent, without
        /// reference to the model: if an actor maps to an author, that
        /// author's actors include it; and every actor listed for an author
        /// maps back to that author.
        #[test]
        fn forward_and_reverse_lookups_are_consistent(init in 0usize..8, ops in gen_ops()) {
            let (authors, model) = apply(init, &ops);
            for actor in 0..model.len() {
                if let Some(author) = authors.get_author_for_actor(actor) {
                    prop_assert!(authors.get_actors_for_author(&author).any(|i| i == actor));
                }
            }
            for author in authors.get_authors() {
                for actor in authors.get_actors_for_author(author).collect::<Vec<_>>() {
                    prop_assert_eq!(
                        authors.get_author_for_actor(actor),
                        Some(author.as_borrowed())
                    );
                }
            }
        }

        /// After any op sequence, `get_authors` is strictly sorted: sorted,
        /// with no duplicates.
        ///
        /// This is the invariant `Authors::put_author` relies on for
        /// `binary_search`.
        #[test]
        fn authors_are_sorted_and_unique(init in 0usize..8, ops in gen_ops()) {
            let (authors, _) = apply(init, &ops);
            prop_assert!(authors.get_authors().is_sorted_by(|a, b| a < b));
        }

        /// `assign_author(a, i)` makes actor `i` map to `a`, and assigning
        /// the same pair again leaves all observable state unchanged.
        #[test]
        fn assign_is_effective_and_idempotent(
            init in 1usize..8,
            ops in gen_ops(),
            author in gen_small_author(),
            actor in any::<usize>(),
        ) {
            let (mut authors, mut model) = apply(init, &ops);
            if model.is_empty() {
                // The ops may have removed every actor slot; restore one so
                // `assign_author`'s precondition holds.
                authors.insert_actor(0);
                model.push(None);
            }
            let actor = actor % model.len();

            authors.assign_author(author.clone(), actor);
            prop_assert_eq!(
                authors.get_author_for_actor(actor),
                Some(author.as_borrowed())
            );
            let first = observe(&authors, model.len());

            authors.assign_author(author.clone(), actor);
            prop_assert_eq!(observe(&authors, model.len()), first);
        }

        /// `with_actors(n)` starts with no authors, every actor slot
        /// unmapped, and no actors for any author.
        #[test]
        fn with_actors_is_empty(n in 0usize..16, probe in gen_author()) {
            let authors = Authors::with_actors(n);
            prop_assert!(authors.get_authors().is_empty());
            // Go out of range, to ensure `None` is still returned
            for i in 0..n + 3 {
                prop_assert_eq!(authors.get_author_for_actor(i), None);
            }
            prop_assert_eq!(authors.get_actors_for_author(&probe).count(), 0);
        }

        /// Every author the model maps some actor to appears in
        /// `get_authors`.
        ///
        /// Subset, not equality: re-assignment and `remove_actor` may leave
        /// dangling authors, as documented on `Authors::remove_actor`.
        #[test]
        fn get_authors_covers_all_live_authors(init in 0usize..8, ops in gen_ops()) {
            let (authors, model) = apply(init, &ops);
            let author_set = authors.get_authors();
            for author in model.iter().flatten() {
                prop_assert!(author_set.contains(author));
            }
        }
    }
}

use std::str::FromStr;

use serde::{de, Deserialize, Deserializer, Serialize, Serializer};

use crate::author::Author;

impl<'de> Deserialize<'de> for Author<'static> {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let s = String::deserialize(deserializer)?;
        Author::from_str(&s)
            .map_err(|_| de::Error::invalid_value(de::Unexpected::Str(&s), &"A valid Author"))
    }
}

impl Serialize for Author<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(self.to_hex_string().as_str())
    }
}

