use super::myers::DiffHook;

/// A [`DiffHook`] that combines deletions and insertions to give blocks
/// of maximal length, and replacements when appropriate.
///
/// It will replace [`DiffHook::insert`] and [`DiffHook::delete`] events when
/// possible with [`DiffHook::replace`] events.  Note that even though the
/// text processing in the crate does not use replace events and always resolves
/// then back to delete and insert, it's useful to always use the replacer to
/// ensure a consistent order of inserts and deletes.  This is why for instance
/// the text diffing automatically uses this hook internally.
pub(super) struct Replace<D: DiffHook> {
    d: D,
    del: Option<(usize, usize, usize)>,
    ins: Option<(usize, usize, usize)>,
    eq: Option<(usize, usize, usize)>,
}

impl<D: DiffHook> Replace<D> {
    /// Creates a new replace hook wrapping another hook.
    pub(super) fn new(d: D) -> Self {
        Replace {
            d,
            del: None,
            ins: None,
            eq: None,
        }
    }

    /// Extracts the inner hook.
    #[allow(dead_code)]
    pub(super) fn into_inner(self) -> D {
        self.d
    }

    fn flush_eq(&mut self) -> Result<(), D::Error> {
        if let Some((eq_old_index, eq_new_index, eq_len)) = self.eq.take() {
            self.d.equal(eq_old_index, eq_new_index, eq_len)?
        }
        Ok(())
    }

    fn flush_del_ins(&mut self) -> Result<(), D::Error> {
        if let Some((del_old_index, del_old_len, del_new_index)) = self.del.take() {
            if let Some((_, ins_new_index, ins_new_len)) = self.ins.take() {
                self.d
                    .replace(del_old_index, del_old_len, ins_new_index, ins_new_len)?;
            } else {
                self.d.delete(del_old_index, del_old_len, del_new_index)?;
            }
        } else if let Some((ins_old_index, ins_new_index, ins_new_len)) = self.ins.take() {
            self.d.insert(ins_old_index, ins_new_index, ins_new_len)?;
        }
        Ok(())
    }
}

impl<D: DiffHook> AsRef<D> for Replace<D> {
    fn as_ref(&self) -> &D {
        &self.d
    }
}

impl<D: DiffHook> AsMut<D> for Replace<D> {
    fn as_mut(&mut self) -> &mut D {
        &mut self.d
    }
}

impl<D: DiffHook> DiffHook for Replace<D> {
    type Error = D::Error;

    fn equal(&mut self, old_index: usize, new_index: usize, len: usize) -> Result<(), D::Error> {
        self.flush_del_ins()?;

        self.eq = if let Some((eq_old_index, eq_new_index, eq_len)) = self.eq.take() {
            Some((eq_old_index, eq_new_index, eq_len + len))
        } else {
            Some((old_index, new_index, len))
        };

        Ok(())
    }

    fn delete(
        &mut self,
        old_index: usize,
        old_len: usize,
        new_index: usize,
    ) -> Result<(), D::Error> {
        self.flush_eq()?;
        if let Some((del_old_index, del_old_len, del_new_index)) = self.del.take() {
            debug_assert_eq!(old_index, del_old_index + del_old_len);
            self.del = Some((del_old_index, del_old_len + old_len, del_new_index));
        } else {
            self.del = Some((old_index, old_len, new_index));
        }
        Ok(())
    }

    fn insert(
        &mut self,
        old_index: usize,
        new_index: usize,
        new_len: usize,
    ) -> Result<(), D::Error> {
        self.flush_eq()?;
        self.ins = if let Some((ins_old_index, ins_new_index, ins_new_len)) = self.ins.take() {
            debug_assert_eq!(ins_new_index + ins_new_len, new_index);
            Some((ins_old_index, ins_new_index, new_len + ins_new_len))
        } else {
            Some((old_index, new_index, new_len))
        };

        Ok(())
    }

    fn replace(
        &mut self,
        old_index: usize,
        old_len: usize,
        new_index: usize,
        new_len: usize,
    ) -> Result<(), D::Error> {
        self.flush_eq()?;
        self.d.replace(old_index, old_len, new_index, new_len)
    }

    fn finish(&mut self) -> Result<(), D::Error> {
        self.flush_eq()?;
        self.flush_del_ins()?;
        self.d.finish()
    }
}

import {
  block,
  Doc,
  isAutomerge,
  isCounter,
  mark,
  splice,
  splitBlock,
  unmark,
  updateBlock,
} from "./implementation.js"
import {
  DelPatch,
  IncPatch,
  InsertPatch,
  MarkPatch,
  MaterializeValue,
  Patch,
  Prop,
  PutPatch,
  SpliceTextPatch,
  UnmarkPatch,
} from "./wasm_types.js"

export function applyPatch(doc: unknown, patch: Patch) {
  const embeddedBlock = resolveEmbeddedBlock(doc, patch.path)
  if (embeddedBlock === "ignore") {
    return
  }
  if (embeddedBlock) {
    // If embeddedBlock exists then embeddedBlock.value is a plain JS object
    // representing the value of the block marker _before_ applying the patch.
    // Furthermore, if embeddedBlock is non-null then we assume we are inside
    // an Automerge document.This means we need to use Automerge.updateBlock to
    // update the block marker. (If we aren't inside a change() callback then
    // updateBlock will throw here and that's intended, it's not valid to
    // modify an automerge value outside of a change()). The `updateBlock`
    // function replaces the existing value with a new value. Thus, we need to
    // first apply the patch to the embedded block value, then pass this
    // updated value to updateBlock.
    applyPatch(embeddedBlock.value, {
      ...patch,
      path: embeddedBlock.relativePath,
    } as Patch)
    updateBlock(
      doc as Doc<unknown>,
      embeddedBlock.textPath,
      embeddedBlock.index,
      embeddedBlock.value,
    )
    return
  }

  let path = resolvePath(doc, patch.path)
  if (patch.action === "put") {
    applyPutPatch(doc, path, patch)
  } else if (patch.action === "insert") {
    applyInsertPatch(doc, path, patch)
  } else if (patch.action === "del") {
    applyDelPatch(doc, path, patch)
  } else if (patch.action === "splice") {
    applySplicePatch(doc, path, patch)
  } else if (patch.action === "inc") {
    applyIncPatch(doc, path, patch)
  } else if (patch.action === "mark") {
    applyMarkPatch(doc, path, patch)
  } else if (patch.action === "unmark") {
    applyUnmarkPatch(doc, path, patch)
  } else if (patch.action === "conflict") {
    // Ignore conflict patches
  } else {
    throw new RangeError(`unsupported patch: ${patch}`)
  }
}

function applyPutPatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: PutPatch,
) {
  let { obj: parent, prop } = pathElemAt(path, -1)
  parent[prop] = patch.value
}

function applyInsertPatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: InsertPatch,
) {
  let { obj: parent, prop, parentPath } = pathElemAt(path, -1)

  if (!(typeof prop === "number")) {
    throw new RangeError(`index is not a number for patch`)
  }
  if (Array.isArray(parent)) {
    parent.splice(prop, 0, ...patch.values)
  } else if (typeof parent === "string") {
    if (isAutomerge(doc)) {
      let index = prop
      for (const value of patch.values) {
        if (
          value == null ||
          typeof value !== "object" ||
          Array.isArray(value)
        ) {
          throw new RangeError(`block marker is not an object`)
        }
        splitBlock(
          doc as Doc<unknown>,
          parentPath,
          index,
          value as { [key: string]: MaterializeValue },
        )
        index += 1
      }
    } else {
      const { obj: grandParent, prop: grandParentProp } = pathElemAt(path, -2)
      const replacement = "\ufffc".repeat(patch.values.length)
      grandParent[grandParentProp] =
        parent.slice(0, prop) + replacement + parent.slice(prop)
    }
  } else {
    throw new RangeError(`target is not an array or string for patch`)
  }
}

function applyDelPatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: DelPatch,
) {
  let { obj: parent, prop, parentPath } = pathElemAt(path, -1)

  if (!(typeof prop === "number")) {
    throw new RangeError(`index is not a number for patch`)
  }
  if (Array.isArray(parent)) {
    parent.splice(prop, patch.length || 1)
  } else if (typeof parent === "string") {
    if (isAutomerge(doc)) {
      splice(doc as Doc<unknown>, parentPath, prop, patch.length || 1)
    } else {
      let { obj: grandParent, prop: grandParentProp } = pathElemAt(path, -2)
      if (typeof prop !== "number") {
        throw new RangeError(`index is not a number for patch`)
      }
      let target = grandParent[grandParentProp]
      if (target == null || typeof target !== "string") {
        throw new RangeError(`target is not a string for patch`)
      }
      let newString =
        target.slice(0, prop) + target.slice(prop + (patch.length || 1))
      grandParent[grandParentProp] = newString
    }
  } else {
    throw new RangeError(`target is not an array or string for patch`)
  }
}

function applySplicePatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: SpliceTextPatch,
) {
  if (isAutomerge(doc)) {
    let { obj: parent, prop, parentPath } = pathElemAt(path, -1)
    if (!(typeof prop === "number")) {
      throw new RangeError(`index is not a number for patch`)
    }
    splice(doc as Doc<unknown>, parentPath, prop, 0, patch.value)
  } else {
    let { obj: parent, prop } = pathElemAt(path, -1)
    let { obj: grandParent, prop: grandParentProp } = pathElemAt(path, -2)
    if (typeof prop !== "number") {
      throw new RangeError(`index is not a number for patch`)
    }
    let target = grandParent[grandParentProp]
    if (target == null || typeof target !== "string") {
      throw new RangeError(`target is not a string for patch`)
    }
    let newString = target.slice(0, prop) + patch.value + target.slice(prop)
    grandParent[grandParentProp] = newString
  }
}

function applyIncPatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: IncPatch,
) {
  let { obj: parent, prop } = pathElemAt(path, -1)
  const counter = parent[prop]
  if (isAutomerge(doc)) {
    if (!isCounter(counter)) {
      throw new RangeError(`target is not a counter for patch`)
    }
    counter.increment(patch.value)
  } else {
    if (!(typeof counter === "number")) {
      throw new RangeError(`target is not a number for patch`)
    }
    parent[prop] = counter + patch.value
  }
}

function applyMarkPatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: MarkPatch,
) {
  let { obj: parent, prop } = pathElemAt(path, -1)
  if (!isAutomerge(doc)) {
    return
  }
  for (const markSpec of patch.marks) {
    mark(
      doc as Doc<unknown>,
      patch.path,
      // TODO: add mark expansion to patches. This will require emitting
      // the expand values in patches.
      { start: markSpec.start, end: markSpec.end, expand: "none" },
      markSpec.name,
      markSpec.value,
    )
  }
}

function applyUnmarkPatch(
  doc: unknown,
  path: ResolvedPathElem[],
  patch: UnmarkPatch,
) {
  if (!isAutomerge(doc)) {
    return
  }
  unmark(
    doc as Doc<unknown>,
    patch.path,
    { start: patch.start, end: patch.end, expand: "none" },
    patch.name,
  )
}

export function applyPatches(doc: unknown, patches: Patch[]) {
  for (const patch of patches) {
    applyPatch(doc, patch)
  }
}

type EmbeddedBlock = {
  textPath: Prop[]
  index: number
  value: { [key: string]: any }
  relativePath: Prop[]
}

/**
 * Find a possible target for a patch which updates a block marker in text
 *
 * In Automerge text can contain embedded block markers, which are maps that
 * appear at some index in the text. When we're applying patches we have to
 * decide what to do with these patches. What we do depends on what kind of
 * object we are applying patches _to_
 *
 * - A plain JS string - ignore this patch. The block marker is rendered as a
 *   unicode object replacement character. Updating it changes nothing
 * - An object (e.g. a marker stored in an array instead of text) - No special
 *   handling is required, whether it is plain JS or a change proxy. Return
 *   `null` so the caller resolves the path and mutates the object directly.
 * - A string _but one that is inside an automerge document_ - in this scenario
 *   we are applying the patch to a plain string in a change() callback. This
 *   means we can use Automerge.updateBlock to update the block marker. In
 *   this case we return a detached copy of the block and the remaining path.
 */
function resolveEmbeddedBlock(
  doc: unknown,
  path: Prop[],
): EmbeddedBlock | "ignore" | null {
  let current: any = doc
  const currentPath: Prop[] = []

  for (const [pathIndex, prop] of path.entries()) {
    if (
      typeof current === "string" &&
      typeof prop === "number" &&
      pathIndex !== path.length - 1
    ) {
      if (!isAutomerge(doc)) {
        // We're trying to apply an update to a block marker but the target
        // is a plain string. Ignore the patch
        return "ignore"
      }
      const value = block(doc as Doc<unknown>, currentPath, prop)
      if (value == null) {
        throw new Error(`Invalid block path: ${path}`)
      }
      return {
        textPath: currentPath,
        index: prop,
        value,
        relativePath: path.slice(pathIndex + 1),
      }
    }

    if (pathIndex !== path.length - 1) {
      if (current == null || typeof current !== "object") {
        return null
      }
      current = current[prop]
      currentPath.push(prop)
    }
  }

  return null
}

type ResolvedPathElem = {
  obj: any
  prop: Prop
  parentPath: Prop[]
}

/**
 * Walk through a path with an object and for each element in the path return a resolved path element.
 *
 * A resolved path element looks like this:
 *
 * ```typescript
 * {
 *   obj: any,           // The object that this element in the path is a property of
 *   prop: Prop,         // The property within `obj` that this path element points at
 *   parentPath: Prop[]  // The path to `obj` within the original `doc` passed to `resolvePath`
 * }
 * ````
 *
 * For example, given an object like this:
 *
 * ```typescript
 * {
 *      todos: [{ task: "remember the milk"}]
 * }
 * ```
 *
 * Then `resolvePath(doc, ["todos", 0, "task"])` would return:
 *
 * ```typescript
 * [
 *   { obj: { todos: [{ task: "remember the milk"}] }, prop: "todos", parentPath: [] },
 *   { obj: [{ task: "remember the milk"}], prop: 0, parentPath: ["todos"] },
 *   { obj: { task: "remember the milk" }, prop: "task", parentPath: ["todos", 0] }
 * ]
 * ```
 */
function resolvePath(doc: unknown, path: Prop[]): ResolvedPathElem[] {
  const result: ResolvedPathElem[] = []
  let current = doc
  let currentPath: Prop[] = []

  for (const [index, prop] of path.entries()) {
    result.push({ obj: current, prop, parentPath: currentPath.slice() })
    currentPath.push(prop)
    if (index !== path.length - 1) {
      if (current == null || typeof current != "object") {
        // If we're not the last item in the path then we need the current
        // object to be an object so we can access it in the next iteration
        throw new Error(`Invalid path: ${path}`)
      }
      current = current[prop]
    } else {
      break
    }
  }

  return result
}

/**
 * Get an element from a resolved path, throwing an exception if the element does not exist
 *
 * @param resolved - The path to lookup in
 * @param index    - The index of the element to lookup, negative indices search backwards
 */
function pathElemAt(
  resolved: ResolvedPathElem[],
  index: number,
): ResolvedPathElem {
  let result = resolved.at(index)
  if (result == undefined) {
    throw new Error("invalid path")
  }
  return result
}

function reversed<T>(array: T[]): T[] {
  return array.slice().reverse()
}

import type { Automerge, Heads, ObjID, Patch } from "./wasm_types.js"

import { CLEAR_CACHE, IS_PROXY, OBJECT_ID, STATE, TRACE } from "./constants.js"

import { Doc, PatchCallback } from "./types.js"

export interface InternalState<T> {
  handle: Automerge
  heads: Heads | undefined
  freeze: boolean
  mostRecentPatch: {
    before: Heads | undefined
    after: Heads | undefined
    patches: Patch[]
  }
  patchCallback?: PatchCallback<T>
}

export function _state<T>(doc: Doc<T>, checkroot = true): InternalState<T> {
  if (typeof doc !== "object") {
    throw new RangeError("must be the document root")
  }
  const state = Reflect.get(doc, STATE) as InternalState<T>
  if (
    state === undefined ||
    state == null ||
    (checkroot && _obj(doc) !== "_root")
  ) {
    throw new RangeError("must be the document root")
  }
  return state
}

export function _clear_cache<T>(doc: Doc<T>): void {
  Reflect.set(doc, CLEAR_CACHE, true)
}

export function _trace<T>(doc: Doc<T>): string | undefined {
  return Reflect.get(doc, TRACE) as string
}

export function _obj<T>(doc: Doc<T>): ObjID | null {
  if (!(typeof doc === "object") || doc === null) {
    return null
  }
  return Reflect.get(doc, OBJECT_ID) as ObjID
}

export function _is_proxy<T>(doc: Doc<T>): boolean {
  return !!Reflect.get(doc, IS_PROXY)
}

use automerge as am;
use std::cell::RefCell;
use std::collections::BTreeMap;

use crate::result::{to_result, AMresult};
use crate::sync::have::AMsyncHave;

macro_rules! to_sync_state {
    ($handle:expr) => {{
        let handle = $handle.as_ref();
        match handle {
            Some(b) => b,
            None => return AMresult::error("Invalid `AMsyncState*`").into(),
        }
    }};
}

pub(crate) use to_sync_state;

/// \struct AMsyncState
/// \installed_headerfile
/// \brief The state of synchronization with a peer.
#[derive(Eq, PartialEq)]
pub struct AMsyncState {
    body: am::sync::State,
    their_haves_storage: RefCell<BTreeMap<usize, AMsyncHave>>,
}

impl AMsyncState {
    pub fn new(state: am::sync::State) -> Self {
        Self {
            body: state,
            their_haves_storage: RefCell::new(BTreeMap::new()),
        }
    }
}

impl AsMut<am::sync::State> for AMsyncState {
    fn as_mut(&mut self) -> &mut am::sync::State {
        &mut self.body
    }
}

impl AsRef<am::sync::State> for AMsyncState {
    fn as_ref(&self) -> &am::sync::State {
        &self.body
    }
}

impl From<AMsyncState> for *mut AMsyncState {
    fn from(b: AMsyncState) -> Self {
        Box::into_raw(Box::new(b))
    }
}

/// \memberof AMsyncState
/// \brief Decodes an array of bytes into a synchronization state.
///
/// \param[in] src A pointer to an array of bytes.
/// \param[in] count The count of bytes to decode from the array pointed to by
///                  \p src.
/// \return A pointer to an `AMresult` struct with an `AM_VAL_TYPE_SYNC_STATE` item.
/// \pre \p src `!= NULL`
/// \pre `sizeof(`\p src `) > 0`
/// \pre \p count `<= sizeof(`\p src `)`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// src must be a byte array of length `>= count`
#[no_mangle]
pub unsafe extern "C" fn AMsyncStateDecode(src: *const u8, count: usize) -> *mut AMresult {
    let data = std::slice::from_raw_parts(src, count);
    to_result(am::sync::State::decode(data))
}

/// \memberof AMsyncState
/// \brief Encodes a synchronization state as an array of bytes.
///
/// \param[in] sync_state A pointer to an `AMsyncState` struct.
/// \return A pointer to an `AMresult` struct with an `AM_VAL_TYPE_BYTE_SPAN` item.
/// \pre \p sync_state `!= NULL`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// sync_state must be a valid pointer to an AMsyncState
#[no_mangle]
pub unsafe extern "C" fn AMsyncStateEncode(sync_state: *const AMsyncState) -> *mut AMresult {
    let sync_state = to_sync_state!(sync_state);
    to_result(sync_state.as_ref().encode())
}

/// \memberof AMsyncState
/// \brief Tests the equality of two synchronization states.
///
/// \param[in] sync_state1 A pointer to an `AMsyncState` struct.
/// \param[in] sync_state2 A pointer to an `AMsyncState` struct.
/// \return `true` if \p sync_state1 `==` \p sync_state2 and `false` otherwise.
/// \pre \p sync_state1 `!= NULL`
/// \pre \p sync_state2 `!= NULL`
/// \post `!(`\p sync_state1 `&&` \p sync_state2 `) -> false`
/// \internal
///
/// #Safety
/// sync_state1 must be a valid pointer to an AMsyncState
/// sync_state2 must be a valid pointer to an AMsyncState
#[no_mangle]
pub unsafe extern "C" fn AMsyncStateEqual(
    sync_state1: *const AMsyncState,
    sync_state2: *const AMsyncState,
) -> bool {
    match (sync_state1.as_ref(), sync_state2.as_ref()) {
        (Some(sync_state1), Some(sync_state2)) => sync_state1.as_ref() == sync_state2.as_ref(),
        (None, None) | (None, Some(_)) | (Some(_), None) => false,
    }
}

/// \memberof AMsyncState
/// \brief Allocates a new synchronization state and initializes it from
///        default values.
///
/// \return A pointer to an `AMresult` struct with an `AM_VAL_TYPE_SYNC_STATE` item.
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
#[no_mangle]
pub extern "C" fn AMsyncStateInit() -> *mut AMresult {
    to_result(am::sync::State::new())
}

/// \memberof AMsyncState
/// \brief Gets the heads that are shared by both peers.
///
/// \param[in] sync_state A pointer to an `AMsyncState` struct.
/// \return A pointer to an `AMresult` struct with `AM_VAL_TYPE_CHANGE_HASH` items.
/// \pre \p sync_state `!= NULL`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// sync_state must be a valid pointer to an AMsyncState
#[no_mangle]
pub unsafe extern "C" fn AMsyncStateSharedHeads(sync_state: *const AMsyncState) -> *mut AMresult {
    let sync_state = to_sync_state!(sync_state);
    to_result(sync_state.as_ref().shared_heads.as_slice())
}

/// \memberof AMsyncState
/// \brief Gets the heads that were last sent by this peer.
///
/// \param[in] sync_state A pointer to an `AMsyncState` struct.
/// \return A pointer to an `AMresult` struct with `AM_VAL_TYPE_CHANGE_HASH` items.
/// \pre \p sync_state `!= NULL`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// sync_state must be a valid pointer to an AMsyncState
#[no_mangle]
pub unsafe extern "C" fn AMsyncStateLastSentHeads(sync_state: *const AMsyncState) -> *mut AMresult {
    let sync_state = to_sync_state!(sync_state);
    to_result(sync_state.as_ref().last_sent_heads.as_slice())
}

/// \memberof AMsyncState
/// \brief Gets a summary of the changes that the other peer already has.
///
/// \param[in] sync_state A pointer to an `AMsyncState` struct.
/// \param[out] has_value A pointer to a boolean flag that is set to `true` if
///             the returned `AMitems` struct is relevant, `false` otherwise.
/// \return A pointer to an `AMresult` struct with `AM_VAL_TYPE_SYNC_HAVE` items.
/// \pre \p sync_state `!= NULL`
/// \pre \p has_value `!= NULL`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// sync_state must be a valid pointer to an AMsyncState
