/// \return A pointer to an `AMresult` struct with an `AM_VAL_TYPE_VOID` item.
/// \pre \p doc `!= NULL`
/// \pre \p key.src `!= NULL`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// doc must be a valid pointer to an AMdoc
/// obj_id must be a valid pointer to an AMobjId or std::ptr::null()
/// key.src must be a byte array of length >= key.count
#[no_mangle]
pub unsafe extern "C" fn AMmapPutUint(
    doc: *mut AMdoc,
    obj_id: *const AMobjId,
    key: AMbyteSpan,
    value: u64,
) -> *mut AMresult {
    let doc = to_doc_mut!(doc);
    let key = to_str!(key);
    to_result(doc.put(to_obj_id!(obj_id), key, value))
}

/// \memberof AMdoc
/// \brief Gets the current or historical items of the map object within the
///        given range.
///
/// \param[in] doc A pointer to an `AMdoc` struct.
/// \param[in] obj_id A pointer to an `AMobjId` struct or `AM_ROOT`.
/// \param[in] begin The first key in a subrange or `AMstr(NULL)` to indicate the
///                  absolute first key.
/// \param[in] end The key one past the last key in a subrange or `AMstr(NULL)`
///                to indicate one past the absolute last key.
/// \param[in] heads A pointer to an `AMitems` struct with `AM_VAL_TYPE_CHANGE_HASH`
///                  items to select historical items or `NULL` to select
///                  current items.
/// \return A pointer to an `AMresult` struct with an `AMitems` struct.
/// \pre \p doc `!= NULL`
/// \warning The returned `AMresult` struct pointer must be passed to
///          `AMresultFree()` in order to avoid a memory leak.
/// \internal
///
/// # Safety
/// doc must be a valid pointer to an AMdoc
/// obj_id must be a valid pointer to an AMobjId or std::ptr::null()
/// begin.src must be a byte array of length >= begin.count or std::ptr::null()
/// end.src must be a byte array of length >= end.count or std::ptr::null()
/// heads must be a valid pointer to an AMitems or std::ptr::null()
#[no_mangle]
pub unsafe extern "C" fn AMmapRange(
    doc: *const AMdoc,
    obj_id: *const AMobjId,
    begin: AMbyteSpan,
    end: AMbyteSpan,
    heads: *const AMitems,
) -> *mut AMresult {
    let doc = to_doc!(doc);
    let obj_id = to_obj_id!(obj_id);
    let heads = match heads.as_ref() {
        None => None,
        Some(heads) => match <Vec<am::ChangeHash>>::try_from(heads) {
            Ok(heads) => Some(heads),
            Err(e) => {
                return AMresult::error(&e.to_string()).into();
            }
        },
    };
    match (begin.is_null(), end.is_null()) {
        (false, false) => {
            let (begin, end) = (to_str!(begin).to_string(), to_str!(end).to_string());
            if begin > end {
                return AMresult::error(&format!("Invalid range [{}-{})", begin, end)).into();
            };
            let bounds = begin..end;
            if let Some(heads) = heads {
                to_result(doc.map_range_at(obj_id, bounds, &heads))
            } else {
                to_result(doc.map_range(obj_id, bounds))
            }
        }
        (false, true) => {
            let bounds = to_str!(begin).to_string()..;
            if let Some(heads) = heads {
                to_result(doc.map_range_at(obj_id, bounds, &heads))
            } else {
                to_result(doc.map_range(obj_id, bounds))
            }
        }
        (true, false) => {
            let bounds = ..to_str!(end).to_string();
            if let Some(heads) = heads {
                to_result(doc.map_range_at(obj_id, bounds, &heads))
            } else {
                to_result(doc.map_range(obj_id, bounds))
            }
        }
        (true, true) => {
            let bounds = ..;
            if let Some(heads) = heads {
                to_result(doc.map_range_at(obj_id, bounds, &heads))
            } else {
                to_result(doc.map_range(obj_id, bounds))
            }
        }
    }
}

use std::collections::HashMap;
use std::ops::{Deref, DerefMut};

use crate::exid::ExId;
use crate::types::Prop;
use crate::{PatchAction, ScalarValue, TextEncoding};

use super::{HydrateError, Value};

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Map(HashMap<String, MapValue>);

#[derive(Clone, Debug, PartialEq)]
pub struct MapValue {
    pub value: Value,
    pub conflict: bool,
}

impl Map {
    pub fn iter(&self) -> impl Iterator<Item = (&String, &MapValue)> {
        self.0.iter()
    }

    pub(crate) fn apply(
        &mut self,
        text_encoding: TextEncoding,
        patch: PatchAction,
    ) -> Result<(), HydrateError> {
        match patch {
            PatchAction::DeleteMap { key } => {
                self.0.remove(&key);
                Ok(())
            }
            PatchAction::PutMap {
                key,
                value,
                conflict,
            } => {
                let h_value = Value::new(value.0, text_encoding);
                self.0
                    .insert(key, MapValue::new(h_value, value.1, conflict));
                Ok(())
            }
            PatchAction::Increment {
                prop: Prop::Map(key),
                value,
            } => {
                self.0
                    .get_mut(&key)
                    .ok_or(HydrateError::InvalidKey(key))?
                    .increment(value)?;
                Ok(())
            }
            PatchAction::Conflict {
                prop: Prop::Map(key),
            } => {
                self.0
                    .get_mut(&key)
                    .ok_or(HydrateError::InvalidKey(key))?
                    .conflict = true;
                Ok(())
            }
            _ => Err(HydrateError::InvalidMapOp),
        }
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.0.get(key).map(|mv| &mv.value)
    }

    pub fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        self.0.get_mut(key).map(|mv| &mut mv.value)
    }

    pub(crate) fn new() -> Self {
        Self(Default::default())
    }
}

impl MapValue {
    pub(crate) fn new(value: Value, _id: ExId, conflict: bool) -> Self {
        Self { value, conflict }
    }

    pub(crate) fn increment(&mut self, n: i64) -> Result<(), HydrateError> {
        if let Value::Scalar(ScalarValue::Counter(c)) = &mut self.value {
            c.increment(n);
            Ok(())
        } else {
            Err(HydrateError::BadIncrement)
        }
    }
}

impl Deref for Map {
    type Target = HashMap<String, MapValue>;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl DerefMut for Map {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.0
    }
}

impl From<HashMap<&str, Value>> for Map {
    fn from(value: HashMap<&str, Value>) -> Self {
        Map(value
            .into_iter()
            .map(|(k, value)| {
                (
                    k.to_string(),
                    MapValue {
                        value,
                        conflict: false,
                    },
                )
            })
            .collect())
    }
}

impl From<HashMap<String, Value>> for Map {
    fn from(value: HashMap<String, Value>) -> Self {
        Map(value
            .into_iter()
            .map(|(k, value)| {
                (
                    k,
                    MapValue {
                        value,
                        conflict: false,
                    },
                )
            })
            .collect())
    }
}

