}

function WebsocketProvider({ children }: React.PropsWithChildren<object>) {
  const [socket, setSocket] = useState<SocketWithAuthentication | null>(null);

  const registerConnectionHandlers = useConnectionHandlers();
  const registerEntityHandlers = useEntityHandlers();
  const registerDocumentHandlers = useDocumentHandlers();
  const registerCollectionHandlers = useCollectionHandlers();
  const registerCommentHandlers = useCommentHandlers();
  const registerGroupHandlers = useGroupHandlers();
  const registerTeamHandlers = useTeamHandlers();
  const registerUserHandlers = useUserHandlers();
  const registerNotificationHandlers = useNotificationHandlers();
  const registerPinHandlers = usePinHandlers();
  const registerStarHandlers = useStarHandlers();
  const registerImportHandlers = useImportHandlers();

  useEffect(() => {
    let currentSocket: SocketWithAuthentication | null = null;

    function createConnection() {
      currentSocket = io(window.location.origin, {
        path: "/realtime",
        transports: ["websocket"],
        reconnectionDelay: 1000,
        reconnectionDelayMax: 30000,
        withCredentials: true,
      });
      invariant(currentSocket, "Socket should be defined");

      currentSocket.authenticated = false;

      registerConnectionHandlers(currentSocket);
      registerEntityHandlers(currentSocket);
      registerDocumentHandlers(currentSocket);
      registerCollectionHandlers(currentSocket);
      registerCommentHandlers(currentSocket);
      registerGroupHandlers(currentSocket);
      registerTeamHandlers(currentSocket);
      registerUserHandlers(currentSocket);
      registerNotificationHandlers(currentSocket);
      registerPinHandlers(currentSocket);
      registerStarHandlers(currentSocket);
      registerImportHandlers(currentSocket);

      setSocket(currentSocket);
    }

    function checkConnection() {
      if (currentSocket?.disconnected && getPageVisible()) {
        // null-ifying this reference is important, do not remove. Without it
        // references to old sockets are potentially held in context
        currentSocket.close();
        currentSocket = null;
        setSocket(null);
        createConnection();
      }
    }

    createConnection();
    document.addEventListener(getVisibilityListener(), checkConnection);

    return () => {
      if (currentSocket) {
        currentSocket.authenticated = false;
        currentSocket.disconnect();
      }
      document.removeEventListener(getVisibilityListener(), checkConnection);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <WebsocketContext.Provider value={socket}>
      {children}
    </WebsocketContext.Provider>
  );
}

export default observer(WebsocketProvider);

import { computed, observable } from "mobx";
import type { AuthenticationProviderSettings } from "@shared/types";
import Model from "./base/Model";
import Field from "./decorators/Field";
import { AfterDelete } from "./decorators/Lifecycle";
import type AuthenticationProvidersStore from "~/stores/AuthenticationProvidersStore";

class AuthenticationProvider extends Model {
  static modelName = "AuthenticationProvider";

  constructor(fields: Record<string, unknown>, store: Model["store"]) {
    super(fields, store);
    this.initialize(fields);
  }

  displayName: string;

  name: string;

  providerId: string;

  groupSyncSupported: boolean;

  groupSyncUsesClaim: boolean;

  @observable
  isConnected: boolean;

  @Field
  @observable
  isEnabled: boolean;

  @Field
  @observable
  settings: AuthenticationProviderSettings | undefined = undefined;

  @computed
  get isActive() {
    return this.isEnabled && this.isConnected;
  }

  @AfterDelete
  static afterDelete(model: AuthenticationProvider) {
    // Restore a placeholder record to allow re-connection
    return (model.store as AuthenticationProvidersStore).add(
      Object.assign({}, model, {
        isEnabled: false,
        isConnected: false,
      })
    );
  }
}

export default AuthenticationProvider;

import * as React from "react";
import useUnmount from "./useUnmount";

/**
 * Hook to handle click intent logic with mouse enter/leave events.
 * Sets a timer on mouse enter to call the intent callback after a delay,
 * and clears the timer on mouse leave or component unmount.
 */
export default function useClickIntent(
  onClickIntent?: React.MouseEventHandler<HTMLElement>,
  delay = 100
) {
  const timer = React.useRef<number | undefined>(undefined);

  const handleMouseEnter = React.useCallback(() => {
    if (timer.current) {
      clearTimeout(timer.current);
    }

    if (onClickIntent) {
      timer.current = window.setTimeout(onClickIntent, delay);
    }
  }, [onClickIntent, delay]);

  const handleMouseLeave = React.useCallback(() => {
    if (timer.current) {
      clearTimeout(timer.current);
    }
  }, []);

  useUnmount(() => {
    if (timer.current) {
      clearTimeout(timer.current);
    }
  });

  return { handleMouseEnter, handleMouseLeave };
}

import passport from "@outlinewiki/koa-passport";
import JWT from "jsonwebtoken";
import type { Context, Request } from "koa";
import type Router from "koa-router";
import { get } from "es-toolkit/compat";
import { toError } from "@shared/utils/error";
import { slugifyDomain } from "@shared/utils/domains";
import { parseEmail } from "@shared/utils/email";
import { getSupportedLanguage } from "@shared/utils/language";
import { isBase64Url } from "@shared/utils/urls";
import accountProvisioner from "@server/commands/accountProvisioner";
import {
  OIDCMalformedUserInfoError,
  AuthenticationError,
} from "@server/errors";
import Logger from "@server/logging/Logger";
import passportMiddleware from "@server/middlewares/passport";
import type { User } from "@server/models";
import { AuthenticationProvider } from "@server/models";
import type { AuthenticationResult } from "@server/types";
import { LogoutTokenStore } from "@server/utils/LogoutTokenStore";
import {
  StateStore,
  getTeamFromContext,
  getClientFromOAuthState,
  getUserFromOAuthState,
  request,
  startOAuthFlow,
  withProxyAgent,
} from "@server/utils/passport";
import config from "../../plugin.json";
import env from "../env";
import { OIDCStrategy } from "./OIDCStrategy";
import { createContext } from "@server/context";

export interface OIDCEndpoints {
  authorizationURL: string;
  tokenURL: string;
  userInfoURL: string;
  logoutURL?: string;
  pkce?: boolean;
}

/**
 * Creates OIDC routes and mounts them into the provided router
 */
export function createOIDCRouter(
  router: Router,
  endpoints: OIDCEndpoints
): void {
  const scopes = env.OIDC_SCOPES.split(" ");
  const logoutTokens = new LogoutTokenStore(config.id);

  passport.use(
    config.id,
    withProxyAgent(
      new OIDCStrategy(
        {
          authorizationURL: endpoints.authorizationURL,
          tokenURL: endpoints.tokenURL,
          clientID: env.OIDC_CLIENT_ID!,
          clientSecret: env.OIDC_CLIENT_SECRET!,
          callbackURL: `${env.URL}/auth/${config.id}.callback`,
          passReqToCallback: true,
          scope: env.OIDC_SCOPES,
          // @ts-expect-error custom state store
          store: new StateStore(endpoints.pkce),
          state: true,
          pkce: endpoints.pkce ?? false,
        },
        // OpenID Connect standard profile claims can be found in the official
        // specification.
        // https://openid.net/specs/openid-connect-core-1_0.html#StandardClaims
        // Non-standard claims may be configured by individual identity providers.
        // Any claim supplied in response to the userinfo request will be
        // available on the `profile` parameter
        async function (
          req: Request,
          accessToken: string,
          refreshToken: string,
          params: { expires_in: number; id_token: string; scope?: string },
          _profile: unknown,
          done: (
            err: Error | null,
            user: User | null,
            result?: AuthenticationResult
          ) => void
        ) {
          const context = req.ctx;
          try {
            // Some providers require a POST request to the userinfo endpoint, add them as exceptions here.
            const usePostMethod = [
              "https://api.dropboxapi.com/2/openid/userinfo",
            ];

            const profile = await request(
              usePostMethod.includes(endpoints.userInfoURL) ? "POST" : "GET",
              endpoints.userInfoURL,
              accessToken
            );

            // Some providers, namely ADFS, don't provide anything more than the `sub` claim in the userinfo endpoint
            // So, we'll decode the params.id_token and see if that contains what we need.
            const token = (() => {
              try {
                const decoded = JWT.decode(params.id_token);

                if (!decoded || typeof decoded !== "object") {
                  Logger.warn("Decoded id_token is not a valid object");
                  return {};
                }

                return decoded as {
                  email?: string;
                  email_verified?: boolean | string;
                  locale?: string;
                  preferred_username?: string;
                  sub?: string;
                };
              } catch (err) {
                Logger.error("id_token decode threw error: ", toError(err));
                return {};
              }
            })();

            const email = profile.email ?? token.email ?? null;
            const language = getSupportedLanguage(profile.locale, token.locale);

            if (!email) {
              throw AuthenticationError(
                `An email field was not returned in the profile or id_token parameter, but is required.`
              );
            }

            // The email_verified claim is part of the OIDC standard claims.
            // https://openid.net/specs/openid-connect-core-1_0.html#StandardClaims
            const emailVerifiedClaim =
              profile.email_verified ?? token.email_verified;
            const emailVerified =
              emailVerifiedClaim === undefined
                ? undefined
                : emailVerifiedClaim === true || emailVerifiedClaim === "true";

            const team = await getTeamFromContext(context);
            const client = getClientFromOAuthState(context);
            const user =
              context.state?.auth?.user ??
              (await getUserFromOAuthState(context));
            const { domain } = parseEmail(email);

            // Only a single OIDC provider is supported – find the existing, if any.
            const authenticationProvider = team
              ? ((await AuthenticationProvider.findOne({
                  where: {
                    name: "oidc",
                    teamId: team.id,
                    providerId: domain,
                  },
                })) ??
                (await AuthenticationProvider.findOne({
                  where: {
                    name: "oidc",
                    teamId: team.id,
                  },
                })))
              : undefined;

            // Derive a providerId from the OIDC location if there is no existing provider.
            const oidcURL = new URL(endpoints.authorizationURL);
            let providerId =
              authenticationProvider?.providerId ?? oidcURL.hostname;

            // The provider can move to a different domain, in which case the
            // stored identifier must follow the configured location.
            if (authenticationProvider && providerId !== oidcURL.hostname) {
              try {
                await authenticationProvider.update({
                  providerId: oidcURL.hostname,
                });
                providerId = oidcURL.hostname;
              } catch (error) {
                Logger.warn(
                  "Could not update OIDC authentication provider identifier",
                  { providerId, hostname: oidcURL.hostname, error }
                );
              }
            }

            if (!domain) {
              throw OIDCMalformedUserInfoError();
            }

            // remove the TLD and form a subdomain from the remaining
            const subdomain = slugifyDomain(domain);

            // Claim name can be overriden using an env variable.
            // Default is 'preferred_username' as per OIDC spec.
            // This will default to the profile.preferred_username, but will fall back to preferred_username from the id_token
            const username =
              get(profile, env.OIDC_USERNAME_CLAIM) ??
              get(token, env.OIDC_USERNAME_CLAIM);
            const name = profile.name || username || profile.username;
            const profileId = profile.sub ?? token.sub ?? profile.id;

            if (!name) {
              throw AuthenticationError(
                `Neither a ${env.OIDC_USERNAME_CLAIM}, "name" or "username" was returned in the profile loaded from ${endpoints.userInfoURL}, but at least one is required.`
              );
            }
            if (!profileId) {
              throw AuthenticationError(
                `A user id was not returned in the profile loaded from ${endpoints.userInfoURL}, searched in "sub" and "id" fields.`
              );
            }

            // Check if the picture field is a Base64 data URL and filter it out
            // to avoid validation errors in the User model
            let avatarUrl = profile.picture;
            if (profile.picture && isBase64Url(profile.picture)) {
              Logger.debug(
                "authentication",
                "Filtering out Base64 data URL from avatar",
                {
                  email,
                }
              );
              avatarUrl = null;
            }

            const ctx = createContext({
              ip: context.ip,
              user,
              authType: context.state?.auth?.type,
            });
            const result = await accountProvisioner(ctx, {
              team: {
                teamId: team?.id,
                name: env.APP_NAME,
                domain,
                subdomain,
              },
              user: {
                name,
                email,
                emailVerified,
                avatarUrl,
                language,
              },
              authenticationProvider: {
                name: config.id,
                providerId,
              },
              authentication: {
                providerId: profileId,
                accessToken,
                refreshToken,
                expiresIn: params.expires_in,
                scopes: params.scope ? params.scope.split(" ") : scopes,
              },
            });
            // Persist the id_token so a later RP-initiated logout can pass it as
            // the `id_token_hint`, allowing the provider to scope the logout to
            // this session rather than terminating its global SSO session.
            if (endpoints.logoutURL && params.id_token) {
              await logoutTokens.persist(context, params.id_token);
            }

            return done(null, result.user, { ...result, client });
          } catch (err) {
            return done(toError(err), null);
          }
        }
      )
    )
  );

  router.get(config.id, startOAuthFlow, passport.authenticate(config.id));
  router.register(
    `${config.id}.callback`,
    ["get", "post"],
    passportMiddleware(config.id)
  );

  // Performs a spec-compliant RP-initiated logout against the provider's end
  // session endpoint. Passing `id_token_hint` identifies the session being
  // ended so the provider can scope the logout and skip a confirmation prompt,
  // while `post_logout_redirect_uri` returns the user to Outline afterwards.
  // https://openid.net/specs/openid-connect-rpinitiated-1_0.html
  router.get(`${config.id}.logout`, async (ctx: Context) => {
    const idToken = await logoutTokens.consume(ctx);

    if (!endpoints.logoutURL) {
      return ctx.redirect("/");
    }

    try {
      const url = new URL(endpoints.logoutURL);
      if (idToken) {
        url.searchParams.set("id_token_hint", idToken);
      }
      if (env.OIDC_CLIENT_ID) {
        url.searchParams.set("client_id", env.OIDC_CLIENT_ID);
      }
      url.searchParams.set("post_logout_redirect_uri", env.URL);

      return ctx.redirect(url.toString());
    } catch (err) {
      Logger.warn("Invalid OIDC logout URL", {
        error: toError(err).message,
      });
      return ctx.redirect("/");
    }
  });
}

import { VerificationCode } from "./VerificationCode";

describe("VerificationCode", () => {
  const teamId = "team-1";
  const otherTeamId = "team-2";
  const email = "user@example.com";

  afterEach(async () => {
    await VerificationCode.delete(teamId, email);
    await VerificationCode.delete(otherTeamId, email);
  });

  describe("generate", () => {
    it("should return a 6-digit string", () => {
      const code = VerificationCode.generate();
      expect(code).toMatch(/^\d{6}$/);
    });

    it("should always produce exactly six digits across many samples", () => {
      for (let i = 0; i < 1000; i++) {
        expect(VerificationCode.generate()).toMatch(/^\d{6}$/);
      }
    });
  });

  describe("store and retrieve", () => {
    it("should store and retrieve a code", async () => {
      const code = "123456";
      await VerificationCode.store(teamId, email, code);
      const retrieved = await VerificationCode.retrieve(teamId, email);
      expect(retrieved).toBe(code);
    });

    it("should return undefined for an unknown email", async () => {
      const retrieved = await VerificationCode.retrieve(
        teamId,
        "unknown@example.com"
      );
      expect(retrieved).toBeUndefined();
    });

    it("should be case-insensitive for email", async () => {
      const code = "654321";
      await VerificationCode.store(teamId, "User@Example.COM", code);
      const retrieved = await VerificationCode.retrieve(
        teamId,
        "user@example.com"
      );
      expect(retrieved).toBe(code);
      await VerificationCode.delete(teamId, "user@example.com");
    });

    it("should isolate codes between teams for the same email", async () => {
      await VerificationCode.store(teamId, email, "111111");
      await VerificationCode.store(otherTeamId, email, "222222");

      expect(await VerificationCode.retrieve(teamId, email)).toBe("111111");
      expect(await VerificationCode.retrieve(otherTeamId, email)).toBe(
        "222222"
      );
    });
  });

  describe("verify", () => {
    it("should return true for a matching code", async () => {
      const code = "123456";
      await VerificationCode.store(teamId, email, code);
      const result = await VerificationCode.verify(teamId, email, code);
      expect(result).toBe(true);
    });

    it("should return false for an incorrect code", async () => {
      await VerificationCode.store(teamId, email, "123456");
      const result = await VerificationCode.verify(teamId, email, "000000");
      expect(result).toBe(false);
    });

    it("should return false when no code is stored", async () => {
      const result = await VerificationCode.verify(teamId, email, "123456");
      expect(result).toBe(false);
    });

    it("should not verify a code issued for a different team", async () => {
      await VerificationCode.store(teamId, email, "123456");
      const result = await VerificationCode.verify(
        otherTeamId,
        email,
        "123456"
      );
      expect(result).toBe(false);
    });

    it("should delete the code after exceeding max attempts", async () => {
      await VerificationCode.store(teamId, email, "123456");

      // Exhaust all 10 allowed attempts with wrong codes
      for (let i = 0; i < 10; i++) {
        await VerificationCode.verify(teamId, email, "000000");
      }

      // 11th attempt should fail even with the correct code
      const result = await VerificationCode.verify(teamId, email, "123456");
      expect(result).toBe(false);

      // Code should be deleted from storage
      const stored = await VerificationCode.retrieve(teamId, email);
      expect(stored).toBeUndefined();
    });
  });

  describe("delete", () => {
    it("should remove the stored code", async () => {
      await VerificationCode.store(teamId, email, "123456");
      await VerificationCode.delete(teamId, email);
      const retrieved = await VerificationCode.retrieve(teamId, email);
      expect(retrieved).toBeUndefined();
    });

    it("should reset the attempt counter", async () => {
      await VerificationCode.store(teamId, email, "123456");

      // Use some attempts
      for (let i = 0; i < 5; i++) {
        await VerificationCode.verify(teamId, email, "000000");
      }

      // Delete and re-store
      await VerificationCode.delete(teamId, email);
      await VerificationCode.store(teamId, email, "654321");

      // Should have a fresh set of attempts
      for (let i = 0; i < 9; i++) {
        await VerificationCode.verify(teamId, email, "000000");
      }

      const result = await VerificationCode.verify(teamId, email, "654321");
      expect(result).toBe(true);
    });
  });
});

import { randomInt } from "node:crypto";
import { Minute } from "@shared/utils/time";
import Redis from "@server/storage/redis";
import { safeEqual } from "./crypto";

/**
 * This class manages verification codes for email authentication.
 * It stores and retrieves 6-digit codes in Redis with a 10-minute TTL.
 */
export class VerificationCode {
  /**
   * Redis client instance (lazy initialized)
   */
  private static get redis() {
    return Redis.defaultClient;
  }

  /**
   * TTL for verification codes in milliseconds (10 minutes)
   */
  private static readonly TTL = Minute.ms * 10;

  /**
   * Maximum number of verification attempts before the code is deleted
   */
  private static readonly MAX_ATTEMPTS = 10;

  /**
   * Prefix for Redis keys
   */
  private static readonly KEY_PREFIX = "email_verification_code:";

  /**
   * Prefix for Redis attempt counter keys
   */
  private static readonly ATTEMPTS_PREFIX = "email_verification_attempts:";

  /**
   * Generate a random 6-digit code, drawn uniformly from the full range of
   * possible values and left-padded to a fixed six characters.
   *
   * @returns A string representing a 6-digit code.
   */
  public static generate(): string {
    return randomInt(0, 1000000).toString().padStart(6, "0");
  }

  /**
   * Store a verification code in Redis with a 10-minute TTL
   *
   * @param teamId The team the code is being issued for
   * @param email The email address associated with the code
   * @param code The 6-digit verification code
   * @returns Promise resolving to true if successful
   */
  public static async store(
    teamId: string,
    email: string,
    code: string
  ): Promise<boolean> {
    const key = this.getKey(teamId, email);
    await this.redis.set(key, code, "PX", this.TTL);
    return true;
  }

  /**
   * Retrieve a verification code from Redis
   *
   * @param teamId The team the code was issued for
   * @param email The email address associated with the code
   * @returns Promise resolving to the code or undefined if not found
   */
  public static async retrieve(
    teamId: string,
    email: string
  ): Promise<string | undefined> {
    const key = this.getKey(teamId, email);
    return (await this.redis.get(key)) ?? undefined;
  }

  /**
   * Verify if a given code matches the stored code for an email within a team.
   *
   * @param teamId The team the code was issued for
   * @param email The email address associated with the code
   * @param code The code to verify
   * @returns Promise resolving to true if the code matches, false otherwise
   */
  public static async verify(
    teamId: string,
    email: string,
    code: string
  ): Promise<boolean> {
    const storedCode = await this.retrieve(teamId, email);

    if (!storedCode) {
      return false;
    }

    const attemptsKey = this.getAttemptsKey(teamId, email);
    const attempts = await this.redis.incr(attemptsKey);

    if (attempts === 1) {
      await this.redis.pexpire(attemptsKey, this.TTL);
    }

    if (attempts > this.MAX_ATTEMPTS) {
      await this.delete(teamId, email);
      return false;
    }

    return safeEqual(storedCode, code);
  }

  /**
   * Delete a verification code from Redis
   *
   * @param teamId The team the code was issued for
   * @param email The email address associated with the code
   * @returns Promise resolving to true if successful
   */
  public static async delete(teamId: string, email: string): Promise<boolean> {
    const key = this.getKey(teamId, email);
    const attemptsKey = this.getAttemptsKey(teamId, email);
    await this.redis.del(key, attemptsKey);
    return true;
  }

  /**
   * Get the Redis key for a code scoped to a team and email address.
   *
   * @param teamId The team the code was issued for
   * @param email The email address
   * @returns The Redis key
   */
  private static getKey(teamId: string, email: string): string {
    return `${this.KEY_PREFIX}${teamId}:${email.trim().toLowerCase()}`;
  }

  /**
   * Get the Redis key for tracking verification attempts.
   *
   * @param teamId The team the code was issued for
   * @param email The email address.
   * @returns the Redis key for attempts.
   */
  private static getAttemptsKey(teamId: string, email: string): string {
    return `${this.ATTEMPTS_PREFIX}${teamId}:${email.trim().toLowerCase()}`;
  }
}

