import { config } from "../../../config";
import {
  FeedbackJobRow,
  FeedbackRating,
  RefundPolicySnapshot,
} from "./internal-types";
import type { RefundClass } from "../../../lib/feedback-job-store";

type RefundablePolicy =
  | {
      mode: "flat";
      reason: string;
      ratings: FeedbackRating[];
      credits: number;
    }
  | {
      mode: "percentage_with_cap";
      reason: string;
      ratings: FeedbackRating[];
      percent: number;
      maxCredits: number;
    };

function optionListIncludes(
  options: unknown,
  key: string,
  value: string,
): boolean {
  const list = (options as Record<string, unknown> | null)?.[key];
  if (!Array.isArray(list)) return false;

  return list.some(item => {
    if (item === value) return true;
    return (
      !!item &&
      typeof item === "object" &&
      (item as { type?: unknown }).type === value
    );
  });
}

function hasActions(options: unknown): boolean {
  const actions = (options as { actions?: unknown } | null)?.actions;
  return Array.isArray(actions) && actions.length > 0;
}

function none(
  job: FeedbackJobRow,
  matchedReason: string,
  refundableRatings: FeedbackRating[] = [],
): { desiredRefund: number; policy: RefundPolicySnapshot } {
  return {
    desiredRefund: 0,
    policy: {
      version: "feedback_refund_v1",
      enabled: config.FEEDBACK_REFUND_ENABLED,
      endpoint: job.endpoint,
      mode: "none",
      refundableRatings,
      matchedReason,
    },
  };
}

function policyForRefundClass(refundClass: RefundClass): RefundablePolicy {
  switch (refundClass) {
    case "search":
      return {
        mode: "flat",
        reason: "search_feedback",
        ratings: ["good", "partial", "bad"],
        credits: 1,
      };
    case "map":
      return {
        mode: "flat",
        reason: "map_feedback",
        ratings: ["partial", "bad"],
        credits: 1,
      };
    case "parse":
      return {
        mode: "percentage_with_cap",
        reason: "parse_feedback",
        ratings: ["partial", "bad"],
        percent: 0.25,
        maxCredits: 10,
      };
    case "scrape_pdf":
      return {
        mode: "percentage_with_cap",
        reason: "scrape_pdf_feedback",
        ratings: ["partial", "bad"],
        percent: 0.25,
        maxCredits: 10,
      };
    case "scrape_json":
    case "scrape_addon":
      return {
        mode: "percentage_with_cap",
        reason:
          refundClass === "scrape_json"
            ? "scrape_json_feedback"
            : "scrape_addon_feedback",
        ratings: ["partial", "bad"],
        percent: 0.25,
        maxCredits: 5,
      };
    case "scrape_basic":
      return {
        mode: "flat",
        reason: "scrape_feedback",
        ratings: ["partial", "bad"],
        credits: 1,
      };
  }
}

function policyFor(job: FeedbackJobRow): RefundablePolicy {
  if (job.refund_class) return policyForRefundClass(job.refund_class);
  if (job.endpoint !== "scrape") return policyForRefundClass(job.endpoint);
  if (optionListIncludes(job.options, "parsers", "pdf")) {
    return policyForRefundClass("scrape_pdf");
  }
  if (optionListIncludes(job.options, "formats", "json")) {
    return policyForRefundClass("scrape_json");
  }
  if (
    optionListIncludes(job.options, "formats", "screenshot") ||
    hasActions(job.options)
  ) {
    return policyForRefundClass("scrape_addon");
  }
  return policyForRefundClass("scrape_basic");
}

export function computeRefundPolicy(
  job: FeedbackJobRow,
  rating: FeedbackRating,
): { desiredRefund: number; policy: RefundPolicySnapshot } {
  const billedCredits = Math.max(0, job.credits_cost ?? 0);
  if (!config.FEEDBACK_REFUND_ENABLED) return none(job, "refunds_disabled");
  if (billedCredits <= 0) return none(job, "zero_billed_credits");

  const policy = policyFor(job);
  if (!policy.ratings.includes(rating)) {
    return none(job, "rating_not_refundable", policy.ratings);
  }

  if (policy.mode === "flat") {
    return {
      desiredRefund: Math.min(policy.credits, billedCredits),
      policy: {
        version: "feedback_refund_v1",
        enabled: true,
        endpoint: job.endpoint,
        mode: "flat",
        refundableRatings: policy.ratings,
        matchedReason: policy.reason,
        flatCredits: policy.credits,
        maxCredits: policy.credits,
      },
    };
  }

  return {
    desiredRefund: Math.min(
      Math.ceil(billedCredits * policy.percent),
      policy.maxCredits,
      billedCredits,
    ),
    policy: {
      version: "feedback_refund_v1",
      enabled: true,
      endpoint: job.endpoint,
      mode: "percentage_with_cap",
      refundableRatings: policy.ratings,
      matchedReason: policy.reason,
      percent: policy.percent,
      maxCredits: policy.maxCredits,
    },
  };
}

import { TeamFlags } from "../controllers/v2/types";
import type { ErrorCodes } from "./error";
import {
  type ResolvedSafeMode,
  SAFE_MODE_CREDENTIAL_HEADERS,
  SAFE_MODE_LOGIN_ACTIONS,
} from "./safe-mode";
import {
  getScrapeZDR,
  getIgnoreRobots,
  getCustomRobotsAgent,
  getThreatProtection,
} from "./zdr-helpers";
import {
  THREAT_PROTECTION_CANNOT_DISABLE_MESSAGE,
  THREAT_PROTECTION_NOT_ENABLED_MESSAGE,
  THREAT_PROTECTION_OVERRIDES_DISABLED_MESSAGE,
} from "./threat-protection/request";

type LocationOptions = { country?: string };
type ThreatProtectionOption = { mode?: string };

interface APIRequest {
  zeroDataRetention?: boolean;
  location?: LocationOptions;
  scrapeOptions?: {
    location?: LocationOptions;
    threatProtection?: ThreatProtectionOption;
  };
  crawlerOptions?: {
    ignoreRobotsTxt?: boolean;
    robotsUserAgent?: string;
  };
  // Per-request threat protection policy override (field-level override of
  // the org config). Presence of any value gates on the team flag.
  threatProtection?: ThreatProtectionOption;
  proxy?: string;
  profile?: unknown;
  actions?: { type: string }[];
  headers?: Record<string, string>;
}

interface PermissionOptions {
  /**
   * Org-level threat protection config (or the relevant slice of it), if
   * already loaded. When the org disables request overrides, any per-request
   * threatProtection option is rejected.
   */
  threatProtectionOrgConfig?: { allowRequestOverrides: boolean } | null;
  safeMode?: ResolvedSafeMode | null;
}

const SUPPORT_EMAIL = "support@firecrawl.com";

export function checkPermissions(
  request: APIRequest,
  flags?: TeamFlags,
  options?: PermissionOptions,
): { error?: string; code?: ErrorCodes } {
  // zdr perms — scrapeZDR must be 'allowed' or 'forced' for request-scoped ZDR
  const scrapeMode = getScrapeZDR(flags);
  if (
    request.zeroDataRetention &&
    scrapeMode !== "allowed" &&
    scrapeMode !== "forced"
  ) {
    return {
      error: `Zero Data Retention (ZDR) is not enabled for your team. Contact ${SUPPORT_EMAIL} to enable this feature.`,
    };
  }

  // robots perms — ignoreRobots must be 'allowed' or 'forced'
  const robotsMode = getIgnoreRobots(flags);
  if (
    request.crawlerOptions?.ignoreRobotsTxt &&
    robotsMode !== "allowed" &&
    robotsMode !== "forced" &&
    // Under Safe Mode (outside lockdown) the robots rejection below returns
    // SAFE_MODE_BLOCKED; don't preempt it with the generic entitlement error.
    !(
      options?.safeMode &&
      !options.safeMode.lockdown &&
      options.safeMode.enforceRobots
    )
  ) {
    return {
      error: `The ignoreRobotsTxt parameter is an enterprise feature. Contact ${SUPPORT_EMAIL} to explore whether it can be enabled for your team.`,
    };
  }
  // customRobotsAgent perms — separate flag for robotsUserAgent
  const customAgentMode = getCustomRobotsAgent(flags);
  if (
    request.crawlerOptions?.robotsUserAgent &&
    customAgentMode !== "allowed"
  ) {
    return {
      error: `The robotsUserAgent parameter is an enterprise feature. Contact ${SUPPORT_EMAIL} to explore whether it can be enabled for your team.`,
    };
  }

  // threat protection perms — the flag must be 'allowed' or 'forced' for any
  // per-request threatProtection option, the org must not have locked down
  // request-level overrides, and a 'forced' team may never disable the
  // feature per-request.
  const threatProtectionOption =
    request.threatProtection ?? request.scrapeOptions?.threatProtection;
  if (threatProtectionOption !== undefined) {
    const effectiveThreatMode =
      options?.safeMode?.domainControls === true
        ? "forced"
        : getThreatProtection(flags);
    if (effectiveThreatMode !== "allowed" && effectiveThreatMode !== "forced") {
      return { error: THREAT_PROTECTION_NOT_ENABLED_MESSAGE };
    }
    if (options?.threatProtectionOrgConfig?.allowRequestOverrides === false) {
      return { error: THREAT_PROTECTION_OVERRIDES_DISABLED_MESSAGE };
    }
    if (
      effectiveThreatMode === "forced" &&
      threatProtectionOption.mode === "off"
    ) {
      return { error: THREAT_PROTECTION_CANNOT_DISABLE_MESSAGE };
    }
  }

  const safeMode = options?.safeMode;
  if (safeMode && !safeMode.lockdown) {
    if (
      safeMode.disableStealthProxy &&
      (request.proxy === "stealth" || request.proxy === "enhanced")
    ) {
      return {
        error:
          'Safe Mode: stealth and enhanced proxies are not allowed for your organization. Remove the proxy option or use proxy: "basic".',
        code: "SAFE_MODE_BLOCKED",
      };
    }
    if (safeMode.enforceRobots && request.crawlerOptions?.ignoreRobotsTxt) {
      return {
        error:
          "Safe Mode: robots.txt is always honored for your organization; the ignoreRobotsTxt parameter is not allowed.",
        code: "SAFE_MODE_BLOCKED",
      };
    }
    if (safeMode.disableAuthentication) {
      if (request.profile !== undefined) {
        return {
          error:
            "Safe Mode: browser profiles are not allowed for your organization (nothing behind a login).",
          code: "SAFE_MODE_BLOCKED",
        };
      }
      const loginAction = (request.actions ?? []).find(a =>
        SAFE_MODE_LOGIN_ACTIONS.includes(a.type),
      );
      if (loginAction) {
        return {
          error: `Safe Mode: the ${loginAction.type} action is not allowed for your organization (nothing behind a login).`,
          code: "SAFE_MODE_BLOCKED",
        };
      }
      const credentialHeader = Object.keys(request.headers ?? {}).find(h =>
        SAFE_MODE_CREDENTIAL_HEADERS.includes(h.toLowerCase()),
      );
      if (credentialHeader) {
        return {
          error: `Safe Mode: the ${credentialHeader} header is not allowed for your organization (nothing behind a login).`,
          code: "SAFE_MODE_BLOCKED",
        };
      }
    }
  }

  // ip whitelist perms
  const needsWhitelist =
    request.location?.country === "us-whitelist" ||
    request.scrapeOptions?.location?.country === "us-whitelist";

  if (needsWhitelist && !flags?.ipWhitelist) {
    return {
      error: `Static IP addresses are not enabled for your team. Contact ${SUPPORT_EMAIL} to get a dedicated set of IP addresses you can whitelist.`,
    };
  }

  return {};
}

use napi::bindgen_prelude::*;
use napi_derive::napi;
use roxmltree::Document;
use std::collections::{HashMap, HashSet};
use std::io::{Cursor, Read};

const MAX_OOXML_PART_BYTES: u64 = 128 * 1024 * 1024;
const MAX_OOXML_TOTAL_BYTES: u64 = 128 * 1024 * 1024;
const MAX_OOXML_PARTS: usize = 256;
const MAX_HEADER_FOOTER_REFERENCES: usize = 256;
const WORDPROCESSINGML_NAMESPACES: [&str; 2] = [
  "http://schemas.openxmlformats.org/wordprocessingml/2006/main",
  "http://purl.oclc.org/ooxml/wordprocessingml/main",
];

#[derive(Clone, Copy, PartialEq, Eq, Hash)]
enum RepeatingPartKind {
  Header,
  Footer,
}

struct Relationship {
  target: String,
  kind: RepeatingPartKind,
}

struct ZipReadBudget {
  bytes_remaining: u64,
  parts_remaining: usize,
}

impl Default for ZipReadBudget {
  fn default() -> Self {
    Self {
      bytes_remaining: MAX_OOXML_TOTAL_BYTES,
      parts_remaining: MAX_OOXML_PARTS,
    }
  }
}

/// Convert a document (doc, docx, odt/ods/odp, rtf, xls/xlsx, ppt/pptx, epub,
/// csv, ...) to GitHub-Flavored Markdown using anydoc. The format is detected
/// from the file content; `extension_hint` (with or without a leading dot) is
/// only consulted for signature-less formats like CSV.
#[napi]
pub fn convert_document_to_markdown(data: &[u8], extension_hint: Option<String>) -> Result<String> {
  let format = anydoc::Format::from_bytes(data).or_else(|| {
    extension_hint
      .as_deref()
      .map(|ext| ext.trim_start_matches('.'))
      .and_then(anydoc::Format::from_extension)
  });

  let markdown = anydoc::to_markdown_bytes(data, format)
    .map_err(|e| Error::new(Status::GenericFailure, e.to_string()))?;

  if format != Some(anydoc::Format::Docx) {
    return Ok(markdown);
  }

  let (headers, footers) = extract_docx_headers_and_footers(data);
  if headers.is_empty() && footers.is_empty() {
    return Ok(markdown);
  }
  let sections = [headers, markdown.trim().to_string(), footers]
    .into_iter()
    .filter(|section| !section.is_empty())
    .collect::<Vec<_>>();

  Ok(format!("{}\n", sections.join("\n\n")))
}

fn extract_docx_headers_and_footers(data: &[u8]) -> (String, String) {
  let Ok(mut archive) = zip::ZipArchive::new(Cursor::new(data)) else {
    return (String::new(), String::new());
  };
  let mut budget = ZipReadBudget::default();

  let main_part = read_zip_text(&mut archive, "_rels/.rels", &mut budget)
    .and_then(|xml| office_document_target(&xml))
    .unwrap_or_else(|| "word/document.xml".to_string());
  let Some(document_xml) = read_zip_text(&mut archive, &main_part, &mut budget) else {
    return (String::new(), String::new());
  };
  let relationship_part = relationship_part_for(&main_part);
  let Some(relationships_xml) = read_zip_text(&mut archive, &relationship_part, &mut budget) else {
    return (String::new(), String::new());
  };
  let relationships = parse_repeating_relationships(&relationships_xml);
  let Ok(document) = Document::parse(&document_xml) else {
    return (String::new(), String::new());
  };

  let mut seen = HashSet::new();
  let mut headers = Vec::new();
  let mut footers = Vec::new();
  let mut reference_count = 0;

  for reference in document
    .descendants()
    .filter(|node| is_wordprocessing_node(*node))
  {
    let reference_kind = match reference.tag_name().name() {
      "headerReference" => RepeatingPartKind::Header,
      "footerReference" => RepeatingPartKind::Footer,
      _ => continue,
    };
    reference_count += 1;
    if reference_count > MAX_HEADER_FOOTER_REFERENCES {
      break;
    }
    let Some(id) = reference
      .attributes()
      .find(|attribute| attribute.name() == "id")
      .map(|attribute| attribute.value())
    else {
      continue;
    };
    let Some(relationship) = relationships.get(id) else {
      continue;
    };
    if relationship.kind != reference_kind {
      continue;
    }
    let Some(part) = resolve_part(&main_part, &relationship.target) else {
      continue;
    };
    if !seen.insert((reference_kind, part.clone())) {
      continue;
    }
    let Some(xml) = read_zip_text(&mut archive, &part, &mut budget) else {
      continue;
    };
    let Some(text) = extract_wordprocessing_text(&xml) else {
      continue;
    };

    match reference_kind {
      RepeatingPartKind::Header => headers.push(text),
      RepeatingPartKind::Footer => footers.push(text),
    }
  }

  (headers.join("\n\n"), footers.join("\n\n"))
}

fn read_zip_text<R: Read + std::io::Seek>(
  archive: &mut zip::ZipArchive<R>,
  name: &str,
  budget: &mut ZipReadBudget,
) -> Option<String> {
  if budget.parts_remaining == 0 || budget.bytes_remaining == 0 {
    return None;
  }
  let mut file = archive.by_name(name.trim_start_matches('/')).ok()?;
  if file.size() > MAX_OOXML_PART_BYTES || file.size() > budget.bytes_remaining {
    return None;
  }
  budget.parts_remaining -= 1;
  let mut bytes = Vec::with_capacity(file.size() as usize);
  let read_limit = MAX_OOXML_PART_BYTES.min(budget.bytes_remaining);
  let read_result = file.by_ref().take(read_limit + 1).read_to_end(&mut bytes);
  budget.bytes_remaining = budget.bytes_remaining.saturating_sub(bytes.len() as u64);
  if read_result.is_err() {
    return None;
  }
  if bytes.len() as u64 > read_limit {
    budget.bytes_remaining = 0;
    return None;
  }
  String::from_utf8(bytes).ok()
}

fn office_document_target(xml: &str) -> Option<String> {
  let document = Document::parse(xml).ok()?;
  let relationship = document.descendants().find(|node| {
    node.is_element()
      && node.tag_name().name() == "Relationship"
      && node
        .attribute("Type")
        .is_some_and(|value| value.ends_with("/officeDocument"))
  })?;
  normalize_part(relationship.attribute("Target")?)
}

fn parse_repeating_relationships(xml: &str) -> HashMap<String, Relationship> {
  let Ok(document) = Document::parse(xml) else {
    return HashMap::new();
  };

  document
    .descendants()
    .filter_map(|node| {
      if !node.is_element()
        || node.tag_name().name() != "Relationship"
        || node
          .attribute("TargetMode")
          .is_some_and(|value| value.eq_ignore_ascii_case("external"))
      {
        return None;
      }
      let kind = match node.attribute("Type")? {
        value if value.ends_with("/header") => RepeatingPartKind::Header,
        value if value.ends_with("/footer") => RepeatingPartKind::Footer,
        _ => return None,
      };
      Some((
        node.attribute("Id")?.to_string(),
        Relationship {
          target: node.attribute("Target")?.to_string(),
          kind,
        },
      ))
    })
    .collect()
}

fn relationship_part_for(part: &str) -> String {
  match part.rsplit_once('/') {
    Some((parent, file_name)) => format!("{parent}/_rels/{file_name}.rels"),
    None => format!("_rels/{part}.rels"),
  }
}

fn resolve_part(base: &str, target: &str) -> Option<String> {
  if target.starts_with('/') {
    return normalize_part(target);
  }
  let parent = base
    .rsplit_once('/')
    .map(|(parent, _)| parent)
    .unwrap_or("");
  normalize_part(&format!("{parent}/{target}"))
}

fn normalize_part(part: &str) -> Option<String> {
  let mut normalized = Vec::new();
  for component in part.trim_start_matches('/').split('/') {
    match component {
      "" | "." => {}
      ".." => normalized.pop().map(|_| ())?,
      value => normalized.push(value),
    }
  }
  (!normalized.is_empty()).then(|| normalized.join("/"))
}

fn extract_wordprocessing_text(xml: &str) -> Option<String> {
  let document = Document::parse(xml).ok()?;
  let paragraphs = document
    .descendants()
    .filter(|node| {
      is_wordprocessing_node(*node)
        && node.tag_name().name() == "p"
        && !node
          .ancestors()
          .skip(1)
          .any(|ancestor| is_wordprocessing_node(ancestor) && ancestor.tag_name().name() == "p")
    })
    .filter_map(|paragraph| {
      let mut text = String::new();
      for node in paragraph
        .descendants()
        .filter(|node| is_wordprocessing_node(*node))
      {
        match node.tag_name().name() {
          "t" => {
            if let Some(value) = node.text() {
              text.push_str(value);
            }
          }
          "tab" => text.push('\t'),
          "br" | "cr" => text.push('\n'),
          _ => {}
        }
      }
      let text = text.trim();
      (!text.is_empty()).then(|| text.to_string())
    })
    .collect::<Vec<_>>();

  (!paragraphs.is_empty()).then(|| paragraphs.join("\n\n"))
}

fn is_wordprocessing_node(node: roxmltree::Node<'_, '_>) -> bool {
  node.is_element()
    && node
      .tag_name()
      .namespace()
      .is_some_and(|namespace| WORDPROCESSINGML_NAMESPACES.contains(&namespace))
}

import { Response } from "express";
