  // Safe Mode lockdown: serve links from the index only — skip the live
  // fireEngineMap search and any sitemap fetch (both are live discovery).
  // Derived from the team flags so every caller honors it.
  const indexOnly =
    resolveSafeMode(flags, undefined, url).safeMode?.lockdown === true;

  // Lockdown (index-only) is cache-only, which implies zero data retention.
  const zeroDataRetention = getScrapeZDR(flags) === "forced" || indexOnly;

  const sc: StoredCrawl = {
    originUrl: url,
    crawlerOptions: {
      ...crawlerOptions,
      limit: crawlerOptions.sitemapOnly ? 10000000 : limit,
      scrapeOptions: undefined,
    },
    scrapeOptions: scrapeOptions.parse({
      ...(location ? { location } : {}),
      ...(headers ? { headers } : {}),
    }),
    internalOptions: { teamId, orgId: orgId ?? null },
    team_id: teamId,
    createdAt: Date.now(),
  };

  const crawler = crawlToCrawler(id, sc, flags);

  try {
    sc.robots = await crawler.getRobotsTxt(false, abort);
    crawler.importRobotsTxt(sc.robots);
  } catch (_) {}

  // If sitemapOnly is true, only get links from sitemap
  if (crawlerOptions.sitemapOnly) {
    const sitemap = await crawler.tryGetSitemap(
      urls => {
        urls.forEach(x => {
          links.push(x);
        });
      },
      true,
      true,
      timeout ?? 30000,
      abort,
      mock,
      ignoreCache ? 0 : undefined,
    );
    if (sitemap > 0) {
      links = links
        .slice(1)
        .map(x => {
          try {
            return checkAndUpdateURLForMap(x).url.trim();
          } catch (_) {
            return null;
          }
        })
        .filter(x => x !== null) as string[];
      // links = links.slice(1, limit); // don't slice, unnecessary
    }
  } else {
    let urlWithoutWww = url.replace("www.", "");

    let mapUrl =
      search && allowExternalLinks
        ? `${search} ${urlWithoutWww}`
        : search
          ? `${search} site:${urlWithoutWww}`
          : `site:${url}`;

    const resultsPerPage = 100;
    const maxPages = Math.ceil(
      Math.min(MAX_FIRE_ENGINE_RESULTS, limit) / resultsPerPage,
    );

    const cacheKey = `fireEngineMap:${mapUrl}`;
    const cachedResult = ignoreCache ? null : await redis.get(cacheKey);

    let allResults: any[] = [];
    let pagePromises: Promise<any>[] = [];

    if (indexOnly) {
      // Lockdown: no live search discovery, serve from the index only.
      allResults = [];
    } else if (cachedResult) {
      allResults = JSON.parse(cachedResult);
    } else {
      const fetchPage = async (page: number) => {
        return fireEngineMap(
          mapUrl,
          {
            numResults: resultsPerPage,
            page: page,
          },
          abort,
        );
      };

      pagePromises = Array.from({ length: maxPages }, (_, i) =>
        fetchPage(i + 1),
      );
      allResults = await Promise.all(pagePromises);

      if (!zeroDataRetention) {
        await redis.set(
          cacheKey,
          JSON.stringify(allResults),
          "EX",
          48 * 60 * 60,
        ); // Cache for 48 hours
      }
    }

    // Parallelize sitemap index query with search results
    const [indexResults, ...searchResults] = await Promise.all([
      queryIndex(url, limit, useIndex, includeSubdomains),
      ...(cachedResult ? [] : pagePromises),
    ]);

    if (indexResults.length > 0) {
      links.push(...indexResults);
    }

    // If sitemap is not ignored, fetch sitemap
    // This will attempt to find it in the index at first, or fetch a fresh one if it's older than 2 days
    if (!ignoreSitemap && !indexOnly) {
      try {
        await crawler.tryGetSitemap(
          urls => {
            links.push(...urls);
          },
          true,
          false,
          timeout ?? 30000,
          abort,
          undefined,
          ignoreCache ? 0 : undefined,
        );
      } catch (e) {
        logger.warn("tryGetSitemap threw an error", { error: e });
      }
    }

    if (!cachedResult) {
      allResults = searchResults;
    }

    mapResults = allResults
      .flat()
      .filter(result => result !== null && result !== undefined);

    const minumumCutoff = Math.min(MAX_MAP_LIMIT, limit);
    if (mapResults.length > minumumCutoff) {
      mapResults = mapResults.slice(0, minumumCutoff);
    }

    if (mapResults.length > 0) {
      if (search) {
        // Ensure all map results are first, maintaining their order
        links = [
          mapResults[0].url,
          ...mapResults.slice(1).map(x => x.url),
          ...links,
        ];
      } else {
        mapResults.map(x => {
          links.push(x.url);
        });
      }
    }

    // Perform cosine similarity between the search query and the list of links
    if (search) {
      const searchQuery = search.toLowerCase();
      links = performCosineSimilarity(links, searchQuery);
    }

    links = links
      .map(x => {
        try {
          return checkAndUpdateURLForMap(
            x,
            crawlerOptions.ignoreQueryParameters ?? true,
          ).url.trim();
        } catch (_) {
          return null;
        }
      })
      .filter(x => x !== null) as string[];

    // allows for subdomains to be included
    links = links.filter(x => isSameDomain(x, url));

    // if includeSubdomains is false, filter out subdomains
    if (!includeSubdomains) {
      links = links.filter(x => isSameSubdomain(x, url));
    }

    // Filter by path if enabled
    if (filterByPath && !allowExternalLinks) {
      try {
        const urlObj = new URL(url);
        const urlPath = urlObj.pathname;
        // Only apply path filtering if the URL has a significant path (not just '/' or empty)
        // This means we only filter by path if the user has not selected a root domain
        if (urlPath && urlPath !== "/" && urlPath.length > 1) {
          links = links.filter(link => {
            try {
              const linkObj = new URL(link);
              return linkObj.pathname.startsWith(urlPath);
            } catch (e) {
              return false;
            }
          });
        }
      } catch (e) {
        // If URL parsing fails, continue without path filtering
        logger.warn(`Failed to parse URL for path filtering: ${url}`, {
          error: e,
        });
      }
    }

    // remove duplicates that could be due to http/https or www
    links = removeDuplicateUrls(links);
  }

  const linksToReturn = crawlerOptions.sitemapOnly
    ? links
    : links.slice(0, limit);

  return {
    success: true,
    links: linksToReturn,
    mapResults: mapResults,
    scrape_id: origin?.includes("website") ? id : undefined,
    job_id: id,
    time_taken: (Date.now() - startTime) / 1000,
  };
}

export async function mapController(
  req: RequestWithAuth<{}, MapResponse, MapRequest>,
  res: Response<MapResponse>,
) {
  // Get timing data from middleware (includes all middleware processing time)
  const middlewareStartTime =
    (req as any).requestTiming?.startTime || new Date().getTime();
  const controllerStartTime = new Date().getTime();

  const originalRequest = req.body;
  req.body = mapRequestSchema.parse(req.body);

  if (getScrapeZDR(req.acuc?.flags) === "forced") {
    return res.status(400).json({
      success: false,
      error:
        "Your team has zero data retention enabled. This is not supported on map. Please contact support@firecrawl.com to unblock this feature.",
    });
  }

  // Safe Mode: force domainControls so discovered links are filtered, and
  // serve index-only under lockdown (no sitemap/robots fetch to the target).
  const safeMode = resolveSafeMode(req.acuc?.flags, undefined, req.body.url);
  const lockdownIndexOnly = safeMode.safeMode?.lockdown === true;
  if (lockdownIndexOnly) {
    // Lockdown: serve links from the index only — no live search / sitemap /
    // robots discovery. A sitemapOnly request keeps its contract and simply
    // yields no links (the sitemap can't be fetched under lockdown).
    req.body.useIndex = true;
  }
  // Map's ignoreRobotsTxt is top-level, so checkPermissions (which reads it
  // under crawlerOptions) can't see it — enforce robots here for Safe Mode.
  if (
    safeMode.safeMode?.enforceRobots &&
    !lockdownIndexOnly &&
    req.body.ignoreRobotsTxt
  ) {
    return res.status(403).json({
      success: false,
      code: "SAFE_MODE_BLOCKED",
      error:
        "Safe Mode: robots.txt is always honored for your organization; the ignoreRobotsTxt parameter is not allowed.",
    });
  }

  const threatProtection = await resolveThreatProtection({
    teamId: req.auth.team_id,
    orgId: req.acuc?.org_id ?? null,
    flags: req.acuc?.flags ?? null,
    override: req.body.threatProtection,
    force: safeMode.safeMode?.domainControls === true,
  });
  if (threatProtection.error) {
    return res.status(403).json({
      success: false,
      error: threatProtection.error,
    });
  }

  const permissions = checkPermissions(req.body, req.acuc?.flags, {
    threatProtectionOrgConfig: threatProtection.orgConfig,
    safeMode: safeMode.safeMode ?? null,
  });
  if (permissions.error) {
    return res.status(403).json({
      success: false,
      code: permissions.code,
      error: permissions.error,
    });
  }

  const middlewareTime = controllerStartTime - middlewareStartTime;

  const mapId = uuidv7();

  logger.info("Map request", {
    request: req.body,
    originalRequest,
    teamId: req.auth.team_id,
    mapId,
  });

  await logRequest({
    id: mapId,
    kind: "map",
    api_version: "v1",
    external_request_id: externalRequestId(req),
    team_id: req.auth.team_id,
    origin: req.body.origin ?? "api",
    integration: req.body.integration,
    target_hint: req.body.url,
    zeroDataRetention: lockdownIndexOnly,
    api_key_id: req.acuc?.api_key_id ?? null,
  });

  let result: Awaited<ReturnType<typeof getMapResults>>;
  let timeoutHandle: NodeJS.Timeout | null = null;

  const abort = new AbortController();
  try {
    result = (await Promise.race([
      getMapResults({
        url: req.body.url,
        search: req.body.search,
        limit: req.body.limit,
        ignoreSitemap: req.body.ignoreSitemap,
        includeSubdomains: req.body.includeSubdomains,
        crawlerOptions: req.body,
        origin: req.body.origin,
        teamId: req.auth.team_id,
        orgId: req.acuc?.org_id ?? null,
        abort: abort.signal,
        mock: req.body.useMock,
        filterByPath: req.body.filterByPath !== false,
        flags: req.acuc?.flags ?? null,
        useIndex: req.body.useIndex,
        ignoreCache: req.body.ignoreCache,
        timeout: req.body.timeout,
        location: req.body.location,
        headers: req.body.headers,
        id: mapId,
      }),
      ...(req.body.timeout !== undefined
        ? [
            new Promise(
              (_resolve, reject) =>
                (timeoutHandle = setTimeout(() => {
                  abort.abort(new MapTimeoutError());
                  reject(new MapTimeoutError());
                }, req.body.timeout)),
            ),
          ]
        : []),
    ])) as any;
  } catch (error) {
    if (error instanceof MapTimeoutError) {
      return res.status(408).json({
        success: false,
        code: error.code,
        error: error.message,
      });
    } else {
      throw error;
    }
  } finally {
    if (timeoutHandle) {
      clearTimeout(timeoutHandle);
    }
  }

  // Threat protection: remove blocked links from the returned URL list
  // entirely. Checks are URL-level; scan fees bill +2 per unique scanned
  // URL (see calculateThreatScanCredits).
  //
  // "zscaler" mode evaluates map results against local rules only, same as
  // the v2 map controller: one map can return thousands of URLs, and inline
  // classification would burn the tenant's 400/hour urlLookup budget on
  // links that may never be fetched.
  let threatScanCredits = 0;
  if (threatProtection.policy && result.links.length > 0) {
    const { decisionsByUrl } = await checkUrlsAgainstThreatPolicy(
      result.links,
      threatProtection.policy,
      {
        teamId: req.auth.team_id,
        localRulesOnly: threatProtection.policy.mode === "zscaler",
      },
    );
    threatScanCredits = calculateThreatScanCredits(decisionsByUrl.values());
    result.links = result.links.filter(x => {
      const decision = decisionsByUrl.get(x);
      return decision === undefined || decision.allowed;
    });
  }

  // Bill the team
  const creditsToBill = 1 + threatScanCredits;
  billTeam(
    req.auth.team_id,
    req.acuc?.org_id ?? null,
    creditsToBill,
    req.acuc?.api_key_id ?? null,
    {
      endpoint: "map",
      externalRequestId: externalRequestId(req),
      jobId: mapId,
      chargeId: mapId,
    },
  ).catch(error => {
    logger.error(
      `Failed to bill team ${req.auth.team_id} for ${creditsToBill} credit(s): ${error}`,
    );
  });

  // Log the job
  logMap({
    id: result.job_id,
    request_id: result.job_id,
    url: req.body.url,
    team_id: req.auth.team_id,
    options: {
      search: req.body.search,
      limit: req.body.limit,
      ignoreSitemap: req.body.ignoreSitemap,
      includeSubdomains: req.body.includeSubdomains,
      filterByPath: req.body.filterByPath !== false,
      useIndex: req.body.useIndex,
      timeout: req.body.timeout,
      location: req.body.location,
    },
    results: result.links,
    credits_cost: creditsToBill,
    zeroDataRetention: lockdownIndexOnly,
  }).catch(error => {
    logger.error("Failed to log map", { error, mapId });
  });

  // Log final timing information
  const totalRequestTime = new Date().getTime() - middlewareStartTime;
  const controllerTime = new Date().getTime() - controllerStartTime;

  logger.info("Request metrics", {
    version: "v1",
    jobId: result.job_id,
    mode: "map",
    middlewareStartTime,
    controllerStartTime,
    middlewareTime,
    controllerTime,
    totalRequestTime,
    linksCount: result.links.length,
  });

  const response = {
    success: true as const,
    links: result.links,
    scrape_id: result.scrape_id,
  };

  return res.status(200).json(response);
}

import { Agent, fetch } from "undici";
import { config } from "../config";

const TIMEOUT_MS = 120_000;
const CONNECT_TIMEOUT_MS = 10_000;

const dispatcher = new Agent({
  connectTimeout: CONNECT_TIMEOUT_MS,
});

function appendQuery(
  url: URL,
  params: Record<string, unknown>,
  allowed: string[],
) {
  for (const key of allowed) {
    const value = params[key];
    if (Array.isArray(value)) {
      for (const item of value) {
        if (item !== undefined && item !== null) {
          url.searchParams.append(key, String(item));
        }
      }
    } else if (value !== undefined && value !== null) {
      url.searchParams.append(key, String(value));
    }
  }
}

export async function fetchResearchUpstream(options: {
  path: string;
  params: Record<string, unknown>;
  queryKeys: string[];
  headers: Record<string, string>;
  timeoutMs?: number;
}) {
  const base = config.RESEARCH_PROXY_URL;
  if (!base) return null;

  const url = new URL(base.replace(/\/+$/, "") + options.path);
  appendQuery(url, options.params, options.queryKeys);

  return fetch(url, {
    method: "GET",
    headers: options.headers,
    signal: AbortSignal.timeout(options.timeoutMs ?? TIMEOUT_MS),
    dispatcher,
  });
}

import { gzipSync } from "zlib";
import { createHash, randomUUID } from "crypto";
import {
  fetch as undiciFetch,
  ProxyAgent,
  type Dispatcher,
  type Response,
} from "undici";
import { config } from "../../config";
import { logger as _logger } from "../logger";
import {
  siemLoggingDeliveryBatchesTotal,
  siemLoggingEventsTotal,
} from "./metrics";
import type { AzureSentinelDestination, ScrapeActivityEvent } from "./types";
import { SiemDeliveryError } from "./types";

const logger = _logger.child({ module: "siem-logging-azure-sentinel" });

const MAX_COMPRESSED_BODY_BYTES = 1_000_000;
const MAX_ATTEMPTS = 3;
const MAX_RETRY_DELAY_MS = 30_000;
const MAX_TOKEN_CACHE_ENTRIES = 1000;
const REQUEST_TIMEOUT_MS = 15_000;

type FetchImpl = (
  input: string,
  init: {
    method: string;
    headers: Record<string, string>;
    body?: string | Buffer;
    dispatcher?: Dispatcher;
    signal?: AbortSignal;
  },
) => Promise<Response>;

export interface SenderDependencies {
  fetchImpl?: FetchImpl;
  sleep?: (ms: number) => Promise<void>;
  dispatcher?: Dispatcher;
  tokenUrl?: string;
}

interface CachedToken {
  token: string;
  expiresAt: number;
}

const tokenCache = new Map<string, CachedToken>();
let proxyDispatcher: ProxyAgent | undefined;
let proxyDispatcherUrl: string | undefined;

function getDispatcher(deps: SenderDependencies): Dispatcher | undefined {
  if (deps.dispatcher) return deps.dispatcher;
  if (!config.PARTNER_EGRESS_PROXY_URL) return undefined;
  if (
    !proxyDispatcher ||
    proxyDispatcherUrl !== config.PARTNER_EGRESS_PROXY_URL
  ) {
    proxyDispatcher = new ProxyAgent(config.PARTNER_EGRESS_PROXY_URL);
    proxyDispatcherUrl = config.PARTNER_EGRESS_PROXY_URL;
  }
  return proxyDispatcher;
}

function tokenCacheKey(destination: AzureSentinelDestination): string {
  const credentialDigest = createHash("sha256")
    .update(destination.clientSecret)
    .digest("base64url");
  return `${destination.tenantId}:${destination.clientId}:${credentialDigest}`;
}

function cacheToken(cacheKey: string, token: CachedToken): void {
  const now = Date.now();
  for (const [key, cached] of tokenCache) {
    if (cached.expiresAt <= now) tokenCache.delete(key);
  }
  tokenCache.delete(cacheKey);
  while (tokenCache.size >= MAX_TOKEN_CACHE_ENTRIES) {
    const oldestKey = tokenCache.keys().next().value;
    if (oldestKey === undefined) break;
    tokenCache.delete(oldestKey);
  }
  tokenCache.set(cacheKey, token);
}

function invalidateToken(destination: AzureSentinelDestination): void {
  tokenCache.delete(tokenCacheKey(destination));
}

function retryAfterMs(response: Response): number | undefined {
  const value = response.headers.get("retry-after");
  if (!value) return undefined;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) {
    return Math.min(Math.max(0, seconds * 1000), MAX_RETRY_DELAY_MS);
  }
  const date = Date.parse(value);
  if (Number.isNaN(date)) return undefined;
  return Math.min(Math.max(0, date - Date.now()), MAX_RETRY_DELAY_MS);
}

async function errorText(response: Response): Promise<string> {
  const text = await response.text();
  return text.slice(0, 2048) || response.statusText || "Request failed";
}

async function waitBeforeRetry(
  attempt: number,
  response: Response,
  sleep: (ms: number) => Promise<void>,
): Promise<void> {
  const delay =
    retryAfterMs(response) ?? Math.min(250 * 2 ** (attempt - 1), 2000);
  await response.body?.cancel();
  await sleep(delay);
}

function networkErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "Network request failed";
}

async function getAccessToken(
  destination: AzureSentinelDestination,
  deps: SenderDependencies,
): Promise<string> {
  const cacheKey = tokenCacheKey(destination);
  const cached = tokenCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now() + 60_000) return cached.token;

  const fetchImpl = deps.fetchImpl ?? (undiciFetch as FetchImpl);
  const sleep =
    deps.sleep ??
    ((ms: number) => new Promise(resolve => setTimeout(resolve, ms)));
  const dispatcher = getDispatcher(deps);
  const tokenUrl =
    deps.tokenUrl ??
    `https://login.microsoftonline.com/${encodeURIComponent(destination.tenantId)}/oauth2/v2.0/token`;
  const body = new URLSearchParams({
    client_id: destination.clientId,
    client_secret: destination.clientSecret,
    scope: "https://monitor.azure.com//.default",
    grant_type: "client_credentials",
  }).toString();

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let response: Response;
    try {
      response = await fetchImpl(tokenUrl, {
        method: "POST",
        headers: { "content-type": "application/x-www-form-urlencoded" },
        body,
        dispatcher,
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
    } catch (error) {
      if (attempt < MAX_ATTEMPTS) {
        await sleep(Math.min(250 * 2 ** (attempt - 1), 2000));
        continue;
      }
      throw new SiemDeliveryError(
        "delivery_error",
        `Failed to obtain an Entra token: ${networkErrorMessage(error)}`,
      );
    }

    if (response.ok) {
      const payload = (await response.json()) as {
        access_token?: unknown;
        expires_in?: unknown;
      };
      if (typeof payload.access_token !== "string") {
        throw new SiemDeliveryError(
          "invalid_credentials",
          "Entra token response did not include an access token",
          response.status,
        );
      }
      const expiresIn =
        typeof payload.expires_in === "number" ? payload.expires_in : 3600;
      cacheToken(cacheKey, {
        token: payload.access_token,
        expiresAt: Date.now() + expiresIn * 1000,
      });
      return payload.access_token;
    }

    if (
      (response.status === 429 || response.status >= 500) &&
      attempt < MAX_ATTEMPTS
    ) {
      await waitBeforeRetry(attempt, response, sleep);
      continue;
    }

    const message = await errorText(response);
    if (
      response.status === 400 ||
      response.status === 401 ||
      response.status === 403
    ) {
      throw new SiemDeliveryError(
        "invalid_credentials",
        `Entra rejected the SIEM credentials: ${message}`,
        response.status,
      );
    }
    throw new SiemDeliveryError(
      response.status === 429 ? "rate_limited" : "delivery_error",
      `Failed to obtain an Entra token: ${message}`,
      response.status,
      retryAfterMs(response),
    );
  }

  throw new SiemDeliveryError(
    "delivery_error",
    "Failed to obtain an Entra token",
  );
}

function gzipEvents(events: ScrapeActivityEvent[]): Buffer {
  return gzipSync(Buffer.from(JSON.stringify(events), "utf8"));
}

/**
 * A gzipped request body plus how many events it carries, so the caller can
 * report what was actually delivered rather than what it was handed — a batch
 * can contain fewer events than the input if any were skipped as undeliverable.
 */
interface CompressedBatch {
  body: Buffer;
  eventCount: number;
}

function compressedBatch(events: ScrapeActivityEvent[]): CompressedBatch {
  return { body: gzipEvents(events), eventCount: events.length };
}

export function* buildCompressedBatches(
  events: ScrapeActivityEvent[],
  maxBytes = MAX_COMPRESSED_BODY_BYTES,
): Generator<CompressedBatch> {
  let pending: ScrapeActivityEvent[] = [];

  for (const event of events) {
    const candidate = [...pending, event];
    if (gzipEvents(candidate).byteLength <= maxBytes) {
      pending = candidate;
      continue;
    }

    // The event doesn't fit alongside what's pending — close that batch out and
    // consider the event on its own.
    if (pending.length > 0) {
      yield compressedBatch(pending);
      pending = [];
    }

    if (gzipEvents([event]).byteLength > maxBytes) {
      // Undeliverable at any batch size, and no retry will change that. Skip it
      // and keep going: failing the call here would take down every other event
      // in the batch, and dead-lettering the batch would duplicate the ones
      // already POSTed in earlier chunks.
      siemLoggingEventsTotal.inc({ result: "dropped_oversized" });
      logger.error("Dropping a SIEM event larger than the payload limit", {
        maxBytes,
        scrapeId: event.scrape_id,
        orgId: event.org_id,
      });
      continue;
    }
    pending = [event];
  }

  if (pending.length > 0) yield compressedBatch(pending);
}

async function sendBatch(
  destination: AzureSentinelDestination,
  token: string,
  body: Buffer,
  deps: SenderDependencies,
): Promise<void> {
  const fetchImpl = deps.fetchImpl ?? (undiciFetch as FetchImpl);
  const sleep =
    deps.sleep ??
    ((ms: number) => new Promise(resolve => setTimeout(resolve, ms)));
  const dispatcher = getDispatcher(deps);
  const url =
    `${destination.dceUrl.replace(/\/+$/, "")}/dataCollectionRules/` +
    `${encodeURIComponent(destination.dcrImmutableId)}/streams/` +
    `${encodeURIComponent(destination.streamName)}?api-version=2023-01-01`;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let response: Response;
    try {
      response = await fetchImpl(url, {
        method: "POST",
        headers: {
          authorization: `Bearer ${token}`,
          "content-type": "application/json",
          "content-encoding": "gzip",
          "x-ms-client-request-id": randomUUID(),
        },
        body,
        dispatcher,
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
    } catch (error) {
      if (attempt < MAX_ATTEMPTS) {
        await sleep(Math.min(250 * 2 ** (attempt - 1), 2000));
        continue;
      }
      throw new SiemDeliveryError(
        "delivery_error",
        `Azure SIEM delivery failed: ${networkErrorMessage(error)}`,
      );
    }
    if (response.ok) return;

    if (
      (response.status === 429 || response.status >= 500) &&
      attempt < MAX_ATTEMPTS
    ) {
      await waitBeforeRetry(attempt, response, sleep);
      continue;
    }

    const message = await errorText(response);
    if (response.status >= 400 && response.status < 500) {
      throw new SiemDeliveryError(
        response.status === 401 || response.status === 403
          ? "invalid_credentials"
          : response.status === 429
            ? "rate_limited"
            : "schema_rejection",
        `Azure rejected the SIEM event batch: ${message}`,
        response.status,
        retryAfterMs(response),
      );
    }
    throw new SiemDeliveryError(
      "delivery_error",
      `Azure SIEM delivery failed: ${message}`,
      response.status,
    );
  }
}

/**
 * Returns how many events were actually accepted by the destination, which is
 * fewer than `events.length` when any were skipped as undeliverable. Callers
 * must attribute their `delivered` metric to this count, not to what they
 * passed in, or a skipped event gets counted as both dropped and delivered.
 */
export async function sendAzureSentinelEvents(
  destination: AzureSentinelDestination,
  events: ScrapeActivityEvent[],
  deps: SenderDependencies = {},
): Promise<number> {
  if (events.length === 0) return 0;
  let token: string | undefined;
  let delivered = 0;
  for (const { body, eventCount } of buildCompressedBatches(events)) {
    try {
      token ??= await getAccessToken(destination, deps);
      try {
        await sendBatch(destination, token, body, deps);
      } catch (error) {
        if (
          error instanceof SiemDeliveryError &&
          (error.statusCode === 401 || error.statusCode === 403)
        ) {
          invalidateToken(destination);
          token = await getAccessToken(destination, deps);
          await sendBatch(destination, token, body, deps);
        } else {
          throw error;
        }
      }
      delivered += eventCount;
      siemLoggingDeliveryBatchesTotal.inc({ result: "success" });
    } catch (error) {
      if (error instanceof SiemDeliveryError) {
        if (error.statusCode === 401 || error.statusCode === 403) {
          invalidateToken(destination);
        }
        // Tell the caller what already landed, so the chunks Azure accepted
        // aren't counted as failures on the way out.
        error.deliveredEvents = delivered;
      }
      siemLoggingDeliveryBatchesTotal.inc({ result: "failure" });
      throw error;
    }
  }
  return delivered;
}

export function clearAzureTokenCache(): void {
  tokenCache.clear();
}

import { Logger } from "winston";
import { logger as _logger } from "../../lib/logger";
import { config } from "../../config";
import { RateLimiterMode, ScrapeJobData } from "../../types";
import { getACUCTeam } from "../../controllers/auth";
import { orgIdForTeam } from "../../lib/team-org";
import { autumnService } from "../autumn/autumn.service";
import { redisEvictConnection } from "../../services/redis";
import { isSelfHosted } from "../../lib/deployment";
import { getApiKeyConcurrencyLimit } from "../../lib/api-key-concurrency";
import {
  getTeamQueueLimit,
  getConcurrencyLimitActiveJobsCount,
  pushConcurrencyLimitActiveJob,
  removeConcurrencyLimitActiveJob,
} from "../../lib/concurrency-redis";
import {
  NuQJob,
  NuQJobStatus,
  NuQGroupStatus,
  NuQJobGroupInstance,
  scrapeQueue as scrapeQueuePg,
  crawlFinishedQueue as crawlFinishedQueuePg,
  crawlGroup as crawlGroupPg,
} from "./nuq";
import {
  scrapeQueueFdb,
  crawlFinishedQueueFdb,
  crawlGroupFdb,
  externalSlotsFdb,
  isFdbConfigured,
  nuqFdbHealthCheck,
  withFdbTimeout,
  NuQFdbQueue,
  NuQFdbJob,
} from "./nuq-fdb";

// Dual-backend router for the NuQ migration to FoundationDB. Exports the same
// `scrapeQueue` / `crawlFinishedQueue` / `crawlGroup` names as ./nuq so call
// sites only swap their import path. Routing rules:
//  - new crawls: team flag (TeamFlags.nuqFdb) or NUQ_BACKEND=fdb decides; the
//    choice is pinned in StoredCrawl.queueBackend so a crawl never spans
//    backends
//  - reads: stored crawl/job backend markers decide the backend; unmarked jobs
//    default to PG so FDB outages do not affect non-FDB traffic
//  - workers: production workers consume PG and FDB via separate entrypoints;
//    this class still tracks in-flight backend for direct/router test consumers

export type QueueBackend = "pg" | "fdb";

export type { NuQJob, NuQJobStatus, NuQGroupStatus, NuQJobGroupInstance };

export function fdbQueueEnabled(): boolean {
  return isFdbConfigured();
}

function fdbForced(): boolean {
  return config.NUQ_BACKEND === "fdb";
}

const fdbFallbackLastWarn = new Map<string, number>();
const FDB_OPTIONAL_OP_TIMEOUT_MS = 500;

function logFdbFallback(
  logger: Logger,
  operation: string,
  error: unknown,
): void {
  const now = Date.now();
  const lastWarn = fdbFallbackLastWarn.get(operation) ?? 0;
  if (now - lastWarn < 60_000) return;
  fdbFallbackLastWarn.set(operation, now);
  logger.warn("FDB queue operation failed, falling back to PG", {
    module: "nuq-router",
    operation,
    error,
  });
}

async function optionalFdb<T>(operation: () => Promise<T>): Promise<T> {
  if (fdbForced()) return operation();
  if (!(await nuqFdbHealthCheck(FDB_OPTIONAL_OP_TIMEOUT_MS))) {
    throw new Error("FDB health check failed before optional operation");
  }
  return await withFdbTimeout(operation(), FDB_OPTIONAL_OP_TIMEOUT_MS);
}

// Whether NEW work for this team should go to FDB. Existing crawls follow
// their StoredCrawl.queueBackend marker instead.
export async function isFdbTeam(teamId: string | undefined): Promise<boolean> {
  if (!fdbQueueEnabled()) return false;
  if (fdbForced()) return true;
  if (!teamId) return false;
  try {
    const acuc = await getACUCTeam(teamId, false, true, RateLimiterMode.Crawl);
    return acuc?.flags?.nuqFdb === true;
  } catch (error) {
    _logger.warn("Failed to resolve nuqFdb team flag, defaulting to pg", {
      module: "nuq-router",
      teamId,
      error,
    });
    return false;
  }
}

export async function resolveNewGroupBackend(
  teamId: string,
): Promise<QueueBackend> {
  return (await isFdbTeam(teamId)) ? "fdb" : "pg";
}

// Reads only the queueBackend marker off the stored crawl. Deliberately not
// getCrawl() -- importing crawl-redis pulls the whole scraper tree in.
async function getCrawlQueueBackend(
  crawlId: string,
): Promise<QueueBackend | null> {
  if (fdbForced()) return "fdb";
  const raw = await redisEvictConnection.get("crawl:" + crawlId);
  if (!raw) return null;
  try {
    const sc = JSON.parse(raw);
    return sc?.queueBackend === "fdb" ? "fdb" : sc ? "pg" : null;
  } catch {
    return null;
  }
}

async function resolveGroupBackend(
  groupId: string,
  logger: Logger = _logger,
): Promise<QueueBackend> {
  const backend = await getCrawlQueueBackend(groupId);
  if (backend) return backend;
  if (!fdbQueueEnabled()) return "pg";

  try {
    const group = await optionalFdb(() =>
      crawlGroupFdb.getGroup(groupId, logger),
    );
    return group ? "fdb" : "pg";
  } catch (error) {
    if (fdbForced()) throw error;
    logFdbFallback(logger, "resolveGroupBackend", error);
    return "pg";
  }
}

const jobBackendKey = (jobId: string) => `nuq:job_backend:${jobId}`;

async function markJobBackend(
  jobId: string,
  backend: QueueBackend,
): Promise<void> {
  if (fdbForced()) return;
  await redisEvictConnection.set(
    jobBackendKey(jobId),
    backend,
    "EX",
    24 * 60 * 60,
  );
}

async function getJobQueueBackend(jobId: string): Promise<QueueBackend> {
  if (fdbForced()) return "fdb";
  return (await redisEvictConnection.get(jobBackendKey(jobId))) === "fdb"
    ? "fdb"
    : "pg";
}

// Which backend a job belongs to at enqueue time. Crawl jobs follow their
// crawl's pinned backend; standalone jobs follow the team flag.
export async function resolveJobBackend(
  data: ScrapeJobData,
): Promise<QueueBackend> {
  if (!fdbQueueEnabled()) return "pg";
  if (fdbForced()) return "fdb";
  if (data.crawl_id) {
    return (await getCrawlQueueBackend(data.crawl_id)) ?? "pg";
  }
  return (await isFdbTeam(data.team_id)) ? "fdb" : "pg";
}

function tagFdbJob<T extends object>(job: T): T & { backend: "fdb" } {
  (job as any).backend = "fdb";
  return job as T & { backend: "fdb" };
}

// === External capacity holders (browser sessions, sync scrapes)
//
// Non-queue work that occupies team capacity mirrors itself into whichever
// ledger the team runs on. Mismatched acquire/release pairs (flag flipped
// mid-hold) self-heal: Redis entries expire by score, FDB external slots are
// reaped by the sweeper.

export async function mirrorExternalSlotAcquire(
  teamId: string,
  holderId: string,
  ttlMs: number,
): Promise<void> {
  if (await isFdbTeam(teamId)) {
    try {
      await optionalFdb(() =>
        externalSlotsFdb.acquire(teamId, holderId, ttlMs),
      );
      return;
    } catch (error) {
      if (fdbForced()) throw error;
      logFdbFallback(_logger, "mirrorExternalSlotAcquire", error);
    }
  }
  await pushConcurrencyLimitActiveJob(teamId, holderId, ttlMs);
}

export async function mirrorExternalSlotRelease(
  teamId: string,
  holderId: string,
): Promise<void> {
  if (await isFdbTeam(teamId)) {
    try {
      await optionalFdb(() => externalSlotsFdb.release(teamId, holderId));
      return;
    } catch (error) {
      if (fdbForced()) throw error;
      logFdbFallback(_logger, "mirrorExternalSlotRelease", error);
    }
  }
  await removeConcurrencyLimitActiveJob(teamId, holderId);
}

// Active count across both ledgers; a migrating team has load on both while
// its old PG crawls drain.
export async function getCombinedTeamActiveCount(
  teamId: string,
): Promise<number> {
  const redisCount = await getConcurrencyLimitActiveJobsCount(teamId);
  if (!(await isFdbTeam(teamId))) return redisCount;
  try {
    return (
      redisCount +
      (await optionalFdb(() => scrapeQueueFdb.getTeamActiveCount(teamId)))
    );
  } catch (error) {
    if (fdbForced()) throw error;
    logFdbFallback(_logger, "getCombinedTeamActiveCount", error);
    return redisCount;
  }
}

// === FDB enqueue (the whole gating block of queue-jobs collapses into this)

export function backlogTimeoutMsForGate(timeoutMs: number): Date {
  return new Date(Date.now() + timeoutMs);
}

export async function fdbEnqueueScrapeJobs(
  jobs: {
    jobId: string;
    data: ScrapeJobData;
    priority: number;
    listenable?: boolean;
    backlogTimeoutMs: number;
  }[],
  teamId: string,
  options?: { bypassGate?: boolean },
): Promise<{
  jobs: (NuQJob<ScrapeJobData> & { backend: "fdb" })[];
  backloggedCount: number;
  teamLimit: number | null;
}> {
  let teamLimit: number | null = null;
  if (!isSelfHosted()) {
    // The org rides the job payload, snapshotted from the request ACUC at
    // acceptance; every job in a batch is one team's, so any of them answers.
    // The ACUC lookup is the fallback for a job enqueued without one (monitor
    // jobs null the field deliberately — it also gates blocklist enforcement),
    // so a monitor team is still gated on its real limit rather than falling
    // open. Batches are enqueued per discovered link, so the payload org keeps
    // the common path free of a lookup.
    const orgId =
      jobs
        .map(j =>
          "internalOptions" in j.data
            ? (j.data.internalOptions?.orgId ?? null)
            : null,
        )
        .find(o => o !== null) ?? (await orgIdForTeam(teamId));
    const autumnLimit = await autumnService.getConcurrencyLimit(teamId, orgId);
    // fdbForced: leave unlimited (null) when Autumn has no concurrency value.
    teamLimit = fdbForced() ? autumnLimit : (autumnLimit ?? 2);
  }

  const queueCap =
    teamLimit === null ? Number.MAX_SAFE_INTEGER : getTeamQueueLimit(teamLimit);

  // API-key-scoped concurrency: applies when every job in the batch was
  // requested with the same key (batches always are; child jobs inherit the
  // kickoff's apiKeyId) and that key has a limit configured.
  let keyGate: { id: string; limit: number } | null = null;
  if (teamLimit !== null) {
    const keyIds = new Set(jobs.map(j => j.data.apiKeyId ?? null));
    const apiKeyId = keyIds.size === 1 ? [...keyIds][0] : null;
    if (apiKeyId !== null) {
      const keyLimit = await getApiKeyConcurrencyLimit(apiKeyId);
      if (keyLimit !== null) {
        keyGate = { id: String(apiKeyId), limit: keyLimit };
      }
    }
  }

  const results = await optionalFdb(() =>
    scrapeQueueFdb.addJobs(
      jobs.map(j => ({
        id: j.jobId,
        data: j.data,
        options: {
          priority: j.priority,
          listenable: j.listenable ?? false,
          ownerId: j.data.team_id ?? undefined,
          groupId: j.data.crawl_id ?? undefined,
          bypassGate:
            options?.bypassGate ||
            j.data.mode === "kickoff" ||
            j.data.mode === "kickoff_sitemap",
          timesOutAt: new Date(Date.now() + j.backlogTimeoutMs),
        },
      })),
      { teamLimit, queueCap, key: keyGate },
    ),
  );

  const tagged = results.map(r => tagFdbJob(r as NuQJob<ScrapeJobData>));
  const markerResults = await Promise.allSettled(
    tagged.map(job => markJobBackend(job.id, "fdb")),
  );
  const markerFailures = markerResults.filter(
    (r): r is PromiseRejectedResult => r.status === "rejected",
  );
  if (markerFailures.length > 0) {
    _logger.warn("Failed to mark some FDB job backends", {
      module: "nuq-router",
      failed: markerFailures.length,
      total: markerResults.length,
      errors: markerFailures.map(r => r.reason),
    });
  }
  return {
    jobs: tagged,
    backloggedCount: tagged.filter(j => j.status === "backlog").length,
    teamLimit,
  };
}

// === Routed scrape queue

class RoutedScrapeQueue {
  // in-flight jobs taken by THIS process, so renew/finish/fail can route
  private inflightBackend = new Map<string, QueueBackend>();

  private backendFor(id: string): QueueBackend {
    return this.inflightBackend.get(id) ?? "pg";
  }

  public async getJobToProcess(
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData> | null> {
    if (fdbQueueEnabled()) {
      try {
        const job = await optionalFdb(() =>
          scrapeQueueFdb.getJobToProcess(logger),
        );
        if (job) {
          this.inflightBackend.set(job.id, "fdb");
          return tagFdbJob(job as NuQJob<ScrapeJobData>);
        }
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "scrape.getJobToProcess", error);
      }
    }
    const job = await scrapeQueuePg.getJobToProcess();
    if (job) this.inflightBackend.set(job.id, "pg");
    return job;
  }

  public async renewLock(
    id: string,
    lock: string,
    logger: Logger = _logger,
  ): Promise<boolean> {
    if (this.backendFor(id) === "fdb") {
      try {
        return await optionalFdb(() =>
          scrapeQueueFdb.renewLock(id, lock, logger),
        );
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "scrape.renewLock", error);
        return false;
      }
    }
    return scrapeQueuePg.renewLock(id, lock, logger);
  }

  public async jobFinish(
    id: string,
    lock: string,
    returnvalue: any | null,
    logger: Logger = _logger,
  ): Promise<boolean> {
    const backend = this.backendFor(id);
    this.inflightBackend.delete(id);
    if (backend === "fdb") {
      try {
        return await optionalFdb(() =>
          scrapeQueueFdb.jobFinish(id, lock, returnvalue, logger),
        );
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "scrape.jobFinish", error);
        return false;
      }
    }
    return scrapeQueuePg.jobFinish(id, lock, returnvalue, logger);
  }

  public async jobFail(
    id: string,
    lock: string,
    failedReason: string,
    logger: Logger = _logger,
  ): Promise<boolean> {
    const backend = this.backendFor(id);
    this.inflightBackend.delete(id);
    if (backend === "fdb") {
      try {
        return await optionalFdb(() =>
          scrapeQueueFdb.jobFail(id, lock, failedReason, logger),
        );
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "scrape.jobFail", error);
        return false;
      }
    }
    return scrapeQueuePg.jobFail(id, lock, failedReason, logger);
  }

  public async getJob(
    id: string,
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData> | null> {
    if ((await getJobQueueBackend(id)) === "fdb") {
      const job = await optionalFdb(() => scrapeQueueFdb.getJob(id, logger));
      return job ? tagFdbJob(job as NuQJob<ScrapeJobData>) : null;
    }
    return scrapeQueuePg.getJob(id, logger);
  }

  public async getJobs(
    ids: string[],
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData>[]> {
    if (ids.length === 0) return [];
    const backends = await Promise.all(ids.map(id => getJobQueueBackend(id)));
    const fdbIds = ids.filter((_, i) => backends[i] === "fdb");
    const pgIds = ids.filter((_, i) => backends[i] === "pg");
    const [fdbJobs, pgJobs] = await Promise.all([
      fdbIds.length > 0
        ? optionalFdb(() => scrapeQueueFdb.getJobs(fdbIds, logger))
        : Promise.resolve([] as NuQFdbJob<ScrapeJobData>[]),
      pgIds.length > 0
        ? scrapeQueuePg.getJobs(pgIds, logger)
        : Promise.resolve([] as NuQJob<ScrapeJobData>[]),
    ]);
    const byId = new Map<string, NuQJob<ScrapeJobData>>();
    for (const j of fdbJobs)
      byId.set(j.id, tagFdbJob(j as NuQJob<ScrapeJobData>));
    for (const j of pgJobs) byId.set(j.id, j);
    return ids
      .map(id => byId.get(id))
      .filter((j): j is NuQJob<ScrapeJobData> => j !== undefined);
  }

  public async getJobsWithStatus(
    ids: string[],
    status: NuQJobStatus,
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData>[]> {
    return (await this.getJobs(ids, logger)).filter(j => j.status === status);
  }

  public async getJobsWithStatuses(
    ids: string[],
    statuses: NuQJobStatus[],
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData>[]> {
    const set = new Set(statuses);
    return (await this.getJobs(ids, logger)).filter(j => set.has(j.status));
  }

  public async getGroupAnyJob(
    groupId: string,
    ownerId: string,
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData> | null> {
    if ((await resolveGroupBackend(groupId, logger)) === "fdb") {
      const job = await optionalFdb(() =>
        scrapeQueueFdb.getGroupAnyJob(groupId, ownerId, logger),
      );
      return job ? tagFdbJob(job as NuQJob<ScrapeJobData>) : null;
    }
    return scrapeQueuePg.getGroupAnyJob(groupId, ownerId);
  }

  public async getGroupNumericStats(
    groupId: string,
    logger: Logger = _logger,
  ): Promise<Record<NuQJobStatus, number>> {
    if ((await resolveGroupBackend(groupId, logger)) === "fdb") {
      return (await optionalFdb(() =>
        scrapeQueueFdb.getGroupNumericStats(groupId, logger),
      )) as Record<NuQJobStatus, number>;
    }
    return scrapeQueuePg.getGroupNumericStats(groupId, logger);
  }

  public async getGroupJobs(
    groupId: string,
    status: "completed" | "failed",
    limit?: number,
    offset = 0,
    logger: Logger = _logger,
  ): Promise<NuQJob<ScrapeJobData>[]> {
    if ((await resolveGroupBackend(groupId, logger)) === "fdb") {
      const jobs = await optionalFdb(() =>
        scrapeQueueFdb.getGroupJobs(groupId, status, limit, offset, logger),
      );
      return jobs.map(j => tagFdbJob(j as NuQJob<ScrapeJobData>));
    }
    return scrapeQueuePg.getGroupJobs(groupId, status, limit, offset, logger);
  }

  public async removeJob(id: string, logger: Logger = _logger): Promise<void> {
    if ((await getJobQueueBackend(id)) === "fdb") {
      await optionalFdb(() => scrapeQueueFdb.removeJob(id, logger));
      return;
    }
    await scrapeQueuePg.removeJob(id, logger);
  }

  public async removeJobs(
    ids: string[],
    logger: Logger = _logger,
  ): Promise<void> {
    for (const id of ids) {
      await this.removeJob(id, logger);
    }
  }

  public async waitForJob<T = any>(
    id: string,
    timeout: number | null,
    logger: Logger = _logger,
  ): Promise<T> {
    if ((await getJobQueueBackend(id)) === "fdb") {
      // Waiting is intentionally long-lived; callers pass the real scrape
      // timeout. optionalFdb is only for quick FDB reads/writes and applies a
      // 500ms guard, which would incorrectly fail synchronous FDB-backed jobs.
      return scrapeQueueFdb.waitForJob(id, timeout, logger);
    }
    return scrapeQueuePg.waitForJob(id, timeout, logger) as Promise<T>;
  }

  public async getMetrics(logger: Logger = _logger) {
    return scrapeQueuePg.getMetrics();
  }
}

// === Routed crawl-finished queue (worker consumer + reads)

class RoutedCrawlFinishedQueue {
  private inflightBackend = new Map<string, QueueBackend>();

  public async getJobToProcess(
    logger: Logger = _logger,
  ): Promise<NuQJob<any> | null> {
    if (fdbQueueEnabled()) {
      try {
        const job = await optionalFdb(() =>
          crawlFinishedQueueFdb.getJobToProcess(logger),
        );
        if (job) {
          this.inflightBackend.set(job.id, "fdb");
          return tagFdbJob(job as NuQJob<any>);
        }
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "crawlFinished.getJobToProcess", error);
      }
    }
    const job = await crawlFinishedQueuePg.getJobToProcess();
    if (job) this.inflightBackend.set(job.id, "pg");
    return job;
  }

  public async renewLock(
    id: string,
    lock: string,
    logger: Logger = _logger,
  ): Promise<boolean> {
    if (this.inflightBackend.get(id) === "fdb") {
      try {
        return await optionalFdb(() =>
          crawlFinishedQueueFdb.renewLock(id, lock, logger),
        );
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "crawlFinished.renewLock", error);
        return false;
      }
    }
    return crawlFinishedQueuePg.renewLock(id, lock, logger);
  }

  public async jobFinish(
    id: string,
    lock: string,
    returnvalue: any | null,
    logger: Logger = _logger,
  ): Promise<boolean> {
    const backend = this.inflightBackend.get(id) ?? "pg";
    this.inflightBackend.delete(id);
    if (backend === "fdb") {
      try {
        return await optionalFdb(() =>
          crawlFinishedQueueFdb.jobFinish(id, lock, returnvalue, logger),
        );
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "crawlFinished.jobFinish", error);
        return false;
      }
    }
    return crawlFinishedQueuePg.jobFinish(id, lock, returnvalue, logger);
  }

  public async jobFail(
    id: string,
    lock: string,
    failedReason: string,
    logger: Logger = _logger,
  ): Promise<boolean> {
    const backend = this.inflightBackend.get(id) ?? "pg";
    this.inflightBackend.delete(id);
    if (backend === "fdb") {
      try {
        return await optionalFdb(() =>
          crawlFinishedQueueFdb.jobFail(id, lock, failedReason, logger),
        );
      } catch (error) {
        if (fdbForced()) throw error;
        logFdbFallback(logger, "crawlFinished.jobFail", error);
        return false;
      }
    }
    return crawlFinishedQueuePg.jobFail(id, lock, failedReason, logger);
  }

  public async getJob(
    id: string,
    logger: Logger = _logger,
  ): Promise<NuQJob<any> | null> {
    if ((await getJobQueueBackend(id)) === "fdb") {
      const job = await optionalFdb(() =>
        crawlFinishedQueueFdb.getJob(id, logger),
      );
      return job ? tagFdbJob(job as NuQJob<any>) : null;
    }
    return crawlFinishedQueuePg.getJob(id, logger);
  }
}

// === Routed crawl group

class RoutedCrawlGroup {
  public async addGroup(
    id: string,
    ownerId: string,
    ttl?: number,
    opts?: {
      backend?: QueueBackend;
      maxConcurrency?: number;
      delaySeconds?: number;
    },
    logger: Logger = _logger,
  ): Promise<NuQJobGroupInstance> {
    if (opts?.backend === "fdb") {
      const g = await optionalFdb(() =>
        crawlGroupFdb.addGroup(
          id,
          ownerId,
          ttl,
          {
            maxConcurrency: opts.maxConcurrency,
            delaySeconds: opts.delaySeconds,
          },
          logger,
        ),
      );
      return g as NuQJobGroupInstance;
    }
    return crawlGroupPg.addGroup(id, ownerId, ttl, logger);
  }

  public async getGroup(
    id: string,
    logger: Logger = _logger,
  ): Promise<NuQJobGroupInstance | null> {
    if ((await resolveGroupBackend(id, logger)) === "fdb") {
      return (await optionalFdb(() =>
        crawlGroupFdb.getGroup(id, logger),
      )) as NuQJobGroupInstance | null;
    }
    return crawlGroupPg.getGroup(id, logger);
  }

  public async getOngoingByOwner(
    ownerId: string,
    logger: Logger = _logger,
  ): Promise<NuQJobGroupInstance[]> {
    if (!(await isFdbTeam(ownerId))) {
      return crawlGroupPg.getOngoingByOwner(ownerId, logger);
    }
    let fdb: NuQJobGroupInstance[] = [];
    try {
      fdb = (await optionalFdb(() =>
        crawlGroupFdb.getOngoingByOwner(ownerId, logger),
      )) as NuQJobGroupInstance[];
    } catch (error) {
      if (fdbForced()) throw error;
      logFdbFallback(logger, "crawlGroup.getOngoingByOwner", error);
      return crawlGroupPg.getOngoingByOwner(ownerId, logger);
    }
    if (fdbForced()) return fdb as NuQJobGroupInstance[];
    const pg = await crawlGroupPg.getOngoingByOwner(ownerId, logger);
    const seen = new Set(fdb.map(g => g.id));
    return [
      ...(fdb as NuQJobGroupInstance[]),
      ...pg.filter(g => !seen.has(g.id)),
    ];
  }

  // O(1) cancel; only meaningful for FDB groups. PG crawls keep their
  // existing Redis-based cancellation path.
  public async cancelGroup(
    id: string,
    logger: Logger = _logger,
  ): Promise<boolean> {
    if ((await resolveGroupBackend(id, logger)) !== "fdb") return false;
    try {
      return await optionalFdb(() => crawlGroupFdb.cancelGroup(id, logger));
    } catch (error) {
      if (fdbForced()) throw error;
      logFdbFallback(logger, "crawlGroup.cancelGroup", error);
      return false;
    }
  }
}

