import type {
	VerificationClaim,
	WorkflowBuildOutcome,
	WorkflowVerificationEvidence,
} from './workflow-loop-state';
import { deriveVerificationClaim } from '../tools/orchestration/verification/claim';

export function getMultiTriggerCoverage(outcome: WorkflowBuildOutcome | undefined) {
	const progress = outcome?.verificationProgress;
	const triggers = outcome?.triggerNodes ?? [];
	if (!outcome || outcome.executionIntent === 'one-off' || !progress || triggers.length < 2) {
		return undefined;
	}

	const passedTriggers = triggers.filter((trigger) => Object.hasOwn(progress, trigger.nodeName));
	const passes = passedTriggers.flatMap((trigger) => progress[trigger.nodeName]);
	const coveredNodes = new Set(passes.flatMap((pass) => pass.evidence?.nodesExecuted ?? []));
	return {
		passes,
		allTriggersPassed: passedTriggers.length === triggers.length,
		pendingTriggers: triggers
			.filter((trigger) => !Object.hasOwn(progress, trigger.nodeName))
			.map((trigger) => trigger.nodeName),
		nodesNotReached: (outcome.nodeSimulationPlan ?? [])
			.map((node) => node.nodeName)
			.filter((nodeName) => !coveredNodes.has(nodeName)),
	};
}

export function deriveWorkflowVerificationClaim(
	outcome: WorkflowBuildOutcome,
	verification: WorkflowVerificationEvidence & { claim: VerificationClaim },
) {
	const coverage = getMultiTriggerCoverage(outcome);
	if (!coverage) return verification.claim;

	const liveNodes = new Set(
		coverage.passes.flatMap(({ evidence, claim }) => {
			const simulated = new Set([
				...claim.simulatedNodes.map((node) => node.nodeName),
				...claim.pinnedNodes,
			]);
			return (evidence?.nodesExecuted ?? []).filter((name) => !simulated.has(name));
		}),
	);
	// Only successful scoped passes contribute coverage. Keep the latest run's limitations.
	const claims = [...coverage.passes.map((pass) => pass.claim), verification.claim];

	const aggregated = deriveVerificationClaim({
		analysis: {
			success: verification.success,
			nodesNotReached: coverage.nodesNotReached,
			reachedSimulatedNodes: [
				...new Map(
					claims
						.flatMap((claim) => claim.simulatedNodes)
						.filter((node) => !liveNodes.has(node.nodeName))
						.map((node) => [node.nodeName, node]),
				).values(),
			],
			workflowPinnedNodeNames: [...new Set(claims.flatMap((claim) => claim.pinnedNodes))].filter(
				(name) => !liveNodes.has(name),
			),
		},
		plannedNodeCount: outcome.nodeSimulationPlan?.length ?? 0,
		fixTargetNodeNames: claims
			.flatMap((claim) => claim.unprovenTargets)
			.filter((name) => !liveNodes.has(name)),
		pendingTriggers: coverage.pendingTriggers,
	});

	// Publish state belongs to the workflow, not to a trigger, so the latest run
	// carries it. Re-deriving coverage would otherwise drop it and report a
	// stale live version as unknown.
	return {
		...aggregated,
		...(verification.claim.liveState ? { liveState: verification.claim.liveState } : {}),
		...(verification.claim.verifiedVersionId
			? { verifiedVersionId: verification.claim.verifiedVersionId }
			: {}),
	};
}

import { deriveWorkflowVerificationClaim } from '../verification-progress';
import type {
	VerificationClaim,
	WorkflowBuildOutcome,
	WorkflowVerificationEvidence,
} from '../workflow-loop-state';

function makeClaim(overrides: Partial<VerificationClaim> = {}): VerificationClaim {
	return {
		level: 'verified',
		plannedNodeCount: 2,
		reachedNodeCount: 2,
		nodesNotReached: [],
		simulatedNodes: [],
		pinnedNodes: [],
		unprovenTargets: [],
		publishReady: true,
		liveTestRecommended: false,
		...overrides,
	};
}

/** Two triggers, one already passed — the shape that re-derives the claim. */
function makeMultiTriggerOutcome(): WorkflowBuildOutcome {
	return {
		workItemId: 'wi-1',
		taskId: 'task-1',
		workflowId: 'wf-1',
		submitted: true,
		triggerType: 'manual_or_testable',
		executionIntent: 'reusable',
		nodeSimulationPlan: [
			{ nodeName: 'Send Email', verdict: 'live' },
			{ nodeName: 'Log Row', verdict: 'live' },
		],
		triggerNodes: [
			{ nodeName: 'Webhook A', nodeType: 'n8n-nodes-base.webhook' },
			{ nodeName: 'Webhook B', nodeType: 'n8n-nodes-base.webhook' },
		],
		verificationProgress: {
			'Webhook A': [
				{
					attempted: true,
					success: true,
					claim: makeClaim(),
					evidence: { nodesExecuted: ['Send Email'] },
				},
			],
		},
		needsUserInput: false,
		summary: 'built ok',
	} as unknown as WorkflowBuildOutcome;
}

describe('deriveWorkflowVerificationClaim', () => {
	it('keeps the publish state of the latest run when it re-derives coverage', () => {
		// Publish state belongs to the workflow, not to one trigger. Re-deriving
		// from per-trigger coverage would otherwise report a stale live version
		// as unknown, which reads as "no reason to mention production".
		const verification: WorkflowVerificationEvidence & { claim: VerificationClaim } = {
			attempted: true,
			success: true,
			claim: makeClaim({ liveState: 'live-stale', verifiedVersionId: 'draft-2' }),
			evidence: { nodesExecuted: ['Log Row'] },
		};

		const claim = deriveWorkflowVerificationClaim(makeMultiTriggerOutcome(), verification);

		expect(claim.liveState).toBe('live-stale');
		expect(claim.verifiedVersionId).toBe('draft-2');
		// The aggregate still reports the trigger nobody verified.
		expect(claim.pendingTriggers).toEqual(['Webhook B']);
	});

	it('leaves publish state absent when the latest run recorded none', () => {
		const verification: WorkflowVerificationEvidence & { claim: VerificationClaim } = {
			attempted: true,
			success: true,
			claim: makeClaim(),
			evidence: { nodesExecuted: ['Log Row'] },
		};

		const claim = deriveWorkflowVerificationClaim(makeMultiTriggerOutcome(), verification);

		expect(claim.liveState).toBeUndefined();
		expect(claim.verifiedVersionId).toBeUndefined();
	});
});

// Forward mapper: on-disk WorkflowTestCase (data/workflows/*.json) → the body the
// lang-tracer REST `POST /api/v1/cases` (create_test_case) expects. Split from the
// network call so the disk→API key-renaming contract is unit-testable without a server.

import type { CaseSeed, EvalTestCaseInput } from '../harness/schema';
import type { TestCaseCredential } from '../types';

/** One scenario in the create-case payload (`executionScenarios` renamed to `scenarios`). */
export interface LangTracerScenario {
	name: string;
	description?: string;
	dataSetup?: string;
	successCriteria?: string;
	requires?: string;
}

/** Body for `POST /api/v1/cases`. Disk keys are renamed (`complexity`→`evalComplexity`,
 *  `tags`→`evalTags`, `triggerType`→`evalTriggerType`, `executionScenarios`→`scenarios`). */
export interface LangTracerCreateCaseBody {
	name: string;
	setKind: 'regression' | 'capability_gap';
	synthetic: boolean;
	suiteId: number;
	description?: string;
	/** `attach` is declared, not just tolerated: the turn shape is the push contract,
	 *  and leaving it off let a hand-off case type-check while losing its attachment.
	 *  Carrying it end-to-end needs lang-tracer #119 deployed. */
	conversation?: NonNullable<EvalTestCaseInput['conversation']>;
	evalComplexity: 'simple' | 'medium' | 'complex';
	evalTags: string[];
	evalTriggerType?: string;
	scenarios?: LangTracerScenario[];
	processExpectations?: string[];
	outcomeExpectations?: string[];
	datasets?: string[];
	messageBudget?: number;
	/** Forwarded verbatim, so the declared shape has to carry every authored
	 *  field — an understated type silently drops `valid`/`blank` from review. */
	credentials?: TestCaseCredential[];
	/** Inline seed, forwarded as authored — lang-tracer stores it at `metadata.seed`.
	 *  Only the authored arm: a replay seed is derived from a source thread by
	 *  promote/scrub over there, so pushing one would fabricate provenance. */
	seed?: PushableSeed;
	credentialFixture?: string;
}

type InlineSeed = Extract<CaseSeed, { mode: 'inline' }>;

/** The seed as the case-write API takes it: without `folders`. The API's `seed`
 *  is `additionalProperties: false` and has no such key, so the schema default
 *  `[]` alone would fail EVERY seeded push, folder case or not. A non-empty
 *  `folders` never reaches here: `unsupportedPushReason` refuses it. */
export type PushableSeed = Omit<InlineSeed, 'folders'>;

function pushableSeed({ folders: _notStored, ...seed }: InlineSeed): PushableSeed {
	return seed;
}

export interface ToLangTracerOptions {
	suiteId: number;
	setKind: 'regression' | 'capability_gap';
	synthetic: boolean;
}

/** Case content the case-write API can't take. An INLINE seed is pushable — it's a
 *  durable fixture, and the API stores it verbatim — unless it carries a slot the
 *  API's fixed key set lacks (folders, today). A REPLAY seed isn't: it points at
 *  a LangSmith trace that expires, lang-tracer derives it from a source thread it
 *  already holds, and such a case is barred from suites anyway. Returns a
 *  human-readable reason, else null. */
export function unsupportedPushReason(testCase: EvalTestCaseInput): string | null {
	if (testCase.credentials?.some((credential) => credential.description !== undefined)) {
		return 'seeds credential descriptions, which the current LangTracer case-write schema does not store. Keep the case on disk until that contract supports descriptions.';
	}
	if (testCase.promptVersion !== undefined) {
		return 'pins promptVersion, which the current case-write contract does not carry. Keep the case on disk.';
	}
	if (testCase.buildMode !== undefined) {
		return 'pins buildMode, which the current LangTracer write/export contract does not carry. Keep the case on disk until that contract supports the mode.';
	}
	if (testCase.allowUserExecution) {
		return 'enables user execution, which the current LangTracer write/export contract does not carry.';
	}
	const seed = testCase.seed;
	switch (seed?.mode) {
		case undefined:
			return null;
		case 'inline':
			// The write API validates `metadata.seed` against a fixed key set
			// (`additionalProperties: false`). It has no `folders` key, and its
			// `workflows[]` items declare no `parentFolderId`, so a push would either
			// 400 or land the case with the folder stripped and every workflow at the
			// root. A stripped folder case is the worst outcome available: it still
			// runs, the folder never exists, and the agent is graded on finding it.
			// Refuse until lang-tracer carries both.
			if (
				seed.folders.length > 0 ||
				seed.workflows.some((workflow) => workflow.parentFolderId !== undefined)
			) {
				return (
					'seeds folders, which the case-write API does not store yet — pushing it would ' +
					'land the case without its folder (and with every workflow at the project root) ' +
					'and grade the agent on finding a folder that does not exist. Keep it on disk ' +
					'until lang-tracer carries `seed.folders` and `seed.workflows[].parentFolderId`.'
				);
			}
			// `projects` IS stored: the case-write contract (the `create_test_case` tool
			// and `POST /api/v1/cases` share it) declares `seed.projects` with the same
			// rules this schema enforces — unique, trimmed, at most 255 characters, at
			// most 5. The push's own read-back check still catches a deployment that
			// predates it.
			return null;
		case 'replay':
			return (
				'uses a replay seed — reconstructed from a LangSmith trace at run time, so it has no ' +
				'durable home in a suite. Derive a synthetic case from it instead.'
			);
		default: {
			// A new arm must decide its own push-ability here. Approving by default
			// would push the case while `diskCaseToLangTracerCreate` forwards only
			// `inline` — landing it in the suite stripped of its seed.
			const unhandled: never = seed;
			throw new Error(`Unhandled seed mode: ${JSON.stringify(unhandled)}`);
		}
	}
}

/** Map a schema-parsed disk case to a create-case body. `conversation.text` is already
 *  collapsed to a string by the loader schema, so no further normalization is needed. */
export function diskCaseToLangTracerCreate(
	testCase: EvalTestCaseInput,
	fileSlug: string,
	opts: ToLangTracerOptions,
): LangTracerCreateCaseBody {
	const body: LangTracerCreateCaseBody = {
		name: fileSlug,
		setKind: opts.setKind,
		synthetic: opts.synthetic,
		suiteId: opts.suiteId,
		evalComplexity: testCase.complexity,
		evalTags: testCase.tags,
	};

	if (testCase.description !== undefined) body.description = testCase.description;
	if (testCase.conversation !== undefined) body.conversation = testCase.conversation;
	if (testCase.triggerType !== undefined) body.evalTriggerType = testCase.triggerType;
	if (testCase.executionScenarios !== undefined) {
		body.scenarios = testCase.executionScenarios.map(mapScenario);
	}
	if (testCase.processExpectations !== undefined) {
		body.processExpectations = testCase.processExpectations;
	}
	if (testCase.outcomeExpectations !== undefined) {
		body.outcomeExpectations = testCase.outcomeExpectations;
	}
	if (testCase.datasets !== undefined) body.datasets = testCase.datasets;
	if (testCase.messageBudget !== undefined) body.messageBudget = testCase.messageBudget;
	if (testCase.credentials !== undefined) body.credentials = testCase.credentials;
	// Replay never reaches here — `unsupportedPushReason` skips those cases upstream.
	if (testCase.seed?.mode === 'inline') body.seed = pushableSeed(testCase.seed);
	if (testCase.credentialFixture !== undefined) body.credentialFixture = testCase.credentialFixture;

	return body;
}

function mapScenario(scenario: {
	name: string;
	description?: string;
	dataSetup?: string;
	successCriteria?: string;
	requires?: string;
}): LangTracerScenario {
	const mapped: LangTracerScenario = { name: scenario.name };
	if (scenario.description !== undefined) mapped.description = scenario.description;
	if (scenario.dataSetup !== undefined) mapped.dataSetup = scenario.dataSetup;
	if (scenario.successCriteria !== undefined) mapped.successCriteria = scenario.successCriteria;
	if (scenario.requires !== undefined) mapped.requires = scenario.requires;
	return mapped;
}

/**
 * Minimal tracing port. The scheduler stays dependency-light: it depends on this
 * interface, and the host adapts its concrete (Sentry-backed) tracer to it. The
 * status codes match Sentry's span status codes so the host adapter is a
 * pass-through.
 */
export const SpanStatus = { ok: 1, error: 2 } as const;

export interface SpanOptions {
	name: string;
	op?: string;
	attributes?: Record<string, string | number | boolean | undefined>;
	/**
	 * Start a fresh trace instead of parenting under whatever span is active on
	 * the calling async context. Needed when `run` executes on a timer/callback
	 * scheduled from inside another span (e.g. a fire span armed from within the
	 * claim span's tick): without this, the async context still carries the
	 * claim span into the timer callback, so the fire span is parented under a
	 * root that may already have finished and been sent — Sentry drops children
	 * that close after their root is sent.
	 */
	newTrace?: boolean;
}

export interface Span {
	setAttribute(key: string, value: string | number | boolean): void;
	setStatus(status: { code: number; message?: string }): void;
}

export interface Tracer {
	/**
	 * Run `run` inside a span. A throw from `run` marks the span errored (the
	 * concrete tracer does that) and propagates.
	 *
	 * The tracer's own machinery is trusted not to throw before invoking `run`
	 * (same trust model as the scheduler's loop hooks): every pass, fire and
	 * handler run goes through this uncaught, so a throwing host tracer would
	 * take the scheduler down with it.
	 */
	startSpan<T>(options: SpanOptions, run: (span: Span) => Promise<T>): Promise<T>;
}

/** Default tracer: runs the work, records nothing. */
export const noopTracer: Tracer = {
	async startSpan(_options, run) {
		return await run({ setAttribute() {}, setStatus() {} });
	},
};

import { APPROVAL_SUSPEND_SCHEMA, type StreamChunk } from '@n8n/agents';
import {
	instanceAiApprovalDetailsSchema,
	credentialRequestSchema,
	workflowSetupNodeSchema,
	taskListSchema,
	plannedTaskArgSchema,
	gatewayConfirmationRequiredPayloadSchema,
	webSearchMetaSchema,
	channelConfigSchema,
	mcpConnectRequestSchema,
	credentialDestinationSchema,
} from '@n8n/api-types';
import type { InstanceAiEvent } from '@n8n/api-types';
import { isRecord } from '@n8n/utils/is-record';
import { z } from 'zod';

import { isQuotaExhaustedError, QUOTA_EXHAUSTED_ERROR_CODE } from '../utils/quota-error';

export { isQuotaExhaustedError, QUOTA_EXHAUSTED_ERROR_CODE } from '../utils/quota-error';

const questionItemSchema = z.object({
	id: z.string(),
	question: z.string(),
	type: z.enum(['single', 'multi', 'text']),
	options: z.array(z.string()).optional(),
});

function getArrayProperty(record: Record<string, unknown>, key: string): unknown[] | undefined {
	const value = record[key];
	return Array.isArray(value) ? value : undefined;
}

function getRecordProperty(value: unknown, key: string): Record<string, unknown> | undefined {
	if (!isRecord(value)) return undefined;
	const recordValue = value[key];
	return isRecord(recordValue) ? recordValue : undefined;
}

const DEFAULT_TOOL_ERROR_MESSAGE = 'Tool execution failed';

function tryParseJson(text: string): unknown {
	try {
		return JSON.parse(text) as unknown;
	} catch {
		return undefined;
	}
}

function nonEmptyString(value: unknown): string | undefined {
	return typeof value === 'string' && value.trim() ? value : undefined;
}

function extractTextContent(content: unknown[]): string | undefined {
	const text = content
		.flatMap((part) => {
			if (!isRecord(part) || part.type !== 'text') return [];
			const textPart = nonEmptyString(part.text);
			return textPart ? [textPart] : [];
		})
		.join('\n');

	return nonEmptyString(text);
}

function extractToolErrorText(error: unknown): string {
	return extractToolErrorTextInner(error) ?? DEFAULT_TOOL_ERROR_MESSAGE;
}

function extractToolErrorTextInner(error: unknown): string | undefined {
	if (error instanceof Error) return nonEmptyString(error.message);

	if (typeof error === 'string') {
		const parsed = tryParseJson(error);
		if (parsed !== undefined && typeof parsed !== 'string') {
			return extractToolErrorTextInner(parsed) ?? nonEmptyString(error);
		}

		return nonEmptyString(error);
	}

	if (!isRecord(error)) return undefined;

	for (const key of ['error', 'message', 'errorMessage']) {
		const text = nonEmptyString(error[key]);
		if (text) return text;
	}

	const nestedError = getRecordProperty(error, 'error');
	const nestedErrorText = extractToolErrorTextInner(nestedError);
	if (nestedErrorText) return nestedErrorText;

	const structuredContentText = extractToolErrorTextInner(error.structuredContent);
	if (structuredContentText) return structuredContentText;

	const content = getArrayProperty(error, 'content');
	if (content) {
		const contentText = extractTextContent(content);
		if (contentText) return extractToolErrorTextInner(contentText) ?? contentText;
	}

	return extractToolErrorTextInner(error.output);
}

const agentStreamChunkTypes = new Set<string>([
	'finish',
	'text-delta',
	'reasoning-delta',
	'tool-input-start',
	'tool-call',
	'tool-result',
	'error',
	'message',
	'tool-call-suspended',
]);

function isAgentStreamChunk(value: unknown): value is StreamChunk {
	return isRecord(value) && typeof value.type === 'string' && agentStreamChunkTypes.has(value.type);
}

interface ErrorInfo {
	content: string;
	statusCode?: number;
	provider?: string;
	technicalDetails?: string;
	code?: 'quota_exhausted';
}

/** Find an ai-sdk `statusCode` on the error or its `cause` chain, alongside the response body. */
function readStatusCode(error: unknown, visited = new WeakSet<object>()): number | undefined {
	if (typeof error !== 'object' || error === null) return undefined;
	if (visited.has(error)) return undefined;
	visited.add(error);
	if ('statusCode' in error && typeof error.statusCode === 'number') return error.statusCode;
	if ('cause' in error && error.cause !== error) return readStatusCode(error.cause, visited);
	return undefined;
}

/** Find an ai-sdk `responseBody` on the error or its `cause` chain (the API error can arrive wrapped). */
function readResponseBody(error: unknown, visited = new WeakSet<object>()): string | undefined {
	if (typeof error !== 'object' || error === null) return undefined;
	if (visited.has(error)) return undefined;
	visited.add(error);
	if ('responseBody' in error && typeof error.responseBody === 'string') return error.responseBody;
	if ('cause' in error && error.cause !== error) return readResponseBody(error.cause, visited);
	return undefined;
}

/** Parse an ai-sdk JSON `responseBody` into its message and machine-readable code, if present. */
function parseResponseBody(responseBody: string): { message?: string; code?: string } {
	try {
		const body = JSON.parse(responseBody) as {
			message?: string;
			code?: string;
			error?: { message?: string; type?: string };
		};
		return {
			message: body?.error?.message ?? body?.message,
			code: body?.code ?? body?.error?.type,
		};
	} catch {
		return {};
	}
}

function extractErrorInfo(error: unknown): ErrorInfo {
	if (typeof error === 'string') return { content: error };

	if (error instanceof Error) {
		const info: ErrorInfo = { content: error.message };

		// APICallError from ai-sdk carries statusCode and responseBody
		const statusCode = readStatusCode(error);
		if (statusCode !== undefined) {
			info.statusCode = statusCode;
		}

		if ('responseBody' in error && typeof error.responseBody === 'string') {
			info.technicalDetails = error.responseBody;
			const { message } = parseResponseBody(error.responseBody);
			if (message) info.content = message;
		} else {
			// No direct responseBody — unwrap the cause chain (mirrors `readErrorCode`).
			const wrappedBody = readResponseBody(error.cause);
			if (wrappedBody) {
				info.technicalDetails = wrappedBody;
				const { message } = parseResponseBody(wrappedBody);
				if (message) info.content = message;
			}
		}

		// Extract provider from error name or URL if available
		if ('url' in error && typeof error.url === 'string') {
			const urlStr = error.url;
			if (urlStr.includes('anthropic')) info.provider = 'Anthropic';
			else if (urlStr.includes('openai')) info.provider = 'OpenAI';
		}

		if (isQuotaExhaustedError(error)) info.code = QUOTA_EXHAUSTED_ERROR_CODE;

		return info;
	}

	if (isRecord(error)) {
		if (error.type === 'overloaded_error') {
			return { content: 'The model is overloaded. Try again in a few minutes.' };
		}

		const message = nonEmptyString(error.message);
		if (message) return { content: message };
	}

	return { content: 'Unknown error' };
}

type EventBase = { runId: string; agentId: string; responseId?: string };

type ConfirmationInputType =
	| 'approval'
	| 'text'
	| 'questions'
	| 'plan-review'
	| 'resource-decision'
	| 'continue';

/** A non-empty string, or undefined for anything else (matches the legacy `value ? value : undefined` gate). */
function presentString(value: unknown): string | undefined {
	return typeof value === 'string' && value ? value : undefined;
}

function parseSchemaArray<T>(value: unknown, schema: z.ZodType<T>): T[] | undefined {
	if (!Array.isArray(value)) return undefined;
	const parsed = value
		.map((item) => schema.safeParse(item))
		.filter((r) => r.success)
		.map((r) => r.data);
	return parsed.length > 0 ? parsed : undefined;
}

function parseSchemaRecord<T>(value: unknown, schema: z.ZodType<T>): T | undefined {
	if (!isRecord(value)) return undefined;
	const parsed = schema.safeParse(value);
	return parsed.success ? parsed.data : undefined;
}

function parseSeverity(value: unknown): 'destructive' | 'warning' | 'info' {
	const raw = typeof value === 'string' ? value : '';
	const valid = ['destructive', 'warning', 'info'] as const;
	return (valid as readonly string[]).includes(raw) ? (raw as (typeof valid)[number]) : 'warning';
}

function parseInputType(value: unknown): ConfirmationInputType | undefined {
	const raw = typeof value === 'string' ? value : undefined;
	const valid = [
		'approval',
		'text',
		'questions',
		'plan-review',
		'resource-decision',
		'continue',
	] as const;
	return (valid as readonly string[]).includes(raw ?? '')
		? (raw as (typeof valid)[number])
		: undefined;
}

function parseDomainAccess(value: unknown): { url: string; host: string } | undefined {
	const raw = isRecord(value) ? value : undefined;
	return raw && typeof raw.url === 'string' && typeof raw.host === 'string'
		? { url: raw.url, host: raw.host }
		: undefined;
}

function parseCredentialFlow(value: unknown): { stage: 'generic' | 'finalize' } | undefined {
	const raw = isRecord(value) ? value : undefined;
	const validStages = new Set<'generic' | 'finalize'>(['generic', 'finalize']);
	const stage = raw && typeof raw.stage === 'string' ? raw.stage : undefined;
	return stage !== undefined && validStages.has(stage as 'generic' | 'finalize')
		? { stage: stage as 'generic' | 'finalize' }
		: undefined;
}

function mapToolCallChunk(
	chunk: Extract<StreamChunk, { type: 'tool-call' }>,
	base: EventBase,
): InstanceAiEvent {
	return {
		type: 'tool-call',
		...base,
		payload: {
			toolCallId: chunk.toolCallId,
			toolName: chunk.toolName,
			args: isRecord(chunk.input) ? chunk.input : {},
		},
	};
}

function mapToolResultChunk(
	chunk: Extract<StreamChunk, { type: 'tool-result' }>,
	base: EventBase,
): InstanceAiEvent {
	if (chunk.isError === true) {
		return {
			type: 'tool-error',
			...base,
			payload: { toolCallId: chunk.toolCallId, error: extractToolErrorText(chunk.output) },
		};
	}

	return {
		type: 'tool-result',
		...base,
		payload: { toolCallId: chunk.toolCallId, result: chunk.output },
	};
}

function mapSuspendedChunk(
	chunk: Extract<StreamChunk, { type: 'tool-call-suspended' }>,
	base: EventBase,
): InstanceAiEvent | null {
	const suspendPayload = isRecord(chunk.suspendPayload) ? chunk.suspendPayload : {};
	const toolCallId = typeof chunk.toolCallId === 'string' ? chunk.toolCallId : '';
	const requestId =
		typeof suspendPayload.requestId === 'string' && suspendPayload.requestId
			? suspendPayload.requestId
			: toolCallId;

	if (!requestId || !toolCallId) return null;

	const credentialRequests = parseSchemaArray(
		suspendPayload.credentialRequests,
		credentialRequestSchema,
	);
	const requireUserSelection = suspendPayload.requireUserSelection === true;
	const projectId = presentString(suspendPayload.projectId);
	const inputType = parseInputType(suspendPayload.inputType);
	const questions = parseSchemaArray(suspendPayload.questions, questionItemSchema);
	const introMessage = presentString(suspendPayload.introMessage);
	const tasks = parseSchemaRecord(suspendPayload.tasks, taskListSchema);
	const planItems = parseSchemaArray(suspendPayload.planItems, plannedTaskArgSchema);
	const domainAccess = parseDomainAccess(suspendPayload.domainAccess);
	const webSearch = parseSchemaRecord(suspendPayload.webSearch, webSearchMetaSchema);
	const credentialFlow = parseCredentialFlow(suspendPayload.credentialFlow);
	const credentialDestination = parseSchemaRecord(
		suspendPayload.credentialDestination,
		credentialDestinationSchema,
	);
	const setupRequests = parseSchemaArray(suspendPayload.setupRequests, workflowSetupNodeSchema);
	const workflowId = presentString(suspendPayload.workflowId);
	const resourceName = presentString(suspendPayload.resourceName);
	const approvalDetails = parseSchemaRecord(
		suspendPayload.approvalDetails,
		instanceAiApprovalDetailsSchema,
	);
	const resourceDecision = parseSchemaRecord(
		suspendPayload.resourceDecision,
		gatewayConfirmationRequiredPayloadSchema,
	);
	const channelConfig = parseSchemaRecord(suspendPayload.channelConfig, channelConfigSchema);
	const mcpConnectRequest = parseSchemaRecord(
		suspendPayload.mcpConnectRequest,
		mcpConnectRequestSchema,
	);
	const targetApprovalResult = isRecord(suspendPayload.builderCheckpoint)
		? APPROVAL_SUSPEND_SCHEMA.safeParse(suspendPayload)
		: undefined;
	const targetApproval = targetApprovalResult?.success
		? {
				toolName: targetApprovalResult.data.toolName,
				...(targetApprovalResult.data.displayName
					? { displayName: targetApprovalResult.data.displayName }
					: {}),
				args: targetApprovalResult.data.args,
			}
		: undefined;

	return {
		type: 'confirmation-request',
		...base,
		payload: {
			requestId,
			toolCallId,
			toolName: typeof chunk.toolName === 'string' ? chunk.toolName : '',
			args: isRecord(chunk.input) ? chunk.input : {},
			severity: parseSeverity(suspendPayload.severity),
			message:
				typeof suspendPayload.message === 'string'
					? suspendPayload.message
					: 'Confirmation required',
			...(targetApproval ? { targetApproval } : {}),
			...(credentialRequests ? { credentialRequests } : {}),
			...(requireUserSelection ? { requireUserSelection } : {}),
			...(projectId ? { projectId } : {}),
			...(inputType ? { inputType } : {}),
			...(domainAccess ? { domainAccess } : {}),
			...(webSearch ? { webSearch } : {}),
			...(credentialFlow ? { credentialFlow } : {}),
			...(credentialDestination ? { credentialDestination } : {}),
			...(setupRequests ? { setupRequests } : {}),
			...(workflowId ? { workflowId } : {}),
			...(resourceName ? { resourceName } : {}),
			...(approvalDetails ? { approvalDetails } : {}),
			...(questions ? { questions } : {}),
			...(introMessage ? { introMessage } : {}),
			...(tasks ? { tasks } : {}),
			...(planItems ? { planItems } : {}),
			...(resourceDecision ? { resourceDecision } : {}),
			...(channelConfig ? { channelConfig } : {}),
			...(mcpConnectRequest ? { mcpConnectRequest } : {}),
		},
	};
}

function toolCallFromContent(part: unknown, base: EventBase): InstanceAiEvent | null {
	if (!isRecord(part) || part.type !== 'tool-call') return null;
	return {
		type: 'tool-call',
		...base,
		payload: {
			toolCallId: typeof part.toolCallId === 'string' ? part.toolCallId : '',
			toolName: typeof part.toolName === 'string' ? part.toolName : '',
			args: isRecord(part.input) ? part.input : {},
		},
	};
}

function toolResultFromContent(part: unknown, base: EventBase): InstanceAiEvent | null {
	if (!isRecord(part) || part.type !== 'tool-result') return null;
	const toolCallId = typeof part.toolCallId === 'string' ? part.toolCallId : '';
	if (part.isError === true) {
		return {
			type: 'tool-error',
			...base,
			payload: { toolCallId, error: extractToolErrorText(part.result) },
		};
	}
	return {
		type: 'tool-result',
		...base,
		payload: { toolCallId, result: part.result },
	};
}

function mapMessageChunk(
	chunk: Extract<StreamChunk, { type: 'message' }>,
	base: EventBase,
): InstanceAiEvent | null {
	const message = getRecordProperty(chunk, 'message');
	if (message?.role !== 'tool') return null;

	const content = getArrayProperty(message, 'content');
	if (!content) return null;

	const toolCall = toolCallFromContent(
		content.find((part) => isRecord(part) && part.type === 'tool-call'),
		base,
	);
	if (toolCall) return toolCall;

	return toolResultFromContent(
		content.find((part) => isRecord(part) && part.type === 'tool-result'),
		base,
	);
}

function mapErrorChunk(
	chunk: Extract<StreamChunk, { type: 'error' }>,
	base: EventBase,
): InstanceAiEvent {
	const errorInfo = extractErrorInfo(chunk.error);
	return {
		type: 'error',
		...base,
		payload: {
			content: errorInfo.content,
			...(errorInfo.statusCode !== undefined ? { statusCode: errorInfo.statusCode } : {}),
			...(errorInfo.code ? { code: errorInfo.code } : {}),
			...(errorInfo.provider ? { provider: errorInfo.provider } : {}),
			...(errorInfo.technicalDetails ? { technicalDetails: errorInfo.technicalDetails } : {}),
		},
	};
}

export function mapAgentChunkToEvent(
	runId: string,
	agentId: string,
	chunk: unknown,
	responseId?: string,
): InstanceAiEvent | null {
	if (!isAgentStreamChunk(chunk)) return null;

	const base: EventBase = { runId, agentId, ...(responseId ? { responseId } : {}) };

	switch (chunk.type) {
		case 'text-delta':
			return { type: 'text-delta', ...base, payload: { text: chunk.delta } };
		case 'reasoning-delta':
			return { type: 'reasoning-delta', ...base, payload: { text: chunk.delta } };
		case 'tool-input-start':
			// Surfaces the pending tool call while its arguments stream — the
			// full `tool-call` event follows once the args are complete.
			return {
				type: 'tool-input-start',
				...base,
				payload: { toolCallId: chunk.toolCallId, toolName: chunk.toolName },
			};
		case 'tool-call':
			return mapToolCallChunk(chunk, base);
		case 'tool-result':
			return mapToolResultChunk(chunk, base);
		case 'tool-call-suspended':
			return mapSuspendedChunk(chunk, base);
		case 'message':
			return mapMessageChunk(chunk, base);
		case 'error':
			return mapErrorChunk(chunk, base);
		default:
			return null;
	}
}

import {
	ContextEstablishmentHook,
	ContextEstablishmentOptions,
	ContextEstablishmentResult,
	HookDescription,
	IContextEstablishmentHook,
} from '@n8n/decorators';

import { HttpHeaderExtractor } from './http-header-extractor';

/**
 * Extracts bearer tokens from the Authorization HTTP header.
 *
 * Automatically extracts tokens from headers in the format:
 * - `Authorization: Bearer <token>`
 * - Case-insensitive "Bearer" prefix
 *
 * The extracted token becomes the credential identity for OAuth2 introspection.
 *
 * @example
 * // Request header:
 * // Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...
 *
 * // Result:
 * // context.credentials.identity = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
 */
@ContextEstablishmentHook()
export class BearerTokenExtractor implements IContextEstablishmentHook {
	constructor(private readonly httpHeaderExtractor: HttpHeaderExtractor) {}

	hookDescription: HookDescription = {
		name: 'BearerTokenExtractor',
		displayName: 'Bearer Token Extractor',
		options: [],
	};

	isApplicableToTriggerNode(nodeType: string): boolean {
		return this.httpHeaderExtractor.isApplicableToTriggerNode(nodeType);
	}

	async execute(options: ContextEstablishmentOptions): Promise<ContextEstablishmentResult> {
		return await this.httpHeaderExtractor.execute({
			...options,
			options: {
				headerName: 'authorization',
				headerValue: '[Bb][Ee][Aa][Rr][Ee][Rr]\\s+(.+)',
			},
		});
	}
}

import { baseUrl, getJson } from '../request';
import type { ListModelsFn } from '../types';

/** Source: LMChatAnthropic `methods/searchModels.ts` (GET /v1/models, newest first). */
export const listAnthropicModels: ListModelsFn = async (options) => {
	const data = (await getJson(
		`${baseUrl(options, 'https://api.anthropic.com')}/v1/models`,
		{ 'x-api-key': options.apiKey, 'anthropic-version': '2023-06-01' },
		options,
		'anthropic',
	)) as { data?: Array<{ id: string; display_name?: string; created_at?: string }> };

	return (data.data ?? [])
		.slice()
		.sort((a, b) => new Date(b.created_at ?? 0).getTime() - new Date(a.created_at ?? 0).getTime())
		.map((model) => ({ id: model.id, name: model.display_name ?? model.id }));
};

