package dynamicconfig

import (
	"fmt"
	"reflect"
	"strings"

	enumspb "go.temporal.io/api/enums/v1"
	enumsspb "go.temporal.io/server/api/enums/v1"
	"go.temporal.io/server/common/log"
)

// DiffAndLogConfigs computes the difference between two ConfigValueMaps. The result is
// returned as a ConfigValueMap that can be merged with old to produce new, except with deleted
// keys mapped to nil. It also logs the differences to a logger.
func DiffAndLogConfigs(logger log.Logger, oldValues ConfigValueMap, newValues ConfigValueMap) ConfigValueMap {
	changedMap := make(map[Key][]ConstrainedValue)

	for key, newValues := range newValues {
		oldValues, ok := oldValues[key]
		if !ok {
			for _, newValue := range newValues {
				// new key added
				diffAndLogValue(logger, key, nil, &newValue)
			}
			changedMap[Key(key)] = newValues
		} else {
			// compare existing keys
			changed := diffAndLogConstraints(logger, key, oldValues, newValues)
			if changed {
				changedMap[Key(key)] = newValues
			}
		}
	}

	// check for removed values
	for key, oldValues := range oldValues {
		if _, ok := newValues[key]; !ok {
			for _, oldValue := range oldValues {
				diffAndLogValue(logger, key, &oldValue, nil)
			}
			changedMap[Key(key)] = nil
		}
	}

	return changedMap
}

func diffAndLogConstraints(logger log.Logger, key Key, oldValues []ConstrainedValue, newValues []ConstrainedValue) bool {
	changed := false
	for _, oldValue := range oldValues {
		matchFound := false
		for _, newValue := range newValues {
			if oldValue.Constraints == newValue.Constraints {
				matchFound = true
				if !reflect.DeepEqual(oldValue.Value, newValue.Value) {
					diffAndLogValue(logger, key, &oldValue, &newValue)
					changed = true
				}
			}
		}
		if !matchFound {
			diffAndLogValue(logger, key, &oldValue, nil)
			changed = true
		}
	}

	for _, newValue := range newValues {
		matchFound := false
		for _, oldValue := range oldValues {
			if oldValue.Constraints == newValue.Constraints {
				matchFound = true
			}
		}
		if !matchFound {
			diffAndLogValue(logger, key, nil, &newValue)
			changed = true
		}
	}
	return changed
}

func diffAndLogValue(logger log.Logger, key Key, oldValue *ConstrainedValue, newValue *ConstrainedValue) {
	logLine := &strings.Builder{}
	logLine.Grow(128)
	logLine.WriteString("dynamic config changed for the key: ")
	logLine.WriteString(key.String())
	logLine.WriteString(" oldValue: ")
	appendConstrainedValue(logLine, oldValue)
	logLine.WriteString(" newValue: ")
	appendConstrainedValue(logLine, newValue)
	logger.Info(logLine.String())
}

func appendConstrainedValue(logLine *strings.Builder, value *ConstrainedValue) {
	if value == nil {
		logLine.WriteString("nil")
	} else {
		logLine.WriteString("{ constraints: {")
		if value.Constraints.Namespace != "" {
			fmt.Fprintf(logLine, "{Namespace:%s}", value.Constraints.Namespace)
		}
		if value.Constraints.NamespaceID != "" {
			fmt.Fprintf(logLine, "{NamespaceID:%s}", value.Constraints.NamespaceID)
		}
		if value.Constraints.TaskQueueName != "" {
			fmt.Fprintf(logLine, "{TaskQueueName:%s}", value.Constraints.TaskQueueName)
		}
		if value.Constraints.TaskQueueType != enumspb.TASK_QUEUE_TYPE_UNSPECIFIED {
			fmt.Fprintf(logLine, "{TaskQueueType:%s}", value.Constraints.TaskQueueType)
		}
		if value.Constraints.ShardID != 0 {
			fmt.Fprintf(logLine, "{ShardID:%d}", value.Constraints.ShardID)
		}
		if value.Constraints.TaskType != enumsspb.TASK_TYPE_UNSPECIFIED {
			fmt.Fprintf(logLine, "{HistoryTaskType:%s}", value.Constraints.TaskType)
		}
		if value.Constraints.Destination != "" {
			fmt.Fprintf(logLine, "{Destination:%s}", value.Constraints.Destination)
		}
		fmt.Fprint(logLine, "} value: ", value.Value, " }")
	}
}

package nexus

import (
	"github.com/nexus-rpc/sdk-go/nexus"
	commonpb "go.temporal.io/api/common/v1"
	failurepb "go.temporal.io/api/failure/v1"
	nexuspb "go.temporal.io/api/nexus/v1"
	"go.temporal.io/server/api/matchingservice/v1"
	"go.temporal.io/server/common/metrics"
)

// DispatchOutcome names the arm of matching's DispatchNexusTaskResponse that came back from a
// DispatchNexusTask call. The nested oneofs and the deprecated variants collapse into one flat set of
// cases. (Including those from a worker sending the deprecated failure responses, those will get
// silently converted into the newer forms.)
//
// The zero value is the empty string and is not a valid outcome, so a switch over a DispatchOutcome
// needs a default clause. For metric tags use DispatchResult.OutcomeTag, not the string value.
type DispatchOutcome string

const (
	// DispatchOutcomeUnrecognized is a response this build cannot interpret: no outcome set, an
	// outcome variant added after this build, or a worker answer that carries nothing usable.
	DispatchOutcomeUnrecognized DispatchOutcome = "unrecognized-outcome"

	// DispatchOutcomeSyncSuccess means the worker ran the operation to completion inline.
	DispatchOutcomeSyncSuccess DispatchOutcome = "sync-success"

	// DispatchOutcomeAsyncSuccess means the worker started the operation; the result arrives later,
	// out of band.
	DispatchOutcomeAsyncSuccess DispatchOutcome = "async-success"

	// DispatchOutcomeCancelAccepted means the worker accepted the cancellation request.
	DispatchOutcomeCancelAccepted DispatchOutcome = "cancel-accepted"

	// DispatchOutcomeOperationFailure means the worker ran the operation and it resolved as failed
	// or canceled. The task was delivered and answered; just the operation itself did not succeed.
	//
	// e.g. the Nexus handler fails with:
	//     nexus.NewOperationFailedError("insufficient funds")
	//     nexus.NewOperationCanceledError("already canceled upstream")
	DispatchOutcomeOperationFailure DispatchOutcome = "operation-failure"

	// DispatchOutcomeHandlerFailure means the worker answered with a Nexus handler error, whose retry
	// behavior says whether another attempt is worthwhile. The handler can return one itself, or the
	// worker can fail the task before the handler runs.
	//
	// e.g.
	//     nexus.NewHandlerErrorf(nexus.HandlerErrorTypeNotFound, "no such workflow")
	//     nexus.NewHandlerErrorf(nexus.HandlerErrorTypeBadRequest, "cannot deserialize input")
	DispatchOutcomeHandlerFailure DispatchOutcome = "nexus-handler-failure"

	// DispatchOutcomeRequestTimeout means matching gave up before the task was answered: no worker
	// was polling the task queue, or a worker took the task and never responded.
	DispatchOutcomeRequestTimeout DispatchOutcome = "request-timeout"
)

// Succeeded reports whether the worker accepted the request. An asynchronous start counts: the worker
// took responsibility for the operation, even though it has not finished it.
func (o DispatchOutcome) Succeeded() bool {
	switch o {
	case DispatchOutcomeSyncSuccess, DispatchOutcomeAsyncSuccess, DispatchOutcomeCancelAccepted:
		return true
	default:
		return false
	}
}

// DispatchResult is the classified form of a DispatchNexusTaskResponse: the outcome, plus whatever
// that arm of the response carried, hoisted out of the nested oneofs.
type DispatchResult struct {
	Outcome DispatchOutcome

	// OperationResult is the operation's result. Set for DispatchOutcomeSyncSuccess, where it may still
	// be nil: an operation is allowed to succeed with no value.
	OperationResult *commonpb.Payload

	// OperationToken is set for DispatchOutcomeAsyncSuccess.
	OperationToken string

	// Links are the handler links the worker attached to a successful start. Set for
	// DispatchOutcomeSyncSuccess and DispatchOutcomeAsyncSuccess.
	Links []*nexuspb.Link

	// Failure is the Temporal failure the worker reported. Set for DispatchOutcomeHandlerFailure
	// and DispatchOutcomeOperationFailure.
	//
	// IMPORTANT: For the current response formats this aliases the proto inside the response rather
	// than copying it, so callers that convert it in place mutate the response too.
	Failure *failurepb.Failure

	// usedDeprecatedFormat records that the worker answered in a format predating Temporal failure
	// responses. Outcome and Failure are normalized either way; only the metric tag differs.
	usedDeprecatedFormat bool
}

// baseClassifyDispatchNexusTaskResponse converts a DispatchNexusTaskResponse into a DispatchResult.
//
// onResponseFn classifies a Response outcome. The DispatchNexusTaskResponse proto is shared by every
// kind of Nexus task, so only the caller knows how to interpret a succesful response.
func baseClassifyDispatchNexusTaskResponse(
	resp *matchingservice.DispatchNexusTaskResponse,
	onResponseFn func(*nexuspb.StartOperationResponse) DispatchResult,
) DispatchResult {
	switch t := resp.GetOutcome().(type) {
	case *matchingservice.DispatchNexusTaskResponse_Failure:
		// A handler error is a Nexus-level refusal whose retry behavior is meaningful; anything else
		// is an arbitrary failure the worker chose to report.
		return DispatchResult{Outcome: DispatchOutcomeHandlerFailure, Failure: t.Failure}

	case *matchingservice.DispatchNexusTaskResponse_HandlerError: //nolint:staticcheck // Deprecated, still sent by older workers.
		return DispatchResult{
			Outcome: DispatchOutcomeHandlerFailure,
			//nolint:staticcheck // Deprecated field on a deprecated variant.
			Failure:              deprecatedHandlerErrorToFailure(t.HandlerError),
			usedDeprecatedFormat: true,
		}

	case *matchingservice.DispatchNexusTaskResponse_RequestTimeout:
		return DispatchResult{Outcome: DispatchOutcomeRequestTimeout}

	case *matchingservice.DispatchNexusTaskResponse_Response:
		// Only the caller knows how to interpret a successful response, so defer to onResponseFn.
		return onResponseFn(t.Response.GetStartOperation())

	default:
		return DispatchResult{Outcome: DispatchOutcomeUnrecognized}
	}
}

// classifyStartOperationResponse classifies the response a worker gave to a StartOperation request.
func classifyStartOperationResponse(resp *nexuspb.StartOperationResponse) DispatchResult {
	switch t := resp.GetVariant().(type) {
	case *nexuspb.StartOperationResponse_SyncSuccess:
		return DispatchResult{
			Outcome:         DispatchOutcomeSyncSuccess,
			OperationResult: t.SyncSuccess.GetPayload(),
			Links:           t.SyncSuccess.GetLinks(),
		}

	case *nexuspb.StartOperationResponse_AsyncSuccess:
		token := t.AsyncSuccess.GetOperationToken()
		if token == "" {
			// Workers predating the operation-token rename only set the operation ID.
			//nolint:staticcheck // Deprecated, still sent by older workers.
			token = t.AsyncSuccess.GetOperationId()
		}
		return DispatchResult{
			Outcome:        DispatchOutcomeAsyncSuccess,
			OperationToken: token,
			Links:          t.AsyncSuccess.GetLinks(),
		}

	case *nexuspb.StartOperationResponse_Failure:
		return DispatchResult{
			Outcome: DispatchOutcomeOperationFailure,
			Failure: t.Failure,
		}

	case *nexuspb.StartOperationResponse_OperationError: //nolint:staticcheck // Deprecated, still sent by older workers.
		return DispatchResult{
			Outcome: DispatchOutcomeOperationFailure,
			//nolint:staticcheck // Deprecated field on a deprecated variant.
			Failure:              deprecatedOperationErrorToFailure(t.OperationError),
			usedDeprecatedFormat: true,
		}

	default:
		return DispatchResult{Outcome: DispatchOutcomeUnrecognized}
	}
}

// ClassifyStartOperationDispatch classifies matching's response to a dispatched StartOperation task.
func ClassifyStartOperationDispatch(resp *matchingservice.DispatchNexusTaskResponse) DispatchResult {
	return baseClassifyDispatchNexusTaskResponse(resp, classifyStartOperationResponse)
}

// ClassifyCancelOperationDispatch classifies matching's response to a dispatched CancelOperation task.
func ClassifyCancelOperationDispatch(resp *matchingservice.DispatchNexusTaskResponse) DispatchResult {
	return baseClassifyDispatchNexusTaskResponse(
		resp,
		func(*nexuspb.StartOperationResponse) DispatchResult {
			// A cancel response carries no fields, so any response means the worker accepted.
			return DispatchResult{Outcome: DispatchOutcomeCancelAccepted}
		})
}

// deprecatedHandlerErrorToFailure converts the deprecated nexuspb.HandlerError into the new format,
// a Temporal failurepb.Failure.
func deprecatedHandlerErrorToFailure(handlerErr *nexuspb.HandlerError) *failurepb.Failure {
	failure := &failurepb.Failure{
		FailureInfo: &failurepb.Failure_NexusHandlerFailureInfo{
			NexusHandlerFailureInfo: &failurepb.NexusHandlerFailureInfo{
				Type:          handlerErr.GetErrorType(),
				RetryBehavior: handlerErr.GetRetryBehavior(),
			},
		},
	}
	if handlerErr.GetFailure() != nil {
		failure.Cause = convertNexusFailureToTemporalFailure(handlerErr.GetFailure())
	}
	return failure
}

// deprecatedOperationErrorToFailure converts the deprecated nexuspb.UnsuccessfulOperationError into
// the new format, a Temporal failurepb.Failure proto.
//
// The deprecated variant reports the operation state in a field of its own and sends the handler's
// failure bare. The current format has no state field: the failure that wraps the handler's failure is
// what reports the state, canceled or failed. So the wrapper is rebuilt here from the state field.
// Workers converting in the other direction drop the wrapper and keep its cause.
func deprecatedOperationErrorToFailure(opErr *nexuspb.UnsuccessfulOperationError) *failurepb.Failure {
	cause := convertNexusFailureToTemporalFailure(opErr.GetFailure())
	// The deprecated variant carries no message of its own, so the wrapper repeats the cause's.
	failure := &failurepb.Failure{Message: cause.GetMessage(), Cause: cause}

	if nexus.OperationState(opErr.GetOperationState()) == nexus.OperationStateCanceled {
		failure.FailureInfo = &failurepb.Failure_CanceledFailureInfo{
			CanceledFailureInfo: &failurepb.CanceledFailureInfo{},
		}
	} else {
		failure.FailureInfo = &failurepb.Failure_ApplicationFailureInfo{
			ApplicationFailureInfo: &failurepb.ApplicationFailureInfo{
				Type:         "OperationError",
				NonRetryable: true,
			},
		}
	}
	return failure
}

// convertNexusFailureToTemporalFailure converts the deprecated nexuspb.Failure into the new format,
// a Temporal failurepb.Failure.
func convertNexusFailureToTemporalFailure(nexusFailure *nexuspb.Failure) *failurepb.Failure {
	//nolint:staticcheck // Deprecated function still in use for backward compatibility.
	converted, err := NexusFailureToTemporalFailure(ProtoFailureToNexusFailure(nexusFailure))
	// A failure that cannot be re-encoded falls back to its message. We know the operation failed,
	// we just don't recognize the format of the data in its cause/details.
	if err != nil {
		return &failurepb.Failure{
			Message: nexusFailure.GetMessage(),
			FailureInfo: &failurepb.Failure_ApplicationFailureInfo{
				ApplicationFailureInfo: &failurepb.ApplicationFailureInfo{
					Type:         "NexusFailure",
					NonRetryable: false,
				},
			},
		}
	}
	return converted
}

// OutcomeTag returns the metrics outcome tag for a dispatch.
//
// A handler failure reports its error type as the tag's suffix. A type outside the Nexus spec, or a
// failure with no type at all, reports "handler_error:UNKNOWN" so that a worker cannot mint new time
// series.
func (r DispatchResult) OutcomeTag() metrics.Tag {
	return metrics.OutcomeTag(r.metricOutcome())
}

func (r DispatchResult) metricOutcome() string {
	// NOTE: Some of these are confusing (e.g. "success" for CancelAccepted), but
	// changing these would break existing dashboards.
	switch r.Outcome {
	case DispatchOutcomeSyncSuccess:
		return "sync_success"
	case DispatchOutcomeAsyncSuccess:
		return "async_success"
	case DispatchOutcomeCancelAccepted:
		return "success"
	case DispatchOutcomeOperationFailure:
		if r.usedDeprecatedFormat {
			return "operation_error"
		}
		return "failure"
	case DispatchOutcomeHandlerFailure:
		// A worker failure has no handler error type to report and will map to UNKNOWN.
		hErrType := r.Failure.GetNexusHandlerFailureInfo().GetType()
		return "handler_error:" + BoundHandlerErrorType(hErrType)
	case DispatchOutcomeRequestTimeout:
		return "handler_timeout"
	case DispatchOutcomeUnrecognized:
		fallthrough
	default:
		return "handler_error:EMPTY_OUTCOME"
	}
}

// handlerErrorTypes are the handler error types that may appear verbatim in a metric tag.
// Keep in sync with the HandlerErrorType consts in nexus-rpc/sdk-go/nexus/errors.go.
var handlerErrorTypes = map[string]struct{}{
	string(nexus.HandlerErrorTypeBadRequest):        {},
	string(nexus.HandlerErrorTypeUnauthenticated):   {},
	string(nexus.HandlerErrorTypeUnauthorized):      {},
	string(nexus.HandlerErrorTypeNotFound):          {},
	string(nexus.HandlerErrorTypeRequestTimeout):    {},
	string(nexus.HandlerErrorTypeConflict):          {},
	string(nexus.HandlerErrorTypeResourceExhausted): {},
	string(nexus.HandlerErrorTypeInternal):          {},
	string(nexus.HandlerErrorTypeNotImplemented):    {},
	string(nexus.HandlerErrorTypeUnavailable):       {},
	string(nexus.HandlerErrorTypeUpstreamTimeout):   {},
}

// BoundHandlerErrorType bounds the metric cardinality a worker or a remote handler can introduce
// through a handler error type. Types in the Nexus spec pass through; anything else, including the
// empty string, collapses to UNKNOWN. The caller supplies its own prefix.
func BoundHandlerErrorType(errType string) string {
	if _, ok := handlerErrorTypes[errType]; ok {
		return errType
	}
	return "UNKNOWN"
}

package nexusoperation

import (
	failurepb "go.temporal.io/api/failure/v1"
	"go.temporal.io/server/chasm"
	"go.temporal.io/server/chasm/lib/nexusoperation/gen/nexusoperationpb/v1"
	"go.temporal.io/server/common/backoff"
	"google.golang.org/protobuf/types/known/timestamppb"
)

// EventCancellationScheduled is triggered when cancellation is meant to be scheduled for the first time - immediately
// after it has been requested.
type EventCancellationScheduled struct {
	// Destination is the endpoint name for the cancellation task.
	// Must be provided by the caller because ParentPtr is not available during inline creation.
	Destination string
}

var TransitionCancellationScheduled = chasm.NewTransition(
	[]nexusoperationpb.CancellationStatus{nexusoperationpb.CANCELLATION_STATUS_UNSPECIFIED},
	nexusoperationpb.CANCELLATION_STATUS_SCHEDULED,
	func(c *Cancellation, ctx chasm.MutableContext, event EventCancellationScheduled) error {
		c.Attempt++

		ctx.AddTask(c, chasm.TaskAttributes{
			Destination: event.Destination,
		}, &nexusoperationpb.CancellationTask{
			Attempt: c.Attempt,
		})

		return nil
	},
)

// EventCancellationRescheduled is triggered when cancellation is meant to be rescheduled after backing off from a
// previous attempt.
type EventCancellationRescheduled struct {
}

var transitionCancellationRescheduled = chasm.NewTransition(
	[]nexusoperationpb.CancellationStatus{nexusoperationpb.CANCELLATION_STATUS_BACKING_OFF},
	nexusoperationpb.CANCELLATION_STATUS_SCHEDULED,
	func(c *Cancellation, ctx chasm.MutableContext, event EventCancellationRescheduled) error {
		c.Attempt++
		c.NextAttemptScheduleTime = nil

		ctx.AddTask(c, chasm.TaskAttributes{
			Destination: c.Operation.Get(ctx).GetEndpoint(),
		}, &nexusoperationpb.CancellationTask{
			Attempt: c.Attempt,
		})

		return nil
	},
)

// EventCancellationAttemptFailed is triggered when a cancellation attempt is failed with a retryable error.
type EventCancellationAttemptFailed struct {
	Failure     *failurepb.Failure
	RetryPolicy backoff.RetryPolicy
}

var transitionCancellationAttemptFailed = chasm.NewTransition(
	[]nexusoperationpb.CancellationStatus{nexusoperationpb.CANCELLATION_STATUS_SCHEDULED},
	nexusoperationpb.CANCELLATION_STATUS_BACKING_OFF,
	func(c *Cancellation, ctx chasm.MutableContext, event EventCancellationAttemptFailed) error {
		currentTime := ctx.Now(c)

		c.LastAttemptCompleteTime = timestamppb.New(currentTime)
		c.LastAttemptFailure = event.Failure

		nextDelay := event.RetryPolicy.ComputeNextDelay(0, int(c.Attempt), nil)
		nextAttemptScheduleTime := currentTime.Add(nextDelay)
		c.NextAttemptScheduleTime = timestamppb.New(nextAttemptScheduleTime)

		ctx.AddTask(c, chasm.TaskAttributes{
			ScheduledTime: nextAttemptScheduleTime,
		}, &nexusoperationpb.CancellationBackoffTask{
			Attempt: c.Attempt,
		})

		return nil
	},
)

// EventCancellationFailed is triggered when a cancellation attempt is failed with a non retryable error.
type EventCancellationFailed struct {
	Failure *failurepb.Failure
}

var TransitionCancellationFailed = chasm.NewTransition(
	[]nexusoperationpb.CancellationStatus{
		// We can immediately transition to failed since we don't know how to send a cancellation request for an
		// unstarted operation.
		// TODO: This doesn't seem to happen in either the HSM or CHASM implementations.
		nexusoperationpb.CANCELLATION_STATUS_UNSPECIFIED,
		nexusoperationpb.CANCELLATION_STATUS_SCHEDULED,
	},
	nexusoperationpb.CANCELLATION_STATUS_FAILED,
	func(c *Cancellation, ctx chasm.MutableContext, event EventCancellationFailed) error {
		currentTime := ctx.Now(c)
		c.LastAttemptCompleteTime = timestamppb.New(currentTime)
		c.LastAttemptFailure = event.Failure
		// Terminal state - no tasks to emit.
		return nil
	},
)

// EventCancellationSucceeded is triggered when a cancellation attempt succeeds.
type EventCancellationSucceeded struct {
}

var TransitionCancellationSucceeded = chasm.NewTransition(
	[]nexusoperationpb.CancellationStatus{nexusoperationpb.CANCELLATION_STATUS_SCHEDULED},
	nexusoperationpb.CANCELLATION_STATUS_SUCCEEDED,
	func(c *Cancellation, ctx chasm.MutableContext, event EventCancellationSucceeded) error {
		currentTime := ctx.Now(c)
		c.LastAttemptCompleteTime = timestamppb.New(currentTime)
		c.LastAttemptFailure = nil

		// Terminal state - no tasks to emit.
		return nil
	},
)

package nexusoperation

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/nexus-rpc/sdk-go/nexus"
	enumspb "go.temporal.io/api/enums/v1"
	failurepb "go.temporal.io/api/failure/v1"
	"go.temporal.io/api/serviceerror"
	"go.temporal.io/server/chasm"
	nexusoperationpb "go.temporal.io/server/chasm/lib/nexusoperation/gen/nexusoperationpb/v1"
	"go.temporal.io/server/common/log"
	"go.temporal.io/server/common/log/tag"
	"go.temporal.io/server/common/metrics"
	"go.temporal.io/server/common/namespace"
	"go.temporal.io/server/common/nexus/nexusrpc"
	queueserrors "go.temporal.io/server/service/history/queues/errors"
	"go.uber.org/fx"
)

type cancellationResult interface {
	mustImplementCancellationResult()
}

type cancellationResultOK struct{}

func (cancellationResultOK) mustImplementCancellationResult() {}

type cancellationResultFail struct {
	failure *failurepb.Failure
}

func (cancellationResultFail) mustImplementCancellationResult() {}

type cancellationResultRetry struct {
	failure *failurepb.Failure
}

func (cancellationResultRetry) mustImplementCancellationResult() {}

func newCancellationResult(callErr error) (cancellationResult, error) {
	if callErr == nil {
		return cancellationResultOK{}, nil
	}

	if opTimeoutBelowMinErr, ok := errors.AsType[*operationTimeoutBelowMinError](callErr); ok {
		failure := &failurepb.Failure{
			Message: "operation timed out before cancellation could be delivered",
			FailureInfo: &failurepb.Failure_TimeoutFailureInfo{
				TimeoutFailureInfo: &failurepb.TimeoutFailureInfo{
					TimeoutType: opTimeoutBelowMinErr.timeoutType,
				},
			},
		}
		return cancellationResultFail{failure: failure}, nil
	}

	failure, retryable, err := callErrorToFailure(callErr)
	if err != nil {
		return nil, err
	}
	if retryable {
		return cancellationResultRetry{failure: failure}, nil
	}
	return cancellationResultFail{failure: failure}, nil
}

type cancellationInvocationTaskHandlerOptions struct {
	fx.In

	InvocationTaskHandlerOptions
}

type cancellationInvocationTaskHandler struct {
	chasm.SideEffectTaskHandlerBase[*nexusoperationpb.CancellationTask]

	nexusTaskHandlerBase
}

func newCancellationInvocationTaskHandler(opts cancellationInvocationTaskHandlerOptions) *cancellationInvocationTaskHandler {
	return &cancellationInvocationTaskHandler{
		nexusTaskHandlerBase: opts.toBase(),
	}
}

func (h *cancellationInvocationTaskHandler) Validate(
	_ chasm.Context,
	cancellation *Cancellation,
	_ chasm.TaskInvocation,
	task *nexusoperationpb.CancellationTask,
) (bool, error) {
	return cancellation.Status == nexusoperationpb.CANCELLATION_STATUS_SCHEDULED &&
		cancellation.GetAttempt() == task.GetAttempt(), nil
}

func (h *cancellationInvocationTaskHandler) Execute(
	ctx context.Context,
	cancelRef chasm.ComponentRef,
	attrs chasm.TaskAttributes,
	task *nexusoperationpb.CancellationTask,
) error {
	ns, err := h.namespaceRegistry.GetNamespaceByID(namespace.ID(cancelRef.NamespaceID))
	if err != nil {
		return serviceerror.NewNotFoundf("failed to get namespace by ID: %v", err)
	}

	args, err := chasm.ReadComponent(ctx, cancelRef, (*Cancellation).loadArgs, nil)
	if err != nil {
		return err
	}

	endpoint, err := h.lookupEndpoint(ctx, ns.ID(), args.endpointID, args.endpointName)
	if err != nil {
		if _, ok := errors.AsType[*serviceerror.NotFound](err); ok {
			h.logger.Error("endpoint not found while processing cancellation invocation", tag.Error(err))
			handlerErr := nexus.NewHandlerErrorf(nexus.HandlerErrorTypeNotFound, "endpoint not registered")
			return h.saveCancellationResult(ctx, cancelRef, handlerErr)
		}
		return err
	}

	callTimeout := h.config.RequestTimeout(ns.Name().String(), attrs.Destination)
	var timeoutType enumspb.TimeoutType
	if args.startToCloseTimeout > 0 {
		if t := args.startToCloseTimeout - args.currentTime.Sub(args.startedTime); t < callTimeout {
			callTimeout = t
			timeoutType = enumspb.TIMEOUT_TYPE_START_TO_CLOSE
		}
	}
	if args.scheduleToCloseTimeout > 0 {
		if t := args.scheduleToCloseTimeout - args.currentTime.Sub(args.scheduledTime); t < callTimeout {
			callTimeout = t
			timeoutType = enumspb.TIMEOUT_TYPE_SCHEDULE_TO_CLOSE
		}
	}

	callCtx, cancel := h.setupCallContext(ctx, callTimeout)
	defer cancel()

	traceCtx := invocationTraceContext{
		operationTag:      "CancelOperation",
		namespaceName:     ns.Name().String(),
		targetNamespaceID: endpoint.GetEndpoint().GetSpec().GetTarget().GetWorker().GetNamespaceId(),
		requestID:         args.requestID,
		operation:         args.operation,
		endpointName:      args.endpointName,
		workflowID:        cancelRef.BusinessID,
		runID:             cancelRef.RunID,
		attemptStart:      args.currentTime.UTC(),
		attempt:           task.GetAttempt(),
	}

	inv, err := h.newInvocation(
		callCtx, ns, endpoint, args.endpointName, args.service,
		callTimeout, timeoutType, traceCtx,
	)
	if err != nil {
		return fmt.Errorf("failed to construct invocation: %w", err)
	}
	header := buildRequestHeader(args.headers)
	// If this request is handled by a newer server that supports Nexus failure serialization, trigger that behavior.
	if h.config.UseNewFailureWireFormat(ns.Name().String()) {
		header.Set(nexusrpc.HeaderTemporalNexusFailureSupport, "true")
	}
	startTime := time.Now() // nolint:forbidigo // Time can be used for timing metrics.
	callErr := inv.Cancel(callCtx, args, nexus.CancelOperationOptions{Header: header})
	failureSource := failureSourceFromContext(callCtx)

	h.recordCallOutcome(endpoint, cancelCallOutcomeTag(callCtx, callErr), callErr, time.Since(startTime), failureSource, traceCtx)

	saveErr := h.saveCancellationResult(ctx, cancelRef, callErr)

	if callErr != nil && isDestinationDown(callErr) {
		saveErr = queueserrors.NewDestinationDownError(callErr.Error(), saveErr)
	}

	return saveErr
}

// saveCancellationResult saves the cancellation result by updating the cancellation component.
func (h *cancellationInvocationTaskHandler) saveCancellationResult(
	ctx context.Context,
	cancelRef chasm.ComponentRef,
	callErr error,
) error {
	result, err := newCancellationResult(callErr)
	if err != nil {
		return fmt.Errorf("failed to construct cancellation result: %w", err)
	}
	_, _, err = chasm.UpdateComponent(
		ctx,
		cancelRef,
		(*Cancellation).saveResult,
		saveCancellationResultInput{
			result:      result,
			retryPolicy: h.config.RetryPolicy,
		},
	)
	return err
}

type cancellationBackoffTaskHandler struct {
	chasm.PureTaskHandlerBase
	config *Config

	metricsHandler metrics.Handler
	logger         log.Logger
}

func newCancellationBackoffTaskHandler(opts commonTaskHandlerOptions) *cancellationBackoffTaskHandler {
	return &cancellationBackoffTaskHandler{
		config:         opts.Config,
		metricsHandler: opts.MetricsHandler,
		logger:         opts.Logger,
	}
}

func (h *cancellationBackoffTaskHandler) Validate(
	_ chasm.Context,
	cancellation *Cancellation,
	_ chasm.TaskInvocation,
	task *nexusoperationpb.CancellationBackoffTask,
) (bool, error) {
	isValid := cancellation.Status == nexusoperationpb.CANCELLATION_STATUS_BACKING_OFF && cancellation.GetAttempt() == task.GetAttempt()
	return isValid, nil
}

func (h *cancellationBackoffTaskHandler) Execute(
	ctx chasm.MutableContext,
	cancellation *Cancellation,
	_ chasm.TaskAttributes,
	_ *nexusoperationpb.CancellationBackoffTask,
) error {
	return transitionCancellationRescheduled.Apply(cancellation, ctx, EventCancellationRescheduled{})
}

