package provider

import (
	"errors"
	"sync"

	"go.temporal.io/server/common/archiver"
	"go.temporal.io/server/common/archiver/filestore"
	"go.temporal.io/server/common/archiver/gcloud"
	"go.temporal.io/server/common/archiver/s3store"
	"go.temporal.io/server/common/config"
	"go.temporal.io/server/common/log"
	"go.temporal.io/server/common/metrics"
	"go.temporal.io/server/common/persistence"
)

var (
	// ErrUnknownScheme is the error for unknown archiver scheme
	ErrUnknownScheme = errors.New("unknown archiver scheme")
	// ErrArchiverConfigNotFound is the error for unable to find the config for an archiver given scheme
	ErrArchiverConfigNotFound = errors.New("unable to find archiver config for the given scheme")
)

type (
	// ArchiverProvider returns history or visibility archiver based on the scheme.
	// The archiver for each scheme will be created only once and cached.
	ArchiverProvider interface {
		GetHistoryArchiver(scheme string) (archiver.HistoryArchiver, error)
		GetVisibilityArchiver(scheme string) (archiver.VisibilityArchiver, error)
	}

	// NewCustomHistoryArchiverParams provides dependencies for constructing a history archiver.
	NewCustomHistoryArchiverParams struct {
		Scheme           string
		ExecutionManager persistence.ExecutionManager
		Logger           log.Logger
		MetricsHandler   metrics.Handler
		Configs          map[string]any
	}

	// NewCustomVisibilityArchiverParams provides dependencies for constructing a visibility archiver.
	NewCustomVisibilityArchiverParams struct {
		Scheme         string
		Logger         log.Logger
		MetricsHandler metrics.Handler
		Configs        map[string]any
	}

	// CustomHistoryArchiverFactory constructs a history archiver for the given scheme.
	// Return ErrUnknownScheme to fall back to the default implementation.
	// If a non-nil archiver is returned, it takes precedence over built-in archiver implementations.
	CustomHistoryArchiverFactory interface {
		NewCustomHistoryArchiver(NewCustomHistoryArchiverParams) (archiver.HistoryArchiver, error)
	}

	// CustomVisibilityArchiverFactory constructs a visibility archiver for the given scheme.
	// Return ErrUnknownScheme to fall back to the default implementation.
	// If a non-nil archiver is returned, it takes precedence over built-in archiver implementations.
	CustomVisibilityArchiverFactory interface {
		NewCustomVisibilityArchiver(NewCustomVisibilityArchiverParams) (archiver.VisibilityArchiver, error)
	}

	CustomHistoryArchiverFactoryFunc func(NewCustomHistoryArchiverParams) (archiver.HistoryArchiver, error)

	CustomVisibilityArchiverFactoryFunc func(NewCustomVisibilityArchiverParams) (archiver.VisibilityArchiver, error)

	archiverProvider struct {
		sync.RWMutex

		historyArchiverConfigs    *config.HistoryArchiverProvider
		visibilityArchiverConfigs *config.VisibilityArchiverProvider

		customHistoryArchiverFactory    CustomHistoryArchiverFactory
		customVisibilityArchiverFactory CustomVisibilityArchiverFactory

		executionManager persistence.ExecutionManager
		logger           log.Logger
		metricsHandler   metrics.Handler

		// Key for the archiver is scheme
		historyArchivers    map[string]archiver.HistoryArchiver
		visibilityArchivers map[string]archiver.VisibilityArchiver
	}
)

func (f CustomHistoryArchiverFactoryFunc) NewCustomHistoryArchiver(
	params NewCustomHistoryArchiverParams,
) (archiver.HistoryArchiver, error) {
	return f(params)
}

func (f CustomVisibilityArchiverFactoryFunc) NewCustomVisibilityArchiver(
	params NewCustomVisibilityArchiverParams,
) (archiver.VisibilityArchiver, error) {
	return f(params)
}

// NewArchiverProvider returns a new Archiver provider
func NewArchiverProvider(
	historyArchiverConfigs *config.HistoryArchiverProvider,
	visibilityArchiverConfigs *config.VisibilityArchiverProvider,
	customHistoryArchiverFactory CustomHistoryArchiverFactory,
	customVisibilityArchiverFactory CustomVisibilityArchiverFactory,
	executionManager persistence.ExecutionManager,
	logger log.Logger,
	metricsHandler metrics.Handler,
) ArchiverProvider {
	return &archiverProvider{
		historyArchiverConfigs:          historyArchiverConfigs,
		visibilityArchiverConfigs:       visibilityArchiverConfigs,
		executionManager:                executionManager,
		logger:                          logger,
		metricsHandler:                  metricsHandler,
		customHistoryArchiverFactory:    customHistoryArchiverFactory,
		customVisibilityArchiverFactory: customVisibilityArchiverFactory,
		historyArchivers:                make(map[string]archiver.HistoryArchiver),
		visibilityArchivers:             make(map[string]archiver.VisibilityArchiver),
	}
}

func (p *archiverProvider) GetHistoryArchiver(scheme string) (historyArchiver archiver.HistoryArchiver, err error) {
	p.RLock()
	if historyArchiver, ok := p.historyArchivers[scheme]; ok {
		p.RUnlock()
		return historyArchiver, nil
	}
	p.RUnlock()

	if p.customHistoryArchiverFactory != nil {
		var customConfigs map[string]any
		if p.historyArchiverConfigs != nil {
			customConfigs = p.historyArchiverConfigs.CustomStores[scheme]
		}
		historyArchiver, err = p.customHistoryArchiverFactory.NewCustomHistoryArchiver(NewCustomHistoryArchiverParams{
			Scheme:           scheme,
			ExecutionManager: p.executionManager,
			Logger:           p.logger,
			MetricsHandler:   p.metricsHandler,
			Configs:          customConfigs,
		})
		if err != nil && !errors.Is(err, ErrUnknownScheme) {
			return nil, err
		}
	}

	if historyArchiver == nil {
		switch scheme {
		case filestore.URIScheme:
			if p.historyArchiverConfigs.Filestore == nil {
				return nil, ErrArchiverConfigNotFound
			}
			historyArchiver, err = filestore.NewHistoryArchiver(p.executionManager, p.logger, p.metricsHandler, p.historyArchiverConfigs.Filestore)

		case gcloud.URIScheme:
			if p.historyArchiverConfigs.Gstorage == nil {
				return nil, ErrArchiverConfigNotFound
			}

			historyArchiver, err = gcloud.NewHistoryArchiver(p.executionManager, p.logger, p.metricsHandler, p.historyArchiverConfigs.Gstorage)

		case s3store.URIScheme:
			if p.historyArchiverConfigs.S3store == nil {
				return nil, ErrArchiverConfigNotFound
			}
			historyArchiver, err = s3store.NewHistoryArchiver(p.executionManager, p.logger, p.metricsHandler, p.historyArchiverConfigs.S3store)
		default:
			return nil, ErrUnknownScheme
		}
	}

	if err != nil {
		return nil, err
	}

	p.Lock()
	defer p.Unlock()
	if existingHistoryArchiver, ok := p.historyArchivers[scheme]; ok {
		return existingHistoryArchiver, nil
	}
	p.historyArchivers[scheme] = historyArchiver
	return historyArchiver, nil
}

func (p *archiverProvider) GetVisibilityArchiver(scheme string) (archiver.VisibilityArchiver, error) {
	p.RLock()
	if visibilityArchiver, ok := p.visibilityArchivers[scheme]; ok {
		p.RUnlock()
		return visibilityArchiver, nil
	}
	p.RUnlock()

	var visibilityArchiver archiver.VisibilityArchiver
	var err error

	if p.customVisibilityArchiverFactory != nil {
		var customConfigs map[string]any
		if p.visibilityArchiverConfigs != nil {
			customConfigs = p.visibilityArchiverConfigs.CustomStores[scheme]
		}
		visibilityArchiver, err = p.customVisibilityArchiverFactory.NewCustomVisibilityArchiver(NewCustomVisibilityArchiverParams{
			Scheme:         scheme,
			Logger:         p.logger,
			MetricsHandler: p.metricsHandler,
			Configs:        customConfigs,
		})
		if err != nil && !errors.Is(err, ErrUnknownScheme) {
			return nil, err
		}
	}

	if visibilityArchiver == nil {
		switch scheme {
		case filestore.URIScheme:
			if p.visibilityArchiverConfigs.Filestore == nil {
				return nil, ErrArchiverConfigNotFound
			}
			visibilityArchiver, err = filestore.NewVisibilityArchiver(p.logger, p.metricsHandler, p.visibilityArchiverConfigs.Filestore)
		case s3store.URIScheme:
			if p.visibilityArchiverConfigs.S3store == nil {
				return nil, ErrArchiverConfigNotFound
			}
			visibilityArchiver, err = s3store.NewVisibilityArchiver(p.logger, p.metricsHandler, p.visibilityArchiverConfigs.S3store)
		case gcloud.URIScheme:
			if p.visibilityArchiverConfigs.Gstorage == nil {
				return nil, ErrArchiverConfigNotFound
			}
			visibilityArchiver, err = gcloud.NewVisibilityArchiver(p.logger, p.metricsHandler, p.visibilityArchiverConfigs.Gstorage)

		default:
			return nil, ErrUnknownScheme
		}
	}
	if err != nil {
		return nil, err
	}

	p.Lock()
	defer p.Unlock()
	if existingVisibilityArchiver, ok := p.visibilityArchivers[scheme]; ok {
		return existingVisibilityArchiver, nil
	}
	p.visibilityArchivers[scheme] = visibilityArchiver
	return visibilityArchiver, nil

}

package authorization

import (
	"crypto/ecdsa"
	"crypto/rsa"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/go-jose/go-jose/v4"
	"github.com/golang-jwt/jwt/v4"
	"go.temporal.io/server/common/config"
	"go.temporal.io/server/common/log"
	"go.temporal.io/server/common/log/tag"
)

// Default token key provider
type defaultTokenKeyProvider struct {
	config   config.JWTKeyProvider
	rsaKeys  map[string]*rsa.PublicKey
	ecKeys   map[string]*ecdsa.PublicKey
	keysLock sync.RWMutex
	ticker   *time.Ticker
	logger   log.Logger
	stop     chan bool
}

var _ TokenKeyProvider = (*defaultTokenKeyProvider)(nil)

func NewDefaultTokenKeyProvider(cfg *config.Authorization, logger log.Logger) *defaultTokenKeyProvider {
	provider := defaultTokenKeyProvider{config: cfg.JWTKeyProvider, logger: logger}
	provider.initialize()
	return &provider
}

func (a *defaultTokenKeyProvider) initialize() {
	a.rsaKeys = make(map[string]*rsa.PublicKey)
	a.ecKeys = make(map[string]*ecdsa.PublicKey)
	if a.config.HasSourceURIsConfigured() {
		err := a.updateKeys()
		if err != nil {
			a.logger.Error("error during initial retrieval of token keys: ", tag.Error(err))
		}
	}
	if a.config.RefreshInterval > 0 {
		a.stop = make(chan bool)
		a.ticker = time.NewTicker(a.config.RefreshInterval)
		go a.timerCallback()
	}
}

func (a *defaultTokenKeyProvider) Close() {
	a.ticker.Stop()
	a.stop <- true
	close(a.stop)
}

func (a *defaultTokenKeyProvider) RsaKey(alg string, kid string) (*rsa.PublicKey, error) {
	if !strings.EqualFold(alg, jwt.SigningMethodRS256.Name) {
		return nil, fmt.Errorf("unexpected signing algorithm: %s", alg)
	}

	a.keysLock.RLock()
	key, found := a.rsaKeys[kid]
	a.keysLock.RUnlock()
	if !found {
		return nil, fmt.Errorf("RSA key not found for key ID: %s", kid)
	}
	return key, nil
}

func (a *defaultTokenKeyProvider) EcdsaKey(alg string, kid string) (*ecdsa.PublicKey, error) {
	if !strings.EqualFold(alg, jwt.SigningMethodES256.Name) {
		return nil, fmt.Errorf("unexpected signing algorithm: %s", alg)
	}

	a.keysLock.RLock()
	key, found := a.ecKeys[kid]
	a.keysLock.RUnlock()
	if !found {
		return nil, fmt.Errorf("ECDSA key not found for key ID: %s", kid)
	}
	return key, nil
}

func (a *defaultTokenKeyProvider) SupportedMethods() []string {
	return []string{jwt.SigningMethodRS256.Name, jwt.SigningMethodES256.Name}
}

func (a *defaultTokenKeyProvider) timerCallback() {
	for {
		select {
		case <-a.stop:
			return
		case <-a.ticker.C:
		}
		if a.config.HasSourceURIsConfigured() {
			err := a.updateKeys()
			if err != nil {
				a.logger.Error("error while refreshing token keys: ", tag.Error(err))
			}
		}
	}
}

func (a *defaultTokenKeyProvider) updateKeys() error {
	if !a.config.HasSourceURIsConfigured() {
		return fmt.Errorf("no URIs configured for retrieving token keys")
	}

	rsaKeys := make(map[string]*rsa.PublicKey)
	ecKeys := make(map[string]*ecdsa.PublicKey)

	for _, uri := range a.config.KeySourceURIs {
		if strings.TrimSpace(uri) == "" {
			continue
		}
		err := a.updateKeysFromURI(uri, rsaKeys, ecKeys)
		if err != nil {
			return err
		}
	}
	// swap old keys with the new ones
	a.keysLock.Lock()
	a.rsaKeys = rsaKeys
	a.ecKeys = ecKeys
	a.keysLock.Unlock()
	return nil
}

func (a *defaultTokenKeyProvider) updateKeysFromURI(
	uri string,
	rsaKeys map[string]*rsa.PublicKey,
	ecKeys map[string]*ecdsa.PublicKey,
) (err error) {

	resp, err := a.openURI(uri)
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, resp.Close())
	}()

	jwks := jose.JSONWebKeySet{}
	if err := json.NewDecoder(resp).Decode(&jwks); err != nil {
		return err
	}

	for _, k := range jwks.Keys {
		switch k.Key.(type) {
		case *rsa.PublicKey:
			rsaKeys[k.KeyID] = k.Key.(*rsa.PublicKey)
		case *ecdsa.PublicKey:
			ecKeys[k.KeyID] = k.Key.(*ecdsa.PublicKey)
		default:
			a.logger.Warn(fmt.Sprintf("unexpected type of JWKS public key %s", k.Algorithm))
		}
	}
	return nil
}

// openURI returns a ReadCloser for the given URI. Supports http://, https://, and file:// schemes.
func (a *defaultTokenKeyProvider) openURI(uri string) (io.ReadCloser, error) {
	u, err := url.Parse(uri)
	if err != nil {
		return nil, err
	}
	if u.Scheme == "file" {
		if u.Host != "" && u.Host != "localhost" {
			return nil, fmt.Errorf("file URI with remote host is not supported: %s", uri)
		}
		return os.Open(u.Path)
	}
	resp, err := http.Get(uri)
	if err != nil {
		return nil, err
	}
	return resp.Body, nil
}

func (a *defaultTokenKeyProvider) HmacKey(alg string, kid string) ([]byte, error) {
	return nil, fmt.Errorf("unsupported key type HMAC for: %s", alg)
}

// Package routing provides utilities to define a number of [Route] instances, which can be...
//
//  1. Used by servers to...
//
//     1.a. Register with [github.com/gorilla/mux.Router] instances via the [Route.Representation] method.
//
//     1.b. Deserialize HTTP path variables into a struct with the [Route.Deserialize] method.
//
//  2. Used by clients to construct HTTP paths for requests by calling the [Route.Path] method.
package routing

import (
	"net/url"
	"strings"
)

// Route represents a series of HTTP path components.
type Route[T any] struct {
	components []Component[T]
}

// Component represents a single HTTP path component, either a constant slug or a variable parameter.
type Component[T any] interface {
	// Representation is the string representation of the component for usage in a path definition, e.g. "v1" for a
	// constant slug or "{namespace}" for a variable. This should be compatible with the format specified in
	// the [github.com/gorilla/mux] package.
	Representation() string
	// Serialize returns the actual value of the slug when used in an HTTP path, e.g. "v1" for a constant slug or
	// "test-namespace" for a variable.
	Serialize(params T) string
	// Deserialize mutates the given params object with the value of the component when parsing an HTTP path, e.g.
	// setting the value of a variable to "test-namespace". If the component is a constant slug, this method should
	// be a no-op.
	Deserialize(vars map[string]string, t *T)
}

// NewRoute returns a new [Route] instance with the given components.
func NewRoute[T any](components ...Component[T]) Route[T] {
	return Route[T]{components: components}
}

// RouteBuilder is a builder for the [Route] interface.
type RouteBuilder[T any] struct {
	components []Component[T]
}

// NewBuilder creates a new [RouteBuilder] instance, which can be used to define a new [Route] via a fluent API.
func NewBuilder[T any]() *RouteBuilder[T] {
	return &RouteBuilder[T]{}
}

// With adds a series of [Component] instances to the [Route].
func (r *RouteBuilder[T]) With(c ...Component[T]) *RouteBuilder[T] {
	r.components = append(r.components, c...)
	return r
}

// Constant adds a [Constant] component to the [Route].
func (r *RouteBuilder[T]) Constant(values ...string) *RouteBuilder[T] {
	return r.With(Constant[T](values...))
}

// StringVariable adds a [StringVariable] component to the [Route].
func (r *RouteBuilder[T]) StringVariable(name string, getter func(*T) *string) *RouteBuilder[T] {
	return r.With(StringVariable[T](name, getter))
}

// Build returns a read-only [Route].
func (r *RouteBuilder[T]) Build() Route[T] {
	return NewRoute[T](r.components...)
}

// Representation returns the [github.com/gorilla/mux] compatible string representation of the route for usage in a
// path definition. It does not add a leading or trailing slash to the representation, but it won't remove them if
// they're present in the components. We do this because it's easier to add a slash depending on the context than to
// remove it.
func (r Route[T]) Representation() string {
	return r.serialize(func(c Component[T]) string {
		return c.Representation()
	})
}

// Path returns the serialized path of the route with the given params. There will be no leading or trailing slashes,
// similar to the behavior of the [Route.Representation] method.
func (r Route[T]) Path(t T) string {
	return r.serialize(func(c Component[T]) string {
		return c.Serialize(t)
	})
}

func (r Route[T]) serialize(f func(c Component[T]) string) string {
	var sb strings.Builder
	for i, c := range r.components {
		if i > 0 {
			sb.WriteString("/")
		}
		sb.WriteString(f(c))
	}
	return sb.String()
}

// Deserialize the given vars into a new instance of the params type, T.
func (r Route[T]) Deserialize(vars map[string]string) T {
	var t T
	for _, c := range r.components {
		c.Deserialize(vars, &t)
	}
	return t
}

// Constant returns a [Component] that represents a series of constant HTTP path components in a Route.
// They will be joined via strings when used to construct a path or path representation.
func Constant[T any](values ...string) constant[T] {
	return values
}

type constant[T any] []string

func (s constant[T]) Representation() string {
	return strings.Join(s, "/")
}

func (s constant[T]) Serialize(T) string {
	return strings.Join(s, "/")
}

func (s constant[T]) Deserialize(map[string]string, *T) {}

// StringVariable returns a [Component] that represents a string variable in a Route.
func StringVariable[T any](name string, getter func(*T) *string) stringVariable[T] {
	return stringVariable[T]{name, getter}
}

type stringVariable[T any] struct {
	name   string
	getter func(*T) *string
}

func (s stringVariable[T]) Representation() string {
	return "{" + s.name + "}"
}

