// Properties used internally by protobufjs on Namespace/ReflectionObject instances.
// A protobuf package component that happens to share one of these names must not be
// promoted to a direct property, or it would corrupt protobufjs's internal state.
// (Such types are still reachable via root.lookup() or root.nested traversal.)
const ROOT_PROPS = new Set([
  'options',
  'parsedOptions',
  'name',
  'parent',
  'resolved',
  'comment',
  'filename',
  'nested',
  '_nestedArray',
]);

/**
 * Create a version of `root` with non-nested namespaces to match the generated types.
 * For more information, see:
 * https://github.com/temporalio/sdk-typescript/blob/main/docs/protobuf-libraries.md#current-solution
 * @param root Generated by `pbjs -t json-module -w commonjs -o json-module.js *.proto`
 * @returns A new patched `root`
 */
export function patchProtobufRoot<T extends Record<string, unknown>>(root: T): T {
  const patched = _patchProtobufRoot(root);

  // Protobufjs >=7.5.2 added a fast-path cache in Namespace#lookup() that accesses
  // `this.root._fullyQualifiedObjects`. The `root` accessor is defined as a non-enumerable
  // getter on `ReflectionObject.prototype`, so it is not copied by `for...in` loops.
  // When the patched root is imported via `import * as proto from '@temporalio/proto'`,
  // TypeScript's `__importStar` helper wraps the CJS module in a plain object by iterating
  // own enumerable properties with `for...in` + `hasOwnProperty`. Because `root` is
  // non-enumerable, it is skipped, the wrapper's `root` is `undefined`, and any subsequent
  // `this.root._fullyQualifiedObjects` access crashes.
  // Defining `root` as an own **enumerable** getter ensures `__importStar` includes it in
  // the wrapper, so that `wrapper.root` delegates back to the patched root (which has the
  // proper `_fullyQualifiedObjects` map and full prototype chain).
  if (!Object.getOwnPropertyDescriptor(patched, 'root')) {
    Object.defineProperty(patched, 'root', {
      get(this: any) {
        // eslint-disable-next-line @typescript-eslint/no-this-alias
        let ptr = this;
        while (ptr.parent !== null) ptr = ptr.parent;
        return ptr;
      },
      enumerable: true,
      configurable: true,
    });
  }

  // Protobufjs >=8 declares `constructor` as a non-enumerable property on the prototypes of its
  // reflection classes; before that it was assigned plainly, making it enumerable. `__importStar`
  // only carries over own enumerable properties, so without this the wrapper it builds for
  // `import * as proto from '@temporalio/proto'` loses its link back to `Root`, and the
  // `constructor.className` checks used to recognize a root would reject it.
  if (!Object.getOwnPropertyDescriptor(patched, 'constructor')) {
    Object.defineProperty(patched, 'constructor', {
      value: patched.constructor,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }

  return patched;
}

function _patchProtobufRoot<T extends Record<string, unknown>>(root: T, name?: string): T {
  const newRoot = new (root.constructor as any)(isNamespace(root) ? name : {});
  for (const key in root) {
    // 'root' is a getter-only accessor defined on ReflectionObject.prototype. Trying to
    // assign it as a plain property on a new Root/Namespace instance throws in strict mode.
    // It is also safe to skip because each object correctly resolves its own root at runtime
    // by traversing the parent chain. The top-level own enumerable getter is added separately
    // by patchProtobufRoot() after recursion completes.
    if (key === 'root') continue;
    newRoot[key] = root[key];
  }

  if (isRecord(root.nested)) {
    for (const typeOrNamespace in root.nested) {
      // Skip names that protobufjs uses internally — overriding them would corrupt
      // the namespace object's internal state. Types/namespaces with these names are
      // still reachable via root.lookup() or by traversing root.nested manually.
      if (ROOT_PROPS.has(typeOrNamespace)) continue;

      const value = root.nested[typeOrNamespace];
      if (isNamespace(value)) {
        newRoot[typeOrNamespace] = _patchProtobufRoot(value, typeOrNamespace);
      } else if (isType(value)) {
        newRoot[typeOrNamespace] = value;
      }
    }
  }

  return newRoot;
}

type Type = Record<string, unknown>;
type Namespace = { nested: Record<string, unknown> };

function isType(value: unknown): value is Type {
  // constructor.name may get mangled by minifiers; thanksfuly protobufjs also sets a constructor.className property
  return isRecord(value) && (value.constructor as any).className === 'Type';
}

function isNamespace(value: unknown): value is Namespace {
  // constructor.name may get mangled by minifiers; thanksfuly protobufjs also sets a constructor.className property
  return isRecord(value) && (value.constructor as any).className === 'Namespace';
}

// Duplicate from type-helpers instead of importing in order to avoid circular dependency
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

import type { Compiler, Compilation } from 'webpack';
import { javascript, sources, WebpackError } from 'webpack';

type Source = sources.Source;

const PLUGIN_NAME = 'TemporalWorkflowModuleCachePlugin';

/**
 * The runtime-injected global that holds the Workflow bundle's module cache.
 *
 * When running Workflows in a reusable V8 context, the Worker injects an object under this
 * name into the sandbox global (see `reusable-vm.ts`). Redirecting webpack's module cache
 * to this global is what makes per-Workflow module isolation possible while sharing a
 * single V8 context.
 */
const MODULE_CACHE_GLOBAL = 'globalThis.__webpack_module_cache__';

/**
 * A fixed, high-entropy marker that we inject into the top-level webpack runtime's
 * `__webpack_require__` function body.
 *
 * The marker is used to reliably locate the *real* (top-level) module-cache declaration
 * emitted by this run of webpack (vs nested dependencies that have themselves been
 * bundled with webpack and thus carry their own module cache declarations).The marker
 * is stripped from the bundle before the final output is produced, so it never ships.
 *
 * It is intentionally a *stable constant* (not randomly generated per build): the marker
 * participates in webpack's chunk/`[fullhash]` computation, so a random value would make
 * the bundle's content hash — and therefore its filename — non-deterministic across
 * otherwise-identical builds.
 */
const MODULE_CACHE_MARKER = '__temporal_module_cache_marker_5f2e9c8a1b7d4e60a3__';
const MARKER_COMMENT = `/* ${MODULE_CACHE_MARKER} */\n`;

// Matches webpack's top-level module-cache initializer, regardless of the declaration
// keyword used (webpack < 5.108 emits `var`; >= 5.108 may emit `const`, 'let' or `var`).
const MODULE_CACHE_DECLARATION = /(?:var|let|const)\s+__webpack_module_cache__\s*=\s*\{\}/g;

/**
 * Webpack plugin that redirects the Workflow bundle's top-level module cache to a
 * runtime-injected global (`globalThis.__webpack_module_cache__`).
 *
 * This plugin operates inside the webpack render pipeline using in two phases:
 *   1. `renderRequire` injects a stable marker into the top-level runtime's
 *      `__webpack_require__` body. That hook is only ever invoked for the bundle's own
 *      runtime, so the marker unambiguously identifies the real module cache — nested,
 *      pre-bundled runtimes carry their own already-rendered require functions and never
 *      pass through this hook.
 *   2. `renderMain` uses the marker to locate the top-level module-cache declaration
 *      (the nearest one preceding the marker), redirects it to the injected global, and
 *      strips the marker. This runs during chunk rendering — before any `processAssets`
 *      stage, hence before minification — and returns a `ReplaceSource` so source maps
 *      are preserved.
 */
export class InjectWorkflowModuleCacheGlobalPlugin {
  apply(compiler: Compiler): void {
    compiler.hooks.compilation.tap(PLUGIN_NAME, (compilation: Compilation) => {
      const hooks = javascript.JavascriptModulesPlugin.getCompilationHooks(compilation);

      hooks.renderRequire.tap(PLUGIN_NAME, (code: string) => {
        return `${MARKER_COMMENT}${code}`;
      });

      hooks.renderMain.tap(PLUGIN_NAME, (source: Source) => {
        return this.redirectModuleCache(source);
      });
    });
  }

  private redirectModuleCache(source: Source): Source {
    const code = source.source().toString();

    // We're only interested in the chunk that carries the top-level runtime marker
    const markerIndex = code.indexOf(MARKER_COMMENT);
    if (markerIndex === -1) {
      return source;
    }

    // The marker is injected exactly once, into the single top-level
    // require function. Confirm there isn't another marker in the code.
    if (code.indexOf(MARKER_COMMENT, markerIndex + MARKER_COMMENT.length) !== -1) {
      throw new WebpackError(
        `Failed to patch the Workflow bundle: expected exactly one module-cache marker, but found more than one. ` +
          `This is likely due to a change in webpack output; please report this at ` +
          `https://github.com/temporalio/sdk-typescript/issues`
      );
    }

    // The top-level module-cache declaration is the one immediately preceding the marked
    // require function. Any other `__webpack_module_cache__ = {}` occurrences belong to
    // nested, pre-bundled dependencies and appear earlier in the emitted module content, so
    // the nearest match before the marker is always the real one.
    let declaration: RegExpExecArray | null = null;
    // Because of the `/g` flag, the regexp is stateful. We must reset the regexp's
    // lastIndex to 0 to make sure it starts from the beginning of the code, rather
    // than continuing from the last match position of a previous iteration.
    MODULE_CACHE_DECLARATION.lastIndex = 0;
    for (let match = MODULE_CACHE_DECLARATION.exec(code); match !== null; match = MODULE_CACHE_DECLARATION.exec(code)) {
      if (match.index >= markerIndex) break;
      declaration = match;
    }

    if (declaration === null) {
      throw new WebpackError(
        `Failed to patch the Workflow bundle: found the module-cache marker but no preceding ` +
          `'__webpack_module_cache__' declaration to redirect. Without this patch, Workflow isolation ` +
          `would be broken. This is likely due to a change in webpack output; please report this at ` +
          `https://github.com/temporalio/sdk-typescript/issues`
      );
    }

    const replaced = new sources.ReplaceSource(source);

    // Redirect the top-level declaration to the runtime-injected global. The declaration regexp
    // ends at the empty-object initializer, so replacing only those last two characters avoids
    // making this replacement sensitive to whitespace around the assignment operator.
    const initializerStart = declaration.index + declaration[0].length - '{}'.length;
    replaced.replace(initializerStart, initializerStart + '{}'.length - 1, MODULE_CACHE_GLOBAL);

    // Strip the marker so it never ships.
    // Note that `ReplaceSource.replace()` takes character indices from the
    // _original_ source; there's therefore no need to adjust the indices to
    // account for the replacement we just performed (`{}` => MODULE_CACHE_GLOBAL).
    const markerEndInclusive = markerIndex + MARKER_COMMENT.length - 1;
    replaced.replace(markerIndex, markerEndInclusive, '');

    return replaced;
  }
}

/**
 * Asserts that the generated Workflow bundle has been correctly patched to redirect the
 * module cache to the runtime-injected global (`globalThis.__webpack_module_cache__`)
 * by `InjectWorkflowModuleCacheGlobalPlugin`.
 *
 * These sanity checks are meant to catch and fail loudly on some specific eventual regressions
 * in the webpack library or configuration that would prevent hijacking webpack's module cache,
 * and thus result in silent reoccurences of #2170 or #2188.
 */
export function assertWorkflowModuleCacheGlobalApplied(code: string): void {
  // Webpack's bootstrap code should contain a declaration of the module cache, similar to:
  //     const __webpack_module_cache__ = {};
  //
  // That line should have been replaced by `InjectWorkflowModuleCacheGlobalPlugin` to:
  //     const __webpack_module_cache__ = globalThis.__webpack_module_cache__;
  //
  // Further webpack plugins (e.g. minification) might further transform that line (e.g. removing
  // spaces or renaming the scoped variable), but the global variable should remain unchanged.
  // Absence of references to that global variable would be an error.
  if (!code.includes(MODULE_CACHE_GLOBAL)) {
    throw new Error(
      `Failed to patch the Workflow bundle: the module cache was not redirected to ` +
        `'${MODULE_CACHE_GLOBAL}'. Without this, Workflow isolation would be broken.` +
        `This may be the result of uncommon and unsupported webpack configurations, ` +
        `but most likely indicates a change in webpack's output format or a bug in the ` +
        `Temporal SDK. Please report this at https://github.com/temporalio/sdk-typescript/issues.`
    );
  }

  // There could be multiple occurences of "__webpack_module_cache__" in the code produced
  // by webpack if the bundle contains nested, pre-bundled dependencies (see #2188).
  // To correctly determine the one to be rewritten, `InjectWorkflowModuleCacheGlobalPlugin`
  // temporarily injects a marker into the top-level runtime's `__webpack_require__` function
  // body. The marker is stripped from the bundle before the final output is produced.
  //
  // The marker being still present in the final bundle code, though unharmful by itself,
  // would be unexpected and should raise doubts about the correctness of the module cache
  // rewrite process.
  if (code.includes(MODULE_CACHE_MARKER)) {
    throw new Error(
      `Failed to patch the Workflow bundle: the internal module-cache marker was ` +
        `not stripped from the output. There's a risk that Workflow isolation would be broken.` +
        `This may be the result of uncommon and unsupported webpack configurations, ` +
        `but most likely indicates a change in webpack's output format or a bug in the ` +
        `Temporal SDK. Please report this at https://github.com/temporalio/sdk-typescript/issues.`
    );
  }
}

import test from 'ava';
import type { Context } from '@temporalio/activity';
import { registerCancelShutdown } from '../worker/stateful-mcp-provider';

test('registerCancelShutdown: cancellation triggers dedicated-worker shutdown', async (t) => {
  let rejectCancelled!: (err: Error) => void;
  const cancelled = new Promise<never>((_resolve, reject) => {
    rejectCancelled = reject;
  });
  const ctx = { cancelled } as unknown as Context;

  let shutdownCalls = 0;
  const dedicatedWorker = {
    shutdown: () => {
      shutdownCalls += 1;
    },
  };

  registerCancelShutdown(ctx, dedicatedWorker);

  t.is(shutdownCalls, 0);

  rejectCancelled(new Error('cancelled'));
  await new Promise((resolve) => setImmediate(resolve));

  t.is(shutdownCalls, 1);
});

import type { MCPServer } from '@openai/agents-core';
import { ApplicationFailure } from '@temporalio/common';
import { Context, activityInfo } from '@temporalio/activity';
import type { NativeConnection } from '@temporalio/worker';
import {
  MCP_CALL_TOOL_SUFFIX,
  MCP_LIST_TOOLS_SUFFIX,
  MCP_SERVER_SESSION_SUFFIX,
  MCP_STATEFUL_SUFFIX,
  type StatefulMcpServerSessionArgs,
} from '../common/mcp-types';
import { startAdaptiveHeartbeat } from './heartbeat';

export function registerCancelShutdown(ctx: Context, dedicatedWorker: { shutdown: () => void }): void {
  ctx.cancelled.catch(() => {
    dedicatedWorker.shutdown();
  });
}

interface CallToolArgs {
  toolName: string;
  args: Record<string, unknown> | null;
}

/**
 * Stateful MCP server provider. Maintains a persistent MCP connection per
 * Workflow run via a dedicated in-process Worker on a per-run Task Queue.
 *
 * Callers must handle `ApplicationFailure` with type `"DedicatedWorkerFailure"`
 * if the dedicated Worker fails to start or misses a heartbeat.
 */
export class StatefulMCPServerProvider {
  private readonly _name: string;
  private readonly _servers: Map<string, MCPServer> = new Map();
  private readonly _serverFactory: (factoryArgument?: unknown) => MCPServer;
  private readonly _nativeConnection: NativeConnection;

  /**
   * @param name - The internal name is `${name}-stateful` to avoid colliding with stateless providers using the same base name.
   * @param serverFactory - Must return a fresh server instance per call (one per Workflow run).
   * @param nativeConnection - NativeConnection used by the dedicated per-run Worker; typically the same one the main Worker uses.
   */
  constructor(
    name: string,
    serverFactory: (factoryArgument?: unknown) => MCPServer,
    nativeConnection: NativeConnection
  ) {
    this._name = `${name}${MCP_STATEFUL_SUFFIX}`;
    this._serverFactory = serverFactory;
    this._nativeConnection = nativeConnection;
  }

  get name(): string {
    return this._name;
  }

  _getActivities(): Record<string, (...args: any[]) => Promise<unknown>> {
    const serverId = (): string => {
      const info = activityInfo();
      // `workflowExecution` is always set for Activities scheduled from a Workflow,
      // which is the only way these per-Run Activities are dispatched.
      return `${this._name}@${info.workflowExecution!.runId}`;
    };

    const getServerOrThrow = (): MCPServer => {
      const id = serverId();
      const server = this._servers.get(id);
      if (!server) {
        throw ApplicationFailure.create({
          message: `No active server for ${id}`,
          type: 'StatefulMCPServerNotFound',
          nonRetryable: true,
        });
      }
      return server;
    };

    // Operation Activities — registered on the per-run Task Queue.
    const listTools = async () => getServerOrThrow().listTools();

    const callTool = async (input: CallToolArgs) => getServerOrThrow().callTool(input.toolName, input.args);

    // Long-running session Activity on the MAIN Worker's Task Queue. Creates
    // a server, connects it, spins up a dedicated per-run Worker, then awaits
    // until cancelled.
    const serverSession = async (input?: StatefulMcpServerSessionArgs): Promise<void> => {
      const info = activityInfo();
      const sid = `${this._name}@${info.workflowExecution!.runId}`;

      // Heartbeats so a slow `server.connect()` doesn't trip the timeout.
      const stopHeartbeat = startAdaptiveHeartbeat();

      try {
        if (this._servers.has(sid)) {
          throw ApplicationFailure.create({
            message:
              'Cannot connect to an already running server. Use a distinct name if running multiple servers in one workflow.',
            type: 'StatefulMCPServerAlreadyRunning',
            nonRetryable: true,
          });
        }

        const server = this._serverFactory(input?.factoryArgument);

        try {
          this._servers.set(sid, server);
          await server.connect();

          const { Worker } = await import('@temporalio/worker');

          const dedicatedTaskQueue = sid;

          const dedicatedActivities: Record<string, (...args: any[]) => Promise<unknown>> = {
            [`${this._name}${MCP_LIST_TOOLS_SUFFIX}`]: listTools,
            [`${this._name}${MCP_CALL_TOOL_SUFFIX}`]: callTool,
          };

          // Wire the Activity interceptor identically to the main Worker so
          // tool Activities still restore trace context and emit
          // `temporal:executeActivity:*` spans. Options are forwarded per-run
          // via input. Lazy import to avoid pulling the Worker package
          // unnecessarily.
          const { OpenAIAgentsTraceActivityInboundInterceptor } = await import('./trace-interceptor');
          const interceptorOpts = input?.activityInterceptorOptions;
          const dedicatedWorker = await Worker.create({
            connection: this._nativeConnection,
            taskQueue: dedicatedTaskQueue,
            activities: dedicatedActivities,
            maxConcurrentActivityTaskExecutions: 1,
            interceptors: {
              activity: [
                (ctx) => ({
                  inbound: new OpenAIAgentsTraceActivityInboundInterceptor(ctx, interceptorOpts),
                }),
              ],
            },
          });

          registerCancelShutdown(Context.current(), dedicatedWorker);

          await dedicatedWorker.run();
        } finally {
          await server.close();
          this._servers.delete(sid);
        }
      } finally {
        stopHeartbeat();
      }
    };

    // Only the session Activity is registered on the main Worker; the
    // operation Activities live on the per-run Worker.
    return {
      [`${this._name}${MCP_SERVER_SESSION_SUFFIX}`]: serverSession,
    };
  }
}

