import { useRef } from "react";

import Editor, { type EditorProps } from "src/components/MonacoEditor";

import { useMonacoTheme } from "src/context/colorMode";

type JsonEditorProps = {
  readonly editable?: boolean;
  readonly height?: string;
  readonly id?: string;
  readonly name?: string;
  readonly onBlur?: () => void;
  readonly onChange?: (value: string) => void;
  readonly onError?: (error: string | undefined) => void;
  readonly prettify?: boolean;
  readonly value?: string;
};

export const JsonEditor = ({
  editable = true,
  height = "200px",
  onBlur,
  onChange,
  onError,
  prettify = false,
  value,
  ...rest
}: JsonEditorProps) => {
  const { beforeMount, theme } = useMonacoTheme();
  const onBlurRef = useRef(onBlur);

  onBlurRef.current = onBlur;

  const options: EditorProps["options"] = {
    automaticLayout: true,
    folding: true,
    fontSize: 14,
    lineNumbers: "on",
    minimap: { enabled: false },
    readOnly: !editable,
    renderLineHighlight: "none",
    scrollBeyondLastLine: false,
  };

  const handleChange = (val: string | undefined = "") => {
    if (!prettify) {
      onChange?.(val);

      return;
    }

    try {
      const formattedJson = JSON.stringify(JSON.parse(val) as unknown, undefined, 2);

      onError?.(undefined);
      if (formattedJson !== value) {
        onChange?.(formattedJson);
      }
    } catch (error) {
      onError?.(error instanceof Error ? error.message : String(error));
    }
  };

  return (
    <div
      style={{
        border: "1px solid var(--chakra-colors-border-emphasized)",
        borderRadius: "8px",
        overflow: "hidden",
        width: "100%",
      }}
      {...rest}
    >
      <Editor
        beforeMount={beforeMount}
        height={height}
        language="json"
        onChange={handleChange}
        onMount={(editor) => {
          editor.onDidBlurEditorText(() => {
            onBlurRef.current?.();
          });
        }}
        options={options}
        theme={theme}
        value={value}
      />
    </div>
  );
};

