package sessionstate

import (
	"os"
	"path/filepath"
	"syscall"
)

// withFileLock — Unix implementation. See the godoc comment in
// sessionstate.go for the contract. Uses BSD flock so the lock is
// advisory and process-scoped; sufficient for the openlit hook
// pattern (one hook subprocess per agent event, never overlapping
// inside the same process).
func withFileLock(lockPath string, fn func()) {
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o700); err != nil {
		fn()
		return
	}
	f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		fn()
		return
	}
	defer f.Close()
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
		fn()
		return
	}
	defer syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
	fn()
}

//go:build windows

package sessionstate

import (
	"os"
	"path/filepath"

	"golang.org/x/sys/windows"
)

// withFileLock — Windows implementation. See the godoc comment in
// sessionstate.go for the contract. Uses LockFileEx with LOCKFILE_EXCLUSIVE_LOCK
// (no LOCKFILE_FAIL_IMMEDIATELY) so the call blocks until the lock is acquired,
// matching the Unix flock behaviour. The lock is process-scoped and released
// either explicitly via UnlockFileEx or implicitly when the handle is closed —
// either way, a crashed hook cannot orphan the lock.
//
// On any setup failure (mkdir, open, lock acquisition) we fall back to running
// fn unlocked rather than dropping the event entirely: telemetry must never
// fail closed on an OS-level hiccup. The worst case is a single last-write-wins
// collision on the session-state file, which the in-process diskMu still
// guards against within a single process.
func withFileLock(lockPath string, fn func()) {
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o700); err != nil {
		fn()
		return
	}
	f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		fn()
		return
	}
	defer f.Close()

	// LockFileEx locks a byte range; pass a max range so we cover the
	// whole (currently-empty) lock file regardless of any future writes.
	// An overlapped structure with zeroed offsets locks from byte 0.
	var ol windows.Overlapped
	const exclusive = windows.LOCKFILE_EXCLUSIVE_LOCK
	if err := windows.LockFileEx(windows.Handle(f.Fd()), exclusive, 0, 0xFFFFFFFF, 0xFFFFFFFF, &ol); err != nil {
		fn()
		return
	}
	defer windows.UnlockFileEx(windows.Handle(f.Fd()), 0, 0xFFFFFFFF, 0xFFFFFFFF, &ol)
	fn()
}

import { withRouteAccess } from "@/lib/access/route-access";
import { MetricParams, TimeLimit } from "@/lib/platform/common";
import { getAgentLoop } from "@/lib/platform/llm/agent-loop";
import {
	validateMetricsRequest,
	validateMetricsRequestType,
} from "@/helpers/server/platform";
import { getRequestEnvironment } from "@/constants/openlit-context";
import getMessage from "@/constants/messages";

async function POSTHandler(request: Request) {
	let formData: Record<string, unknown>;
	try {
		formData = await request.json();
	} catch {
		return Response.json(getMessage().TELEMETRY_SOURCE_INVALID_JSON, {
			status: 400,
		});
	}

	const timeLimit = formData.timeLimit as TimeLimit;
	const params: MetricParams = {
		timeLimit,
		selectedConfig: formData.selectedConfig,
		...(typeof formData.sourceId === "string" ? { sourceId: formData.sourceId } : {}),
		environment:
			typeof formData.environment === "string"
				? formData.environment
				: getRequestEnvironment(request),
	};

	const validationParam = validateMetricsRequest(
		params,
		validateMetricsRequestType.AGENT_LOOP
	);

	if (!validationParam.success) {
		return Response.json(validationParam.err, {
			status: 400,
		});
	}

	const res = await getAgentLoop(params);
	return Response.json(res);
}

export const POST = withRouteAccess("metrics.read", POSTHandler, {
	requireDbConfig: true,
});

"use client";

import { useCallback, useEffect } from "react";
import { getFilterDetails, getUpdateFilter } from "@/selectors/filter";
import { getPingStatus } from "@/selectors/database-config";
import { getCurrentProjectEnvironment } from "@/selectors/project";
import { useRootStore } from "@/store";
import useFetchWrapper from "@/utils/hooks/useFetchWrapper";
import { getFilterParamsForDashboard } from "@/helpers/client/filter";
import getMessage from "@/constants/messages";
import type { AgentLoopRow } from "@/lib/platform/llm/agent-loop";
import {
	asFiniteNumber,
	agentLoopCountLine,
	agentLoopTipMeaning,
	fillTemplate,
} from "@/lib/platform/agent-loop/format";
import {
	Tooltip,
	TooltipContent,
	TooltipProvider,
	TooltipTrigger,
} from "@/components/ui/tooltip";

export default function AgentLoopBar() {
	const m = getMessage();
	const filter = useRootStore(getFilterDetails);
	const pingStatus = useRootStore(getPingStatus);
	const environment = useRootStore(getCurrentProjectEnvironment);
	const updateFilter = useRootStore(getUpdateFilter);
	const { data, isFetched, isLoading, fireRequest, reset } = useFetchWrapper();
	const selected = Boolean(filter.selectedConfig.agentLoop);

	const fetchData = useCallback(async () => {
		fireRequest({
			body: JSON.stringify({
				...getFilterParamsForDashboard(filter),
				...(environment ? { environment } : {}),
			}),
			requestType: "POST",
			url: "/api/telemetry/llm/agent-loop",
			responseDataKey: "data[0]",
		});
	}, [environment, filter, fireRequest]);

	useEffect(() => {
		// Drop previous environment's counts — do not keep production chips
		// when the next environment's request fails or returns empty.
		reset();
	}, [environment, reset]);

	useEffect(() => {
		if (
			filter.timeLimit.start &&
			filter.timeLimit.end &&
			pingStatus === "success"
		) {
			fetchData();
		}
	}, [filter, fetchData, pingStatus, environment]);

	const row = (data || {}) as AgentLoopRow;
	if (row.unsupported) return null;

	const isLoadingData = isLoading || !isFetched || pingStatus === "pending";
	const count = asFiniteNumber(row.loops);
	const eligible = asFiniteNumber(row.tool_traces);
	const hasHits = !isLoadingData && count > 0;
	const ratio = fillTemplate(m.GENERATION_HEALTH_STAT_OF_ELIGIBLE, {
		count: isLoadingData ? "—" : count,
		eligible: isLoadingData ? "—" : eligible,
	});
	const meaning = agentLoopTipMeaning();
	const clickHint = selected
		? m.AGENT_LOOP_CLICK_TO_CLEAR
		: m.AGENT_LOOP_CLICK_TO_FILTER;

	const toggle = () => {
		updateFilter("selectedConfig", {
			agentLoop: selected ? false : true,
		});
	};

	return (
		<div
			className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1.5"
			aria-label={m.AGENT_LOOP_CHIP_GROUP}
		>
			<p className="text-[11px] font-medium text-stone-500 dark:text-stone-400">
				{m.AGENT_LOOP_CHIP_GROUP}
			</p>
			<TooltipProvider delayDuration={200}>
				<Tooltip>
					<TooltipTrigger asChild>
						<button
							type="button"
							aria-pressed={selected}
							aria-label={`${m.AGENT_LOOP_CHIP}. ${meaning} ${ratio}. ${clickHint}`}
							onClick={toggle}
							className={`inline-flex cursor-pointer items-center gap-1.5 rounded-md border px-2 py-1 text-[11px] tabular-nums transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/70 ${
								selected
									? "border-violet-700 bg-violet-700 text-white shadow-sm dark:border-violet-500 dark:bg-violet-600"
									: hasHits
										? "border-violet-300 bg-violet-50 font-medium text-violet-950 hover:border-violet-400 hover:bg-violet-100 dark:border-violet-800 dark:bg-violet-950/50 dark:text-violet-100 dark:hover:bg-violet-900/50"
										: "border-stone-300 bg-white text-stone-700 hover:border-stone-400 hover:bg-stone-50 dark:border-stone-600 dark:bg-stone-950 dark:text-stone-200 dark:hover:border-stone-400"
							}`}
						>
							<span>{m.AGENT_LOOP_CHIP}</span>
							<span className="font-medium">{ratio}</span>
						</button>
					</TooltipTrigger>
					<TooltipContent
						side="bottom"
						className="max-w-[260px] px-3 py-2 text-xs leading-relaxed"
					>
						{isLoadingData ? (
							m.LOADING
						) : (
							<div className="flex flex-col gap-1.5">
								<p className="font-medium text-stone-950 dark:text-stone-50">
									{meaning}
								</p>
								<p>{agentLoopCountLine(count, eligible)}</p>
								<p className="text-stone-500 dark:text-stone-400">
									{clickHint}
								</p>
							</div>
						)}
					</TooltipContent>
				</Tooltip>
			</TooltipProvider>
		</div>
	);
}

package cpupmu

import "strings"

// resolveEvents maps config PMUEvents names to hardware event specs and whether
// uncore/IMC memory bandwidth should be opened.
func resolveEvents(names []string) (core []EventSpec, wantUncore bool) {
	if len(names) == 0 {
		names = []string{"instructions", "cycles"}
	}
	seen := make(map[string]bool)
	for _, raw := range names {
		n := strings.ToLower(strings.TrimSpace(raw))
		if n == "" || seen[n] {
			continue
		}
		seen[n] = true
		switch {
		case n == "instructions" || n == "hw.cpu.instructions":
			core = append(core, EventSpec{Name: "instructions"})
		case n == "cycles" || n == "cpu_cycles" || n == "hw.cpu.cycles":
			core = append(core, EventSpec{Name: "cycles"})
		case strings.Contains(n, "memory_bandwidth") || n == "uncore" || strings.Contains(n, "memory.bandwidth") || n == "memory.io":
			wantUncore = true
		case strings.Contains(n, "cache"):
			core = append(core, cacheSpecsFor(n)...)
		case strings.Contains(n, "tlb"):
			core = append(core, tlbSpecsFor(n)...)
		case strings.Contains(n, "branch"):
			core = append(core, branchSpecsFor(n)...)
		}
	}
	return core, wantUncore
}

func cacheSpecsFor(n string) []EventSpec {
	level := "ll"
	op := "access"
	switch {
	case strings.Contains(n, "l1i"):
		level = "l1i"
	case strings.Contains(n, "l1d") || strings.Contains(n, "l1"):
		level = "l1d"
	case strings.Contains(n, "l2"):
		level = "l2"
	case strings.Contains(n, "l3") || strings.Contains(n, "ll"):
		level = "ll"
	}
	if strings.Contains(n, "miss") {
		op = "miss"
	}
	if n == "cache" || n == "cache_events" {
		return []EventSpec{
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "l1d", "hw.cpu.cache.op": "access"}},
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "l1d", "hw.cpu.cache.op": "miss"}},
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "ll", "hw.cpu.cache.op": "access"}},
			{Name: "cache", Attrs: map[string]string{"hw.cpu.cache.level": "ll", "hw.cpu.cache.op": "miss"}},
		}
	}
	return []EventSpec{{Name: "cache", Attrs: map[string]string{
		"hw.cpu.cache.level": level,
		"hw.cpu.cache.op":    op,
	}}}
}

func tlbSpecsFor(n string) []EventSpec {
	level := "dtlb"
	op := "miss"
	if strings.Contains(n, "itlb") {
		level = "itlb"
	}
	if strings.Contains(n, "access") {
		op = "access"
	}
	return []EventSpec{{Name: "tlb", Attrs: map[string]string{
		"hw.cpu.tlb.level": level,
		"hw.cpu.tlb.op":    op,
	}}}
}

func branchSpecsFor(n string) []EventSpec {
	if n == "branch" || n == "branch_events" {
		return []EventSpec{
			{Name: "branch", Attrs: map[string]string{"hw.cpu.branch.result": "retired"}},
			{Name: "branch", Attrs: map[string]string{"hw.cpu.branch.result": "mispredicted"}},
		}
	}
	result := "retired"
	if strings.Contains(n, "miss") || strings.Contains(n, "mispred") {
		result = "mispredicted"
	}
	return []EventSpec{{Name: "branch", Attrs: map[string]string{"hw.cpu.branch.result": result}}}
}

