"""
Server-side validation for label schemas.

Type immutability post-create is enforced server-side (the field is
documented as immutable but the entity does not enforce it on its own).

The validation surface is intentionally split:

- :py:func:`validate_schema_for_create` is called from the store layer's
  create path.
- :py:func:`validate_schema_for_update` is called from the store layer's
  patch path and enforces the immutable-field constraints (`type`).

This module is store-layer-internal; callers should not need to import
it directly.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from mlflow.exceptions import MlflowException

if TYPE_CHECKING:
    from mlflow.genai.label_schemas.label_schemas import (
        InputNumeric,
        InputPassFail,
        InputText,
        LabelSchema,
        LabelSchemaType,
    )


# Field length and count limits. `name` is the reviewer-facing label and
# the assessment key, so it can read as a prompt, e.g. "Is the answer
# correct?". Its bound matches the assessment key/name length used
# elsewhere in the tracking store (250) for consistency.
NAME_MIN_LENGTH = 1
NAME_MAX_LENGTH = 250

INSTRUCTION_MAX_LENGTH = 1000

PASS_FAIL_LABEL_MIN_LENGTH = 1
PASS_FAIL_LABEL_MAX_LENGTH = 64

CATEGORICAL_OPTIONS_MIN_COUNT = 1
CATEGORICAL_OPTIONS_MAX_COUNT = 10
CATEGORICAL_OPTION_MIN_LENGTH = 1
CATEGORICAL_OPTION_MAX_LENGTH = 64

TEXT_MAX_LENGTH_MIN = 1

_SUPPORTED_INPUT_TYPE_NAMES = ("InputPassFail", "InputCategorical", "InputNumeric", "InputText")

# The experiment's protected default question, seeded lazily by the store's list
# path (see `_ensure_default_label_schema`). Its name is reserved so a user
# schema can't masquerade as the default; it is undeletable and uneditable
# (enforced in the store + `validate_schema_for_update`).
DEFAULT_LABEL_SCHEMA_NAME = "Feedback"
DEFAULT_LABEL_SCHEMA_INSTRUCTION = "Share any feedback on this trace."


def _validate_not_reserved_name(name: str) -> None:
    if name.strip().lower() == DEFAULT_LABEL_SCHEMA_NAME.lower():
        raise MlflowException.invalid_parameter_value(
            f"`{name}` is reserved for the experiment's default question and cannot be used "
            "for another label schema."
        )


def _validate_name(name: str) -> None:
    if not isinstance(name, str) or len(name) < NAME_MIN_LENGTH:
        raise MlflowException.invalid_parameter_value(
            f"Label schema `name` must be a non-empty string; got {name!r}."
        )
    if len(name) > NAME_MAX_LENGTH:
        raise MlflowException.invalid_parameter_value(
            f"Label schema `name` must be at most {NAME_MAX_LENGTH} characters; got {len(name)}."
        )


def _validate_instruction(instruction: str | None) -> None:
    if instruction is None:
        return
    if not isinstance(instruction, str):
        cls_name = instruction.__class__.__name__
        raise MlflowException.invalid_parameter_value(
            f"Label schema `instruction` must be a string or None; got {cls_name}."
        )
    if len(instruction) > INSTRUCTION_MAX_LENGTH:
        raise MlflowException.invalid_parameter_value(
            f"Label schema `instruction` must be at most {INSTRUCTION_MAX_LENGTH} characters; "
            f"got {len(instruction)}."
        )


def _validate_pass_fail_input(input_obj: InputPassFail) -> None:
    for field_name in ("positive_label", "negative_label"):
        label = getattr(input_obj, field_name)
        if not isinstance(label, str) or len(label) < PASS_FAIL_LABEL_MIN_LENGTH:
            raise MlflowException.invalid_parameter_value(
                f"`InputPassFail.{field_name}` must be a non-empty string; got {label!r}."
            )
        if len(label) > PASS_FAIL_LABEL_MAX_LENGTH:
            raise MlflowException.invalid_parameter_value(
                f"`InputPassFail.{field_name}` must be at most {PASS_FAIL_LABEL_MAX_LENGTH} "
                f"characters; got {len(label)}."
            )
    if input_obj.positive_label == input_obj.negative_label:
        raise MlflowException.invalid_parameter_value(
            "`InputPassFail.positive_label` and `negative_label` must be distinct; "
            f"got {input_obj.positive_label!r} for both."
        )


def _validate_categorical_options(options) -> None:
    if not isinstance(options, list) or len(options) < CATEGORICAL_OPTIONS_MIN_COUNT:
        raise MlflowException.invalid_parameter_value(
            f"`InputCategorical.options` must be a non-empty list; got {options!r}."
        )
    if len(options) > CATEGORICAL_OPTIONS_MAX_COUNT:
        raise MlflowException.invalid_parameter_value(
            f"`InputCategorical.options` must have at most {CATEGORICAL_OPTIONS_MAX_COUNT} "
            f"entries; got {len(options)}."
        )
    seen: set[str] = set()
    for opt in options:
        if not isinstance(opt, str) or len(opt) < CATEGORICAL_OPTION_MIN_LENGTH:
            raise MlflowException.invalid_parameter_value(
                f"`InputCategorical.options` entries must be non-empty strings; got {opt!r}."
            )
        if len(opt) > CATEGORICAL_OPTION_MAX_LENGTH:
            raise MlflowException.invalid_parameter_value(
                f"`InputCategorical.options` entries must be at most "
                f"{CATEGORICAL_OPTION_MAX_LENGTH} characters; got {len(opt)} for {opt!r}."
            )
        if opt in seen:
            raise MlflowException.invalid_parameter_value(
                f"`InputCategorical.options` must be deduplicated; {opt!r} appears twice."
            )
        seen.add(opt)


def _validate_text_input(input_obj: InputText) -> None:
    max_length = input_obj.max_length
    if max_length is None:
        return
    if not isinstance(max_length, int) or isinstance(max_length, bool):
        raise MlflowException.invalid_parameter_value(
            f"`InputText.max_length` must be an int or None; got {max_length.__class__.__name__}."
        )
    if max_length < TEXT_MAX_LENGTH_MIN:
        raise MlflowException.invalid_parameter_value(
            f"`InputText.max_length` must be at least {TEXT_MAX_LENGTH_MIN}; got {max_length}."
        )


def _validate_numeric_input(input_obj: InputNumeric) -> None:
    for field_name in ("min_value", "max_value"):
        value = getattr(input_obj, field_name)
        # `bool` is a subclass of `int`; reject it so True/False can't slip
        # through as 1/0 bounds (mirrors `InputText.max_length`).
        if value is not None and (not isinstance(value, (int, float)) or isinstance(value, bool)):
            raise MlflowException.invalid_parameter_value(
                f"`InputNumeric.{field_name}` must be numeric or None; "
                f"got {value.__class__.__name__}."
            )

    if input_obj.min_value is not None and input_obj.max_value is not None:
        if input_obj.min_value >= input_obj.max_value:
            raise MlflowException.invalid_parameter_value(
                f"`InputNumeric.min_value` must be strictly less than `max_value`; "
                f"got min={input_obj.min_value}, max={input_obj.max_value}."
            )


def _validate_input(input_obj) -> None:
    # Imported here to avoid a circular import; the entity module is the
    # public surface and may import constants from this module later.
    from mlflow.genai.label_schemas.label_schemas import (
        InputCategorical,
        InputNumeric,
        InputPassFail,
        InputText,
    )

    if input_obj is None:
        raise MlflowException.invalid_parameter_value("Label schema `input` is required.")

    if isinstance(input_obj, InputPassFail):
        _validate_pass_fail_input(input_obj)
        return
    if isinstance(input_obj, InputCategorical):
        _validate_categorical_options(input_obj.options)
        if not isinstance(input_obj.multi_select, bool):
            raise MlflowException.invalid_parameter_value(
                f"`InputCategorical.multi_select` must be a bool; "
                f"got {input_obj.multi_select.__class__.__name__}."
            )
        return
    if isinstance(input_obj, InputNumeric):
        _validate_numeric_input(input_obj)
        return
    if isinstance(input_obj, InputText):
        _validate_text_input(input_obj)
        return

    cls_name = input_obj.__class__.__name__
    raise MlflowException.invalid_parameter_value(
        f"Label schema `input` of type {cls_name!r} is not supported. "
        f"Supported input types are: {', '.join(_SUPPORTED_INPUT_TYPE_NAMES)}."
    )


def _validate_schema_type(type_value) -> "LabelSchemaType":
    from mlflow.genai.label_schemas.label_schemas import LabelSchemaType

    if isinstance(type_value, LabelSchemaType):
        return type_value
    if isinstance(type_value, str):
        try:
            return LabelSchemaType(type_value)
        except ValueError as exc:
            raise MlflowException.invalid_parameter_value(
                f"Label schema `type` must be one of "
                f"{[t.value for t in LabelSchemaType]}; got {type_value!r}."
            ) from exc
    raise MlflowException.invalid_parameter_value(
        f"Label schema `type` must be a LabelSchemaType or string; got {type(type_value).__name__}."
    )


def _validate_enable_comment(enable_comment) -> None:
    # `bool` is a subclass of `int`, so guard against ints sneaking through.
    if not isinstance(enable_comment, bool):
        raise MlflowException.invalid_parameter_value(
            f"Label schema `enable_comment` must be a bool; "
            f"got {enable_comment.__class__.__name__}."
        )


def validate_schema_for_create(
    *,
    name: str,
    type,
    input,
    instruction: str | None = None,
    enable_comment: bool = False,
) -> None:
    """Validate fields supplied to ``create_label_schema``.

    Raises:
        MlflowException(INVALID_PARAMETER_VALUE): if any field violates the rules.
    """
    _validate_name(name)
    _validate_not_reserved_name(name)
    _validate_schema_type(type)
    _validate_instruction(instruction)
    _validate_enable_comment(enable_comment)
    _validate_input(input)


def _validate_input_immutable(existing_input, new_input) -> None:
    """Reject changes to a schema's input variant or ``multi_select`` on update.

    Both are fixed at creation: switching the variant or toggling
    ``multi_select`` would silently invalidate every label already collected
    under the schema. Within-variant edits (e.g. the categorical option list)
    remain allowed.
    """
    from mlflow.genai.label_schemas.label_schemas import InputCategorical

    if type(new_input) is not type(existing_input):
        raise MlflowException.invalid_parameter_value(
            "A label schema's input type cannot be changed after creation "
            f"(existing: {type(existing_input).__name__}, got: {type(new_input).__name__})."
        )
    if isinstance(new_input, InputCategorical) and bool(new_input.multi_select) != bool(
        existing_input.multi_select
    ):
        raise MlflowException.invalid_parameter_value(
            "`InputCategorical.multi_select` cannot be changed after creation."
        )


def validate_schema_for_update(
    *,
    existing: LabelSchema,
    name: str | None,
    instruction: str | None,
    enable_comment: bool | None,
    input,
) -> None:
    """Validate fields supplied to ``update_label_schema``.

    ``type`` immutability is enforced implicitly (no ``type`` parameter is
    accepted). The input variant and a categorical schema's ``multi_select``
    flag are likewise immutable — switching variants or toggling
    ``multi_select`` would silently invalidate already-collected labels —
    while within-variant edits (e.g. the option list) remain allowed.
    Validates whichever fields are non-None.

    Raises:
        MlflowException(INVALID_PARAMETER_VALUE): if any field violates the rules.
    """
    if existing.is_default:
        raise MlflowException.invalid_parameter_value(
            "The experiment's default question cannot be edited."
        )
    if name is not None:
        _validate_name(name)
        _validate_not_reserved_name(name)
    if instruction is not None:
        _validate_instruction(instruction)
    if enable_comment is not None:
        _validate_enable_comment(enable_comment)
    if input is not None:
        _validate_input(input)
        _validate_input_immutable(existing.input, input)

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "PR Review Payload",
  "description": "Payload emitted by the pr-review skill and posted via POST /repos/{owner}/{repo}/pulls/{pull_number}/reviews.",
  "type": "object",
  "additionalProperties": false,
  "required": ["event", "body", "comments"],
  "properties": {
    "event": {
      "description": "Review action, determined by the comments: COMMENT when at least one comment carries the CRITICAL prefix, APPROVE otherwise. Enforced by the conditional below.",
      "type": "string",
      "enum": ["APPROVE", "COMMENT"]
    },
    "body": {
      "description": "Concise top-level review summary in 2-3 sentences capturing the overall assessment. Do not restate individual findings (those belong in inline comments).",
      "type": "string",
      "minLength": 1
    },
    "commit_id": {
      "description": "Head commit SHA being reviewed. Optional; GitHub defaults to the latest commit when omitted.",
      "type": "string",
      "pattern": "^[0-9a-f]{40}$"
    },
    "comments": {
      "description": "Inline review comments. Empty array is allowed (e.g., clean APPROVE).",
      "type": "array",
      "items": { "$ref": "#/$defs/comment" }
    }
  },
  "if": {
    "properties": {
      "comments": { "contains": { "$ref": "#/$defs/criticalComment" } }
    },
    "required": ["comments"]
  },
  "then": { "properties": { "event": { "const": "COMMENT" } } },
  "else": { "properties": { "event": { "const": "APPROVE" } } },
  "$defs": {
    "side": {
      "type": "string",
      "enum": ["LEFT", "RIGHT"]
    },
    "criticalPrefix": {
      "type": "string",
      "pattern": "^🔴 \\*\\*CRITICAL:\\*\\* "
    },
    "moderatePrefix": {
      "type": "string",
      "pattern": "^🟡 \\*\\*MODERATE:\\*\\* "
    },
    "nitPrefix": {
      "type": "string",
      "pattern": "^🟢 \\*\\*NIT:\\*\\* "
    },
    "criticalComment": {
      "type": "object",
      "properties": { "body": { "$ref": "#/$defs/criticalPrefix" } },
      "required": ["body"]
    },
    "comment": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "body", "line", "side"],
      "properties": {
        "path": {
          "description": "File path relative to the repo root. Must be a file with at least one hunk in the PR diff.",
          "type": "string",
          "minLength": 1
        },
        "body": {
          "description": "Comment body. Must start with '🔴 **CRITICAL:** ', '🟡 **MODERATE:** ', or '🟢 **NIT:** '.",
          "anyOf": [
            { "$ref": "#/$defs/criticalPrefix" },
            { "$ref": "#/$defs/moderatePrefix" },
            { "$ref": "#/$defs/nitPrefix" }
          ]
        },
        "line": {
          "description": "Anchor line. Must be inside a diff hunk on the chosen side (added/context on RIGHT, deleted/context on LEFT). For multi-line comments, this is the last line of the range.",
          "type": "integer",
          "minimum": 1
        },
        "side": {
          "description": "RIGHT for the post-merge file (added/context lines), LEFT for the pre-change file (deleted/context lines). RIGHT is the common case.",
          "$ref": "#/$defs/side"
        },
        "start_line": {
          "description": "First line of a multi-line range. Same hunk requirement as `line`, and must be < line. Must be set together with start_side.",
          "type": "integer",
          "minimum": 1
        },
        "start_side": {
          "description": "Side for start_line. Must be set together with start_line.",
          "$ref": "#/$defs/side"
        }
      },
      "dependentRequired": {
        "start_line": ["start_side"],
        "start_side": ["start_line"]
      }
    }
  }
}

async function getMaintainers({ github, context }) {
  const collaborators = await github.paginate(github.rest.repos.listCollaborators, {
    owner: context.repo.owner,
    repo: context.repo.repo,
  });
  return collaborators
    .filter(({ role_name }) => ["admin", "maintain"].includes(role_name))
    .map(({ login }) => login)
    .sort();
}

const EXEMPTION_RULES = [
  // Exemption for GenAI evaluation PRs.
  {
    authors: ["alkispoly-db", "AveshCSingh", "danielseong1", "smoorjani", "SomtochiUmeh", "xsh310"],
    allowedPatterns: [
      /^mlflow\/genai\//,
      /^tests\/genai\//,
      /^docs\//,
      /^mlflow\/entities\/(assessment|dataset|evaluation|scorer)/,
    ],
    excludedPatterns: [/^mlflow\/genai\/(agent_server|git_versioning|prompts|optimize)\//],
  },
  // Exemption for UI PRs.
  {
    authors: ["daniellok-db", "danielseong1", "hubertzub-db"],
    allowedPatterns: [/^mlflow\/server\/js\//],
  },
];

function matchesAnyPattern(path, patterns) {
  if (!patterns) {
    return false;
  }
  return patterns.some((pattern) => pattern.test(path));
}

function isAllowedPath(path, rule) {
  return (
    matchesAnyPattern(path, rule.allowedPatterns) && !matchesAnyPattern(path, rule.excludedPatterns)
  );
}

function isExempted(authorLogin, files) {
  let filesToCheck = files;
  for (const rule of EXEMPTION_RULES) {
    if (rule.authors.includes(authorLogin)) {
      filesToCheck = filesToCheck.filter(
        ({ filename, previous_filename }) =>
          // Keep files where NOT all before/after file paths are allowed by the rule.
          ![filename, previous_filename].filter(Boolean).every((path) => isAllowedPath(path, rule))
      );
      if (filesToCheck.length === 0) {
        return true;
      }
    }
  }
  return false;
}

function hasAnyApproval(reviews) {
  return reviews.some(({ state }) => state === "APPROVED");
}

module.exports = async ({ github, context, core }) => {
  const { pull_request: pr } = context.payload;
  const authorLogin = pr?.user?.login;
  if (["mlflow-app[bot]", "dependabot[bot]"].includes(authorLogin)) {
    return;
  }

  const maintainers = await getMaintainers({ github, context });
  const reviews = await github.paginate(github.rest.pulls.listReviews, {
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number: context.issue.number,
  });
  const APPROVED_BOTS = new Set(["nailaopus[bot]"]);
  const maintainerApproved = reviews.some(
    ({ state, user }) =>
      state === "APPROVED" &&
      // GitHub returns `user: null` on reviews from accounts that have since
      // been deleted; skip them rather than crashing on `user.login`.
      user &&
      (maintainers.includes(user.login) ||
        (user.type.toLowerCase() === "bot" && APPROVED_BOTS.has(user.login)))
  );

  const files = await github.paginate(github.rest.pulls.listFiles, {
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number: context.issue.number,
  });

  if (isExempted(authorLogin, files)) {
    if (!hasAnyApproval(reviews)) {
      core.setFailed(
        "PR from exempted author needs at least one approval (maintainer approval not required)."
      );
    }
    return;
  }

  if (!maintainerApproved) {
    const maintainerList = maintainers.join(", ");
    const message = `This PR requires an approval from at least one of the core maintainers: ${maintainerList}.`;
    core.setFailed(message);
  }
};

