/**
 * Daemon supervisor - handles the "is the uploader daemon alive? if not,
 * spawn one" check invoked by `MlflowWalSpanExporter` on each WAL append.
 */

import { spawn } from 'node:child_process';
import { createConnection } from 'node:net';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { getLockSocketPath } from './paths';

const PROBE_TIMEOUT_MS = 1000;

/**
 * Upper bound on how long {@link ensureDaemon} waits for a freshly
 * spawned daemon to bind its lock socket.
 */
const SPAWN_BIND_WAIT_TIMEOUT_MS = 2000;
const SPAWN_BIND_WAIT_POLL_MS = 50;

/**
 * Probe the daemon's liveness lock with a short timeout.
 *
 * Returns:
 * - `true` if the socket/pipe at `getLockSocketPath()` is currently
 *   accepting connections (i.e. a daemon has bound it).
 * - `false` on any error (ENOENT — no socket file; ECONNREFUSED — a
 *   stale socket file with no listener) or on probe timeout.
 */
export function isDaemonAlive(): Promise<boolean> {
  return new Promise((resolve) => {
    const socketPath = getLockSocketPath();
    const socket = createConnection(socketPath);

    let settled = false;
    const finish = (alive: boolean): void => {
      if (settled) {
        return;
      }
      settled = true;
      socket.destroy();
      resolve(alive);
    };

    const timer = setTimeout(() => finish(false), PROBE_TIMEOUT_MS);

    socket.once('connect', () => {
      clearTimeout(timer);
      finish(true);
    });
    socket.once('error', () => {
      clearTimeout(timer);
      finish(false);
    });
  });
}

/**
 * Resolve the absolute path of the daemon entry point.
 *
 * Precedence:
 *   1. `MLFLOW_TRACE_DAEMON_EXECUTABLE` env var — used by tests and
 *      advanced operators who want to override the bundled daemon.
 *   2. The bundled daemon at `<@mlflow/core install dir>/bundle/daemon.cjs`.
 */
export function resolveDaemonEntry(): string {
  const override = process.env.MLFLOW_TRACE_DAEMON_EXECUTABLE;
  if (override !== undefined && override !== '') {
    return override;
  }
  // DO NOT collapse this into a plain string literal. esbuild
  // evaluates `require.resolve(literal)` at build time and bakes the
  // resolved (developer-machine) path directly into the shipped
  // bundle. On end users' machines that path does not exist, so
  // `spawn` fails with ENOENT and traces silently stop uploading
  // while the WAL grows unbounded. The string-concat hides the
  // specifier from esbuild's AST scanner so the lookup runs at
  // runtime against the user's own node_modules.
  //
  // This defense lives in the supervisor (not in consumers' esbuild
  // configs) because every plugin-marketplace consumer must bundle
  // @mlflow/core into their hook to ship as a self-contained file.
  const pkgJsonModule = '@mlflow' + '/core' + '/package.json';
  const requireFromHere = createRequire(__filename);
  const pkgJsonPath = requireFromHere.resolve(pkgJsonModule);
  return join(dirname(pkgJsonPath), 'bundle', 'daemon.cjs');
}

/**
 * Fork a detached daemon process. Assumes no daemon is currently bound —
 * the caller is responsible for guarding with {@link isDaemonAlive}.
 */
export function spawnDaemon(): void {
  const entry = resolveDaemonEntry();
  const child = spawn(process.execPath, [entry], {
    detached: true,
    stdio: 'ignore',
    env: process.env,
  });

  child.once('error', (err) => {
    console.error(`[mlflow][wal] daemon spawn failed (entry=${entry}):`, err);
  });

  child.once('exit', (code, signal) => {
    if (code != null && code !== 0) {
      console.error(
        `[mlflow][wal] daemon exited unexpectedly: entry=${entry} code=${code} signal=${signal ?? 'none'}`,
      );
    }
  });
  child.unref();
}

let spawnInFlight: Promise<void> | null = null;

/**
 * Poll {@link isDaemonAlive} until it returns true or `timeoutMs`
 * elapses. Does not throw on timeout — the IPC client's own retry
 * loop will surface any persistent connection failure.
 */
async function waitForDaemonBind(timeoutMs: number, pollIntervalMs: number): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const remainingMs = deadline - Date.now();

    let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
    const result = await Promise.race<boolean | 'timeout'>([
      isDaemonAlive(),
      new Promise((resolve) => {
        timeoutHandle = setTimeout(() => resolve('timeout'), remainingMs);
      }),
    ]);
    clearTimeout(timeoutHandle);
    if (result === true || result === 'timeout') {
      return;
    }
    const sleepMs = Math.min(pollIntervalMs, deadline - Date.now());
    if (sleepMs > 0) {
      await new Promise<void>((resolve) => setTimeout(resolve, sleepMs));
    }
  }
}

/**
 * Ensure a daemon is alive; spawn one if not.
 */
export function ensureDaemon(): Promise<void> {
  if (spawnInFlight != null) {
    return spawnInFlight;
  }
  const inFlight = (async () => {
    try {
      if (await isDaemonAlive()) {
        return;
      }
      spawnDaemon();
      await waitForDaemonBind(SPAWN_BIND_WAIT_TIMEOUT_MS, SPAWN_BIND_WAIT_POLL_MS);
    } catch (err) {
      console.error('[mlflow][wal] ensureDaemon failed:', err);
    } finally {
      spawnInFlight = null;
    }
  })();
  spawnInFlight = inFlight;
  return inFlight;
}

import {
  Alert,
  Empty,
  Input,
  Modal,
  SearchIcon,
  Table,
  TableCell,
  TableHeader,
  TableRow,
  TableRowSelectCell,
  TableSkeletonRows,
  useDesignSystemTheme,
} from '@databricks/design-system';
import type { ColumnDef } from '@tanstack/react-table';
import { flexRender, getCoreRowModel } from '@tanstack/react-table';
import { useReactTable_unverifiedWithReact18 as useReactTable } from '@databricks/web-shared/react-table';
import { FormattedMessage, useIntl } from 'react-intl';
import { useInfiniteScrollFetch } from '../hooks/useInfiniteScrollFetch';
import { useSearchEvaluationDatasets } from '../hooks/useSearchEvaluationDatasets';
import type { EvaluationDataset } from '../types';
import { useCallback, useState } from 'react';
import { getModelTraceId } from '@databricks/web-shared/model-trace-explorer';
import type { ModelTrace } from '@databricks/web-shared/model-trace-explorer';
import { compact } from 'lodash';
import { extractDatasetInfoFromTraces } from '../utils/datasetUtils';
import { useUpsertDatasetRecordsMutation } from '../hooks/useUpsertDatasetRecordsMutation';
import { CreateEvaluationDatasetButton } from './CreateEvaluationDatasetButton';
import { useFetchTraces } from '../hooks/useFetchTraces';
import { useCheckMultiturnDatasets } from '../hooks/useCheckMultiturnDatasets';
import Utils from '@mlflow/mlflow/src/common/utils/Utils';

const columns: ColumnDef<EvaluationDataset, string>[] = [
  {
    id: 'name',
    accessorKey: 'name',
    header: 'Name',
  },
];

export const ExportTracesToDatasetModal = ({
  experimentId,
  visible,
  setVisible,
  selectedTraceInfos,
}: {
  experimentId: string;
  visible: boolean;
  setVisible: (visible: boolean) => void;
  selectedTraceInfos: ModelTrace['info'][];
}) => {
  const { theme } = useDesignSystemTheme();
  const intl = useIntl();
  const [searchFilter, setSearchFilter] = useState('');
  const [internalSearchFilter, setInternalSearchFilter] = useState(searchFilter);

  const traceIds = selectedTraceInfos.map((traceInfo) =>
    // hacky wrap just to get the id, as this util function expects
    // the full trace, which is not available in the trace table
    getModelTraceId({ info: traceInfo, data: { spans: [] } }),
  );
  const { isLoading: isLoadingTraces, refetch: refetchTraces } = useFetchTraces({
    traceIds,
  });
  const [isExporting, setIsExporting] = useState(false);

  const {
    data: datasets,
    isLoading: isLoadingDatasets,
    isFetching,
    fetchNextPage,
    hasNextPage,
  } = useSearchEvaluationDatasets({ experimentId, nameFilter: searchFilter });

  const isInitialLoading = isLoadingDatasets || isLoadingTraces;

  const fetchMoreOnBottomReached = useInfiniteScrollFetch({
    isFetching,
    hasNextPage: hasNextPage ?? false,
    fetchNextPage,
  });

  const table = useReactTable(
    'mlflow/server/js/src/experiment-tracking/pages/experiment-evaluation-datasets/components/ExportTracesToDatasetModal.tsx',
    {
      columns,
      getRowId: (row) => row.dataset_id,
      data: datasets ?? [],
      getCoreRowModel: getCoreRowModel(),
      enableColumnResizing: false,
    },
  );

  const selectedDatasets = table.getSelectedRowModel().rows.map((row) => row.original);
  const selectedDatasetIds = selectedDatasets.map((dataset) => dataset.dataset_id);
  const { data: hasMultiturnDataset = false, isLoading: isCheckingMultiturn } = useCheckMultiturnDatasets({
    datasetIds: selectedDatasetIds,
  });

  const {
    upsertDatasetRecordsMutationAsync,
    invalidateAfterUpsert,
    isLoading: isUpsertingDatasetRecords,
  } = useUpsertDatasetRecordsMutation();

  const handleExport = useCallback(async () => {
    setIsExporting(true);
    try {
      // This modal stays mounted, so FETCH_TRACES can be from before the user
      // added expectations. Refetch at export time so the dataset snapshot
      // includes current assessments.
      const { data: freshTraces } = await refetchTraces({ throwOnError: true });
      const datasetRowsToExport = extractDatasetInfoFromTraces(compact(freshTraces));
      const results = await Promise.allSettled(
        selectedDatasets.map((dataset) =>
          upsertDatasetRecordsMutationAsync({
            datasetId: dataset.dataset_id,
            records: JSON.stringify(datasetRowsToExport),
          }),
        ),
      );
      const succeededDatasetIds = selectedDatasets.flatMap((dataset, index) =>
        results[index].status === 'fulfilled' ? [dataset.dataset_id] : [],
      );
      invalidateAfterUpsert(succeededDatasetIds);
      if (results.some((result) => result.status === 'rejected')) {
        throw new Error('Failed to export traces to datasets.');
      }
      setVisible(false);
    } catch {
      Utils.displayGlobalErrorNotification(
        intl.formatMessage({
          defaultMessage: 'Failed to export traces to datasets.',
          description: 'Error toast when exporting traces to evaluation datasets fails',
        }),
      );
    } finally {
      setIsExporting(false);
    }
  }, [selectedDatasets, upsertDatasetRecordsMutationAsync, invalidateAfterUpsert, refetchTraces, intl, setVisible]);

  return (
    <Modal
      componentId="mlflow.export-traces-to-dataset-modal"
      visible={visible}
      onCancel={() => setVisible(false)}
      okText={<FormattedMessage defaultMessage="Export" description="Export traces to dataset modal action button" />}
      okButtonProps={{
        disabled:
          isLoadingTraces || isExporting || selectedDatasets.length === 0 || hasMultiturnDataset || isCheckingMultiturn,
        loading: isUpsertingDatasetRecords || isExporting,
      }}
      onOk={handleExport}
      title={
        <FormattedMessage
          defaultMessage="Export traces to datasets"
          description="Export traces to dataset modal title"
        />
      }
      zIndex={theme.options.zIndexBase + 10}
    >
      <div css={{ height: '500px', overflow: 'hidden' }}>
        {hasMultiturnDataset && (
          <Alert
            componentId="mlflow.export-traces-to-dataset-modal.multiturn-error"
            type="error"
            css={{ marginBottom: theme.spacing.sm }}
            message={
              <FormattedMessage
                defaultMessage="Exporting to multi-turn datasets is not yet supported."
                description="Error message when trying to export traces to a multiturn dataset"
              />
            }
            closable={false}
          />
        )}
        <div css={{ display: 'flex', gap: theme.spacing.sm, alignItems: 'center', marginBottom: theme.spacing.sm }}>
          <Input
            allowClear
            placeholder="Search by dataset name"
            value={internalSearchFilter}
            onChange={(e) => {
              setInternalSearchFilter(e.target.value);
              if (!e.target.value) {
                setSearchFilter(e.target.value);
              }
            }}
            onClear={() => {
              setInternalSearchFilter('');
              setSearchFilter('');
            }}
            onPressEnter={() => setSearchFilter(internalSearchFilter)}
            componentId="mlflow.eval-datasets.search-input"
            css={{ flex: 1 }}
            prefix={<SearchIcon />}
          />
          <CreateEvaluationDatasetButton experimentId={experimentId} />
        </div>
        <Table
          scrollable
          onScroll={(e) => fetchMoreOnBottomReached(e.currentTarget as HTMLDivElement)}
          someRowsSelected={table.getIsSomeRowsSelected() || table.getIsAllRowsSelected()}
          empty={
            !isLoadingDatasets &&
            !isFetching &&
            datasets.length === 0 && (
              <Empty
                description={
                  <FormattedMessage
                    defaultMessage="No evaluation datasets found"
                    description="Empty state for the evaluation datasets page"
                  />
                }
              />
            )
          }
        >
          <TableRow isHeader>
            <TableRowSelectCell
              componentId="mlflow.export-traces-to-dataset-modal.header-checkbox"
              checked={table.getIsAllRowsSelected()}
              indeterminate={table.getIsSomeRowsSelected()}
              onChange={table.getToggleAllRowsSelectedHandler()}
            />
            {table.getLeafHeaders().map((header) => (
              <TableHeader
                key={header.id}
                componentId="mlflow.eval-datasets.column-header"
                header={header}
                column={header.column}
                css={{ width: header.column.columnDef.size, maxWidth: header.column.columnDef.maxSize }}
              >
                {flexRender(header.column.columnDef.header, header.getContext())}
              </TableHeader>
            ))}
          </TableRow>
          {!isInitialLoading &&
            table.getRowModel().rows.map((row) => (
              <TableRow key={row.id}>
                <div>
                  <TableRowSelectCell
                    componentId="mlflow.export-traces-to-dataset-modal.row-checkbox"
                    checked={row.getIsSelected()}
                    onChange={row.getToggleSelectedHandler()}
                  />
                </div>
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    css={{ width: cell.column.columnDef.size, maxWidth: cell.column.columnDef.maxSize }}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          {(isInitialLoading || isFetching) && <TableSkeletonRows table={table} />}
        </Table>
      </div>
    </Modal>
  );
};

import { isNil } from 'lodash';

import { Empty, Typography, useDesignSystemTheme, XCircleIcon } from '@databricks/design-system';
import { FormattedMessage } from '@databricks/i18n';

import { CodeSnippetRenderMode, type ModelTraceSpanNode, type SearchMatch } from '../ModelTrace.types';
import { getEventAttributeKey } from '../ModelTraceExplorer.utils';
