export function ModelTraceExplorerEventsTab({
  activeSpan,
  searchFilter,
  activeMatch,
}: {
  activeSpan: ModelTraceSpanNode;
  searchFilter: string;
  activeMatch: SearchMatch | null;
}) {
  const { theme } = useDesignSystemTheme();
  const { events } = activeSpan;
  const isActiveMatchSpan = !isNil(activeMatch) && activeMatch.span.key === activeSpan.key;

  if (!Array.isArray(events) || events.length === 0) {
    return (
      <div css={{ marginTop: theme.spacing.sm }}>
        <SpanModelCostBadge css={{ marginLeft: theme.spacing.sm }} activeSpan={activeSpan} />
        <div css={{ marginTop: theme.spacing.sm }}>
          <Empty
            description={
              <FormattedMessage
                defaultMessage="No events found"
                description="Empty state for the events tab in the model trace explorer. Events are logs of arbitrary things (e.g. exceptions) that occur during the execution of a span, and can be user-defined."
              />
            }
          />
        </div>
      </div>
    );
  }

  return (
    <div>
      <SpanModelCostBadge
        css={{ marginLeft: theme.spacing.sm, marginBlock: theme.spacing.sm }}
        activeSpan={activeSpan}
      />
      {events.map((event, index) => {
        const attributes = event.attributes;
        const title =
          event.name === 'exception' ? (
            <>
              <XCircleIcon css={{ marginRight: theme.spacing.sm }} color="danger" />
              <Typography.Text color="error" bold>
                Exception
              </Typography.Text>
            </>
          ) : (
            event.name
          );

        if (!attributes) return null;

        return (
          <ModelTraceExplorerCollapsibleSection
            key={`${event.name}-${index}`}
            css={{
              marginBottom: theme.spacing.sm,
              // avoid double border clashing with the tab bar
              '& > div:first-of-type': { borderTop: 'none' },
            }}
            sectionKey={event.name}
            title={title}
            withBorder
          >
            <div css={{ display: 'flex', flexDirection: 'column', gap: theme.spacing.sm }}>
              {Object.keys(attributes).map((attribute) => {
                const key = getEventAttributeKey(event.name, index, attribute);

                return (
                  <ModelTraceExplorerCodeSnippet
                    key={key}
                    title={attribute}
                    data={JSON.stringify(attributes[attribute], null, 2)}
                    searchFilter={searchFilter}
                    activeMatch={activeMatch}
                    containsActiveMatch={
                      isActiveMatchSpan && activeMatch.section === 'events' && activeMatch.key === key
                    }
                    initialRenderMode={CodeSnippetRenderMode.TEXT}
                  />
                );
              })}
            </div>
          </ModelTraceExplorerCollapsibleSection>
        );
      })}
    </div>
  );
}

import * as fs from 'fs';
import { XMLParser } from 'fast-xml-parser';
import fetch from 'node-fetch';

async function readSitemap(input: string): Promise<string> {
  if (/^https?:\/\//.test(input)) {
    const res = await fetch(input);
    if (!res.ok) {
      const responseBody = await res.text();
      throw new Error(`Failed to fetch ${input}: ${res.status} ${res.statusText}. Response body: ${responseBody}`);
    }
    return await res.text();
  } else {
    return await fs.promises.readFile(input, 'utf8');
  }
}

function normalizePath(url: string): string {
  const idx = url.indexOf('/latest/');
  return idx >= 0 ? url.slice(idx + 'latest/'.length) : url;
}

async function parseSitemap(input: string): Promise<Map<string, string>> {
  const xml = await readSitemap(input);
  const parser = new XMLParser();
  const parsed = parser.parse(xml);
  const urlset = parsed.urlset.url as { loc: string }[];

  const urlMap = new Map<string, string>();
  for (const { loc } of urlset) {
    const normalized = normalizePath(loc);
    urlMap.set(normalized, loc);
  }
  return urlMap;
}

function compareSitemaps(mapA: Map<string, string>, mapB: Map<string, string>) {
  const onlyInA: string[] = [];
  const onlyInB: string[] = [];
  const inBoth: string[] = [];

  for (const [url, _] of mapA) {
    if (!mapB.has(url)) {
      onlyInA.push(url);
    } else {
      inBoth.push(url);
    }
  }

  for (const url of mapB.keys()) {
    if (!mapA.has(url)) {
      onlyInB.push(url);
    }
  }

  return { onlyInA, onlyInB, inBoth };
}

(async () => {
  const fileA = process.argv[2];
  const fileB = process.argv[3];

  if (!fileA || !fileB) {
    console.error('Usage: tsx compare-sitemaps.ts <fileA|urlA> <fileB|urlB>');
    process.exit(1);
  }

  const [mapA, mapB] = await Promise.all([parseSitemap(fileA), parseSitemap(fileB)]);

  const { onlyInA, onlyInB, inBoth } = compareSitemaps(mapA, mapB);

  console.log(`URLs in both: ${inBoth.length}`);
  console.log(`Only in ${fileA}: ${onlyInA.length}`);
  onlyInA.forEach((url) => console.log(`  ${url}`));

  console.log(`Only in ${fileB}: ${onlyInB.length}`);
  onlyInB.forEach((url) => console.log(`  ${url}`));
})();

