package leet

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/wandb/wandb/core/internal/observability"
)

const (
	quitConfirmStatusBrowse = "Unsaved changes — press q/esc/ctrl+c again to discard, or s to save & quit."
	quitConfirmStatusEdit   = "Unsaved changes — press q/ctrl+c again to discard, or Esc to keep editing."

	ConfigEditorPalettePreviewBlock = "█"
)

// ConfigEditorParams configures a [ConfigEditor].
type ConfigEditorParams struct {
	// Config is the config manager to read from and persist to.
	// If nil, a default manager is created from the standard config path.
	Config *ConfigManager

	// Logger is used for error reporting.
	// If nil, a no-op logger is used.
	Logger *observability.CoreLogger
}

// ConfigEditor is a standalone Bubble Tea model for interactively editing
// LEET's persisted configuration.
//
// Launch it with `wandb leet config`. It reads the current config from
// disk, presents every editable field in a navigable table, and writes changes
// back atomically on save.
//
// # Schema derivation
//
// The editor schema is derived from the [Config] struct at init time via
// [buildConfigEditorFields]. Supported field types are bool, int, and
// string enums (string fields must declare an enum provider via
// `leet:"options=<provider>"`). See [configeditorfields.go] for the full
// tag grammar and reflection logic.
//
// # Modes
//
// The editor operates in one of three modes:
//
//   - Browse: navigate settings with ↑/↓, quick-adjust with ←/→,
//     toggle bools with Space, or press Enter to open a type-specific
//     sub-editor.
//   - Enum select: pick from a list of allowed values (opened from
//     enum fields).
//   - Int edit: type a numeric value with validation against min/max
//     constraints (opened from int fields).
//
// # Key bindings
//
// Browse mode:
//   - ↑/↓ or k/j: select setting
//   - Enter: open sub-editor for the selected field
//   - ←/→ or h/l: quick-adjust (toggle bool, bump int, cycle enum)
//   - Space: toggle bool (otherwise acts like Enter)
//   - s / ctrl+s: save and quit
//   - q / esc / ctrl+c: quit (prompts if there are unsaved changes)
//
// Enum select / Int edit:
//   - Enter: apply
//   - Esc: cancel (return to browse)
//
// Implements [tea.Model].
type ConfigEditor struct {
	// cfg is the config manager used to read the initial snapshot and
	// persist changes on save.
	cfg    *ConfigManager
	logger *observability.CoreLogger

	// original holds the config snapshot taken at editor creation.
	// Compared with draft to detect unsaved changes.
	original Config

	// draft is the working copy that the user edits. On save it is
	// written to disk via cfg; on quit it is discarded.
	draft Config

	// fields is the flat list of editable settings derived from [Config]
	// struct tags. See [buildConfigEditorFields].
	fields []configField

	// selected is the index into fields of the currently highlighted row.
	selected int

	// width and height cache the latest terminal dimensions for layout.
	width  int
	height int

	// mode is the current interaction state (browse, enum select, or int edit).
	mode editorMode

	// enum holds transient state for the enum picker modal (active when
	// mode == modeEnumSelect).
	enum enumSelectState

	// intE holds transient state for the integer input modal (active when
	// mode == modeIntEdit).
	intE intEditState

	// confirmQuit is set after the first quit attempt with unsaved changes.
	// A second quit attempt while confirmQuit is true exits unconditionally.
	confirmQuit bool

	// status is an ephemeral message shown in the footer (e.g. unsaved
	// changes warning, save-failure error). Cleared on the next key press.
	status string
}

// NewConfigEditor creates a [ConfigEditor] from the given params.
//
// It snapshots the current config from disk and builds the editable field
// schema via [buildConfigEditorFields]. If no editable fields are found
// (indicating a schema bug), an error is logged but the editor is still
// returned so the caller sees the empty-state UI.
func NewConfigEditor(params ConfigEditorParams) *ConfigEditor {
	logger := params.Logger
	if logger == nil {
		logger = observability.NewNoOpLogger()
	}

	cfg := params.Config
	if cfg == nil {
		cfg = NewConfigManager(leetConfigPath(), logger)
	}

	orig := cfg.Snapshot()
	fields := buildConfigEditorFields()
	if len(fields) == 0 {
		logger.Error("config editor: no editable config fields found")
	}

	return &ConfigEditor{
		cfg:      cfg,
		logger:   logger,
		original: orig,
		draft:    orig,
		fields:   fields,
		selected: 0,
		mode:     modeBrowse,
	}
}

// editorMode tracks which interaction state the editor is in.
type editorMode int

const (
	modeUnknown editorMode = iota
	modeBrowse
	modeEnumSelect
	modeIntEdit
)

// configFieldKind distinguishes the three supported field types.
type configFieldKind int

const (
	fieldUnknown configFieldKind = iota
	fieldBool
	fieldInt
	fieldEnum
)

// enumProvider identifies a registered options source for enum fields.
//
// Provider names appear in struct tags as `leet:"options=<name>"`;
// [parseEnumProvider] converts the tag string to a typed constant, and
// [enumProvider.options] returns the allowed values. Adding a new enum
// field requires a new constant here and a case in each of those two
// functions.
type enumProvider int

const (
	enumProviderUndefined    enumProvider = iota
	enumProviderColorSchemes              // color palette names
	enumProviderColorModes                // per_series | per_plot
	enumProviderStartupModes              // workspace_latest | single_run_latest
	enumProviderChartGuides               // off | dots | horizontal
)

// options returns the allowed values for this provider.
//
// Returns nil for [enumProviderUndefined], which causes the field to be
// skipped during schema construction.
func (p enumProvider) options() []string {
	switch p {
	case enumProviderColorSchemes:
		return availableColorSchemes()
	case enumProviderColorModes:
		return []string{ColorModePerSeries, ColorModePerPlot}
	case enumProviderStartupModes:
		return []string{StartupModeWorkspaceLatest, StartupModeSingleRunLatest}
	case enumProviderChartGuides:
		return []string{ChartGuidesOff, ChartGuidesDots, ChartGuidesHorizontal}
	default:
		return nil
	}
}

// configField describes a single editable setting.
//
// Each field carries typed getter/setter closures that operate on
// [Config] values by index path, plus display metadata (label,
// description, JSON key) and type-specific constraints (min/max
// for ints, allowed options for enums).
type configField struct {
	// Label is the human-readable name shown in the settings table
	// (e.g. "Metrics grid rows").
	Label string

	// JSONKey is the dot-joined config path used in the footer and for
	// identifying the field in tests (e.g. "metrics_grid.rows").
	JSONKey string

	// Description is the help text shown in the footer when this field
	// is selected.
	Description string

	// Kind indicates the field type and determines which getter/setter
	// pair and sub-editor are used.
	Kind configFieldKind

	// getBool and setBool are the typed accessors for bool fields.
	getBool func(Config) bool
	setBool func(*Config, bool)

	// getInt and setInt are the typed accessors for int fields.
	getInt func(Config) int
	setInt func(*Config, int)

	// min is the lower bound for int fields (default 0).
	min int

	// max is the upper bound for int fields. Zero means no upper bound.
	max int

	// options lists the allowed values for enum fields, populated at init
	// time by calling [enumProvider.options] on the provider.
	options []string

	// provider identifies which [enumProvider] produced options. Used by
	// [configField.showsColorSchemePreview] to decide whether to render
	// palette swatches in the enum picker.
	provider enumProvider

	// getEnum and setEnum are the typed accessors for enum (string) fields.
	getEnum func(Config) string
	setEnum func(*Config, string)
}

// enumSelectState holds transient state while the user picks from an
// enum's allowed values.
type enumSelectState struct {
	// fieldIndex is the index into [ConfigEditor.fields] for the field
	// being edited.
	fieldIndex int

	// options is a copy of the field's allowed values, displayed in the
	// picker list.
	options []string

	// index is the currently highlighted option within options.
	index int
}

// intEditState holds transient state while the user types an integer value.
type intEditState struct {
	// fieldIndex is the index into [ConfigEditor.fields] for the field
	// being edited.
	fieldIndex int

	// input is the raw digit string the user has typed so far.
	input string

	// err is a validation message shown below the input (e.g. "Must be >= 1").
	// Empty when the input is valid or not yet submitted.
	err string
}

// Init implements [tea.Model]. No initial commands are needed.
func (m *ConfigEditor) Init() tea.Cmd { return nil }

// dirty reports whether the draft diverges from the on-disk snapshot.
func (m *ConfigEditor) dirty() bool {
	return m.draft != m.original
}

// Update implements [tea.Model].
//
// It handles terminal resize events and dispatches key presses to the
// active mode handler. Global quit keys (q, esc, ctrl+c) and save keys
// (s, ctrl+s) are processed before mode-specific handlers.
func (m *ConfigEditor) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		return m, nil
	case tea.KeyPressMsg:
		key := msg.String()

		// Global quit keys.
		if key == "ctrl+c" || key == "q" || (key == "esc" && m.mode == modeBrowse) {
			return m.handleQuit()
		}

		// Save & quit only from browse mode. (In edit modes, Enter applies changes;
		// this avoids the surprising behavior of saving a half-edited int input.)
		if m.mode == modeBrowse && (key == "s" || key == "ctrl+s") {
			return m.handleSave()
		}

		// Any other key cancels quit confirmation.
		if m.confirmQuit {
			m.confirmQuit = false
			m.status = ""
		}

		switch m.mode {
		case modeEnumSelect:
			return m.updateEnumSelect(msg)
		case modeIntEdit:
			return m.updateIntEdit(msg)
		case modeBrowse:
			return m.updateBrowse(msg)
		default:
			return m, nil
		}
	default:
		return m, nil
	}
}

// handleQuit processes a quit request.
//
// If the draft has unsaved changes and this is the first quit attempt, the
// editor enters a confirmation state with a status-bar warning. A second
// quit attempt proceeds unconditionally.
func (m *ConfigEditor) handleQuit() (tea.Model, tea.Cmd) {
	if m.dirty() && !m.confirmQuit {
		m.confirmQuit = true
		if m.mode == modeBrowse {
			m.status = quitConfirmStatusBrowse
		} else {
			m.status = quitConfirmStatusEdit
		}
		return m, nil
	}
	return m, tea.Quit
}

// handleSave persists the draft to disk and exits.
//
// On write failure, the error is logged and displayed in the status bar
// without quitting, giving the user a chance to retry or discard.
func (m *ConfigEditor) handleSave() (tea.Model, tea.Cmd) {
	if err := m.cfg.SetConfig(&m.draft); err != nil {
		m.logger.Error(fmt.Sprintf("config editor: save failed: %v", err))
		m.status = fmt.Sprintf("Save failed: %v", err)
		return m, nil
	}
	return m, tea.Quit
}

// updateBrowse handles key presses in browse mode: cursor movement,
// quick-adjust via arrow keys, and field activation via Enter/Space.
func (m *ConfigEditor) updateBrowse(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if len(m.fields) == 0 {
		return m, nil
	}

	switch normalizeKey(msg.String()) {
	case "up", "k":
		if m.selected > 0 {
			m.selected--
		}
		return m, nil
	case "down", "j":
		if m.selected < len(m.fields)-1 {
			m.selected++
		}
		return m, nil
	case "left", "h":
		m.bumpSelected(-1)
		return m, nil
	case "right", "l":
		m.bumpSelected(1)
		return m, nil
	case "enter":
		return m.activateSelected()
	case "space":
		// Space toggles bools; otherwise acts like enter.
		f := &m.fields[m.selected]
		if f.Kind == fieldBool {
			cur := f.getBool(m.draft)
			f.setBool(&m.draft, !cur)
			return m, nil
		}
		return m.activateSelected()
	default:
		return m, nil
	}
}

// activateSelected opens the appropriate sub-editor for the selected field.
//
// Bool fields are toggled inline without entering a sub-editor. Enum fields
// open the enum picker modal, and int fields open the numeric input modal.
func (m *ConfigEditor) activateSelected() (tea.Model, tea.Cmd) {
	f := &m.fields[m.selected]
	switch f.Kind {
	case fieldBool:
		cur := f.getBool(m.draft)
		f.setBool(&m.draft, !cur)
		return m, nil
	case fieldEnum:
		opts := f.options
		if len(opts) == 0 {
			return m, nil
		}
		cur := f.getEnum(m.draft)
		idx := max(indexOf(opts, cur), 0)
		m.mode = modeEnumSelect
		m.enum = enumSelectState{
			fieldIndex: m.selected,
			options:    opts,
			index:      idx,
		}
		return m, nil
	case fieldInt:
		cur := f.getInt(m.draft)
		m.mode = modeIntEdit
		m.intE = intEditState{
			fieldIndex: m.selected,
			input:      strconv.Itoa(cur),
		}
		return m, nil
	default:
		return m, nil
	}
}

// bumpSelected applies a quick in-place adjustment to the selected field.
//
// For enums the value cycles through options; for ints it increments or
// decrements within [min, max]; for bools it toggles.
func (m *ConfigEditor) bumpSelected(delta int) {
	if len(m.fields) == 0 {
		return
	}

	f := &m.fields[m.selected]
	switch f.Kind {
	case fieldEnum:
		opts := f.options
		if len(opts) == 0 {
			return
		}
		cur := f.getEnum(m.draft)
		idx := max(indexOf(opts, cur), 0)
		idx = (idx + delta) % len(opts)
		if idx < 0 {
			idx += len(opts)
		}
		f.setEnum(&m.draft, opts[idx])
	case fieldInt:
		cur := f.getInt(m.draft)
		next := max(cur+delta, f.min)
		if f.max > 0 && next > f.max {
			next = f.max
		}
		f.setInt(&m.draft, next)
	case fieldBool:
		cur := f.getBool(m.draft)
		f.setBool(&m.draft, !cur)
	default:
	}
}

// updateEnumSelect handles key presses in the enum picker modal.
//
// Up/Down navigate the option list, Enter applies the selection, and
// Esc cancels back to browse mode without changing the value.
func (m *ConfigEditor) updateEnumSelect(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.mode = modeBrowse
		m.enum = enumSelectState{}
		return m, nil
	case "enter":
		if m.enum.fieldIndex < 0 || m.enum.fieldIndex >= len(m.fields) {
			m.mode = modeBrowse
			m.enum = enumSelectState{}
			return m, nil
		}
		f := m.fields[m.enum.fieldIndex]
		if m.enum.index >= 0 && m.enum.index < len(m.enum.options) {
			f.setEnum(&m.draft, m.enum.options[m.enum.index])
		}
		m.mode = modeBrowse
		m.enum = enumSelectState{}
		return m, nil
	case "up", "k":
		if m.enum.index > 0 {
			m.enum.index--
		}
		return m, nil
	case "down", "j":
		if m.enum.index < len(m.enum.options)-1 {
			m.enum.index++
		}
		return m, nil
	default:
		return m, nil
	}
}

// updateIntEdit handles key presses in the integer input modal.
//
// Digit keys append to the input buffer, Backspace removes the last
// character, Enter validates against [configField.min]/[configField.max]
// and applies on success, and Esc cancels without applying.
func (m *ConfigEditor) updateIntEdit(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.mode = modeBrowse
		m.intE = intEditState{}
		return m, nil
	case "enter":
		if m.intE.fieldIndex < 0 || m.intE.fieldIndex >= len(m.fields) {
			m.mode = modeBrowse
			m.intE = intEditState{}
			return m, nil
		}
		f := m.fields[m.intE.fieldIndex]
		raw := strings.TrimSpace(m.intE.input)
		val, err := strconv.Atoi(raw)
		if err != nil {
			m.intE.err = "Invalid integer"
			return m, nil
		}
		if val < f.min {
			m.intE.err = fmt.Sprintf("Must be >= %d", f.min)
			return m, nil
		}
		if f.max > 0 && val > f.max {
			m.intE.err = fmt.Sprintf("Must be <= %d", f.max)
			return m, nil
		}
		f.setInt(&m.draft, val)
		m.mode = modeBrowse
		m.intE = intEditState{}
		return m, nil
	case "backspace":
		if m.intE.input == "" {
			return m, nil
		}
		m.intE.input = m.intE.input[:len(m.intE.input)-1]
		m.intE.err = ""
		return m, nil
	default:
		if msg.Text != "" {
			for _, r := range msg.Text {
				if unicode.IsDigit(r) {
					m.intE.input += string(r)
					m.intE.err = ""
				}
			}
		}
		return m, nil
	}
}

// View implements [tea.Model].
//
// The layout is a vertical stack: header (title + config path), body, and
// footer (status/description/key hints). In browse mode the body is the
// settings table, scrolled so the selection stays visible; in enum/int edit
// modes the sub-editor modal takes the table's place so it always fits on
// screen. The view uses alt-screen mode.
func (m *ConfigEditor) View() tea.View {
	w := m.width
	if w <= 0 {
		w = 80
	}

	title := "W&B LEET Config"
	if m.dirty() {
		title += " *"
	}

	top := lipgloss.JoinVertical(
		lipgloss.Left,
		headerStyle.Render(title),
		navInfoStyle.Render(fmt.Sprintf("Path: %s", m.cfg.Path())),
	)

	footer := m.renderFooter(w)

	var body string
	switch m.mode {
	case modeEnumSelect:
		body = m.renderEnumPicker(w)
	case modeIntEdit:
		body = m.renderIntEditor(w)
	default:
		maxRows := len(m.fields)
		if m.height > 0 {
			// Chrome around the field rows: outer padding (2), header
			// block, two blank separators, table header row (1), footer.
			chrome := 2 + lipgloss.Height(top) + 2 + 1 + lipgloss.Height(footer)
			maxRows = max(m.height-chrome, 1)
		}
		body = m.renderTable(w, maxRows)
	}

	view := lipgloss.JoinVertical(lipgloss.Left, top, "", body, "", footer)

	v := tea.NewView(lipgloss.NewStyle().Padding(1, 2).Render(view))
	v.AltScreen = true
	return v
}

// renderTable renders the two-column settings table (Setting | Value),
// showing at most maxRows field rows scrolled so the selection is visible.
//
// The selected row is highlighted with [colorSelected]. Column widths
// adapt to the longest label and available terminal width.
func (m *ConfigEditor) renderTable(width, maxRows int) string {
	// Column widths.
	maxLabel := 0
	for i := range m.fields {
		if lw := lipgloss.Width(m.fields[i].Label); lw > maxLabel {
			maxLabel = lw
		}
	}
	keyW := min(maxLabel, max(20, width/2))
	valW := max(12, width-keyW-3)

	headerLine := lipgloss.JoinHorizontal(
		lipgloss.Left,
		lipgloss.NewStyle().Width(keyW).Bold(true).Render("Setting"),
		"   ",
		lipgloss.NewStyle().Width(valW).Bold(true).Render("Value"),
	)

	var lines []string
	lines = append(lines, headerLine)

	if len(m.fields) == 0 {
		lines = append(lines, navInfoStyle.Width(width).Render("No editable config fields found."))
		return strings.Join(lines, "\n")
	}

	visible := min(max(maxRows, 1), len(m.fields))
	start := 0
	if m.selected >= visible {
		start = m.selected - visible + 1
	}

	for i := start; i < start+visible; i++ {
		f := &m.fields[i]
		val := fieldValue(f, &m.draft)
		val = truncateRight(val, valW)

		line := lipgloss.JoinHorizontal(
			lipgloss.Left,
			lipgloss.NewStyle().Width(keyW).Render(f.Label),
			"   ",
			lipgloss.NewStyle().Width(valW).Render(val),
		)

		if i == m.selected {
			line = lipgloss.NewStyle().
				Width(width).
				Background(colorSelected).
				Foreground(colorDark).
				Render(line)
		}
		lines = append(lines, line)
	}

	return strings.Join(lines, "\n")
}

// renderFooter renders the bottom section: an optional status bar, the
// selected field's description and JSON key, and the key-binding hints.
func (m *ConfigEditor) renderFooter(width int) string {
	var parts []string

	if m.status != "" {
		parts = append(parts, statusBarStyle.Width(width).Render(m.status))
	}

	if len(m.fields) > 0 && m.selected >= 0 && m.selected < len(m.fields) {
		f := m.fields[m.selected]
		desc := fmt.Sprintf("%s  (%s)", f.Description, f.JSONKey)
		parts = append(parts, navInfoStyle.Width(width).Render(desc))
	}

	help := "↑/↓ select • Enter edit • ←/→ adjust • s save & quit • q/esc/ctrl+c quit"
	parts = append(parts, navInfoStyle.Width(width).Render(help))

	return strings.Join(parts, "\n")
}

// renderEnumPicker renders the bordered modal for choosing among an
// enum field's allowed values. Color scheme fields additionally show
// inline palette swatches via [renderColorSchemePreview].
func (m *ConfigEditor) renderEnumPicker(width int) string {
	f := m.fields[m.enum.fieldIndex]

	var lines []string
	lines = append(
		lines,
		headerStyle.Render(fmt.Sprintf("Select %s", f.Label)),
		navInfoStyle.Render("Enter: apply • Esc: cancel"),
	)

	for i, opt := range m.enum.options {
		prefix := "  "
		if i == m.enum.index {
			prefix = "> "
		}

		line := prefix + opt
		if f.showsColorSchemePreview() {
			line += "  " + renderColorSchemePreview(opt)
		}
		lines = append(lines, line)
	}

	box := lipgloss.NewStyle().
		Width(min(width, 80)).
		Border(lipgloss.RoundedBorder()).
		Padding(1, 2).
		Render(strings.Join(lines, "\n"))

	return box
}

// showsColorSchemePreview reports whether this field's enum picker should
// display inline color swatches next to each option.
func (f *configField) showsColorSchemePreview() bool {
	return f != nil && f.Kind == fieldEnum && f.provider == enumProviderColorSchemes
}

// renderColorSchemePreview returns a compact swatch strip for a palette.
//
// Each block is rendered with the scheme's AdaptiveColor, so lipgloss resolves
// the light or dark variant automatically for the current terminal theme.
func renderColorSchemePreview(scheme string) string {
	colors := GraphColors(scheme)
	if len(colors) == 0 {
		return ""
	}

	var b strings.Builder
	for _, c := range colors {
		b.WriteString(
			lipgloss.NewStyle().Foreground(c).Render(ConfigEditorPalettePreviewBlock))
	}
	return b.String()
}

// renderIntEditor renders the bordered modal for typing an integer value,
// including the allowed range hint and any validation error.
func (m *ConfigEditor) renderIntEditor(width int) string {
	f := m.fields[m.intE.fieldIndex]
	hint := "Enter: apply • Esc: cancel"
	rangeHint := ""
	if f.max > 0 {
		rangeHint = fmt.Sprintf("Range: %d..%d", f.min, f.max)
	} else {
		rangeHint = fmt.Sprintf("Min: %d", f.min)
	}

	var lines []string
	lines = append(lines, headerStyle.Render(fmt.Sprintf("Edit %s", f.Label)),
		navInfoStyle.Render(rangeHint),
		navInfoStyle.Render(hint),
		"",
		fmt.Sprintf("> %s", m.intE.input),
	)
	if m.intE.err != "" {
		lines = append(lines, "", errorStyle.Render(m.intE.err))
	}

	box := lipgloss.NewStyle().
		Width(min(width, 80)).
		Border(lipgloss.RoundedBorder()).
		Padding(1, 2).
		Render(strings.Join(lines, "\n"))

	return box
}

// availableColorSchemes returns the sorted names of all registered color schemes.
func availableColorSchemes() []string {
	names := make([]string, 0, len(colorSchemes))
	for name := range colorSchemes {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// fieldValue returns the human-readable string representation of a field's
// current value in the given config.
func fieldValue(f *configField, c *Config) string {
	switch f.Kind {
	case fieldBool:
		return strconv.FormatBool(f.getBool(*c))
	case fieldInt:
		return strconv.Itoa(f.getInt(*c))
	case fieldEnum:
		return f.getEnum(*c)
	default:
		return ""
	}
}

// indexOf returns the position of v in opts, or -1 if not found.
func indexOf(opts []string, v string) int {
	for i := range opts {
		if opts[i] == v {
			return i
		}
	}
	return -1
}

// truncateRight truncates s to fit within maxW display columns, appending
// an ellipsis ("...") when truncation is necessary.
func truncateRight(s string, maxW int) string {
	if maxW <= 0 || lipgloss.Width(s) <= maxW {
		return s
	}
	if maxW <= 3 {
		return "..."
	}
	// Simple rune-safe truncation with ellipsis.
	r := []rune(s)
	out := string(r)
	for lipgloss.Width(out) > maxW-3 && len(r) > 0 {
		r = r[:len(r)-1]
		out = string(r)
	}
	return out + "..."
}

package leet

import (
	"reflect"
	"strconv"
	"strings"
	"sync"
	"unicode"
)

var (
	configEditorFieldsOnce   sync.Once
	configEditorFieldsCached []configField
)

// buildConfigEditorFields returns the config editor schema.
//
// The schema is derived from the [Config] struct (and nested structs) by
// inspecting `json` and `leet` struct tags. Results are computed once and
// cached; callers receive a defensive copy.
//
// # Tag grammar
//
// The `leet` tag supports the following comma-separated directives:
//
//   - `-`               Skip this field entirely.
//   - `label=<text>`    Override the auto-generated display label.
//   - `desc=<text>`     Description shown in the editor footer when
//     the field is selected.
//   - `min=<int>`       Minimum value for int fields (default 0).
//   - `max=<int>`       Maximum value for int fields (0 means no upper
//     bound).
//   - `options=<n>`  Marks a string field as an enum and names the
//     options provider. The name must resolve to a known
//     [enumProvider] constant via [parseEnumProvider].
//
// # Field resolution rules
//
//   - Only exported fields with a non-empty `json` tag name are considered.
//   - Struct fields are traversed recursively. A struct field's
//     `leet:"desc=..."` is treated as a group description for its
//     children, enabling nice auto-descriptions for shared leaf types
//     (e.g. [GridConfig] rows/cols become "Rows in the main metrics grid.").
//   - String fields without an `options` provider are skipped to avoid
//     exposing free-text editing in the TUI.
//   - Unknown `leet` tag keys are silently ignored for forward compatibility.
func buildConfigEditorFields() []configField {
	configEditorFieldsOnce.Do(func() {
		configEditorFieldsCached = buildConfigEditorFieldsFromType(reflect.TypeFor[Config]())
	})

	// Defensively copy so callers can't mutate the cached slice.
	out := make([]configField, len(configEditorFieldsCached))
	copy(out, configEditorFieldsCached)
	return out
}

// leetTag holds the parsed result of a `leet:"..."` struct tag.
type leetTag struct {
	skip bool

	label   string
	desc    string
	options string

	min    int
	hasMin bool
	max    int
	hasMax bool
}

// parseLeetTag parses a raw `leet` struct tag value into a [leetTag].
//
// Examples:
//
//	""                          → zero leetTag
//	"-"                         → leetTag{skip: true}
//	"label=Foo,desc=Bar,min=1"  → leetTag{label:"Foo", desc:"Bar", min:1, hasMin:true}
func parseLeetTag(raw string) leetTag {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return leetTag{}
	}
	if raw == "-" {
		return leetTag{skip: true}
	}

	var t leetTag
	for part := range strings.SplitSeq(raw, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		key, val, ok := strings.Cut(part, "=")
		if !ok {
			// Reserved for future boolean flags, e.g. "readonly".
			continue
		}
		key = strings.TrimSpace(key)
		val = strings.TrimSpace(val)

		switch key {
		case "label":
			t.label = val
		case "desc":
			t.desc = val
		case "options":
			t.options = val
		case "min":
			if n, err := strconv.Atoi(val); err == nil {
				t.min = n
				t.hasMin = true
			}
		case "max":
			if n, err := strconv.Atoi(val); err == nil {
				t.max = n
				t.hasMax = true
			}
		default:
			// Unknown keys are ignored (forward-compatible).
		}
	}
	return t
}

// parseEnumProvider maps a `leet:"options=..."` tag value to its typed
// [enumProvider] constant.
//
// Unrecognized names resolve to [enumProviderUndefined], causing the
// field to be skipped during schema construction.
func parseEnumProvider(s string) enumProvider {
	switch s {
	case "colorSchemes":
		return enumProviderColorSchemes
	case "colorModes":
		return enumProviderColorModes
	case "startupModes":
		return enumProviderStartupModes
	case "chartGuides":
		return enumProviderChartGuides
	default:
		return enumProviderUndefined
	}
}

// buildConfigEditorFieldsFromType reflects over a struct type and produces
// a flat list of [configField] values for every editable leaf.
func buildConfigEditorFieldsFromType(t reflect.Type) []configField {
	var out []configField
	walkConfigFields(t, nil, nil, nil, "", &out)
	return out
}

// walkConfigFields recursively traverses struct fields to build [configField]
// entries for every editable leaf.
//
// Parameters accumulate state as we recurse into nested structs:
//   - indexPath tracks the [reflect.StructField.Index] chain for FieldByIndex.
//   - jsonPath tracks the dot-joined JSON key (e.g. "metrics_grid.rows").
//   - labelSegments accumulate humanized path segments for the display label.
//   - groupDesc propagates a parent struct's `leet:"desc=..."` to children.
func walkConfigFields(
	t reflect.Type,
	indexPath []int,
	jsonPath []string,
	labelSegments []string,
	groupDesc string,
	out *[]configField,
) {
	// Only structs can be walked.
	if t.Kind() != reflect.Struct {
		return
	}

	for sf := range t.Fields() {
		sf := sf
		if !sf.IsExported() {
			continue
		}

		jsonName, ok := jsonTagName(sf)
		if !ok {
			continue
		}

		tag := parseLeetTag(sf.Tag.Get("leet"))
		if tag.skip {
			continue
		}

		fieldIndex := appendIndex(indexPath, sf.Index)
		fieldJSONPath := appendString(jsonPath, jsonName)
		fieldLabelSegs := appendString(labelSegments, humanizeSegment(jsonName))

		// If this field is a struct, recurse into it.
		//
		// We treat a struct field's `leet:"desc=..."` as a *group description*
		// for children (e.g. metrics_grid.*) to allow nice auto-descriptions for
		// shared leaf types like GridConfig.
		if sf.Type.Kind() == reflect.Struct {
			childGroupDesc := groupDesc
			if tag.desc != "" {
				childGroupDesc = tag.desc
			}
			walkConfigFields(
				sf.Type,
				fieldIndex,
				fieldJSONPath,
				fieldLabelSegs,
				childGroupDesc,
				out,
			)
			continue
		}

		label := buildLabel(fieldLabelSegs, tag.label)
		key := strings.Join(fieldJSONPath, ".")

		switch sf.Type.Kind() {
		case reflect.Bool:
			desc := tag.desc
			if desc == "" {
				desc = defaultDescription(fieldJSONPath, groupDesc, label)
			}
			idx := cloneIndex(fieldIndex)

			*out = append(*out, configField{
				Label:       label,
				JSONKey:     key,
				Description: desc,
				Kind:        fieldBool,
				getBool: func(c Config) bool {
					return reflect.ValueOf(c).FieldByIndex(idx).Bool()
				},
				setBool: func(c *Config, v bool) {
					reflect.ValueOf(c).Elem().FieldByIndex(idx).SetBool(v)
				},
			})

		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			desc := tag.desc
			if desc == "" {
				desc = defaultDescription(fieldJSONPath, groupDesc, label)
			}

			minimum := 0
			if tag.hasMin {
				minimum = tag.min
			}
			maximum := 0
			if tag.hasMax {
				maximum = tag.max
			}
			idx := cloneIndex(fieldIndex)

			*out = append(*out, configField{
				Label:       label,
				JSONKey:     key,
				Description: desc,
				Kind:        fieldInt,
				getInt: func(c Config) int {
					return int(reflect.ValueOf(c).FieldByIndex(idx).Int())
				},
				setInt: func(c *Config, v int) {
					reflect.ValueOf(c).Elem().FieldByIndex(idx).SetInt(int64(v))
				},
				min: minimum,
				max: maximum,
			})

		case reflect.String:
			// Only string fields with a recognized options provider are
			// treated as editable enums. This keeps behavior explicit and
			// avoids introducing free-text editing in the UI.
			if tag.options == "" {
				continue
			}
			provider := parseEnumProvider(tag.options)
			if provider == enumProviderUndefined {
				// Unrecognized provider name. Skip rather than
				// silently producing a broken field.
				continue
			}
			opts := provider.options()
			if len(opts) == 0 {
				continue
			}
			desc := tag.desc
			if desc == "" {
				desc = defaultDescription(fieldJSONPath, groupDesc, label)
			}
			idx := cloneIndex(fieldIndex)

			*out = append(*out, configField{
				Label:       label,
				JSONKey:     key,
				Description: desc,
				Kind:        fieldEnum,
				options:     opts,
				provider:    provider,
				getEnum: func(c Config) string {
					return reflect.ValueOf(c).FieldByIndex(idx).String()
				},
				setEnum: func(c *Config, v string) {
					reflect.ValueOf(c).Elem().FieldByIndex(idx).SetString(v)
				},
			})

		default:
			// Unsupported type: skip.
			continue
		}
	}
}

// jsonTagName extracts the field name from a `json` struct tag.
// Returns ("", false) for empty tags and the explicit skip marker "-".
func jsonTagName(sf reflect.StructField) (string, bool) {
	raw := sf.Tag.Get("json")
	if raw == "" {
		return "", false
	}
	name, _, _ := strings.Cut(raw, ",")
	name = strings.TrimSpace(name)
	if name == "" || name == "-" {
		return "", false
	}
	return name, true
}

// humanizeSegment converts a JSON key segment (e.g. "heartbeat_interval")
// into a space-separated lowercase form ("heartbeat interval").
func humanizeSegment(seg string) string {
	seg = strings.ReplaceAll(seg, "_", " ")
	seg = strings.ReplaceAll(seg, "-", " ")
	return strings.ToLower(seg)
}

// buildLabel returns the display label for a field, using the tag override
// if provided or joining the humanized path segments with sentence casing.
func buildLabel(labelSegments []string, override string) string {
	if override != "" {
		return override
	}
	return sentenceCase(strings.Join(labelSegments, " "))
}

// sentenceCase upper-cases the first rune of s.
func sentenceCase(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

// lowerFirst lower-cases the first rune of s.
func lowerFirst(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = unicode.ToLower(r[0])
	return string(r)
}

// defaultDescription generates a fallback description when none is specified
// via `leet:"desc=..."`.
//
// Grid leaf fields (rows/cols) get contextual descriptions like "Rows in the
// main metrics grid." using the parent's groupDesc. Everything else falls back
// to "Set <label>."
func defaultDescription(jsonPath []string, groupDesc, label string) string {
	// Special case for grid configs: infer nice descriptions automatically.
	if len(jsonPath) >= 2 {
		leaf := jsonPath[len(jsonPath)-1]
		if leaf == "rows" || leaf == "cols" {
			target := strings.TrimSpace(groupDesc)
			if target == "" {
				target = humanizeSegment(jsonPath[len(jsonPath)-2])
			}

			if leaf == "rows" {
				return "Rows in the " + target + "."
			}
			return "Columns in the " + target + "."
		}
	}

	// Generic fallback: good enough for new fields until you add a `leet:"desc=..."`.
	if label != "" {
		return "Set " + lowerFirst(label) + "."
	}

	return ""
}

// appendIndex returns a new slice containing prefix followed by suffix.
func appendIndex(prefix, suffix []int) []int {
	out := make([]int, 0, len(prefix)+len(suffix))
	out = append(out, prefix...)
	out = append(out, suffix...)
	return out
}

// cloneIndex returns an independent copy of in.
func cloneIndex(in []int) []int {
	out := make([]int, len(in))
	copy(out, in)
	return out
}

// appendString returns a new slice containing prefix followed by elem.
func appendString(prefix []string, elem string) []string {
	out := make([]string, 0, len(prefix)+1)
	out = append(out, prefix...)
	out = append(out, elem)
	return out
}

package filestream

import (
	"fmt"
	"maps"
	"slices"
	"time"

	"github.com/wandb/wandb/core/internal/nullify"
	"github.com/wandb/wandb/core/internal/observability"
	"github.com/wandb/wandb/core/internal/runsummary"
)

// FileStreamState turns a [FileStreamRequest] into sequence
// of [FileStreamRequestJSON].
type FileStreamState struct {
	// MaxRequestSizeBytes is an approximate maximum FileStream request size
	// in bytes.
	MaxRequestSizeBytes int

	// MaxFileLineSize is an approximate maximum per-line size in bytes for
	// the "Files" uploaded in FileStream.
	MaxFileLineSize int

	// HistoryLineNum is the line number where to append history.
	HistoryLineNum int

	// EventsLineNum is the line number where to append system metrics.
	EventsLineNum int

	// SummaryLineNum is the line number where to write the summary.
	//
	// The same line is always overwritten. The reason we don't solely
	// update line 0 is for compatibility with previous versions which
	// appended summaries. The backend only looks at the last line, so
	// to properly resume such a run we must update the last line.
	SummaryLineNum int

	// RunSummary is the run's full summary.
	//
	// It may be nil if the run has no summary.
	RunSummary *runsummary.RunSummary

	// UnsentSummary is the serialized RunSummary if it did not fit in
	// a previous request.
	UnsentSummary string

	// LastRunSummarySize is the size in bytes of the RunSummary's
	// last successfully serialized JSON value.
	//
	// If there is a non-empty UnsentSummary, this is its length.
	LastRunSummarySize int

	// ConsoleLineOffset is an offset to add to all console updates.
	//
	// This is used when resuming a run, in which case we want the new
	// console logs to be appended to the old ones.
	ConsoleLineOffset int
}

// IsAtSizeLimit returns true if the next JSON chunk of the request could
// contain more than around maxBytes of data.
func (s *FileStreamState) IsAtSizeLimit(request *FileStreamRequest) bool {
	approxSize := 0

	for _, line := range request.HistoryLines {
		approxSize += len(line)
		if approxSize >= s.MaxRequestSizeBytes {
			return true
		}
	}

	for _, line := range request.EventsLines {
		approxSize += len(line)
		if approxSize >= s.MaxRequestSizeBytes {
			return true
		}
	}

	// Use the last summary size to approximate the next.
	// It is too expensive to serialize the summary every time and too complex
	// to track its size incrementally.
	if !request.SummaryUpdates.IsEmpty() || s.UnsentSummary != "" {
		approxSize += s.LastRunSummarySize
		if approxSize >= s.MaxRequestSizeBytes {
			return true
		}
	}

	for line := range request.ConsoleLines.FirstRunValues() {
		approxSize += len(line)
		if approxSize >= s.MaxRequestSizeBytes {
			return true
		}
	}

	return false
}

// Pop extracts a chunk of data from the request, limiting its JSON
// representation to approximately the maximum size.
//
// The second return value is true if there remains unsent data in the request.
func (s *FileStreamState) Pop(
	request *FileStreamRequest,
	logger *observability.CoreLogger,
	printer *observability.Printer,
) (*FileStreamRequestJSON, bool) {
	builder := &requestJSONBuilder{}
	builder.MaxSizeBytes = s.MaxRequestSizeBytes

	s.popHistory(builder, request)
	s.popEvents(builder, request)
	s.popSummary(builder, request, logger, printer)
	s.popConsoleLines(builder, request)

	s.popUploadedFiles(builder, request)
	s.popPreempting(builder, request)

	if !builder.HasMore && request.Complete {
		builder.Complete = true
		builder.ExitCode = request.ExitCode
	}

	return builder.Build(), builder.HasMore
}

func (s *FileStreamState) popHistory(
	builder *requestJSONBuilder,
	request *FileStreamRequest,
) {
	poppedLines := false
	defer func() {
		if poppedLines {
			// Free unused memory.
			request.HistoryLines = slices.Clone(request.HistoryLines)
		}
	}()

	builder.HistoryChunk.Offset = s.HistoryLineNum

	for len(request.HistoryLines) > 0 {
		line := request.HistoryLines[0]

		if !builder.TryAddSize(len(line)) {
			builder.HasMore = true
			return
		}

		poppedLines = true
		builder.HistoryChunk.Content = append(builder.HistoryChunk.Content, line)
		request.HistoryLines = request.HistoryLines[1:]
		s.HistoryLineNum++
	}
}

func (s *FileStreamState) popEvents(
	builder *requestJSONBuilder,
	request *FileStreamRequest,
) {
	poppedLines := false
	defer func() {
		if poppedLines {
			// Free unused memory.
			request.EventsLines = slices.Clone(request.EventsLines)
		}
	}()

	builder.EventsChunk.Offset = s.EventsLineNum

	for len(request.EventsLines) > 0 {
		line := request.EventsLines[0]

		if !builder.TryAddSize(len(line)) {
			builder.HasMore = true
			return
		}

		poppedLines = true
		builder.EventsChunk.Content = append(builder.EventsChunk.Content, line)
		request.EventsLines = request.EventsLines[1:]
		s.EventsLineNum++
	}
}

func (s *FileStreamState) popSummary(
	builder *requestJSONBuilder,
	request *FileStreamRequest,
	logger *observability.CoreLogger,
	printer *observability.Printer,
) {
	if !request.SummaryUpdates.IsEmpty() {
		if s.RunSummary == nil {
			s.RunSummary = runsummary.New()
		}

		err := request.SummaryUpdates.Apply(s.RunSummary)
		request.SummaryUpdates = nil

		if err != nil {
			// A partial success is possible, so we log and continue.
			logger.CaptureError(
				"filestream",
				fmt.Errorf("filestream: error applying summary updates: %v", err),
			)
		}

		summaryJSON, err := s.RunSummary.Serialize()
		if err != nil {
			// On error, we don't modify UnsentSummary so that we still upload
			// a previous successfully-serialized value.
			logger.CaptureError(
				"filestream",
				fmt.Errorf("filestream: failed to serialize summary: %v", err),
			)
		} else {
			s.UnsentSummary = string(summaryJSON)
			s.LastRunSummarySize = len(summaryJSON)
		}
	}

	if s.UnsentSummary == "" {
		return
	}

	if len(s.UnsentSummary) > s.MaxFileLineSize {
		logger.Warn(
			"filestream: run summary line too long, skipping",
			"len", len(s.UnsentSummary),
			"max", s.MaxFileLineSize,
		)
		printer.
			AtMostEvery(time.Minute).
			Warnf(
				"Skipped uploading summary data that exceeded"+
					" size limit (%d > %d bytes).",
				len(s.UnsentSummary),
				s.MaxFileLineSize,
			)

		// Clear the unsent value; we will not attempt to send it unless
		// it is modified, in which case it'll be serialized again.
		s.UnsentSummary = ""
		return
	}

	if !builder.TryAddSize(len(s.UnsentSummary)) {
		builder.HasMore = true
		return
	}

	builder.SummaryChunk.Offset = s.SummaryLineNum
	builder.SummaryChunk.Content = []string{s.UnsentSummary}
	s.UnsentSummary = ""
}

func (s *FileStreamState) popConsoleLines(
	builder *requestJSONBuilder,
	request *FileStreamRequest,
) {
	builder.ConsoleLinesChunk.Offset =
		s.ConsoleLineOffset + request.ConsoleLines.FirstIndex()

	for idx, line := range request.ConsoleLines.FirstRun() {
		if !builder.TryAddSize(len(line)) {
			builder.HasMore = true
			return
		}

		builder.ConsoleLinesChunk.Content = append(
			builder.ConsoleLinesChunk.Content,
			line,
		)
		request.ConsoleLines.Delete(idx)
	}

	// We can only upload one consecutive run of console lines at a time.
	if request.ConsoleLines.Len() > 0 {
		builder.HasMore = true
	}
}

func (s *FileStreamState) popUploadedFiles(
	builder *requestJSONBuilder,
	request *FileStreamRequest,
) {
	builder.Uploaded = slices.Collect(maps.Keys(request.UploadedFiles))
	request.UploadedFiles = nil
}

func (s *FileStreamState) popPreempting(
	builder *requestJSONBuilder,
	request *FileStreamRequest,
) {
	builder.Preempting = request.Preempting
	request.Preempting = false
}

// requestJSONBuilder builds a [FileStreamRequestJSON].
type requestJSONBuilder struct {
	ApproxSizeBytes, MaxSizeBytes int
	HasMore                       bool

	HistoryChunk      OffsetAndContent
	EventsChunk       OffsetAndContent
	SummaryChunk      OffsetAndContent
	ConsoleLinesChunk OffsetAndContent

	Uploaded   []string
	Preempting bool

	Complete bool
	ExitCode int32 // only sent if Complete
}

// TryAddSize returns whether n more bytes can be added to the request
// and updates the request size if so.
func (b *requestJSONBuilder) TryAddSize(n int) bool {
	newSize := b.ApproxSizeBytes + n

	if b.ApproxSizeBytes == 0 || newSize <= b.MaxSizeBytes {
		b.ApproxSizeBytes = newSize
		return true
	} else {
		return false
	}
}

// Build returns the JSON value to upload.
func (x *requestJSONBuilder) Build() *FileStreamRequestJSON {
	json := &FileStreamRequestJSON{}
	json.Files = make(map[string]OffsetAndContent)

	if len(x.HistoryChunk.Content) > 0 {
		json.Files[HistoryFileName] = x.HistoryChunk
	}
	if len(x.EventsChunk.Content) > 0 {
		json.Files[EventsFileName] = x.EventsChunk
	}
	if len(x.SummaryChunk.Content) > 0 {
		json.Files[SummaryFileName] = x.SummaryChunk
	}
	if len(x.ConsoleLinesChunk.Content) > 0 {
		json.Files[OutputFileName] = x.ConsoleLinesChunk
	}

	json.Uploaded = x.Uploaded
	json.Preempting = nullify.NilIfZero(x.Preempting)

	if x.Complete {
		complete := x.Complete
		json.Complete = &complete

		exitCode := x.ExitCode
		json.ExitCode = &exitCode
	}

	return json
}

package filetransfer

import (
	"context"
	"fmt"
	"net/http"
	"strings"
)

// DefaultTask is the default task to upload/download files
type DefaultTask struct {
	OnComplete TaskCompletionCallback

	// FileKind is the category of file being uploaded or downloaded
	FileKind RunFileKind

	// Path is the local path to the file
	Path string

	// Name is the name of the file
	Name string

	// Url is the endpoint to upload to/download from
	Url string

	// Headers to send on the upload
	Headers http.Header

	// Size is the number of bytes to upload
	//
	// If this is zero, then all bytes starting at `Offset` are uploaded; if non-zero,
	// then that many bytes starting from `Offset` are uploaded.
	Size int64

	// Offset is the beginning of the file segment to upload
	Offset int64

	// Response is the http.Response from a successful upload or download request.
	//
	// This is nil for failed requests, or requests that have not completed.
	Response *http.Response

	// Error, if any.
	Err error

	// ProgressCallback is a callback to execute on progress updates
	ProgressCallback func(int, int)

	// This can be used to cancel the file upload or download if it is no longer needed.
	Context context.Context
}

type DefaultUploadTask DefaultTask

func (t *DefaultUploadTask) Execute(fts *FileTransfers) error {
	if t.RequiresAzureUpload() {
		return fts.Azure.Upload(t)
	}
	return fts.Default.Upload(t)
}
func (t *DefaultUploadTask) Complete(fts FileTransferStats) {
	t.OnComplete.Complete()
	if fts != nil {
		fts.UpdateUploadStats(FileUploadInfo{
			FileKind:      t.FileKind,
			Path:          t.Path,
			UploadedBytes: t.Size,
			TotalBytes:    t.Size,
		})
	}
}
func (t *DefaultUploadTask) String() string {
	return fmt.Sprintf(
		"DefaultUploadTask{FileKind: %d, Path: %s, Name: %s, Url: %s, Size: %d}",
		t.FileKind, t.Path, t.Name, t.Url, t.Size,
	)
}
func (t *DefaultUploadTask) SetError(err error) { t.Err = err }

type DefaultDownloadTask DefaultTask

func (t *DefaultDownloadTask) Execute(fts *FileTransfers) error {
	return fts.Default.Download(t)
}
func (t *DefaultDownloadTask) Complete(fts FileTransferStats) {
	t.OnComplete.Complete()
}
func (t *DefaultDownloadTask) String() string {
	return fmt.Sprintf(
		"DefaultDownloadTask{FileKind: %d, Path: %s, Name: %s, Url: %s, Size: %d}",
		t.FileKind, t.Path, t.Name, t.Url, t.Size,
	)
}
func (t *DefaultDownloadTask) SetError(err error) { t.Err = err }

func (t *DefaultUploadTask) RequiresAzureUpload() bool {
	return t.Headers.Get("x-ms-blob-type") != ""
}

// ParseHeaders converts a list of "Key: Value" header strings, as returned by
// the W&B backend, into an http.Header.
//
// It returns the successfully parsed headers along with an error naming any
// entries that lacked a colon separator and were skipped, so callers can log
// the anomaly without aborting an otherwise-valid transfer.
func ParseHeaders(headers []string) (http.Header, error) {
	parsed := make(http.Header, len(headers))
	var malformed []string
	for _, header := range headers {
		key, value, found := strings.Cut(header, ":")
		if !found {
			malformed = append(malformed, header)
			continue
		}
		parsed.Add(key, strings.TrimSpace(value))
	}
	if len(malformed) > 0 {
		return parsed, fmt.Errorf("skipped malformed headers: %q", malformed)
	}
	return parsed, nil
}

package filestream

import (
	"time"

	"golang.org/x/time/rate"

	"github.com/wandb/wandb/core/internal/observability"
)

// CollectLoop batches changes together to make filestream requests.
//
// This batches all incoming requests while waiting for transmissions
// to go through.
type CollectLoop struct {
	Logger            *observability.CoreLogger
	Printer           *observability.Printer
	TransmitRateLimit *rate.Limiter
}

// Start ingests requests and outputs rate-limited, batched requests.
func (cl CollectLoop) Start(
	state *FileStreamState,
	requests <-chan *FileStreamRequest,
) *TransmitChan {
	switch {
	case cl.Logger == nil:
		panic("filestream: CollectLoop.Logger is nil")
	case cl.Printer == nil:
		panic("filestream: CollectLoop.Printer is nil")
	case cl.TransmitRateLimit == nil:
		panic("filestream: CollectLoop.TransmitRateLimit is nil")
	}

	output := NewTransmitChan()

	go func() {
		buffer := &FileStreamRequest{}
		hasMore := true

		for request := range requests {
			buffer.Merge(request)

			cl.waitForRateLimit(state, buffer, requests)
			hasMore = cl.transmit(state, buffer, requests, output)
		}

		for hasMore {
			var json *FileStreamRequestJSON
			json, hasMore = cl.pop(state, buffer)
			output.Push(json)
		}

		output.Close()
	}()

	return output
}

// waitForRateLimit merges requests until the rate limit allows us
// to transmit data.
func (cl CollectLoop) waitForRateLimit(
	state *FileStreamState,
	buffer *FileStreamRequest,
	requests <-chan *FileStreamRequest,
) {
	if cl.shouldSendASAP(state, buffer) {
		return
	}

	reservation := cl.TransmitRateLimit.Reserve()

	// If we would be rate-limited forever, just ignore the limit.
	if !reservation.OK() {
		return
	}

	for {
		timer := time.NewTimer(reservation.Delay())
		select {
		case <-timer.C:
			return

		case request, ok := <-requests:
			_ = timer.Stop()

			if !ok {
				return
			}

			buffer.Merge(request)

			if cl.shouldSendASAP(state, buffer) {
				return
			}
		}
	}
}

// transmit accumulates incoming requests until a transmission goes through.
//
// Returns whether there remains unsent data in the buffer.
func (cl CollectLoop) transmit(
	state *FileStreamState,
	buffer *FileStreamRequest,
	requests <-chan *FileStreamRequest,
	output *TransmitChan,
) bool {
	for {
		// If we're at max size, stop adding to the buffer.
		if state.IsAtSizeLimit(buffer) {
			cl.Logger.Info("filestream: waiting to send request of max size")
			json, hasMore := cl.pop(state, buffer)
			output.Push(json)
			return hasMore
		}

		// Otherwise, either send the buffer or add to it.
		select {
		case pushChan := <-output.PreparePush():
			json, hasMore := cl.pop(state, buffer)
			pushChan <- json
			return hasMore

		case request, ok := <-requests:
			if !ok {
				json, hasMore := cl.pop(state, buffer)
				output.Push(json)
				return hasMore
			}

			buffer.Merge(request)
		}
	}
}

// pop calls [FileStreamState.Pop], extracting a JSON value to send from the
// request and returning whether the request contains more data.
func (cl CollectLoop) pop(
	state *FileStreamState,
	request *FileStreamRequest,
) (*FileStreamRequestJSON, bool) {
	return state.Pop(
		request,
		cl.Logger,
		cl.Printer,
	)
}

// shouldSendASAP returns a request should be made regardless of rate limits.
func (cl CollectLoop) shouldSendASAP(
	state *FileStreamState,
	request *FileStreamRequest,
) bool {
	switch {
	// Send the "pre-empting" state immediately.
	//
	// This state indicates that the process may be about to yield the
	// CPU for an unknown amount of time, and we want to let the backend
	// know ASAP.
	case request.Preempting:
		return true

	// If we've accumulated a request of the maximum size, send it immediately.
	case state.IsAtSizeLimit(request):
		return true

	default:
		return false
	}
}

package filestream

import "time"

// TransmitLoop makes requests to the backend.
type TransmitLoop struct {
	HeartbeatPeriod        time.Duration
	Send                   func(*FileStreamRequestJSON, chan<- map[string]any) error
	LogFatalAndStopWorking func(error)
}

// Start makes requests to the filestream API.
//
// It ingests a channel of requests and outputs a channel of API responses.
func (tr TransmitLoop) Start(
	data *TransmitChan,
) <-chan map[string]any {
	feedback := make(chan map[string]any)

	go func() {
		defer func() {
			data.IgnoreFutureRequests()
			close(feedback)
		}()

		heartbeat := time.NewTicker(tr.HeartbeatPeriod)

		for {
			x, ok := data.NextRequest(heartbeat.C)
			if !ok {
				break
			}

			heartbeat.Reset(tr.HeartbeatPeriod)
			err := tr.Send(x, feedback)

			if err != nil {
				tr.LogFatalAndStopWorking(err)
				break
			}
		}
	}()

	return feedback
}

