)

const (
	// defaultExportInterval is the interval at which metrics and logs are sent to the backend.
	defaultExportInterval = 60 * time.Second

	// defaultExportTimeout is the total time allowed for an export to complete.
	// It includes the time to collect and send metric/log records.
	defaultExportTimeout = 5 * time.Second

	// httpClientTimeout is the timeout for HTTP requests to the backend.
	httpClientTimeout = 10 * time.Second

	// probeTimeout is the timeout for the server capability probe.
	probeTimeout = 2 * time.Second

	metricsPath = "/sdk/otel/v1/metrics"
	logsPath    = "/sdk/otel/v1/logs"
)

// ConfigureOTelErrorHandler routes OpenTelemetry SDK errors to the logger.
//
// Without this, the OpenTelemetry SDK prints errors to stderr, which
// corrupts the display of terminal UIs like leet.
func ConfigureOTelErrorHandler(logger *slog.Logger) {
	otel.SetErrorHandler(otel.ErrorHandlerFunc(func(err error) {
		logger.Error(
			"analytics: failed to send telemetry to backend proxy",
			"error", err,
		)
	}))
}

// LowCardinalityAttributes is the fixed set of low-cardinality attributes
// that can be added to the telemetry context.
type LowCardinalityAttributes struct {
	GoVersion       string
	WandbVersion    string
	OperatingSystem string
	Architecture    string
	ErrorOriginator string

	PythonVersion string
	PythonRuntime string
	ExceptionType string

	// LeetMode is the leet launch mode: leet, config, inspect or symon.
	LeetMode string

	// ExecutionContext classifies where the process runs:
	// kubernetes, container, slurm, ci, ssh or local.
	ExecutionContext string
}

// merge overwrites attrs with the non-empty fields of other.
func (attrs *LowCardinalityAttributes) merge(other LowCardinalityAttributes) {
	attrs.GoVersion = cmp.Or(other.GoVersion, attrs.GoVersion)
	attrs.WandbVersion = cmp.Or(other.WandbVersion, attrs.WandbVersion)
	attrs.OperatingSystem = cmp.Or(other.OperatingSystem, attrs.OperatingSystem)
	attrs.Architecture = cmp.Or(other.Architecture, attrs.Architecture)
	attrs.ErrorOriginator = cmp.Or(other.ErrorOriginator, attrs.ErrorOriginator)

	attrs.PythonVersion = cmp.Or(other.PythonVersion, attrs.PythonVersion)
	attrs.PythonRuntime = cmp.Or(other.PythonRuntime, attrs.PythonRuntime)
	attrs.ExceptionType = cmp.Or(other.ExceptionType, attrs.ExceptionType)

	attrs.LeetMode = cmp.Or(other.LeetMode, attrs.LeetMode)
	attrs.ExecutionContext = cmp.Or(other.ExecutionContext, attrs.ExecutionContext)
}

func (attrs LowCardinalityAttributes) toMap() map[string]string {
	out := map[string]string{
		"go_version":        attrs.GoVersion,
		"operating_system":  attrs.OperatingSystem,
		"architecture":      attrs.Architecture,
		"error.originator":  attrs.ErrorOriginator,
		"python_version":    attrs.PythonVersion,
		"python_runtime":    attrs.PythonRuntime,
		"exception_type":    attrs.ExceptionType,
		"wandb_version":     attrs.WandbVersion,
		"leet_mode":         attrs.LeetMode,
		"execution_context": attrs.ExecutionContext,
	}
	maps.DeleteFunc(out, func(_ string, value string) bool {
		return value == ""
	})
	return out
}

// disabled gates OpenTelemetryProxy in this process.
var disabled atomic.Bool

// Disable turns analytics off for the whole process.
//
// Once this function is called, no further telemetry will be recorded.
func Disable() {
	disabled.Store(true)
}

// TelemetryContext holds persistent attributes added to all telemetry records.
//
// Attributes are split into two buckets:
//
//   - Low-cardinality attributes are a small, bounded set of values
//     (e.g. wandb_version, go_version, operating_system).
//     These are restricted to a known set of keys,
//
//   - High-cardinality attributes are an unbounded set of values.
//     These are attached to log records where high cardinality is acceptable.
type TelemetryContext struct {
	// lowCardinalityAttributes is a bounded set of attributes.
	// These attributes are added to all telemetry records.
	lowCardinalityAttributes LowCardinalityAttributes

	// highCardinalityAttributes is an unbounded set of attributes.
	// These attributes are added to telemetry records
	// where high cardinality is acceptable, such as log records.
	highCardinalityAttributes map[string]string
}

func NewTelemetryContext() TelemetryContext {
	lowCardinalityAttributes := LowCardinalityAttributes{
		WandbVersion:    version.Version,
		GoVersion:       runtime.Version(),
		OperatingSystem: runtime.GOOS,
		Architecture:    runtime.GOARCH,
	}

	return TelemetryContext{
		lowCardinalityAttributes:  lowCardinalityAttributes,
		highCardinalityAttributes: map[string]string{},
	}
}

// with returns a child context that inherits this context's attributes
// merged with the provided ones. The receiver is not modified.
//
// Non-empty low-cardinality fields and high-cardinality keys in the
// arguments take precedence over the parent's attributes.

func (s *TelemetryContext) with(
	lowCardinalityAttributes LowCardinalityAttributes,
	highCardinalityAttributes map[string]string,
) TelemetryContext {
	low := s.lowCardinalityAttributes
	low.merge(lowCardinalityAttributes)

	high := make(map[string]string, len(s.highCardinalityAttributes))
	maps.Copy(high, s.highCardinalityAttributes)
	maps.Copy(high, highCardinalityAttributes)

	return TelemetryContext{
		lowCardinalityAttributes:  low,
		highCardinalityAttributes: high,
	}
}

// TelemetryRecorder handles recording telemetry events to the OpenTelemetry.
//
// Recorders form a hierarchy using `With` derives a child recorder with
// additional attributes. Child recorders share the root provider's
// OpenTelemetry providers, and therefore do not need to be shut down.
type TelemetryRecorder struct {
	root             *OpenTelemetryProxy
	telemetryContext TelemetryContext
}

// NewTelemetryRecorder returns a new TelemetryRecorder with the given root
// OpenTelemetryProxy and telemetry context.
//
// If the root is nil, a nil pointer is returned.
// A nil TelemetryRecorder is a no-op, as if telemetry is disabled.
func NewTelemetryRecorder(
	root *OpenTelemetryProxy,
	telemetryContext TelemetryContext,
) *TelemetryRecorder {
	if root == nil {
		return nil
	}

	return &TelemetryRecorder{
		root:             root,
		telemetryContext: telemetryContext,
	}
}

// With returns a derived recorder whose telemetry context inherits
// this recorder's attributes merged with the provided ones.
//
// The receiver is unchanged: attributes added to the derived recorder
// never appear on records emitted through the parent or its siblings.
//
// If the receiver is nil, a nil pointer is returned.
// A nil TelemetryRecorder is a no-op, as if telemetry is disabled.
func (r *TelemetryRecorder) With(
	lowCardinalityAttributes LowCardinalityAttributes,
	highCardinalityAttributes map[string]string,
) *TelemetryRecorder {
	if r == nil {
		return nil
	}

	return &TelemetryRecorder{
		root: r.root,
		telemetryContext: r.telemetryContext.with(
			lowCardinalityAttributes,
			highCardinalityAttributes,
		),
	}
}

// IncrementCounter increments a counter metric by 1
// with the telemetry context's low-cardinality attributes
func (r *TelemetryRecorder) IncrementCounter(
	ctx context.Context,
	name string,
	lowCardinalityAttributes LowCardinalityAttributes,
) {
	if r == nil {
		return
	}

	mergedLowCardinalityAttributes := r.telemetryContext.lowCardinalityAttributes
	mergedLowCardinalityAttributes.merge(lowCardinalityAttributes)
	r.root.incrementCounter(ctx, name, mergedLowCardinalityAttributes)
}

// RecordDuration records a duration histogram metric in seconds with the
// telemetry context's low-cardinality attributes.
func (r *TelemetryRecorder) RecordDuration(
	ctx context.Context,
	name string,
	duration time.Duration,
	lowCardinalityAttributes LowCardinalityAttributes,
) {
	if r == nil {
		return
	}

	mergedLowCardinalityAttributes := r.telemetryContext.lowCardinalityAttributes
	mergedLowCardinalityAttributes.merge(lowCardinalityAttributes)
	r.root.recordDuration(
		ctx,
		name,
		duration,
		mergedLowCardinalityAttributes,
	)
}

// IncrementCounterAndLogEvent increments a counter metric by 1
// with the telemetry context's low-cardinality attributes
//
// It additionally records a log record with the telemetry
// context's attributes plus the caller-supplied attributes under the same
// name
func (r *TelemetryRecorder) IncrementCounterAndLogEvent(
	ctx context.Context,
	name string,
	attributes map[string]string,
	lowCardinalityAttributes LowCardinalityAttributes,
) {
	if r == nil {
		return
	}

	r.IncrementCounter(ctx, name, lowCardinalityAttributes)

	recordAttributes := make(map[string]string)
	maps.Copy(recordAttributes, r.telemetryContext.highCardinalityAttributes)
	maps.Copy(recordAttributes, r.telemetryContext.lowCardinalityAttributes.toMap())
	maps.Copy(recordAttributes, attributes)
	r.root.log(
		ctx,
		name,
		recordAttributes,
		otellogapi.SeverityInfo,
	)
}

// Log emits an OpenTelemetry log record with the specified severity level.
//
// The log record contains the telemetry context's attributes,
// in addition to the caller-supplied attributes
func (r *TelemetryRecorder) Log(
	ctx context.Context,
	message string,
	attributes map[string]string,
	severity otellogapi.Severity,
) {
	if r == nil {
		return
	}

	// Copy attributes in order of precedence:
	// 1. Context's high-cardinality attributes
	// 2. Context's low-cardinality attributes
	// 3. Per-record low-cardinality attributes
	// 4. Per-record attributes
	logAttributes := make(map[string]string)
	maps.Copy(logAttributes, r.telemetryContext.highCardinalityAttributes)
	maps.Copy(logAttributes, r.telemetryContext.lowCardinalityAttributes.toMap())
	maps.Copy(logAttributes, attributes)
	r.root.log(ctx, message, logAttributes, severity)
}

// ErrorMetric records an error as a counter metric.
//
// The counter metric has the name "error" and contains
// the low-cardinality attributes from the current telemetry context plus an
// "error.type" attribute (the caller-supplied error type) so the
// rate of each error type can be aggregated and graphed.
func (r *TelemetryRecorder) ErrorMetric(
	ctx context.Context,
	message string,
	err error,
	errorOriginator string,
) {
	if r == nil {
		return
	}

	r.IncrementCounter(
		ctx,
		"error",
		LowCardinalityAttributes{
			ErrorOriginator: errorOriginator,
		},
	)
}

// ErrorLog emits an OpenTelemetry log record with the specified severity level.
//
// The log record contains the attributes from the current telemetry context,
// plus "error.type", "error.message", "error.stacktrace", "error.originator",
// and the caller-supplied attributes.
//
// The stack trace is captured at the point Error is called.
func (r *TelemetryRecorder) ErrorLog(
	ctx context.Context,
	message string,
	err error,
	errorOriginator string,
	attributes map[string]string,
) {
	if r == nil {
		return
	}

	mergedLowCardinalityAttributes := r.telemetryContext.lowCardinalityAttributes
	mergedLowCardinalityAttributes.merge(LowCardinalityAttributes{
		ErrorOriginator: errorOriginator,
	})

	errorMessage := ""
	if err != nil {
		errorMessage = err.Error()
	}
	logAttributes := make(map[string]string)
	maps.Copy(logAttributes, r.telemetryContext.highCardinalityAttributes)
	maps.Copy(logAttributes, mergedLowCardinalityAttributes.toMap())
	maps.Copy(logAttributes, attributes)
	maps.Copy(logAttributes, map[string]string{
		"error.message":    errorMessage,
		"error.stacktrace": captureStacktrace(),
	})
	r.root.log(
		ctx,
		message,
		logAttributes,
		otellogapi.SeverityError,
	)
}

// OpenTelemetryProxyImpl sends metrics, logs events through the W&B
// backend's OpenTelemetry proxy API.
type OpenTelemetryProxy struct {
	// endpoint is the URL of the OpenTelemetry proxy API.
	endpoint string

	// logProvider is the OpenTelemetry log provider.
	logProvider *otellog.LoggerProvider
	// meterProvider is the OpenTelemetry meter provider.
	meterProvider *metric.MeterProvider

	// httpClient is the HTTP client used to send metrics and logs
	// to the OpenTelemetry proxy API.
	httpClient *http.Client

	// serviceName is the name of the service being monitored.
	// This is used to identify the service in the OpenTelemetry backend.
	serviceName string

	// serverSupported reports whether the server exposes the proxy API,
	// probing it on the first call. The exporters drop every batch when
	// it is false.
	serverSupported func() bool

	// shutdown guards Shutdown so the providers are only shut down once.
	shutdown atomic.Bool
}

// NewOpenTelemetryProxy returns an OpenTelemetryProxy for the given endpoint.
//
// When analytics is disabled or the wandbSettings are offline, a nil pointer
// is returned, making calls to the proxy a no-op.
//
// The server is probed for the proxy API on the first export, off the
// recording goroutine; telemetry bound for a server without it is dropped.
func NewOpenTelemetryProxy(
	ctx context.Context,
	wandbSettings *settings.Settings,
	serviceName string,
) *OpenTelemetryProxy {
	if disabled.Load() || wandbSettings.IsOffline() {
		return nil
	}

	httpClient, err := newOTLPHTTPClient(wandbSettings)
	if err != nil {
		slog.Debug(
			"analytics: failed to configure telemetry authentication",
			"error", err,
		)
		return nil
	}

	proxy := &OpenTelemetryProxy{
		endpoint:    wandbSettings.GetBaseURL(),
		httpClient:  httpClient,
		serviceName: serviceName,
	}
	proxy.serverSupported = sync.OnceValue(proxy.probeServer)
	if err := proxy.initializeOTelResources(ctx); err != nil {
		return nil
	}
	return proxy
}

// probeServer reports whether the server exposes the proxy API.
func (o *OpenTelemetryProxy) probeServer() bool {
	ctx, cancel := context.WithTimeout(context.Background(), probeTimeout)
	defer cancel()
	if !checkServerSupportsOpenTelemetryProxy(ctx, o.httpClient, o.endpoint) {
		slog.Debug(
			"analytics: server does not support OpenTelemetry proxy, disabling telemetry",
		)
		return false
	}
	return true
}

// newOTLPHTTPClient builds the HTTP client used for OTLP exports.
//
// The backend accepts unauthenticated telemetry uploads, so when no
// credentials are configured the requests are simply sent without an
// Authorization header.
func newOTLPHTTPClient(
	wandbSettings *settings.Settings,
) (*http.Client, error) {
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.Proxy = wandbSettings.GetProxyFn()
	transport.ProxyConnectHeader = wandbSettings.GetProxyConnectHeader()
	if wandbSettings.IsInsecureDisableSSL() {
		transport.TLSClientConfig = &tls.Config{
			InsecureSkipVerify: true,
		}
	}

	extraHeaders := wandbSettings.GetExtraHTTPHeaders()

	client := &http.Client{
		Timeout: httpClientTimeout,
	}
	client.Transport = httplayers.WrapRoundTripper(
		transport,
		httplayers.Concat(
			httplayers.DefaultHeaders(extraHeaders),
		),
	)
	return client, nil
}

// initializeOTelResources initializes the OpenTelemetry meter and log providers.
func (o *OpenTelemetryProxy) initializeOTelResources(
	ctx context.Context,
) error {
	if o == nil {
		return nil
	}

	res, err := resource.New(
		ctx,
		resource.WithAttributes(semconv.ServiceName(o.serviceName)),
	)
	if err != nil {
		return fmt.Errorf("create resource: %w", err)
	}

	meterProvider, err := o.setupMetrics(ctx, res)
	if err != nil {
		return err
	}
	logProvider, err := o.setupLogs(ctx, res)
	if err != nil {
		if shutdownErr := shutdownTelemetryProviders(
			context.Background(),
			meterProvider,
			nil,
		); shutdownErr != nil {
			return fmt.Errorf("%w; cleanup failed: %v", err, shutdownErr)
		}
		return err
	}

	o.meterProvider = meterProvider
	o.logProvider = logProvider
	return nil
}

// setupMetrics sets up the OpenTelemetry meter provider, used to record metrics.
func (o *OpenTelemetryProxy) setupMetrics(
	ctx context.Context,
	res *resource.Resource,
) (*metric.MeterProvider, error) {
	if o == nil {
		return nil, fmt.Errorf("OpenTelemetryProxy is nil")
	}

	exporter, err := otlpmetrichttp.New(ctx,
		otlpmetrichttp.WithEndpointURL(o.endpoint),
		otlpmetrichttp.WithURLPath(metricsPath),
		otlpmetrichttp.WithHTTPClient(o.httpClient),
		otlpmetrichttp.WithTemporalitySelector(metric.DeltaTemporalitySelector),
	)
	if err != nil {
		return nil, fmt.Errorf("create metric exporter: %w", err)
	}

	return metric.NewMeterProvider(
		metric.WithResource(res),
		metric.WithReader(
			metric.NewPeriodicReader(
				probedMetricExporter{exporter, o.serverSupported},
				metric.WithInterval(defaultExportInterval),
				metric.WithTimeout(defaultExportTimeout),
			),
		),
	), nil
}

// probedMetricExporter drops exports bound for a server without the proxy API.
type probedMetricExporter struct {
	metric.Exporter
	serverSupported func() bool
}

func (e probedMetricExporter) Export(
	ctx context.Context,
	rm *metricdata.ResourceMetrics,
) error {
	if !e.serverSupported() {
		return nil
	}
	return e.Exporter.Export(ctx, rm)
}

// setupLogs sets up the OpenTelemetry log provider, used to record logs.
func (o *OpenTelemetryProxy) setupLogs(
	ctx context.Context,
	res *resource.Resource,
) (*otellog.LoggerProvider, error) {
	if o == nil {
		return nil, fmt.Errorf("OpenTelemetryProxy is nil")
	}

	exporter, err := otlploghttp.New(ctx,
		otlploghttp.WithEndpointURL(o.endpoint),
		otlploghttp.WithURLPath(logsPath),
		otlploghttp.WithHTTPClient(o.httpClient),
	)
	if err != nil {
		return nil, fmt.Errorf("create log exporter: %w", err)
	}

	return otellog.NewLoggerProvider(
		otellog.WithResource(res),
		otellog.WithProcessor(
			otellog.NewBatchProcessor(
				probedLogExporter{exporter, o.serverSupported},
				otellog.WithExportInterval(defaultExportInterval),
				otellog.WithExportTimeout(defaultExportTimeout),
			),
		),
	), nil
}

// probedLogExporter drops exports bound for a server without the proxy API.
type probedLogExporter struct {
	otellog.Exporter
	serverSupported func() bool
}

func (e probedLogExporter) Export(
	ctx context.Context,
	records []otellog.Record,
) error {
	if !e.serverSupported() {
		return nil
	}
	return e.Exporter.Export(ctx, records)
}

func shutdownTelemetryProviders(
	ctx context.Context,
	meterProvider *metric.MeterProvider,
	logProvider *otellog.LoggerProvider,
) error {
	var errs []error
	if meterProvider != nil {
		if err := meterProvider.Shutdown(ctx); err != nil {
			errs = append(errs, err)
		}
	}
	if logProvider != nil {
		if err := logProvider.Shutdown(ctx); err != nil {
			errs = append(errs, err)
		}
	}
	if len(errs) > 0 {
		return fmt.Errorf("shutdown errors: %v", errs)
	}
	return nil
}

// Shutdown flushes any pending records and shuts down all providers,
// after which this proxy and every recorder derived from it become
// no-ops.
//
// It should be called once when telemetry is no longer needed.
// Additional calls to Shutdown are no-ops.
func (o *OpenTelemetryProxy) Shutdown(ctx context.Context) error {
	if o == nil || !o.shutdown.CompareAndSwap(false, true) {
		return nil
	}

	return shutdownTelemetryProviders(ctx, o.meterProvider, o.logProvider)
}

// incrementCounter increments a counter metric by 1.
func (o *OpenTelemetryProxy) incrementCounter(
	ctx context.Context,
	name string,
	lowCardinalityAttributes LowCardinalityAttributes,
) {
	if o == nil {
		return
	}

	meter := o.meterProvider.Meter(o.serviceName)
	counter, err := meter.Int64Counter(name)
	if err != nil {
		return
	}

	counter.Add(ctx, 1, toOTelAttrs(lowCardinalityAttributes.toMap()))
}

// recordDuration records a duration histogram metric in seconds.
func (o *OpenTelemetryProxy) recordDuration(
	ctx context.Context,
	name string,
	duration time.Duration,
	lowCardinalityAttributes LowCardinalityAttributes,
) {
	if o == nil {
		return
	}

	meter := o.meterProvider.Meter(o.serviceName)
	histogram, err := meter.Float64Histogram(
		name,
		otelmetric.WithUnit("s"),
	)
	if err != nil {
		return
	}

	histogram.Record(
		ctx,
		duration.Seconds(),
		toOTelAttrs(lowCardinalityAttributes.toMap()),
	)
}

// log emits an OpenTelemetry log record with the supplied attributes
// and severity level.
func (o *OpenTelemetryProxy) log(
	ctx context.Context,
	body string,
	attributes map[string]string,
	severity otellogapi.Severity,
) {
	if o == nil {
		return
	}

	logger := o.logProvider.Logger(o.serviceName)
	var record otellogapi.Record
	record.SetBody(attribute.StringValue(body))
	record.SetSeverity(severity)

	if len(attributes) > 0 {
		kvs := make([]attribute.KeyValue, 0, len(attributes))
		for k, v := range attributes {
			kvs = append(kvs, attribute.String(k, v))
		}
		record.AddAttributes(kvs...)
	}

	logger.Emit(ctx, record)
}

// captureStacktrace returns a formatted stack trace of the calling goroutine,
// starting at the caller of Error.
//
// This uses only the standard library: it captures the current call stack
// rather than the site where err was created (which Go does not record for
// plain errors.New/fmt.Errorf values).
func captureStacktrace() string {
	pcs := make([]uintptr, 64)
	// Skip runtime.Callers, captureStacktrace, and Error so the trace
	// starts at the code that reported the error.
	n := runtime.Callers(3, pcs)
	if n == 0 {
		return ""
	}
	return formatStackPCs(pcs[:n])
}

// formatStackPCs symbolizes program counters into a human-readable, multi-line
// stack trace of the form:
//
//	package/path.Function
//		/abs/path/file.go:123
func formatStackPCs(pcs []uintptr) string {
	var b strings.Builder
	frames := runtime.CallersFrames(pcs)
	for {
		frame, more := frames.Next()
		fmt.Fprintf(
			&b,
			"%s\n\t%s:%d\n",
			frame.Function,
			frame.File,
			frame.Line,
		)
		if !more {
			break
		}
	}
	return b.String()
}

// toOTelAttrs converts a map of string attributes
// to an otelmetric.WithAttributes option.
func toOTelAttrs(attrs map[string]string) otelmetric.MeasurementOption {
	kvs := make([]attribute.KeyValue, 0, len(attrs))
	for k, v := range attrs {
		kvs = append(kvs, attribute.String(k, v))
	}
	return otelmetric.WithAttributes(kvs...)
}

// checkServerSupportsOpenTelemetryProxy probes the W&B OpenTelemetry proxy
// endpoint to determine whether the server exposes it.
func checkServerSupportsOpenTelemetryProxy(
	ctx context.Context,
	httpClient *http.Client,
	endpoint string,
) bool {
	url := endpoint + metricsPath
	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPost,
		url,
		http.NoBody,
	)
	if err != nil {
		return false
	}

	resp, err := httpClient.Do(req)
	if err != nil {
		return false
	}
	defer resp.Body.Close()

	// Depending on the server configuration, it may respond with a
	// 404 Not Found or a 405 Method Not Allowed when it does not support
	// the proxy API.
	return resp.StatusCode != http.StatusMethodNotAllowed &&
		resp.StatusCode != http.StatusNotFound
}

package leet

import (
	"maps"
	"reflect"
	"runtime"
	"slices"
	"strings"
	"unicode"

	tea "charm.land/bubbletea/v2"
)

// sessionFeatures records the UI features used during this process.
var sessionFeatures = &usedFeatures{names: map[string]struct{}{}}

type usedFeatures struct {
	names map[string]struct{}
}

func (f *usedFeatures) mark(name string) {
	f.names[name] = struct{}{}
}

// attributes returns the used features as one sorted, comma-joined value.
func (f *usedFeatures) attributes() map[string]string {
	attrs := map[string]string{}
	if len(f.names) > 0 {
		attrs["features_used"] = strings.Join(slices.Sorted(maps.Keys(f.names)), ",")
	}
	return attrs
}

// recordFeatureUsage wraps a key handler to record its use, naming the
// feature after the handler method (run.toggle_metrics_grid).
func recordFeatureUsage[T any](
	handler func(*T, tea.KeyPressMsg) tea.Cmd,
) func(*T, tea.KeyPressMsg) tea.Cmd {
	feature := featureName(handler)
	return func(t *T, msg tea.KeyPressMsg) tea.Cmd {
		sessionFeatures.mark(feature)
		return handler(t, msg)
	}
}

func featureName[T any](handler func(*T, tea.KeyPressMsg) tea.Cmd) string {
	name := runtime.FuncForPC(reflect.ValueOf(handler).Pointer()).Name()
	_, method, _ := strings.Cut(name, ").handle")
	return camelToSnake(reflect.TypeFor[T]().Name()) + "." + camelToSnake(method)
}

func camelToSnake(s string) string {
	var b strings.Builder
	for i, r := range s {
		if unicode.IsUpper(r) {
			if i > 0 {
				b.WriteByte('_')
			}
			r = unicode.ToLower(r)
		}
		b.WriteRune(r)
	}
	return b.String()
}

package filetransfer

import "io"

type ProgressReader struct {
	reader   io.ReadSeeker
	len      int64
	read     int64
	callback func(processed, total int64)
}

func NewProgressReader(
	reader io.ReadSeeker,
	size int64,
	callback func(processed, total int64),
) *ProgressReader {
	return &ProgressReader{
		reader:   reader,
		len:      size,
		callback: callback,
	}
}

// Seek implements io.Seeker.
func (pr *ProgressReader) Seek(offset int64, whence int) (n int64, err error) {
	n, err = pr.reader.Seek(offset, whence)

	if err == nil {
		pr.read = n
		pr.invokeCallback()
	}

	return
}

// Read implements io.Reader.
func (pr *ProgressReader) Read(p []byte) (n int, err error) {
	n, err = pr.reader.Read(p)

	if n > 0 {
		pr.read += int64(n)
		pr.invokeCallback()
	}

	return
}

// Len implements retryablehttp.LenReader.
func (pr *ProgressReader) Len() int {
	return int(pr.len)
}

func (pr *ProgressReader) invokeCallback() {
	if pr.callback != nil {
		pr.callback(pr.read, pr.len)
	}
}

package monitor

// suppress golangci-lint unused code warning as it is only used on darwin
var _ = queryMapNumber
var _ = queryMapString

// queryMapNumber reads a number-valued property from a JSON object.
//
// Returns 0 and false if the key is not found or isn't a number.
func queryMapNumber(jsonObj map[string]any, key string) (float64, bool) {
	value, exists := jsonObj[key]
	if !exists {
		return 0, false
	}

	// encoding/json returns all numbers as float64.
	switch x := value.(type) {
	case float64:
		return x, true
	default:
		return 0, false
	}
}

// queryMapString reads a string-valued property from a JSON object.
//
// Returns 0 and false if the key is not found or has the wrong type.
func queryMapString(jsonObj map[string]any, key string) (string, bool) {
	value, exists := jsonObj[key]
	if !exists {
		return "", false
	}

	str, ok := value.(string)
	return str, ok
}

// Package filestream communicates with the W&B backend filestream service.
package filestream

import (
	"context"
	"fmt"
	"net/url"
	"sync"
	"sync/atomic"
	"time"

	"github.com/google/wire"
	"golang.org/x/time/rate"

	"github.com/wandb/wandb/core/internal/api"
	"github.com/wandb/wandb/core/internal/featurechecker"
	"github.com/wandb/wandb/core/internal/observability"
	"github.com/wandb/wandb/core/internal/settings"
	"github.com/wandb/wandb/core/internal/wboperation"
)

const (
	BufferSize               = 32
	EventsFileName           = "wandb-events.jsonl"
	HistoryFileName          = "wandb-history.jsonl"
	SummaryFileName          = "wandb-summary.json"
	OutputFileName           = "output.log"
	defaultHeartbeatInterval = 30 * time.Second
	defaultTransmitInterval  = 15 * time.Second

	// Maximum line length for filestream jsonl files, imposed by the back-end.
	//
	// See https://github.com/wandb/core/pull/7339 for history.
	defaultMaxFileLineBytes = (10 << 20) - (100 << 10)

	// defaultMaxRequestSizeBytes is a default approximate maximum size in bytes
	// for a FileStream request.
	defaultMaxRequestSizeBytes = 10 << 20

	// Retry filestream requests for 7 days before dropping chunk
	// retry_count = seconds_in_7_days / max_retry_time + num_retries_until_max_60_sec
	//             = 7 * 86400 / 60 + ceil(log2(60/2))
	//             = 10080 + 5
	DefaultRetryMax     = 10085
	DefaultRetryWaitMin = 2 * time.Second
	DefaultRetryWaitMax = 60 * time.Second
	// A 3-minute timeout for all filestream post requests
	DefaultNonRetryTimeout = 180 * time.Second
)

type ChunkTypeEnum int8
type FileStreamOffsetMap map[ChunkTypeEnum]int

const (
	NoneChunk ChunkTypeEnum = iota
	HistoryChunk
	OutputChunk
	EventsChunk
	SummaryChunk
)

type FileStream interface {
	// Start asynchronously begins to upload to the backend.
	//
	// All operations are associated with the specified run (defined by
	// `entity`, `project` and `runID`). In case we are resuming a run,
	// the `offsetMap` specifies the initial file offsets for each file
	// type (history, output logs, events, summary).
	Start(
		entity string,
		project string,
		runID string,
		offsetMap FileStreamOffsetMap,
	)

	// FinishWithExit marks the run as complete and blocks until all
	// uploads finish.
	FinishWithExit(exitCode int32)

	// FinishWithoutExit blocks until all uploads finish but does not
	// mark the run as complete.
	FinishWithoutExit()

	// StreamUpdate uploads information through the filestream API.
	StreamUpdate(update Update)

	// IsStopped returns whether the run has been requested to stop.
	//
	// This happens if the user pressed the Stop button in the UI.
	IsStopped() bool
}

// fileStream is a stream of data to the server
type fileStream struct {
	// The relative path on the server to which to make requests.
	//
	// This must not include the schema and hostname prefix.
	path string

	mu              sync.Mutex
	isFinished      bool
	beforeRunEndCtx context.Context

	processChan  chan Update
	feedbackWait *sync.WaitGroup

	// settings is the settings for the filestream
	settings *settings.Settings

	// A logger for internal debug logging.
	logger *observability.CoreLogger

	// The context in which to track filestream operations.
	operations *wboperation.WandbOperations

	// A way to print console messages to the user.
	printer *observability.Printer

	// featureProvider indicates which features the server supports.
	featureProvider *featurechecker.FeatureProvider

	// The client for making API requests.
	apiClient api.RetryableClient
	baseURL   *url.URL

	// The rate limit for sending data to the backend.
	transmitRateLimit *rate.Limiter

	// How long to wait between sending heartbeats to the backend
	// to prove the run is still alive.
	heartbeatPeriod time.Duration

	// A channel that is closed if there is a fatal error.
	deadChan     chan struct{}
	deadChanOnce *sync.Once

	// stopState is the last-known stopped status as reported by the backend.
	//
	// Once it becomes true, it does not switch back to false.
	stopState atomic.Bool
}

// FileStreamProviders binds FileStreamFactory.
var FileStreamProviders = wire.NewSet(
	wire.Struct(new(FileStreamFactory), "*"),
)

type FileStreamFactory struct {
	BaseURL         api.WBBaseURL
	FeatureProvider *featurechecker.FeatureProvider
	Logger          *observability.CoreLogger
	Operations      *wboperation.WandbOperations
	Printer         *observability.Printer
	Settings        *settings.Settings
}

// New returns a new FileStream.
func (f *FileStreamFactory) New(
	apiClient api.RetryableClient,
	beforeRunEndCtx context.Context,
	heartbeatPeriod time.Duration,
	transmitRateLimit *rate.Limiter,
) FileStream {
	// Panic early to avoid surprises. These fields are required.
	switch {
	case f.FeatureProvider == nil:
		panic("filestream: nil feature provider")
	case f.Logger == nil:
		panic("filestream: nil logger")
	case f.Printer == nil:
		panic("filestream: nil printer")
	}

	fs := &fileStream{
		beforeRunEndCtx: beforeRunEndCtx,
		settings:        f.Settings,
		featureProvider: f.FeatureProvider,
		logger:          f.Logger,
		operations:      f.Operations,
		printer:         f.Printer,
		apiClient:       apiClient,
		baseURL:         f.BaseURL,
		processChan:     make(chan Update, BufferSize),
		feedbackWait:    &sync.WaitGroup{},
		deadChanOnce:    &sync.Once{},
		deadChan:        make(chan struct{}),
	}

	fs.heartbeatPeriod = heartbeatPeriod
	if fs.heartbeatPeriod < time.Second { // Prevent spammy mistakes.
		fs.heartbeatPeriod = defaultHeartbeatInterval
	}

	fs.transmitRateLimit = transmitRateLimit
	if fs.transmitRateLimit == nil {
		fs.transmitRateLimit = rate.NewLimiter(rate.Every(defaultTransmitInterval), 1)
	}

	return fs
}

func (fs *fileStream) Start(
	entity string,
	project string,
	runID string,
	offsetMap FileStreamOffsetMap,
) {
	fs.logger.Debug("filestream: start", "path", fs.path)

	fs.path = fmt.Sprintf(
		"files/%s/%s/%s/file_stream",
		entity,
		project,
		runID,
	)

	transmitChan := fs.startProcessingUpdates(fs.processChan)
	feedbackChan := fs.startTransmitting(transmitChan, offsetMap)
	fs.startProcessingFeedback(feedbackChan, fs.feedbackWait)
}

func (fs *fileStream) StreamUpdate(update Update) {
	fs.logger.Debug("filestream: stream update", "update", update)

	fs.mu.Lock()
	defer fs.mu.Unlock()

	if fs.isFinished {
		fs.logger.CaptureError(
			"filestream",
			fmt.Errorf("filestream: StreamUpdate after Finish"),
		)
		return
	}

	select {
	case fs.processChan <- update:
	case <-fs.deadChan:
		// Ignore everything if the filestream is dead.
	case <-fs.beforeRunEndCtx.Done():
		// Ignore new requests if the run got aborted.
	}
}

func (fs *fileStream) FinishWithExit(exitCode int32) {
	fs.StreamUpdate(&ExitUpdate{ExitCode: exitCode})
	fs.FinishWithoutExit()
}

func (fs *fileStream) FinishWithoutExit() {
	fs.mu.Lock()
	if fs.isFinished {
		fs.mu.Unlock()
		return
	}
	fs.isFinished = true
	fs.mu.Unlock()

	close(fs.processChan)
	fs.feedbackWait.Wait()
	fs.logger.Debug("filestream: closed")
}

// IsStopped implements FileStream.IsStopped.
func (fs *fileStream) IsStopped() bool { return fs.stopState.Load() }

// logFatalAndStopWorking logs a fatal error and kills the filestream.
//
// After this, most filestream operations are no-ops. This is meant for
// when we can't guarantee correctness, in which case we stop uploading
// data but continue to save it to disk to avoid data loss.
func (fs *fileStream) logFatalAndStopWorking(err error) {
	if fs.settings.IsStopOnFatalError() {
		fs.stopState.Store(true)
	}

	fs.logger.CaptureFatal(
		"filestream",
		fmt.Errorf("filestream: fatal error: %v", err),
	)
	fs.deadChanOnce.Do(func() {
		close(fs.deadChan)
		fs.printer.Errorf(
			"Fatal error while uploading data. Some run data will" +
				" not be synced, but it will still be written to disk. Use" +
				" `wandb sync` at the end of the run to try uploading.",
		)
	})
}

// isDead reports whether the filestream has been killed.
func (fs *fileStream) isDead() bool {
	select {
	case <-fs.deadChan:
		return true
	default:
		return false
	}
}

package analyticstest

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"slices"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"
	otellogapi "go.opentelemetry.io/otel/log"
	collogspb "go.opentelemetry.io/proto/otlp/collector/logs/v1"
	colmetricspb "go.opentelemetry.io/proto/otlp/collector/metrics/v1"
	commonpb "go.opentelemetry.io/proto/otlp/common/v1"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/wrapperspb"

	"github.com/wandb/wandb/core/internal/analytics"
	wbsettings "github.com/wandb/wandb/core/internal/settings"
	spb "github.com/wandb/wandb/core/pkg/service_go_proto"
)

// Log is a OTLP log record received by an OpenTelemetryProxyTest,
// with its body, severity, and attributes extracted.
type Log struct {
	Body       string
	Severity   otellogapi.Severity
	Attributes map[string]string
}

// Metric is a OTLP metric data point received by an OpenTelemetryProxyTest,
// with its name, value, and attributes extracted.
type Metric struct {
	Name           string
	Unit           string
	Value          int64
	HistogramCount uint64
	HistogramSum   float64
	Attributes     map[string]string
}

// Request is an HTTP request received by an OpenTelemetryProxyTest.
type Request struct {
	Path          string
	Authorization string
	Headers       http.Header
	URLHost       string
	ContentLength int64
}

// OpenTelemetryProxyTest is an OpenTelemetry proxy and test OTLP collector.
type OpenTelemetryProxyTest struct {
	*analytics.OpenTelemetryProxy

	server *httptest.Server

	mu       sync.Mutex
	logs     []Log
	metrics  []Metric
	requests []Request
}

// Requests returns a snapshot of received HTTP requests.
func (s *OpenTelemetryProxyTest) Requests() []Request {
	s.mu.Lock()
	defer s.mu.Unlock()
	return slices.Clone(s.requests)
}

// FindLog returns the first received log with the given body.
func (s *OpenTelemetryProxyTest) FindLog(body string) (Log, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, log := range s.logs {
		if log.Body == body {
			return log, true
		}
	}
	return Log{}, false
}

// FindMetric returns the first received metric with the given name.
func (s *OpenTelemetryProxyTest) FindMetric(name string) (Metric, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, metric := range s.metrics {
		if metric.Name == name {
			return metric, true
		}
	}
	return Metric{}, false
}

// NewOpenTelemetryProxyTest creates an OpenTelemetry proxy backed by an OTLP
// test server.
//
// Call Shutdown before asserting exports to flush the proxy's batch processors.
func NewOpenTelemetryProxyTest(
	t *testing.T,
) *OpenTelemetryProxyTest {
	t.Helper()

	testProxy := &OpenTelemetryProxyTest{}
	testProxy.server = httptest.NewServer(http.HandlerFunc(testProxy.handleExport))
	t.Cleanup(testProxy.server.Close)

	settings := wbsettings.From(&spb.Settings{
		BaseUrl: wrapperspb.String(testProxy.server.URL),
		ApiKey:  wrapperspb.String("test-api-key"),
	})
	proxy := analytics.NewOpenTelemetryProxy(t.Context(), settings, "wandb-core")
	require.NotNil(t, proxy)
	t.Cleanup(func() {
		require.NoError(t, proxy.Shutdown(context.Background()))
	})
	testProxy.OpenTelemetryProxy = proxy
	return testProxy
}

func (s *OpenTelemetryProxyTest) handleExport(w http.ResponseWriter, r *http.Request) {
	s.addRequest(r)
	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "read export body", http.StatusInternalServerError)
		return
	}

	switch r.URL.Path {
	case "/sdk/otel/v1/logs":
		if err := s.addLogs(body); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
	case "/sdk/otel/v1/metrics":
		if err := s.addMetrics(body); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
	default:
		http.Error(w, "unexpected export path", http.StatusNotFound)
		return
	}

	w.WriteHeader(http.StatusOK)
}

func (s *OpenTelemetryProxyTest) addLogs(body []byte) error {
	var request collogspb.ExportLogsServiceRequest
	if err := proto.Unmarshal(body, &request); err != nil {
		return err
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	for _, resourceLogs := range request.GetResourceLogs() {
		for _, scopeLogs := range resourceLogs.GetScopeLogs() {
			for _, logRecord := range scopeLogs.GetLogRecords() {
				s.logs = append(s.logs, Log{
					Body:       logRecord.GetBody().GetStringValue(),
					Severity:   otellogapi.Severity(logRecord.GetSeverityNumber()),
					Attributes: keyValuesToMap(logRecord.GetAttributes()),
				})
			}
		}
	}
	return nil
}

func (s *OpenTelemetryProxyTest) addMetrics(body []byte) error {
	var request colmetricspb.ExportMetricsServiceRequest
	if err := proto.Unmarshal(body, &request); err != nil {
		return err
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	for _, resourceMetrics := range request.GetResourceMetrics() {
		for _, scopeMetrics := range resourceMetrics.GetScopeMetrics() {
			for _, metric := range scopeMetrics.GetMetrics() {
				for _, dataPoint := range metric.GetSum().GetDataPoints() {
					s.metrics = append(s.metrics, Metric{
						Name:       metric.GetName(),
						Value:      dataPoint.GetAsInt(),
						Attributes: keyValuesToMap(dataPoint.GetAttributes()),
					})
				}
				for _, dataPoint := range metric.GetHistogram().GetDataPoints() {
					s.metrics = append(s.metrics, Metric{
						Name:           metric.GetName(),
						Unit:           metric.GetUnit(),
						HistogramCount: dataPoint.GetCount(),
						HistogramSum:   dataPoint.GetSum(),
						Attributes: keyValuesToMap(
							dataPoint.GetAttributes()),
					})
				}
			}
		}
	}
	return nil
}

func (s *OpenTelemetryProxyTest) addRequest(request *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.requests = append(s.requests, Request{
		Path:          request.URL.Path,
		Authorization: request.Header.Get("Authorization"),
		Headers:       request.Header.Clone(),
		URLHost:       request.URL.Host,
		ContentLength: request.ContentLength,
	})
}

func keyValuesToMap(keyValues []*commonpb.KeyValue) map[string]string {
	attributes := make(map[string]string, len(keyValues))
	for _, keyValue := range keyValues {
		attributes[keyValue.GetKey()] = keyValue.GetValue().GetStringValue()
	}
	return attributes
}

#!/usr/bin/env python3
#
# Chris Dolan (chris@semgrep.com)
# Copyright (C) Semgrep 2022
#
# This script translates from jsonschema to protobuf v3 definitions.
# Stable field numbers are calculated using Java's String.hashCode() algorithm
#
# Note: This is not a rigorous 1:1 mapping from jsonschema to protobuf; there
# are likely bugs and/or untranslatable structures.
#

import os
import hashlib
import json
import logging
import sys

logger = logging.getLogger(__name__)

MAX_FIELD_NUMBER = 536870911  # 2^29-1
FIRST_RESERVED_FIELD_NUMBER = 19000
LAST_RESERVED_NUMBER = 19999

JSON_SCHEMA_TO_MESSAGE_TYPE = {
    "object": "message",
    "string": "string",
    "integer": "int64",
    "boolean": "bool",
    "number": "float",
}

JSON_SCHEMA_SCALAR_TYPES = set(["string", "integer", "boolean", "number"])


def hash_code(s):
    return sum([ord(c) * pow(31, i) for i, c in enumerate(s)])


def field_num(s):
    iterations = 0
    num = None
    while not num or (
        num >= FIRST_RESERVED_FIELD_NUMBER and num <= LAST_RESERVED_NUMBER
    ):
        num = hash_code(s + " " * iterations) % MAX_FIELD_NUMBER
        iterations += 1
    return num


def pascal_case(s):
    return s.replace("_", " ").title().replace(" ", "")


def get_type(item):
    t = item.get("type")
    if isinstance(t, str):
        return t
    elif isinstance(t, list):
        t.remove("null")
        if len(t) == 1:
            return t[0]
    else:
        return None


class Message:
    def __init__(self, name, fields):
        self.name = name
        self.fields = fields

    def __str__(self):
        return "message {name} {{\n{fields}\n}}\n".format(
            name=self.name, fields="\n".join([str(f) for f in self.fields])
        )


class Field:
    def __init__(self, name, ftype, rule=None):
        self.name = name
        self.ftype = ftype
        self.rule = rule

    def __str__(self):
        return f"  {self.rule if self.rule else ''}{' ' if self.rule else ''}{self.ftype} {self.name} = {field_num(self.name)};"


class Visitor:
    def __init__(self, definitions):
        self.definitions = definitions

    def resolve(self, name, item):
        ref_id = item.get("$ref")
        if ref_id:
            name = ref_id.split("/")[-1]
            item = self.definitions.get(name)
            return self.resolve(name, item)

        return (name, item)

    def visit_property(self, name, prop, debug_prefix=""):
        logger.debug(f"{debug_prefix}Visiting property: {name} {prop}")
        resolved_name, resolved_prop = self.resolve(name, prop)
        logger.debug(
            f"{debug_prefix}Resolved property: {resolved_name} {resolved_prop}"
        )

        resolved_type = get_type(resolved_prop)
        if resolved_type in JSON_SCHEMA_SCALAR_TYPES:
            logger.debug(f"{debug_prefix}Processing scalar type")
            return Field(name, JSON_SCHEMA_TO_MESSAGE_TYPE.get(resolved_type))
        elif resolved_type == "object":
            logger.debug(f"{debug_prefix}Processing object type")
            additional_properties = resolved_prop.get("additionalProperties")
            if additional_properties:
                ap_name, ap = self.resolve(
                    "additionalProperties", additional_properties
                )
                ap_type = get_type(ap)
                if ap_type == "object":
                    return Field(name, f"map<string, {pascal_case(ap_name)}>")
                else:
                    return Field(
                        name, f"map<string, {JSON_SCHEMA_TO_MESSAGE_TYPE.get(ap_type, 'google.protobuf.Any')}>"
                    )
            return Field(name, pascal_case(resolved_name))
        elif resolved_type is None:
            logger.debug(f"{debug_prefix}Processing None type")
            return Field(name, "google.protobuf.Any")
        elif resolved_type == "array":
            logger.debug(f"{debug_prefix}Processing array type")
            items = resolved_prop.get("items")
            logger.debug(f"{debug_prefix}  Visiting items {items}")
            resolved_item_name, resolved_items = self.resolve("items", items)
            logger.debug(
                f"{debug_prefix}  Resolved items {resolved_item_name} {resolved_items}"
            )

            resolved_item_type = get_type(resolved_items)
            if resolved_item_type in JSON_SCHEMA_SCALAR_TYPES:
                logger.debug(f"{debug_prefix}  Processing scalar type")
                return Field(
                    name,
                    JSON_SCHEMA_TO_MESSAGE_TYPE.get(resolved_item_type),
                    rule="repeated",
                )
            elif resolved_item_type == "object":
                logger.debug(f"{debug_prefix}  Processing object type")
                return Field(name, pascal_case(resolved_item_name), rule="repeated")
            elif resolved_item_type is None:
                logger.debug(f"{debug_prefix}  Processing None type")
                return Field(name, "google.protobuf.Any", rule="repeated")
            elif resolved_item_type == "array" and "prefixItems" in resolved_items:
                logger.debug(f"{debug_prefix} Processing prefixItems type")
                return Field(
                    name, "google.protobuf.Any", rule="repeated"
                )  # TODO: can we model this better?

        raise RuntimeError(f"Conversion Error: {resolved_type=} {resolved_item_type=}")

    def visit_definition(self, name, definition):
        properties = definition.get("properties")
        if not properties:
            return None

        return Message(
            pascal_case(name),
            [
                self.visit_property(prop_name, prop_def)
                for prop_name, prop_def in properties.items()
            ],
        )


def convert(contents, prefix=None, package=None):
    lines = []

    if prefix:
        lines.append(prefix)

    lines.append('syntax = "proto3";\n')
    lines.append('import "google/protobuf/any.proto";\n')

    if package:
        lines.append(f"package {package};\n")

    json_contents = json.loads(contents)
    definitions = json_contents.get("definitions", {})
    visitor = Visitor(definitions)

    message = visitor.visit_definition(json_contents.get("title"), json_contents)
    lines.append(str(message))

    for name, definition in definitions.items():
        dtype = get_type(definition)
        if dtype == "object":
            message = visitor.visit_definition(name, definition)
            if message:
                lines.append(str(message))

    return "\n".join(lines)


def main():
    filename = sys.argv[1]
    package = sys.argv[2]

    logging.basicConfig(
        level=logging.DEBUG if os.environ.get("JS2P_DEBUG") else logging.INFO
    )

    with open(filename, "r") as f:
        contents = f.read()

    prefix = f"""// Generated by jsonschema2protobuf.  DO NOT EDIT!
// Source file: {filename}
// Source file sha256 digest: {hashlib.sha256(contents.encode('utf-8')).hexdigest()}
"""

    print(convert(contents, prefix=prefix, package=package))


if __name__ == "__main__":
    main()

