    let error = anyhow::anyhow!("test error");
    let error_fmt = ErrorFormat {
      context: &ErrorContext::PatternHasError,
      inner: &error,
    };
    let display = format!("{error_fmt}");
    assert_eq!(display.lines().count(), 3);
    assert!(display.contains("Pattern contains an ERROR node"));
    assert!(display.contains("Warning"));
  }

  #[test]
  fn test_bare_anyhow() {
    let error = anyhow::anyhow!(ErrorContext::ReadConfiguration);
    let error_fmt = ErrorFormat {
      context: &ErrorContext::ReadConfiguration,
      inner: &error,
    };
    let display = format!("{error_fmt}");
    assert_eq!(display.lines().count(), 3);
    assert!(display.contains("Cannot read configuration."));
    assert!(
      !display.contains("Caused by"),
      "Should not contain error chain"
    );
  }

  #[test]
  fn test_exit_interactive_editing_is_soft_error() {
    let error = anyhow::anyhow!(ErrorContext::ExitInteractiveEditing);
    let error_fmt = ErrorFormat {
      context: &ErrorContext::ExitInteractiveEditing,
      inner: &error,
    };
    let display = format!("{error_fmt}");
    assert_eq!(display.lines().count(), 2);
    assert!(display.contains("Interactive editing exited."));
    assert!(display.contains("Warning"));
    assert!(!display.contains("Error"));

    // Check that it's considered a soft error with exit code 0
    assert_eq!(ErrorContext::ExitInteractiveEditing.exit_code(), 0);
    assert!(ErrorContext::ExitInteractiveEditing.is_soft_error());
  }

  #[test]
  fn test_broken_pipe_exits_quietly() {
    let io_err = std::io::Error::from(std::io::ErrorKind::BrokenPipe);
    let error = anyhow::Error::new(io_err).context("while printing matches");
    assert!(matches!(
      exit_with_error(error),
      Ok(code) if code == std::process::ExitCode::SUCCESS
    ));
  }

  #[test]
  fn test_other_io_error_is_reported() {
    let io_err = std::io::Error::from(std::io::ErrorKind::PermissionDenied);
    let error = anyhow::Error::new(io_err);
    assert!(exit_with_error(error).is_err());
  }
}

use std::borrow::Cow;

use ast_grep_outline::model::{
  EntryRole, OutlineEntry, OutlineItem, OutlineMember, SourcePosition, SourceRange, SymbolType,
};

use crate::print::JsonStyle;

use super::*;
use crate::outline::{OutlineItems, OutlineView};

fn style(view: OutlineView) -> OutlineStyle {
  OutlineStyle::new(view, false, OutlineItems::All)
}

fn color_style(view: OutlineView) -> OutlineStyle {
  OutlineStyle::new(view, true, OutlineItems::All)
}

fn range(line: usize) -> SourceRange {
  SourceRange {
    byte_offset: 0..0,
    start: SourcePosition { line, column: 0 },
    end: SourcePosition { line, column: 0 },
  }
}

fn entry(
  role: EntryRole,
  symbol_type: SymbolType,
  name: &'static str,
  signature: &'static str,
  line: usize,
) -> OutlineEntry<'static> {
  OutlineEntry {
    role,
    symbol_type,
    name: Cow::Borrowed(name),
    range: range(line),
    signature: Cow::Borrowed(signature),
    ast_kind: Cow::Borrowed("test_node"),
  }
}

fn member(
  symbol_type: SymbolType,
  name: &'static str,
  signature: &'static str,
  line: usize,
  is_public: bool,
) -> OutlineMember<'static> {
  OutlineMember {
    entry: entry(EntryRole::Member, symbol_type, name, signature, line),
    is_public,
  }
}

fn outline_file() -> OutlineFile<'static> {
  OutlineFile {
    path: "src/parser.ts".to_string(),
    language: "TypeScript".to_string(),
    items: vec![OutlineItem {
      entry: entry(
        EntryRole::Item,
        SymbolType::Class,
        "Parser",
        "export class Parser",
        39,
      ),
      is_import: false,
      is_exported: true,
      members: vec![
        member(SymbolType::Method, "parse", "parse(...)", 43, true),
        member(SymbolType::Method, "recover", "recover(...)", 72, false),
      ],
    }],
  }
}

fn item(
  symbol_type: SymbolType,
  name: &'static str,
  signature: &'static str,
  line: usize,
) -> OutlineItem<'static> {
  OutlineItem {
    entry: entry(EntryRole::Item, symbol_type, name, signature, line),
    is_import: false,
    is_exported: false,
    members: vec![],
  }
}

