                )
            })
            .unwrap();
        let generate_result = tree_sitter_generate::generate_parser_for_grammar(
            &grammar_json,
            Some((0, 0, 0)),
            OptLevel::default(),
            &mut Vec::new(),
        );

        if error_message_path.exists() {
