        });

        // opening another file in a split should not influence the LSP query counter
        workspace.update_in(cx, |workspace, window, cx| {
            assert_eq!(
                workspace.panes().len(),
                1,
                "Should have one pane with one editor"
            );
            workspace.move_item_to_pane_in_direction(
                &MoveItemToPaneInDirection {
                    direction: workspace::SplitDirection::Right,
                    focus: false,
                    clone: true,
                },
                window,
                cx,
            );
        });
        cx.run_until_parked();
        workspace.update_in(cx, |workspace, _, cx| {
            let panes = workspace.panes();
            assert_eq!(panes.len(), 2, "Should have two panes after splitting");
            for pane in panes {
                let editor = pane
                    .read(cx)
                    .active_item()
                    .and_then(|item| item.downcast::<Editor>())
                    .expect("Should have opened an editor in each split");
                let editor_file = editor
                    .read(cx)
                    .buffer()
                    .read(cx)
                    .as_singleton()
                    .expect("test deals with singleton buffers")
                    .read(cx)
                    .file()
                    .expect("test buffese should have a file")
                    .path();
                assert_eq!(
                    editor_file.as_ref(),
                    rel_path("first.rs"),
                    "Both editors should be opened for the same file"
                )
            }
        });

        cx.executor().advance_clock(Duration::from_millis(500));
        let save = editor.update_in(cx, |editor, window, cx| {
            editor.move_to_end(&MoveToEnd, window, cx);
            editor.handle_input("dirty", window, cx);
            editor.save(
                SaveOptions {
                    format: true,
                    force_format: false,
                    autosave: true,
                },
                project.clone(),
                window,
                cx,
            )
        });
        save.await.unwrap();

        color_request_handle.next().await.unwrap();
        cx.run_until_parked();
        assert_eq!(
            2,
            requests_made.load(atomic::Ordering::Acquire),
            "Should query for colors once per save (deduplicated) and once per formatting after save"
        );

        drop(editor);
        let close = workspace.update_in(cx, |workspace, window, cx| {
            workspace.active_pane().update(cx, |pane, cx| {
                pane.close_active_item(&CloseActiveItem::default(), window, cx)
            })
        });
        close.await.unwrap();
        let close = workspace.update_in(cx, |workspace, window, cx| {
            workspace.active_pane().update(cx, |pane, cx| {
                pane.close_active_item(&CloseActiveItem::default(), window, cx)
            })
        });
        close.await.unwrap();
        assert_eq!(
            2,
            requests_made.load(atomic::Ordering::Acquire),
            "After saving and closing all editors, no extra requests should be made"
        );
        workspace.update_in(cx, |workspace, _, cx| {
            assert!(
                workspace.active_item(cx).is_none(),
                "Should close all editors"
            )
        });

        workspace.update_in(cx, |workspace, window, cx| {
            workspace.active_pane().update(cx, |pane, cx| {
                pane.navigate_backward(&workspace::GoBack, window, cx);
            })
        });
        cx.executor().advance_clock(LSP_REQUEST_DEBOUNCE_TIMEOUT);
        cx.run_until_parked();
        let editor = workspace.update_in(cx, |workspace, _, cx| {
            workspace
                .active_item(cx)
                .expect("Should have reopened the editor again after navigating back")
                .downcast::<Editor>()
                .expect("Should be an editor")
        });

        assert_eq!(
            2,
            requests_made.load(atomic::Ordering::Acquire),
            "Cache should be reused on buffer close and reopen"
        );
        editor.update(cx, |editor, cx| {
            assert_eq!(
                vec![expected_color],
                extract_color_inlays(editor, cx),
                "Should have an initial inlay"
            );
        });

        drop(color_request_handle);
        let closure_requests_made = Arc::clone(&requests_made);
        let mut empty_color_request_handle = fake_language_server
            .set_request_handler::<lsp::request::DocumentColor, _, _>(move |params, _| {
                let requests_made = Arc::clone(&closure_requests_made);
                async move {
                    assert_eq!(
                        params.text_document.uri,
                        lsp::Uri::from_file_path(path!("/a/first.rs")).unwrap()
                    );
                    requests_made.fetch_add(1, atomic::Ordering::Release);
                    Ok(Vec::new())
                }
            });
        let save = editor.update_in(cx, |editor, window, cx| {
            editor.move_to_end(&MoveToEnd, window, cx);
            editor.handle_input("dirty_again", window, cx);
            editor.save(
                SaveOptions {
                    format: false,
                    force_format: false,
                    autosave: true,
                },
                project.clone(),
                window,
                cx,
            )
        });
        save.await.unwrap();

        cx.executor().advance_clock(LSP_REQUEST_DEBOUNCE_TIMEOUT);
        empty_color_request_handle.next().await.unwrap();
        cx.run_until_parked();
        assert_eq!(
            3,
            requests_made.load(atomic::Ordering::Acquire),
            "Should query for colors once per save only, as formatting was not requested"
        );
        editor.update(cx, |editor, cx| {
            assert_eq!(
                Vec::<Rgba>::new(),
                extract_color_inlays(editor, cx),
                "Should clear all colors when the server returns an empty response"
            );
        });
    }
}

use collections::HashMap;
use futures::future::join_all;
use gpui::{App, Entity, Task};
use itertools::Itertools;
use language::{Buffer, BufferSnapshot};
use lsp::LanguageServerId;
use project::lsp_store::{BufferDocumentLinks, LspDocumentLink, ResolvedDocumentLink};
use settings::Settings;
use text::BufferId;
use ui::Context;

use crate::{Editor, LSP_REQUEST_DEBOUNCE_TIMEOUT, editor_settings::EditorSettings};

pub(super) struct LspDocumentLinks {
    pub(super) enabled: bool,
    pub(super) per_buffer: HashMap<BufferId, BufferDocumentLinks>,
    pub(super) refresh_task: Task<()>,
}

impl LspDocumentLinks {
    pub(super) fn new(cx: &App) -> Self {
        Self {
            enabled: EditorSettings::get_global(cx).lsp_document_links,
            per_buffer: HashMap::default(),
            refresh_task: Task::ready(()),
        }
    }
}

impl Editor {
    pub(super) fn refresh_document_links(
        &mut self,
        for_buffer: Option<BufferId>,
        cx: &mut Context<Self>,
    ) {
        if !self.lsp_data_enabled() || !self.lsp_document_links.enabled {
            return;
        }
        let Some(project) = self.project.as_ref().map(|p| p.downgrade()) else {
            return;
        };

        let buffers_to_query = self
            .visible_buffers(cx)
            .into_iter()
            .filter(|buffer| self.is_lsp_relevant(buffer.read(cx).file(), cx))
            .chain(for_buffer.and_then(|id| self.buffer.read(cx).buffer(id)))
            .filter(|buffer| {
                let id = buffer.read(cx).remote_id();
                for_buffer.is_none_or(|target| target == id)
                    && self.registered_buffers.contains_key(&id)
            })
            .unique_by(|buffer| buffer.read(cx).remote_id())
            .collect::<Vec<_>>();
        if buffers_to_query.is_empty() {
            self.lsp_document_links.refresh_task = Task::ready(());
            return;
        }

        self.lsp_document_links.refresh_task = cx.spawn(async move |editor, cx| {
            cx.background_executor()
                .timer(LSP_REQUEST_DEBOUNCE_TIMEOUT)
                .await;

            let Some(tasks_for_buffers) = project
                .update(cx, |project, cx| {
                    project.lsp_store().update(cx, |lsp_store, cx| {
                        buffers_to_query
                            .into_iter()
                            .map(|buffer| {
                                let buffer_id = buffer.read(cx).remote_id();
                                let task = lsp_store.fetch_document_links(&buffer, cx);
                                async move { (buffer_id, task.await) }
                            })
                            .collect::<Vec<_>>()
                    })
                })
                .ok()
            else {
                return;
            };

            let new_links_for_buffers = join_all(tasks_for_buffers).await;
            editor
                .update(cx, |editor, _| {
                    for (buffer_id, links) in new_links_for_buffers {
                        let Some(links) = links else {
                            continue;
                        };
                        if links.is_empty() {
                            editor.lsp_document_links.per_buffer.remove(&buffer_id);
                        } else {
                            editor
                                .lsp_document_links
                                .per_buffer
                                .insert(buffer_id, links);
                        }
                    }
                })
                .ok();
        });
    }

    /// Returns a task yielding the resolved document links covering `position`
    /// in `buffer`, paired with the language server that owns each link.
    /// Resolution is deduplicated through `LspStore`'s per-`(server_id,
    /// link_id)` `Shared` task; the editor's mirror is updated when the
    /// resolves complete so subsequent renders/hovers find resolved data
    /// without re-issuing requests.
    ///
    /// Returns `None` when nothing is cached at `position` so callers can skip
    /// spawning anything.
    pub fn document_links_at(
        &mut self,
        buffer: Entity<Buffer>,
        position: text::Anchor,
        cx: &mut Context<Self>,
    ) -> Option<Task<Vec<(LanguageServerId, LspDocumentLink)>>> {
        let buffer_id = buffer.read(cx).remote_id();
        let snapshot = buffer.read(cx).snapshot();
        let matches = self
            .lsp_document_links
            .per_buffer
            .get(&buffer_id)?
            .iter()
            .flat_map(|(server_id, per_server)| {
                per_server
                    .iter()
                    .map(move |(link_id, link)| (*server_id, *link_id, link))
            })
            .filter(|(_, _, link)| link_contains(link, &position, &snapshot))
            .map(|(server_id, link_id, link)| (server_id, link_id, link.clone()))
            .collect::<Vec<_>>();
        if matches.is_empty() {
            return None;
        }

        let project = self.project.clone()?;
        let mut resolved_links = Vec::with_capacity(matches.len());
        let mut pending = Vec::new();
        project.update(cx, |project, cx| {
            project.lsp_store().update(cx, |lsp_store, cx| {
                for (server_id, link_id, _link) in matches {
                    match lsp_store.resolved_document_link(&buffer, server_id, link_id, cx) {
                        Some(ResolvedDocumentLink::Resolved(resolved)) => {
                            resolved_links.push((server_id, link_id, resolved));
                        }
                        Some(ResolvedDocumentLink::Resolving(task)) => {
                            pending.push((server_id, task));
                        }
                        None => {
                            // Cache no longer holds the link (likely a version
                            // bump between the mirror snapshot and now); skip.
                        }
                    }
                }
            })
        });

        if pending.is_empty() {
            return Some(Task::ready(
                resolved_links
                    .into_iter()
                    .map(|(server_id, _, link)| (server_id, link))
                    .collect(),
            ));
        }

        Some(cx.spawn(async move |editor, cx| {
            let pending_results =
                join_all(pending.into_iter().map(|(server_id, task)| async move {
                    task.await.map(|(link_id, link)| (server_id, link_id, link))
                }))
                .await;
            resolved_links.extend(pending_results.into_iter().flatten());
            editor
                .update(cx, |editor, cx| {
                    if let Some(by_server) =
                        editor.lsp_document_links.per_buffer.get_mut(&buffer_id)
                    {
                        for (server_id, link_id, resolved) in &resolved_links {
                            if let Some(slot) = by_server
                                .get_mut(server_id)
                                .and_then(|links| links.get_mut(link_id))
                            {
                                *slot = resolved.clone();
                            }
                        }
                    }
                    cx.notify();
                })
                .ok();

            resolved_links
                .into_iter()
                .map(|(server_id, _, link)| (server_id, link))
                .collect()
        }))
    }
}

fn link_contains(
    link: &LspDocumentLink,
    position: &text::Anchor,
    snapshot: &BufferSnapshot,
) -> bool {
    link.range.start.cmp(position, snapshot).is_le()
        && link.range.end.cmp(position, snapshot).is_ge()
}

