package com.tabbyml.tabby4eclipse.editor;

import java.net.URI;

import org.eclipse.core.resources.IFile;
import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.IDocumentExtension4;
import org.eclipse.jface.text.ITextSelection;
import org.eclipse.jface.text.ITextViewer;
import org.eclipse.jface.text.ITextViewerExtension5;
import org.eclipse.jface.viewers.ISelection;
import org.eclipse.lsp4e.LSPEclipseUtils;
import org.eclipse.swt.SwtCallable;
import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.widgets.Display;
import org.eclipse.ui.IEditorPart;
import org.eclipse.ui.IWorkbenchPage;
import org.eclipse.ui.IWorkbenchWindow;
import org.eclipse.ui.PlatformUI;
import org.eclipse.ui.contexts.IContextService;
import org.eclipse.ui.texteditor.ITextEditor;

public class EditorUtils {
	public static IWorkbenchPage getActiveWorkbenchPage() {
		IWorkbenchWindow window = PlatformUI.getWorkbench().getActiveWorkbenchWindow();
		if (window != null) {
			IWorkbenchPage page = window.getActivePage();
			return page;
		}
		return null;
	}

	public static ITextEditor getActiveTextEditor() {
		IWorkbenchPage page = getActiveWorkbenchPage();
		if (page != null) {
			IEditorPart activeEditor = page.getActiveEditor();
			if (activeEditor instanceof ITextEditor textEditor) {
				return textEditor;
			}
		}
		return null;
	}

	public static boolean isActiveEditor(ITextEditor textEditor) {
		return textEditor == EditorUtils.getActiveTextEditor();
	}

	public static ITextViewer getTextViewer(ITextEditor textEditor) {
		return (ITextViewer) textEditor.getAdapter(ITextViewer.class);
	}

	public static IDocument getDocument(ITextEditor textEditor) {
		return LSPEclipseUtils.getDocument(textEditor.getEditorInput());
	}

	public static URI getUri(ITextEditor textEditor) {
		IDocument document = getDocument(textEditor);
		return LSPEclipseUtils.toUri(document);
	}

	public static StyledText getStyledTextWidget(ITextEditor textEditor) {
		return getTextViewer(textEditor).getTextWidget();
	}

	public static Display getDisplay(ITextEditor textEditor) {
		return getStyledTextWidget(textEditor).getDisplay();
	}

	public static IContextService getContextService(ITextEditor textEditor) {
		return textEditor.getSite().getService(IContextService.class);
	}

	public static void asyncExec(Runnable runnable) {
		PlatformUI.getWorkbench().getDisplay().asyncExec(runnable);
	}

	public static void asyncExec(ITextEditor textEditor, Runnable runnable) {
		getDisplay(textEditor).asyncExec(runnable);
	}

	public static void syncExec(Runnable runnable) {
		PlatformUI.getWorkbench().getDisplay().syncExec(runnable);
	}

	public static void syncExec(ITextEditor textEditor, Runnable runnable) {
		getDisplay(textEditor).syncExec(runnable);
	}

	public static <T, E extends Exception> T syncCall(SwtCallable<T, E> callable) throws E {
		return PlatformUI.getWorkbench().getDisplay().syncCall(callable);
	}

	public static <T, E extends Exception> T syncCall(ITextEditor textEditor, SwtCallable<T, E> callable) throws E {
		return getDisplay(textEditor).syncCall(callable);
	}

	public static long getDocumentModificationStamp(ITextEditor textEditor) {
		IDocument document = getDocument(textEditor);
		if (document instanceof IDocumentExtension4 documentExt) {
			return documentExt.getModificationStamp();
		} else if (document != null) {
			IFile file = LSPEclipseUtils.getFile(document);
			if (file != null) {
				return file.getModificationStamp();
			}
		}
		return IDocumentExtension4.UNKNOWN_MODIFICATION_STAMP;
	}

	public static int getCurrentOffsetInDocument(ITextEditor textEditor) throws IllegalStateException {
		return syncCall(textEditor, () -> {
			int offset = -1;
			ISelection selection = textEditor.getSelectionProvider().getSelection();
			if (selection instanceof ITextSelection textSelection) {
				offset = textSelection.getOffset();
			}
			if (offset != -1) {
				return offset;
			}

			int offsetInWidget = getStyledTextWidget(textEditor).getCaretOffset();
			ITextViewer textViewer = getTextViewer(textEditor);
			if (textViewer instanceof ITextViewerExtension5 textViewerExt) {
				offset = textViewerExt.widgetOffset2ModelOffset(offsetInWidget);
			}
			if (offset != -1) {
				return offset;
			}

			throw new IllegalStateException("Failed to get current offset in document.");
		});
	}

	public static String getSelectedText() {
		ITextEditor editor = getActiveTextEditor();
		if (editor != null) {
			return getSelectedText(editor);
		}
		return null;
	}

	public static String getSelectedText(ITextEditor textEditor) {
		ISelection selection = textEditor.getSelectionProvider().getSelection();
		if (selection instanceof ITextSelection textSelection) {
			return textSelection.getText();
		}
		return null;
	}
}

package com.tabbyml.intellijtabby.events

import com.intellij.openapi.Disposable
import com.intellij.openapi.components.Service
import com.intellij.openapi.components.service
import com.intellij.openapi.project.Project
import com.intellij.util.messages.Topic
import com.tabbyml.intellijtabby.lsp.ConnectionService
import com.tabbyml.intellijtabby.lsp.LanguageClient
import com.tabbyml.intellijtabby.lsp.protocol.Config
import com.tabbyml.intellijtabby.lsp.protocol.StatusInfo
import com.tabbyml.intellijtabby.notifications.hideAuthRequiredNotification
import com.tabbyml.intellijtabby.notifications.notifyAuthRequired
import com.tabbyml.intellijtabby.safeSyncPublisher
import com.tabbyml.intellijtabby.settings.SettingsService

@Service(Service.Level.PROJECT)
class CombinedState(private val project: Project) : Disposable {
  private val messageBusConnection = project.messageBus.connect()

  data class State(
    val settings: SettingsService.Settings,
    val connectionState: ConnectionService.State,
    val agentStatus: StatusInfo?,
    val agentConfig: Config?,
  ) {
    fun withSettings(settings: SettingsService.Settings): State {
      return State(settings, connectionState, agentStatus, agentConfig)
    }

    fun withConnectionState(connectionState: ConnectionService.State): State {
      return State(settings, connectionState, agentStatus, agentConfig)
    }

    fun withStatus(status: StatusInfo): State {
      return State(settings, connectionState, status, agentConfig)
    }

    fun withConfig(config: Config): State {
      return State(settings, connectionState, agentStatus, config)
    }
  }

  var state = State(
    service<SettingsService>().settings(),
    ConnectionService.State.INITIALIZING,
    null,
    null,
  )
    private set

  init {
    messageBusConnection.subscribe(SettingsService.Listener.TOPIC, object : SettingsService.Listener {
      override fun settingsChanged(settings: SettingsService.Settings) {
        state = state.withSettings(settings)
        project.safeSyncPublisher(Listener.TOPIC)?.stateChanged(state)
      }
    })
    messageBusConnection.subscribe(ConnectionService.Listener.TOPIC, object : ConnectionService.Listener {
      override fun connectionStateChanged(state: ConnectionService.State) {
        this@CombinedState.state = this@CombinedState.state.withConnectionState(state)
        project.safeSyncPublisher(Listener.TOPIC)?.stateChanged(this@CombinedState.state)
      }
    })
    messageBusConnection.subscribe(LanguageClient.StatusListener.TOPIC, object : LanguageClient.StatusListener {
      override fun statusChanged(status: StatusInfo) {
        state = state.withStatus(status)
        project.safeSyncPublisher(Listener.TOPIC)?.stateChanged(state)

        if (status.status == StatusInfo.Status.UNAUTHORIZED) {
          notifyAuthRequired()
        } else {
          hideAuthRequiredNotification()
        }
      }
    })
    messageBusConnection.subscribe(LanguageClient.ConfigListener.TOPIC, object : LanguageClient.ConfigListener {
      override fun configChanged(config: Config) {
        state = state.withConfig(config)
        project.safeSyncPublisher(Listener.TOPIC)?.stateChanged(state)
      }
    })
  }

  override fun dispose() {
    messageBusConnection.dispose()
  }

  interface Listener {
    fun stateChanged(state: State) {}

    companion object {
      @Topic.ProjectLevel
      val TOPIC = Topic(Listener::class.java, Topic.BroadcastDirection.NONE)
    }
  }
}

package com.tabbyml.intellijtabby.events

import com.intellij.openapi.Disposable
import com.intellij.openapi.components.Service
import com.intellij.openapi.project.Project
import com.intellij.util.messages.Topic
import com.tabbyml.intellijtabby.lsp.LanguageClient
import com.tabbyml.intellijtabby.safeSyncPublisher

@Service(Service.Level.PROJECT)
class FeaturesState(private val project: Project) : Disposable {
  private val messageBusConnection = project.messageBus.connect()
  private val registrations = mutableMapOf<String, Pair<String, Any>>()

  data class Features(
    val inlineCompletion: Boolean,
    val chat: Boolean,
  )

  val features: Features
    get() = Features(
      inlineCompletion = registrations.containsKey("textDocument/inlineCompletion"),
      chat = registrations.containsKey("tabby/chat"),
    )

  init {
    messageBusConnection.subscribe(
      LanguageClient.CapabilityRegistrationListener.TOPIC,
      object : LanguageClient.CapabilityRegistrationListener {
        override fun onRegisterCapability(id: String, method: String, options: Any) {
          registrations[method] = Pair(id, options)
          project.safeSyncPublisher(Listener.TOPIC)?.stateChanged(features)
        }

        override fun onUnregisterCapability(id: String, method: String) {
          registrations.remove(method)
          project.safeSyncPublisher(Listener.TOPIC)?.stateChanged(features)
        }
      })
  }

  override fun dispose() {
    messageBusConnection.dispose()
  }

  interface Listener {
    fun stateChanged(features: Features) {}

    companion object {
      @Topic.ProjectLevel
      val TOPIC = Topic(Listener::class.java, Topic.BroadcastDirection.NONE)
    }
  }
}

use std::{
    collections::VecDeque,
    env::var,
    net::TcpListener,
    process::Stdio,
    time::{Duration, Instant},
};

use tokio::{
    io::{AsyncBufReadExt, BufReader},
    task::JoinHandle,
};
use tracing::{debug, warn};
use which::which;

use crate::api_endpoint;

pub struct LlamaCppSupervisor {
    name: &'static str,
    port: u16,
    handle: JoinHandle<()>,
}

impl LlamaCppSupervisor {
    pub fn new(
        name: &'static str,
        num_gpu_layers: u16,
        embedding: bool,
        model_path: &str,
        parallelism: u8,
        chat_template: Option<String>,
        enable_fast_attention: bool,
        context_size: usize,
    ) -> LlamaCppSupervisor {
        let Some(binary_name) = find_binary_name() else {
            panic!("Failed to locate llama-server binary, please make sure you have llama-server binary locates in the same directory as the current executable.");
        };

        let model_path = model_path.to_owned();
        let port = get_available_port();
        let mut retry_count = 0;
        let initial_time = Instant::now();

        let handle = tokio::spawn(async move {
            loop {
                let server_binary = std::env::current_exe()
                    .expect("Failed to get current executable path")
                    .parent()
                    .expect("Failed to get parent directory")
                    .join(&binary_name)
                    .display()
                    .to_string();
                let mut command = tokio::process::Command::new(server_binary);

                command
                    .arg("-m")
                    .arg(&model_path)
                    .arg("--cont-batching")
                    .arg("--port")
                    .arg(port.to_string())
                    .arg("-np")
                    .arg(parallelism.to_string())
                    .arg("--ctx-size")
                    .arg(context_size.to_string())
                    .kill_on_drop(true)
                    .stderr(Stdio::piped())
                    .stdout(Stdio::null());

                if let Ok(n_threads) = std::env::var("LLAMA_CPP_N_THREADS") {
                    command.arg("-t").arg(n_threads);
                }

                if num_gpu_layers > 0 {
                    command.arg("-ngl").arg(num_gpu_layers.to_string());
                }

                if embedding {
                    command
                        .arg("--embedding")
                        .arg("--ubatch-size")
                        .arg(var("LLAMA_CPP_EMBEDDING_N_UBATCH_SIZE").unwrap_or("4096".into()));
                }

                if let Some(chat_template) = chat_template.as_ref() {
                    command.arg("--chat-template").arg(chat_template);
                }

                if enable_fast_attention {
                    command.arg("-fa");
                };

                let command_args = format!("{:?}", command);

                let mut process = command.spawn().unwrap_or_else(|e| {
                    panic!(
                        "Failed to start llama-server <{}> with command {:?}: {}",
                        name, command, e
                    )
                });

                let mut stderr = BufReader::new(
                    process
                        .stderr
                        .take()
                        .expect("Failed to get llama.cpp stderr"),
                )
                .lines();
                let mut error_lines = VecDeque::with_capacity(100);

                let wait_handle = process.wait();

                while let Ok(Some(line)) = stderr.next_line().await {
                    if !line.contains("GET /health") {
                        if error_lines.len() >= 100 {
                            error_lines.pop_front();
                        }
                        error_lines.push_back(line);
                    }
                }

                let status_code = wait_handle.await.ok().and_then(|s| s.code()).unwrap_or(-1);

                if status_code != 0 {
                    warn!(
                        "llama-server <{}> exited with status code {}, args: `{}`",
                        name, status_code, command_args
                    );

                    // print only the initial round error message.
                    if retry_count == 0 {
                        eprintln!(
                            "{}\n",
                            tabby_common::terminal::HeaderFormat::BoldRed
                                .format("Recent llama-cpp errors:")
                        );
                    }
                    for line in error_lines {
                        // print only the initial round error message.
                        if retry_count == 0 {
                            eprintln!("{}", line);
                        }
                        if let Some(solution) = analyze_error_message(&line) {
                            let solution_lines: Vec<_> = solution.split('\n').collect();
                            let msg = tabby_common::terminal::InfoMessage::new(
                                "ERROR",
                                tabby_common::terminal::HeaderFormat::BoldRed,
                                &solution_lines,
                            );
                            msg.print();
                            break;
                        }
                    }

                    // exit only after the retry loop has been exhausted 5 times and Tabby was initialing for fewer than 1 minute.
                    if retry_count >= 5 && initial_time.elapsed().as_secs() < 60 {
                        eprintln!(
                            "llama-server <{}> encountered a fatal error. Exiting service. Please check the above logs and suggested solutions for details.",
                            name
                        );
                        std::process::exit(1);
                    }

                    retry_count += 1;
                    warn!("Attempting to restart the llama-server...");
                    tokio::time::sleep(Duration::from_secs(1)).await;
                }
            }
        });

        Self { name, handle, port }
    }

    pub fn port(&self) -> u16 {
        self.port
    }

    pub async fn start(&self) {
        debug!("Waiting for llama-server <{}> to start...", self.name);
        let client = reqwest::Client::builder().no_proxy().build().unwrap();
        loop {
            let Ok(resp) = client
                .get(api_endpoint(self.port) + "/health")
                .timeout(Duration::from_secs(1))
                .send()
                .await
            else {
                debug!("llama-server <{}> not ready yet, retrying...", self.name);
                tokio::time::sleep(Duration::from_secs(1)).await;
                continue;
            };

            if resp.status().is_success() {
                debug!("llama-server <{}> started successfully", self.name);
                return;
            }
        }
    }
}

fn analyze_error_message(error_message: &str) -> Option<String> {
    if error_message.contains("cudaMalloc") {
        return Some(String::from(
            "CUDA memory allocation error detected:\n\
             1. Try using a smaller Model\n\
             2. Try to reduce GPU memory usage\n",
        ));
    }

    #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
    {
        if error_message.contains("Illegal instruction")
            && !std::arch::is_x86_feature_detected!("avx2")
        {
            return Some(String::from(
                "Illegal instruction detected: Your CPU does not support AVX2 instruction set.\n\
                 Suggestion: Download a compatible binary from https://github.com/ggml-org/llama.cpp/releases"
            ));
        }
    }

    None
}

fn find_binary_name() -> Option<String> {
    let current_exe = std::env::current_exe().expect("Failed to get current executable path");
    let binary_dir = current_exe
        .parent()
        .expect("Failed to get parent directory");
    let binary_name = "llama-server".to_owned();
    let binary_from_path = which("llama-server")
        .ok()
        .map(|path| path.display().to_string());
    std::fs::read_dir(binary_dir)
        .expect("Failed to read directory")
        .filter_map(|entry| entry.ok())
        .filter(|entry| {
            entry
                .file_name()
                .to_string_lossy()
                .starts_with(&binary_name)
        })
        .map(|entry| entry.path().display().to_string())
        .next()
        .or(binary_from_path)
}

fn get_available_port() -> u16 {
    (30888..40000)
        .find(|port| port_is_available(*port))
        .expect("Failed to find available port")
}

fn port_is_available(port: u16) -> bool {
    TcpListener::bind(("127.0.0.1", port)).is_ok()
}

impl Drop for LlamaCppSupervisor {
    fn drop(&mut self) {
        self.handle.abort();
    }
}

'use client'

import React from 'react'
import TopBarProgress from 'react-topbar-progress-indicator'

import { useCurrentTheme } from '@/lib/hooks/use-current-theme'
import { useDebounceValue } from '@/lib/hooks/use-debounce'
import { useLatest } from '@/lib/hooks/use-latest'

interface TopbarProgressProviderProps {
  children: React.ReactNode
}

interface TopbarProgressContextValue {
  progress: boolean
  setProgress: (v: boolean) => void
}

const TopbarProgressContext = React.createContext<TopbarProgressContextValue>(
  {} as TopbarProgressContextValue
)

const TopbarProgressProvider: React.FC<TopbarProgressProviderProps> = ({
  children
}) => {
  const { theme } = useCurrentTheme()

  const [progress, setProgress] = React.useState(false)
  const [debouncedProgress] = useDebounceValue(progress, 200, { leading: true })
  const latestProgress = useLatest(progress)

  React.useEffect(() => {
    TopBarProgress.config({
      barColors: {
        0: theme === 'dark' ? '#DC981A' : '#B7942B'
        // 0: '#2563eb'
      }
    })
  }, [])

  const updateProgress = React.useCallback((v: boolean) => {
    if (!!v && v === latestProgress.current) return

    setProgress(v)
  }, [])

  return (
    <TopbarProgressContext.Provider
      value={{ progress: debouncedProgress, setProgress: updateProgress }}
    >
      {debouncedProgress && <TopBarProgress />}
      {children}
    </TopbarProgressContext.Provider>
  )
}

const useTopbarProgress = () => {
  return React.useContext(TopbarProgressContext)
}

export { TopbarProgressProvider, useTopbarProgress }

package com.tabbyml.tabby4eclipse.inlineCompletion.trigger;

import java.util.HashMap;
import java.util.Map;

import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.events.KeyEvent;
import org.eclipse.swt.events.KeyListener;
import org.eclipse.swt.events.MouseEvent;
import org.eclipse.swt.events.MouseListener;
import org.eclipse.ui.texteditor.ITextEditor;

import com.tabbyml.tabby4eclipse.Logger;
import com.tabbyml.tabby4eclipse.editor.EditorUtils;
import com.tabbyml.tabby4eclipse.inlineCompletion.IInlineCompletionService;
import com.tabbyml.tabby4eclipse.inlineCompletion.InlineCompletionService;

/**
 * This DocumentBasedTrigger listens to keyboard and mouse events to determine
 * when to trigger inline completion. When a keyboard or mouse key up event is
 * received, check if the cursor is moved, then check if document has changes,
 * and trigger inline completion if so, otherwise dismiss inline completion.
 */
public class BasicInputEventTrigger implements IInlineCompletionTrigger {
	private Logger logger = new Logger("InlineCompletionTrigger.BasicInputEventTrigger");

	private IInlineCompletionService inlineCompletionService = InlineCompletionService.getInstance();

	private Map<ITextEditor, KeyListener> keyListeners = new HashMap<>();
	private Map<ITextEditor, MouseListener> mouseListeners = new HashMap<>();

	private int lastOffset = -1;
	private long lastModificationStamp = -1;

	@Override
	public void register(ITextEditor textEditor) {
		StyledText widget = EditorUtils.getStyledTextWidget(textEditor);
		widget.getDisplay().syncExec(() -> {
			KeyListener keyListener = new KeyListener() {
				@Override
				public void keyPressed(KeyEvent e) {
				}

				@Override
				public void keyReleased(KeyEvent e) {
					handleEvent();
				}
			};
			widget.addKeyListener(keyListener);
			keyListeners.put(textEditor, keyListener);
			logger.debug("Created key listener for TextEditor " + textEditor.toString());

			MouseListener mouseListener = new MouseListener() {
				@Override
				public void mouseDoubleClick(MouseEvent e) {
				}

				@Override
				public void mouseDown(MouseEvent e) {
				}

				@Override
				public void mouseUp(MouseEvent e) {
					handleEvent();
				}
			};
			widget.addMouseListener(mouseListener);
			mouseListeners.put(textEditor, mouseListener);
			logger.debug("Created mouse listener for TextEditor " + textEditor.toString());
		});
	}

	@Override
	public void unregister(ITextEditor textEditor) {
		StyledText widget = EditorUtils.getStyledTextWidget(textEditor);
		widget.getDisplay().syncExec(() -> {
			KeyListener keyListener = keyListeners.get(textEditor);
			if (keyListener != null) {
				widget.removeKeyListener(keyListener);
				keyListeners.remove(textEditor);
				logger.debug("Removed key listener for TextEditor " + textEditor.toString());
			}
			MouseListener mouseListener = mouseListeners.get(textEditor);
			if (mouseListener != null) {
				widget.removeMouseListener(mouseListener);
				mouseListeners.remove(textEditor);
				logger.debug("Removed mouse listener for TextEditor " + textEditor.toString());
			}
		});
	}

	private void handleEvent() {
		logger.debug("handle input event.");
		ITextEditor textEditor = EditorUtils.getActiveTextEditor();
		if (textEditor == null) {
			return;
		}
		int offset = EditorUtils.getCurrentOffsetInDocument(textEditor);
		long modificationStamp = EditorUtils.getDocumentModificationStamp(textEditor);
		if (lastOffset != -1 && lastModificationStamp != -1) {
			if (offset != lastOffset) {
				logger.debug("offset cahnged, check next...");
				if (modificationStamp != lastModificationStamp) {
					logger.debug("modificationStamp changed, trigger inline completion.");
					inlineCompletionService.trigger(false);
				} else {
					logger.debug("modificationStamp not changed, dismiss inline completion.");
					inlineCompletionService.dismiss();
				}
			} else {
				logger.debug("offset not changed, ignore event.");
			}
		} else {
			logger.debug("init offset and modificationStamp.");
		}
		lastOffset = offset;
		lastModificationStamp = modificationStamp;
	}
}

package com.tabbyml.tabby4eclipse.inlineCompletion.trigger;

import java.util.HashMap;
import java.util.Map;

import org.eclipse.jface.text.DocumentEvent;
import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.IDocumentListener;
import org.eclipse.swt.custom.CaretEvent;
import org.eclipse.swt.custom.CaretListener;
import org.eclipse.swt.custom.StyledText;
import org.eclipse.ui.texteditor.ITextEditor;

import com.tabbyml.tabby4eclipse.DebouncedRunnable;
import com.tabbyml.tabby4eclipse.Logger;
import com.tabbyml.tabby4eclipse.editor.EditorUtils;
import com.tabbyml.tabby4eclipse.inlineCompletion.IInlineCompletionService;
import com.tabbyml.tabby4eclipse.inlineCompletion.InlineCompletionService;

/**
 * This DocumentBasedTrigger listens to document and caret events to determine
 * when to trigger inline completion. When a document changed event is received,
 * it waits for a debouncing interval, then triggers inline completion. When a
 * caret event is received, it waits for a debouncing interval, then checks if
 * the current completion context is valid, and dismisses completion if not
 * valid.
 */
public class DebouncedDocumentEventTrigger implements IInlineCompletionTrigger {
	private final static int DOCUMENT_CHANGED_DEBOUNCE_INTERVAL = 3; // ms
	private final static int CARET_MOVED_DEBOUNCE_INTERVAL = 16; // ms

	private Logger logger = new Logger("InlineCompletionTrigger.DebouncedDocumentEventTrigger");

	private IInlineCompletionService inlineCompletionService = InlineCompletionService.getInstance();

	private Map<ITextEditor, CaretListener> caretListeners = new HashMap<>();
	private Map<ITextEditor, IDocumentListener> documentListeners = new HashMap<>();

	@Override
	public void register(ITextEditor textEditor) {
		StyledText widget = EditorUtils.getStyledTextWidget(textEditor);
		widget.getDisplay().syncExec(() -> {
			CaretListener caretListener = new CaretListener() {
				@Override
				public void caretMoved(CaretEvent event) {
					handleCaretMoved(textEditor, event);
				}
			};
			widget.addCaretListener(caretListener);
			caretListeners.put(textEditor, caretListener);
			logger.debug("Created caret listener for TextEditor " + textEditor.toString());
		});

		IDocument document = EditorUtils.getDocument(textEditor);
		IDocumentListener documentListener = new IDocumentListener() {
			@Override
			public void documentAboutToBeChanged(DocumentEvent event) {
			}

			@Override
			public void documentChanged(DocumentEvent event) {
				handleDocumentChanged(textEditor, event);
			}
		};
		document.addDocumentListener(documentListener);
		documentListeners.put(textEditor, documentListener);
		logger.debug("Created document listener for TextEditor " + textEditor.toString());
	}

	@Override
	public void unregister(ITextEditor textEditor) {
		StyledText widget = EditorUtils.getStyledTextWidget(textEditor);
		widget.getDisplay().syncExec(() -> {
			CaretListener caretListener = caretListeners.get(textEditor);
			if (caretListener != null) {
				widget.removeCaretListener(caretListener);
				caretListeners.remove(textEditor);
				logger.debug("Removed caret listener for TextEditor " + textEditor.toString());
			}
		});

		IDocument document = EditorUtils.getDocument(textEditor);
		IDocumentListener documentListener = documentListeners.get(textEditor);
		if (documentListener != null) {
			document.removeDocumentListener(documentListener);
			documentListeners.remove(textEditor);
			logger.debug("Removed document listener for TextEditor " + textEditor.toString());
		}
	}

	private DebouncedRunnable documentChangedRunnable = new DebouncedRunnable(() -> {
		try {
			EditorUtils.syncExec(() -> {
				logger.debug("Trigger inline completion after debouncing.");
				inlineCompletionService.trigger(false);
			});
		} catch (Exception e) {
			logger.error("Failed to handle documentChangedRunnable after debouncing.", e);
		}
	}, DOCUMENT_CHANGED_DEBOUNCE_INTERVAL);

	private DebouncedRunnable caretMovedRunnable = new DebouncedRunnable(() -> {
		try {
			EditorUtils.syncExec(() -> {
				if (!inlineCompletionService.isValid()) {
					logger.debug("Dismiss invalid inline completion after debouncing.");
					inlineCompletionService.dismiss();
				} else {
					logger.debug("Keep still valid inline completion after debouncing.");
				}
			});
		} catch (Exception e) {
			logger.error("Failed to handle caretMovedRunnable after debouncing.", e);
		}
	}, CARET_MOVED_DEBOUNCE_INTERVAL);

	private void handleCaretMoved(ITextEditor textEditor, CaretEvent event) {
		if (!EditorUtils.isActiveEditor(textEditor)) {
			return;
		}
		logger.debug("handleCaretMoved: " + event.toString() + " offset: " + event.caretOffset);
		caretMovedRunnable.call();
	}

	private void handleDocumentChanged(ITextEditor textEditor, DocumentEvent event) {
		if (!EditorUtils.isActiveEditor(textEditor)) {
			return;
		}
		logger.debug("handleDocumentChanged: " + event.toString());
		documentChangedRunnable.call();
	}
}

import type { CancellationToken, Connection, Range } from "vscode-languageserver";
import { TextDocument } from "vscode-languageserver-textdocument";
import fs from "fs-extra";
import type { TextDocuments } from "../extensions/textDocuments";
import type { Feature } from "../feature";
import { ClientCapabilities, ServerCapabilities, ReadFileRequest, ReadFileParams } from "../protocol";
import { getLogger } from "../logger";
import { isBrowser } from "../env";
import { getLanguageId } from "../utils/languageId";

export interface TextDocumentRangeContext {
  uri: string;
  language: string;
  /**
   * If the range is provided, this context presents a range of the text document.
   */
  range?: Range;
  /**
   * The full text of the document if the range is not provided.
   * The text in the range of the document if the range is provided.
   */
  text: string;
}

export class TextDocumentReader implements Feature {
  private readonly logger = getLogger("TextDocumentReader");

  private lspConnection: Connection | undefined = undefined;
  private clientCapabilities: ClientCapabilities | undefined = undefined;

  constructor(private readonly documents: TextDocuments<TextDocument>) {}

  initialize(connection: Connection, clientCapabilities: ClientCapabilities): ServerCapabilities {
    this.lspConnection = connection;
    this.clientCapabilities = clientCapabilities;
    return {};
  }

  async read(
    documentOrUri: TextDocument | string,
    range: Range | undefined,
    token: CancellationToken | undefined,
  ): Promise<TextDocumentRangeContext | undefined> {
    let targetDocument: TextDocument | undefined = undefined;
    let targetUri: string | undefined = undefined;
    if (typeof documentOrUri === "string") {
      targetDocument = this.documents.get(documentOrUri);
      targetUri = documentOrUri;
    } else {
      targetDocument = documentOrUri;
      targetUri = documentOrUri.uri;
    }

    let context: TextDocumentRangeContext | undefined = undefined;
    if (targetDocument) {
      context = {
        uri: targetDocument.uri,
        language: targetDocument.languageId,
        range: range,
        text: targetDocument.getText(range),
      };
      this.logger.trace("Read context from synced text document.", context);
    } else if (targetUri) {
      const language = getLanguageId(targetUri);
      // read from lsp connection
      if (this.lspConnection && this.clientCapabilities?.tabby?.workspaceFileSystem) {
        try {
          const params: ReadFileParams = {
            uri: targetUri,
            format: "text",
            range: range,
          };
          const result = await this.lspConnection.sendRequest(ReadFileRequest.type, params, token);
          if (result && typeof result.text === "string") {
            context = {
              uri: targetUri,
              language: language,
              range: range,
              text: result.text,
            };
            this.logger.trace("Read context from LSP ReadFileRequest.", { result });
          }
        } catch (error) {
          this.logger.trace("ReadFileRequest failed.", { error });
        }
      }

      // fallback to fs
      if (!context && !isBrowser) {
        try {
          const fileContent = await new Promise<string>((resolve, reject) => {
            const readFilePromise = fs.readFile(targetUri, "utf-8");
            if (token) {
              token.onCancellationRequested(() => {
                reject(new Error("Operation canceled"));
              });
            }
            readFilePromise.then(resolve).catch(reject);
          });

          const textDocument = TextDocument.create(targetUri, language, 0, fileContent);
          const text = textDocument.getText(range);
          context = {
            uri: targetUri,
            language: language,
            range: range,
            text: text,
          };
          this.logger.trace("Read context from file system.", { text });
        } catch (error) {
          this.logger.trace("Read file failed.", { error });
        }
      }
    }
    return context;
  }
}

package com.tabbyml.tabby4eclipse.git;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.net.URI;
import java.util.List;

import org.eclipse.jgit.api.Git;
import org.eclipse.jgit.lib.Repository;
